const SEARCH_INDEX=[{"title":"Атлас изборних манипулација","url":"index.html","text":"Атлас изборних манипулација АТЛАС изборних манипулација Ћир Lat Дигитално издање Атлас изборних манипулација Систематизован приказ изборних манипулација, начина њиховог препознавања и документовања, правног оквира и конкретних студија случаја. Претражи Претрага обухвата комплетан садржај дигиталног издања. Главна структура Манипулације према фази изборног процеса PRE Пре избора Изборни услови, бирачки списак, кандидовање и институционална припрема. KAM Током кампање Јавни ресурси, медији, притисци, функционерска кампања и дезинформације. BM На бирачком месту Гласање, рад бирачког одбора и неправилности током изборног дана. BR Током бројања Бројање гласова, записници и поступање са изборним материјалом. POST Након избора Увид, приговори, жалбе, рокови и делотворност правне заштите. CASE Студије случаја Документовани примери изборних неправилности и институционалних реакција. Садржај публикације Основни делови О Атласу Циљ, намена, начин настанка и корисници Атласа изборних манипулација. Правни оквир Уставне основе, изборни закони, правна средства, одговорност и надлежне институције. Методологија Јединствен модел обраде, извори, докази, правни оквир и процена утицаја. Глосар појмова Значење 30 основних појмова који се користе у анализи изборних неправилности и манипулација. Практични обрасци Захтеви, приговори, службене белешке и други документи за практичну примену. Студије случаја Десет документованих примера изборних манипулација, институционалних реакција и поука за будуће изборне процесе. Системски механизми Повезивање неправилности у обрасце, анализа кумулативног ефекта и доказивање системске манипулације. Изборна форензика Правила за чињенично документовање, чување доказа и законито поступање контролора и посматрача. 50 најчешћих грешака контролора Практична контролна листа за припрему, гласање, доказе, записник, приговоре и примопредају материјала. Завршна порука Завршна разматрања о улози контролора и посматрача, употребљивим доказима и очувању изборног интегритета. Атлас изборних манипулација није само опис неправилности, већ практичан водич за њихово препознавање, документовање и правно оспоравање."},{"title":"50 најчешћих грешака изборних контролора — Атлас изборних манипулација","url":"pages/50-gresaka-kontrolora.html","text":"50 најчешћих грешака изборних контролора — Атлас изборних манипулација АТЛАС изборних манипулација Ћир Lat Почетна / Прилог / 50 најчешћих грешака Практични прилог 50 најчешћих грешака изборних контролора Како се губе избори и онда када су гласови освојени Одштампај као контролну листу Отвори списак Категорије I Пре отварања бирачког места 5 II Током гласања 10 III Докази 9 IV Записник 6 V Приговори 10 VI После бројања 5 VII Комуникација 5 ★ Златно правило Грешке су организоване према фази рада контролора. Списак може да се користи као кратак подсетник пре и током изборног дана. I Пре отварања бирачког места Провера основних услова пре почетка гласања. 5 грешака 1 Долазак на бирачко место после почетка рада. 2 Непроверавање да ли је гласачка кутија празна. 3 Непроверавање серијских бројева и печата. 4 Непроверавање броја примљених гласачких листића. 5 Неупознавање са члановима бирачког одбора. II Током гласања Правовремено реаговање и прецизно бележење током изборног дана. 10 грешака 6 Неевидентирање времена када се неправилност догодила. 7 Ослањање на памћење уместо вођења белешки. 8 Неписање службене белешке одмах по догађају. 9 Бележење закључака уместо чињеница. 10 Улазак у расправу са члановима бирачког одбора. 11 Расправљање са гласачима. 12 Напуштање бирачког места без замене. 13 Недовољно познавање изборних прописа. 14 Неуказивање на неправилност одмах након што је уочена. 15 Усмено реаговање без тражења да се примедба унесе у записник. III Докази Прикупљање и чување употребљивих доказа. 9 грешака 16 Нефотографисање неправилности када је то дозвољено. 17 Прављење нечитљивих фотографија. 18 Неснимање видео-записа када постоји потреба. 19 Брисање оригиналних снимака. 20 Слање једине копије снимка преко апликација које смањују квалитет. 21 Необележавање шта који доказ приказује. 22 Незаписивање имена сведока. 23 Незаписивање контакт података сведока. 24 Ослањање искључиво на усмене изјаве. IV Записник Контрола садржаја записника пре потписивања. 6 грешака 25 Непажљиво читање записника пре потписивања. 26 Потписивање записника без примедбе. 27 Неуношење издвојеног мишљења. 28 Непроверавање математичких података у записнику. 29 Непроверавање да ли се бројеви слажу. 30 Неузимање копије записника. V Приговори Формална исправност и благовременост правне заштите. 10 грешака 31 Пропуштање законског рока. 32 Погрешно означавање подносиоца. 33 Погрешан назив изборне листе. 34 Недостаје овлашћење. 35 Недостаје потпис. 36 Недостаје правни основ. 37 Недовољно прецизан опис неправилности. 38 Неприлагање доказа. 39 Непотпун списак прилога. 40 Нејасан захтев шта комисија треба да одлучи. VI После бројања Завршна контрола материјала, записника и примопредаје. 5 грешака 41 Одлазак пре завршетка рада бирачког одбора. 42 Непроверавање паковања изборног материјала. 43 Непроверавање да ли су сви записници потписани. 44 Неевидентирање неправилности приликом примопредаје материјала. 45 Непраћење транспорта изборног материјала када је то дозвољено. VII Комуникација Правовремена сарадња са изборним и правним тимом. 5 грешака 46 Самостално доношење важних правних одлука без консултације са правним тимом. 47 Касно обавештавање изборног штаба о озбиљним неправилностима. 48 Објављивање доказа на друштвеним мрежама пре него што буду достављени правном тиму. 49 Остављање оригиналних докумената без копије. 50 Претпоставка да је „све јасно“ и да мањи формални пропусти неће бити искоришћени против изборне листе. Завршна напомена Златно правило изборног контролора Контролор не побеђује на изборима доказујући да је у праву, већ доказујући чињенице на начин који се може правно употребити. Неправилност која није благовремено забележена, документована и поткрепљена доказима, као да се није ни догодила. Једнако тако, захтев или приговор који није сачињен у складу са законом може бити одбачен без разматрања његове суштине. Зато је задатак контролора да сваки догађај забележи прецизно, потпуно и на начин који омогућава његову каснију правну употребу. ↑ На врх странице"},{"title":"BM — Манипулације на бирачком месту","url":"pages/bm.html","text":"BM — Манипулације на бирачком месту АТЛАС изборних манипулација Ћир Lat Почетна / BM — бирачко место BM Манипулације на бирачком месту Комплетан текст седмог поглавља Атласа изборних манипулација: 29 манипулација на бирачком месту, поступање контролора, документовање и препознавање организованих образаца. Изаберите фазу изборног процеса: PRE Пре избора KAM Током кампање BM На бирачком месту BR Током бројања POST Након избора 7.1. Значај бирачког места Бирачко место је тачка на којој се уставно право грађанина претвара у конкретан глас. Зато су процедура, ред, тајност и тачно евидентирање сваке радње од пресудног значаја. Неправилност на бирачком месту може бити: ненамерна грешка; последица недовољне обуке; појединачна злоупотреба; део организованог механизма; покушај да се утиче на већи број гласова. Није сваки пропуст доказ преваре. Међутим, ни наизглед мала неправилност не сме бити занемарена ако се понавља, ако је намерна или ако онемогућава каснију проверу. За сваку спорну радњу треба забележити: тачно време; бирачко место; име или функцију лица које је поступало; опис радње; реакцију бирачког одбора; сведоке; расположиве доказе; да ли је примедба унета у записник. Преглед BM манипулација BM-01 Неправилно отварање бирачког места BM-02 Неисправна контрола идентитета бирача BM-03 Гласање у туђе име BM-04 Вишеструко гласање BM-05 Неупотребљавање или неправилна употреба ув лампе и спреја BM-06 Издавање листића без потписа бирача BM-07 Лажно потписивање у бирачком списку BM-08 Издавање више гласачких листића једном бирачу BM-09 Неовлашћено додавање, уклањање или изношење листића BM-10 „Бугарски воз“ BM-11 Фотографисање гласачког листића BM-12 Нарушавање тајности гласања BM-13 Породично или групно гласање BM-14 Неовлашћено помагање бирачу BM-15 Злоупотреба гласања ван бирачког места BM-16 Вођење паралелних спискова на бирачком месту BM-17 Организовано праћење излазности конкретних бирача BM-18 Страначки пунктови у близини бирачког места BM-19 Неовлашћено присуство лица на бирачком месту BM-20 Притисак на чланове бирачког одбора BM-21 Онемогућавање рада посматрача BM-22 Агитација на бирачком месту BM-23 Застрашивање бирача BM-24 Организовани превоз уз контролу бирача BM-25 Неосновано спречавање бирача да гласа BM-26 Неовлашћено снимање и нарушавање приватности BM-27 Несагласност броја бирача, потписа и издатих листића BM-28 Организовано прекомерно пријављивање бирача за гласање ван бирачког места BM-29 Инсценирање изборних неправилности ради дискредитације изборне контроле BM-01 Неправилно отварање бирачког места Фаза Гласање на бирачком месту Процена утицаја Средњи, а ако је пропуст намеран или онемогућава контролу — висок. Кључни докази забележити време доласка и отварања;; фотографисати простор пре почетка гласања када је то дозвољено;; проверити број примљених листића;; тражити да се сва одступања унесу у записник; Надлежни органи Бирачки одбор и надлежна изборна комисија; други органи зависно од чињеница. Повезане манипулације BM-11 Кратка дефиниција Неправилно отварање постоји када бирачко место почне рад супротно прописаној процедури или без испуњених услова за безбедно и законито гласање. Могући облици кашњење без оправданог разлога; отварање без потребног броја чланова; непроверена гласачка кутија; непопуњен или неправилно попуњен контролни лист; непотпун изборни материјал; неевидентиране гласачке коверте; присуство страначког материјала; неприступачан простор; одсуство паравана; присуство неовлашћених лица; неусаглашено стање примљених листића. Како документовати забележити време доласка и отварања; фотографисати простор пре почетка гласања када је то дозвољено; проверити број примљених листића; тражити да се сва одступања унесу у записник; забележити који чланови су били присутни. Процена утицаја Средњи, а ако је пропуст намеран или онемогућава контролу — висок. ↑ Назад на преглед BM-02 Неисправна контрола идентитета бирача Фаза Гласање на бирачком месту Процена утицаја Висок. Кључни докази Записник, службена белешка, изјаве сведока и законито прибављени материјали. Надлежни органи Бирачки одбор и надлежна изборна комисија; други органи зависно од чињеница. Повезане манипулације BM-11 Кратка дефиниција Постоји када се бирачу дозволи гласање без прописане провере идентитета или када се документ прихвати иако не припада лицу које гласа. Могући облици прихватање туђег документа; гласање без важећег документа; површно поређење фотографије; прихватање копије када није дозвољена; игнорисање очигледног неслагања; издавање листића пре завршене провере. Показатељи лице избегава да покаже документ; подаци и изглед се не поклапају; документ се брзо прослеђује без контроле; исти члан одбора понавља такво поступање; члан одбора каже да „познаје“ бирача и не врши проверу. Хитна реакција Не издавати листић док се идентитет законито не утврди. Спор решава цео бирачки одбор, а не један члан самостално. Процена утицаја Висок. ↑ Назад на преглед BM-03 Гласање у туђе име Фаза Гласање на бирачком месту Процена утицаја Висок. Кључни докази извод из бирачког списка;; спорни потпис;; изјава стварног бирача;; сведочење чланова одбора; Надлежни органи бирачки одбор;; изборна комисија;; полиција;; јавно тужилаштво. Повезане манипулације BM-02 BM-07 Кратка дефиниција Гласање у туђе име постоји када лице користи идентитет другог бирача и гласа уместо њега. Начин функционисања употреба туђег документа; коришћење података преминулог или одсутног лица; сарадња са чланом бирачког одбора; лажно потписивање; гласање пре доласка стварног бирача; издавање листића без провере. Показатељи стварни бирач долази и затиче потпис; потпис се очигледно разликује; лице не зна основне податке; члан одбора покушава да убрза поступак; документ и изглед не одговарају. Докази извод из бирачког списка; спорни потпис; изјава стварног бирача; сведочење чланова одбора; видео-надзор испред објекта, ако постоји; службена белешка. Надлежне институције бирачки одбор; изборна комисија; полиција; јавно тужилаштво. Процена утицаја Висок. ↑ Назад на преглед BM-04 Вишеструко гласање Фаза Гласање на бирачком месту Процена утицаја Висок. Кључни докази Записник, службена белешка, изјаве сведока и законито прибављени материјали. Надлежни органи Бирачки одбор и надлежна изборна комисија; други органи зависно од чињеница. Повезане манипулације BM-02 BM-05 BM-07 Кратка дефиниција Вишеструко гласање постоји када исто лице гласа више пута. Обухвата покушај или извршење гласања истог лица више пута на истим или различитим бирачким местима. Могући механизми гласање на више бирачких места; вишеструки упис; гласање под више идентитета; пропуст у употреби УВ лампе и спреја; сарадња са члановима одбора; гласање у земљи и иностранству супротно правилима; употреба више листића. Показатељи траг спреја на прсту; лице не жели проверу; више докумената; податак да је лице већ потписано; организовано кретање истих лица; неслагање између броја потписа и листића. Хитна реакција Не дозволити гласање док се не провери чињенично стање. Сумњу забележити и, по потреби, обавестити надлежне органе. Процена утицаја Висок. ↑ Назад на преглед BM-05 Неупотребљавање или неправилна употреба ув лампе и спреја Фаза Гласање на бирачком месту Процена утицаја Средњи до висок. Кључни докази Записник, службена белешка, изјаве сведока и законито прибављени материјали. Надлежни органи Бирачки одбор и надлежна изборна комисија; други органи зависно од чињеница. Повезане манипулације BM-04 Кратка дефиниција Постоји када се не проверава да ли је бирач већ гласао или се бирач не обележава у складу са процедуром. Могући облици лампа се уопште не користи; провера се врши површно; спреј се не наноси; наноси се на погрешно место; опрема не ради, а гласање се наставља без решења; бирач се неосновано одбија због сумњивог трага. Значај Ове радње имају превентивну функцију. Њихово занемаривање повећава ризик од вишеструког гласања. Процена утицаја Средњи до висок. ↑ Назад на преглед BM-06 Издавање листића без потписа бирача Фаза Гласање на бирачком месту Процена утицаја Висок. Кључни докази Записник, службена белешка, изјаве сведока и законито прибављени материјали. Надлежни органи Бирачки одбор и надлежна изборна комисија; други органи зависно од чињеница. Повезане манипулације BM-03 BM-07 Кратка дефиниција Гласачки листић издаје се лицу које није претходно потписало извод из бирачког списка. Ризици број издатих листића не одговара броју потписа; могуће је прикривање вишка листића; отежава се утврђивање броја бирача; може се прикрити гласање у туђе име. Хитна реакција Поступак треба зауставити док се пропуст не исправи на законит начин. Ако је бирач већ отишао, догађај се мора забележити. Процена утицаја Висок. ↑ Назад на преглед BM-07 Лажно потписивање у бирачком списку Фаза Гласање на бирачком месту Процена утицаја Висок. Кључни докази оригинални извод;; фотографија спорног дела када је дозвољена;; изјава стварног бирача;; графолошко вештачење; Надлежни органи Бирачки одбор и надлежна изборна комисија; други органи зависно од чињеница. Повезане манипулације BM-11 Кратка дефиниција Постоји када неко потпише извод уместо другог лица или накнадно додаје потписе ради прикривања неслагања. Показатељи више потписа истим рукописом; потписи исте величине и нагиба; стварни бирач затиче потпис; потпис је унет после гласања; потписи се додају током бројања. Докази оригинални извод; фотографија спорног дела када је дозвољена; изјава стварног бирача; графолошко вештачење; сведочење присутних чланова. Процена утицаја Висок. ↑ Назад на преглед BM-08 Издавање више гласачких листића једном бирачу Фаза Гласање на бирачком месту Процена утицаја Висок. Кључни докази Записник, службена белешка, изјаве сведока и законито прибављени материјали. Надлежни органи Бирачки одбор и надлежна изборна комисија; други органи зависно од чињеница. Повезане манипулације BM-09 Кратка дефиниција Бирачу се издаје више листића за исту врсту избора. Могући узроци немар; неорганизован рад; листићи су слепљени; намерно издавање вишка; сарадња са бирачем; припрема за изношење листића. Хитна реакција Вишак листића се не сме самовољно уништити. Цео одбор мора утврдити стање и поступити по важећем упутству. Процена утицаја Висок. ↑ Назад на преглед BM-09 Неовлашћено додавање, уклањање или изношење листића Фаза Гласање на бирачком месту Процена утицаја Висок или системски. Кључни докази Записник, службена белешка, изјаве сведока и законито прибављени материјали. Надлежни органи Бирачки одбор и надлежна изборна комисија; други органи зависно од чињеница. Повезане манипулације — Кратка дефиниција Обухвата свако неовлашћено поступање којим се гласачки листић додаје у кутију, уклања из ње или износи са бирачког места. Могући облици убацивање већег броја листића; изношење празног листића; замена попуњеног листића; сакривање листића; неовлашћено располагање неискоришћеним листићима; убацивање листића из другог изборног поступка. Показатељи листић без одговарајућег поступка издавања; више листића у руци једног лица; покушај изношења пресавијеног папира; неовлашћено лице прилази материјалу; број листића не одговара евиденцији. Процена утицаја Висок или системски. ↑ Назад на преглед BM-10 „Бугарски воз“ Фаза Гласање на бирачком месту Процена утицаја Висок или системски. Кључни докази Записник, службена белешка, изјаве сведока и законито прибављени материјали. Надлежни органи Бирачки одбор и надлежна изборна комисија; други органи зависно од чињеница. Повезане манипулације BM-18 Кратка дефиниција „Бугарски воз“ је организовани облик контролисаног гласања у којем бирач добија унапред попуњен листић, убацује га у кутију, а празан листић који је добио на бирачком месту износи организатору. Типичан механизам организатор обезбеди један празан листић; листић попуни; преда га првом бирачу; бирач убацује попуњен листић; износи празан листић; организатор га попуњава за следећег бирача; циклус се понавља. Показатељи бирач улази са пресавијеним листићем; покушава да сакрије празан листић; бирачи после гласања одлазе истом лицу; постоји пункт за предају листића; исти активиста контролише више лица; лице одбија да покаже шта износи. Хитна реакција Чланови одбора не смеју претресати бирача. Потребно је забележити радњу, заштитити изборни материјал и обавестити надлежне органе када постоји основана сумња. Процена утицаја Висок или системски. ↑ Назад на преглед BM-11 Фотографисање гласачког листића Фаза Гласање на бирачком месту Процена утицаја Средњи, а као део контролисаног гласања — висок или системски. Кључни докази Записник, службена белешка, изјаве сведока и законито прибављени материјали. Надлежни органи Бирачки одбор и надлежна изборна комисија; други органи зависно од чињеница. Повезане манипулације BM-12 BM-23 Кратка дефиниција Бирач фотографише попуњен листић, најчешће ради доказивања начина гласања другом лицу. Може служити као доказ купцу гласа, послодавцу, страначком активисти или другом лицу. Могуће сврхе куповина гласа; политичка контрола; доказ послодавцу; доказ страначком активисти; лично објављивање; застрашивање или показивање лојалности. Правна и практична оцена Фотографија сама по себи не доказује куповину гласа. Потребно је утврдити контекст: коме се шаље; да ли је тражена; да ли следи исплата; да ли постоји притисак; да ли је део ширег система. Хитна реакција Треба заштитити тајност гласања и поступити према упутству. Не сме се самовољно одузимати телефон нити брисати садржај. Процена утицаја Средњи, а као део контролисаног гласања — висок или системски. ↑ Назад на преглед BM-12 Нарушавање тајности гласања Фаза Гласање на бирачком месту Процена утицаја Висок, јер тајност гласања штити слободу избора. Кључни докази Записник, службена белешка, изјаве сведока и законито прибављени материјали. Надлежни органи Бирачки одбор и надлежна изборна комисија; други органи зависно од чињеница. Повезане манипулације BM-11 Кратка дефиниција Тајност је нарушена када друго лице може видети, сазнати, контролисати или накнадно утврдити за кога је бирач гласао. Могући облици неправилно постављени паравани; видљивост попуњеног листића; више лица иза паравана; праћење бирача; читање листића наглас; означавање листића ради идентификације; фотографисање; притисак да се покаже листић; члан одбора стоји сувише близу. Процена утицаја Висок, јер тајност гласања штити слободу избора. ↑ Назад на преглед BM-13 Породично или групно гласање Фаза Гласање на бирачком месту Процена утицаја Средњи, а уз принуду — висок. Кључни докази Записник, службена белешка, изјаве сведока и законито прибављени материјали. Надлежни органи Бирачки одбор и надлежна изборна комисија; други органи зависно од чињеница. Повезане манипулације — Кратка дефиниција Породично или групно гласање постоји када један члан породице или групе одређује, контролише или обавља гласање других чланова без законског основа. Типичне ситуације више чланова заједно иза паравана; једно лице попуњава више листића; члан породице или групе говори шта да се заокружи; старије или зависно лице не може слободно да гласа; помоћ се пружа иако није потребна. Важно разграничење Законита помоћ бирачу не сме се изједначити са породичним или групним гласањем. Кључно је да бирач сам изрази вољу и сам одабере лице које му помаже, када су услови испуњени. Процена утицаја Средњи, а уз принуду — висок. ↑ Назад на преглед BM-14 Неовлашћено помагање бирачу Фаза Гласање на бирачком месту Процена утицаја Висок ако је организовано. Кључни докази Записник, службена белешка, изјаве сведока и законито прибављени материјали. Надлежни органи Бирачки одбор и надлежна изборна комисија; други органи зависно од чињеница. Повезане манипулације — Кратка дефиниција Помоћ се пружа лицу које за њу не испуњава услове или је пружа лице које утиче на избор. Ризични облици исто лице помаже великом броју бирача; члан одбора сугерише избор; пратилац попуњава листић без питања бирача; бирач не даје сагласност; помоћ се користи као средство контроле; лице које помаже има страначку улогу. Процена утицаја Висок ако је организовано. ↑ Назад на преглед BM-15 Злоупотреба гласања ван бирачког места Фаза Гласање на бирачком месту Процена утицаја Висок. Кључни докази списак пријављених лица;; време одласка и повратка;; имена чланова тима;; број понетих и враћених коверата; Надлежни органи Бирачки одбор и надлежна изборна комисија; други органи зависно од чињеница. Повезане манипулације BM-12 Кратка дефиниција Постоји када се поступак гласања ван бирачког места организује или спроведе супротно прописима. Могући облици лице није тражило гласање ван бирачког места; захтев подноси друго лице без основа; тим одлази на погрешну адресу; тајност није обезбеђена; члан породице утиче на бирача; коверта се не затвара правилно; материјал остаје без надзора; листић се замењује; нетачно се евидентира ко је гласао; тим се не враћа у прописаном саставу. Документовање списак пријављених лица; време одласка и повратка; имена чланова тима; број понетих и враћених коверата; примедбе чланова; сведочење бирача или породице; стање материјала. Посебни ризици организованог гласања ван бирачког места Гласање ван бирачког места спроводи се изван простора у коме су присутни сви чланови бирачког одбора, посматрачи и јавност, па је степен непосредне контроле мањи него на редовном бирачком месту. Због тога велики или нагло увећан број захтева мора бити посматран као показатељ повећаног ризика, а не као доказ неправилности сам по себи. Посебан ризик постоји када захтеве организовано подносе страначки активисти, када се пријављују лица која нису лично исказала вољу да гласају на овај начин или када тим на адреси не може да пронађе пријављеног бирача. У таквим околностима могу настати услови за контролисано гласање, гласање другог лица, нарушавање тајности и накнадно прилагођавање евиденција. Контролори треба да упореде број примљених захтева са уобичајеним обимом, забележе ко је и када захтев примио, провере да ли је бирач затечен на пријављеној адреси и у записник унесу сваки случај у коме чињенично стање не одговара пријави. Већи број оваквих случајева на више бирачких места може указивати на организован образац. Повезана анализа: Студија случаја 4 — тајност гласања, породично гласање и доказивање политичке лојалности . Процена утицаја Висок. ↑ Назад на преглед BM-16 Вођење паралелних спискова на бирачком месту Фаза Гласање на бирачком месту Процена утицаја Висок или системски. Кључни докази Записник, службена белешка, изјаве сведока и законито прибављени материјали. Надлежни органи Бирачки одбор и надлежна изборна комисија; други органи зависно од чињеница. Повезане манипулације BM-17 Кратка дефиниција Неовлашћена лица или чланови одбора бележе ко је гласао и податке достављају политичким штабовима. Показатељи преписивање имена из извода; означавање бирача у приватној табели; телефоном се јавља ко је дошао; активиста добија редовне извештаје; спискови се износе са бирачког места; бележи се редни број бирача у бирачком списку. Зашто је опасно Омогућава: контролу излазности; накнадно позивање бирача; политички притисак; повезивање службених и страначких података; одмазду. Процена утицаја Висок или системски. ↑ Назад на преглед BM-17 Организовано праћење излазности конкретних бирача Фаза Гласање на бирачком месту Процена утицаја Системски. Кључни докази Записник, службена белешка, изјаве сведока и законито прибављени материјали. Надлежни органи Бирачки одбор и надлежна изборна комисија; други органи зависно од чињеница. Повезане манипулације BM-24 Кратка дефиниција Праћење постаје манипулативно када се користи за позивање, притисак, превоз или контролу одређених лица. Разграничење Објављивање укупне излазности је легитимно. Спорно је праћење именом и презименом. Показатељи штаб добија спискове лица која нису гласала; активисти одмах позивају конкретне бираче; руководилац проверава запослене; бележи се време доласка; организује се превоз након извештаја са бирачког места. Процена утицаја Системски. ↑ Назад на преглед BM-18 Страначки пунктови у близини бирачког места Фаза Гласање на бирачком месту Процена утицаја Висок. Кључни докази тачна локација;; удаљеност од бирачког места;; фотографија;; имена или опис лица; Надлежни органи Бирачки одбор и надлежна изборна комисија; други органи зависно од чињеница. Повезане манипулације BM-11 BM-23 BM-24 Кратка дефиниција Пунктови су места на којима активисти евидентирају бираче, који могу бити уцењени или подмићени, дају им упутства, организују превоз или им дају новац и деле користи. Могуће функције вођење спискова; позивање бирача; подела новца; проверa фотографија; организовање превоза; давање упутстава; застрашивање; координација посматрања бирачког места. Документовање тачна локација; удаљеност од бирачког места; фотографија; имена или опис лица; регистарске ознаке возила; материјал који се дели; време активности; сведоци. Процена утицаја Висок. ↑ Назад на преглед BM-19 Неовлашћено присуство лица на бирачком месту Фаза Гласање на бирачком месту Процена утицаја Средњи до висок. Кључни докази Записник, службена белешка, изјаве сведока и законито прибављени материјали. Надлежни органи Бирачки одбор и надлежна изборна комисија; други органи зависно од чињеница. Повезане манипулације BM-12 BM-20 BM-21 Кратка дефиниција На бирачком месту борави лице које нема законски основ да буде присутно. Обухвата страначке активисте, функционере, руководиоце, обезбеђење, представнике неовлашћених медија или друга лица без законског основа. Могућа лица страначки активисти; локални функционери; директори јавних предузећа; неакредитовани посматрачи; приватно обезбеђење; лица која дају инструкције одбору; медији без одговарајућег основа; полиција без потребе утврђене законом. Ризици утицај на бираче; притисак на чланове; нарушавање тајности; приступ изборном материјалу; стварање страха. Процена утицаја Средњи до висок. ↑ Назад на преглед BM-20 Притисак на чланове бирачког одбора Фаза Гласање на бирачком месту Процена утицаја Висок. Кључни докази тачне речи претње;; време;; имена присутних;; поруке; Надлежни органи Бирачки одбор и надлежна изборна комисија; други органи зависно од чињеница. Повезане манипулације BM-07 Кратка дефиниција Члан бирачког одбора се принуђава да поступи супротно закону, да не реагује на неправилност или да потпише спорни документ. Облици претња; викање; физичко приближавање; претња смењивањем; налог страначког координатора; ускраћивање увида; одузимање материјала; захтев за потписивање празног записника; онемогућавање примедбе. Документовање тачне речи претње; време; имена присутних; поруке; сведоци; примедба у записнику; пријава полицији ако постоји непосредна опасност. Процена утицаја Висок. ↑ Назад на преглед BM-21 Онемогућавање рада посматрача Фаза Гласање на бирачком месту Процена утицаја Висок. Кључни докази Записник, службена белешка, изјаве сведока и законито прибављени материјали. Надлежни органи Бирачки одбор и надлежна изборна комисија; други органи зависно од чињеница. Повезане манипулације BM-25 Кратка дефиниција Акредитованом посматрачу се неоправдано ограничава присуство или праћење поступка. Облици удаљавање без разлога; постављање на место без видљивости; забрана бележења; ускраћивање приступа отварању или бројању; претње; захтев да преда белешке; спречавање да види кључне процедуре. Важно разграничење Посматрач нема право да руководи радом одбора, додирује материјал или омета гласање. Ограничење је оправдано само ако је засновано на конкретном поступању, а не на самој улози посматрача. Процена утицаја Висок. ↑ Назад на преглед BM-22 Агитација на бирачком месту Фаза Гласање на бирачком месту Процена утицаја Средњи, а ако је организована — висок. Кључни докази Записник, службена белешка, изјаве сведока и законито прибављени материјали. Надлежни органи Бирачки одбор и надлежна изборна комисија; други органи зависно од чињеница. Повезане манипулације — Кратка дефиниција Постоји када се бирачи позивају или усмеравају да гласају за одређеног учесника. Облици усмени позив; страначка значка; слоган; списак кандидата на видљивом месту; одећа са политичким обележјем; летак; показивање редног броја; сигнал или договорени гест; страначка порука на телефону. Процена утицаја Средњи, а ако је организована — висок. ↑ Назад на преглед BM-23 Застрашивање бирача Фаза Гласање на бирачком месту Процена утицаја Висок. Кључни докази Записник, службена белешка, изјаве сведока и законито прибављени материјали. Надлежни органи Бирачки одбор и надлежна изборна комисија; други органи зависно од чињеница. Повезане манипулације BM-26 Кратка дефиниција Обухвата присуство лица чија је улога да изазову страх, претње, снимање бирача, праћење или демонстрацију политичке и физичке моћи. Бирач се доводи у стање страха Показатељи групе лица испред улаза; снимање сваког бирача; прозивање именом; праћење након гласања; присуство послодавца; познате насилне групе; упозорење да ће се знати ко није гласао. Процена утицаја Висок. ↑ Назад на преглед BM-24 Организовани превоз уз контролу бирача Фаза Гласање на бирачком месту Процена утицаја Висок. Кључни докази Записник, службена белешка, изјаве сведока и законито прибављени материјали. Надлежни органи Бирачки одбор и надлежна изборна комисија; други органи зависно од чињеница. Повезане манипулације BM-18 Кратка дефиниција Превоз постаје манипулативан када је повезан са притиском, евиденцијом, куповином гласа или провером политичке лојалности. Показатељи возач има списак; бирачи се прозивају; одлазе на пункт после гласања; превоз је условљен политичком подршком; исти организатор контролише више возила; путници добијају упутства. путници добијају попуњен листић уз обавезу да донесу празан Процена утицаја Висок. ↑ Назад на преглед BM-25 Неосновано спречавање бирача да гласа Фаза Гласање на бирачком месту Процена утицаја Висок. Кључни докази Записник, службена белешка, изјаве сведока и законито прибављени материјали. Надлежни органи Бирачки одбор и надлежна изборна комисија; други органи зависно од чињеница. Повезане манипулације — Кратка дефиниција Бирачу се без законског основа ускраћује гласачки листић или приступ бирачком месту. Могући облици неосновано одбијање документа; погрешно тумачење података у списку; тврдња да је бирач већ гласао; физичко спречавање; затварање пре времена; неприступачан улаз; одбијање разумне помоћи особи са инвалидитетом; неједнако поступање према појединим групама. Хитна реакција Захтевати да цео одбор размотри случај и да се разлог одбијања документује. Процена утицаја Висок. ↑ Назад на преглед BM-26 Неовлашћено снимање и нарушавање приватности Фаза Гласање на бирачком месту Процена утицаја Средњи до висок. Кључни докази Записник, службена белешка, изјаве сведока и законито прибављени материјали. Надлежни органи Бирачки одбор и надлежна изборна комисија; други органи зависно од чињеница. Повезане манипулације BM-11 Кратка дефиниција Обухвата снимање докумената, извода, бирача или гласачких листића на начин који открива личне податке или политички избор. Ризични облици снимање извода из бирачког списка; фотографисање личних докумената; снимање простора иза паравана; снимање попуњених листића; јавно објављивање имена бирача; директан пренос са места на којем се види поступак гласања. Процена утицаја Средњи до висок. ↑ Назад на преглед BM-27 Несагласност броја бирача, потписа и издатих листића Фаза Гласање на бирачком месту Процена утицаја Висок. Кључни докази Записник, службена белешка, изјаве сведока и законито прибављени материјали. Надлежни органи Бирачки одбор и надлежна изборна комисија; други органи зависно од чињеница. Повезане манипулације BM-07 BM-09 Кратка дефиниција Постоји када број потписаних бирача, издатих листића, употребљених листића и преосталог материјала није логички усаглашен. Могући узроци административна грешка; издавање без потписа; више листића једном бирачу; лажно потписивање; изношење листића; додавање листића; погрешно вођење евиденције; мешање материјала различитих избора. Значај Неслагање није увек доказ преваре, али се не сме прикривати. Мора бити утврђено и описано пре попуњавања записника. Недозвољени начини „исправке“ накнадно додавање потписа; уништавање листића; мењање бројева без поновне провере; договор да се неслагање не унесе; прилагођавање резултата очекиваном броју. Процена утицаја Висок. ↑ Назад на преглед BM-28 Организовано прекомерно пријављивање бирача за гласање ван бирачког места Фаза Гласање на бирачком месту Процена утицаја Висок, нарочито ако је организовано на већем броју бирачких места. Кључни докази евиденцију поднетих захтева;; време и начин пријављивања;; записнике бирачког одбора;; податке о броју гласања ван бирачког места; Надлежни органи Бирачки одбор и надлежна изборна комисија; други органи зависно од чињеница. Повезане манипулације BM-12 BM-15 Студија 4 Фаза изборног процеса: BM – дан гласања Опис Ова неправилност обухвата организовано пријављивање већег броја бирача за гласање ван бирачког места без њихове стварне иницијативе или без постојања законом прописаних разлога. Уместо да захтев за гласање ван бирачког места поднесе сам бирач или члан његовог домаћинства због старости, болести, инвалидитета или других оправданих разлога, пријаве организовано подносе политички субјекти или њихови активисти, користећи претходно формиране евиденције тзв. сигурних или капиларних гласача. На овај начин број гласача који гласају ван бирачког места може бити знатно већи од уобичајеног, чиме се ствара простор за различите облике изборних злоупотреба. Начин функционисања Манипулација се најчешће спроводи: организованим прикупљањем спискова сигурних гласача; пријављивањем бирача без њихове непосредне иницијативе; подношењем већег броја захтева преко страначких активиста; усмеравањем чланова бирачког одбора на адресе које су претходно одредили страначки штабови; организовањем великог броја гласања ван бирачког места без стварне потребе. Зашто је важно Гласање ван бирачког места представља изузетак од редовног поступка гласања и подразумева знатно мањи степен јавне контроле. Уколико се број таквих гласања вештачки повећава, повећава се и ризик од: контролисаног гласања; повреде тајности гласања; присуства неовлашћених лица приликом гласања; утицаја на вољу бирача; гласања другог лица у име бирача; других неправилности које је значајно теже открити него на самом бирачком месту. Посебан ризик постоји ако у трочланој комисији која обилази бираче нема представника стварне опозиције или ако је њен састав фактички под контролом једног политичког субјекта. Како препознати неуобичајено велики број захтева за гласање ван бирачког места; велики број захтева поднетих преко истих лица; организовано пријављивање читавих група бирача; значајно одступање броја таквих гласања у односу на претходне изборе; велики број гласача који нису сами поднели захтев; истовремено појављивање великог броја адреса које су повезане са истим страначким активистима. Како документовати евиденцију поднетих захтева; време и начин пријављивања; записнике бирачког одбора; податке о броју гласања ван бирачког места; изјаве самих бирача о томе ко је поднео захтев; упоредне статистичке анализе са претходним изборима. Правни оквир Може указивати на злоупотребу поступка гласања ван бирачког места, повреду начела слободног и непосредног вршења бирачког права, као и повреду начела једнакости изборних учесника, у зависности од конкретних околности. Процена утицаја Висок, нарочито ако је организовано на већем броју бирачких места. Јачина доказа Највећу доказну вредност имају службене евиденције о пријавама, записници бирачких одбора, статистички подаци који показују необично висок број гласања ван бирачког места, као и изјаве бирача о начину подношења захтева. Препоручена реакција Захтевати евидентирање начина подношења сваког захтева, документовати број и структуру пријављених бирача, обезбедити присуство представника различитих изборних листа у комисијама које обилазе бираче и пријавити сваки случај када постоји основана сумња да захтев није поднет вољом самог бирача. ↑ Назад на преглед BM-29 Инсценирање изборних неправилности ради дискредитације изборне контроле Фаза Гласање на бирачком месту Процена утицаја Средњи до висок, нарочито ако је праћена организованом медијском кампањом. Кључни докази идентитет и формални статус учесника;; записнике бирачких одбора;; оригиналне снимке и њихову временску линију;; изјаве сведока; Надлежни органи Бирачки одбор и надлежна изборна комисија; други органи зависно од чињеница. Повезане манипулације BM-02 Фаза изборног процеса: BM – дан гласања Опис Ова манипулација обухвата намерно изазивање или инсценирање изборних неправилности са циљем да се одговорност за њих припише другој изборној листи, њеним контролорима или другим учесницима изборног процеса. Манипулација може бити спроведена ангажовањем лица која се лажно представљају као контролори или представници одређене изборне листе, или лица која су формално именована испред једне изборне листе, а у стварности поступају по налогу другог политичког субјекта. Циљ није непосредна промена резултата гласања, већ стварање привида да све стране подједнако крше изборна правила, чиме се релативизују стварно утврђене неправилности и умањује кредибилитет изборне контроле. Начин функционисања Манипулација се може испољити: намерним чињењем лако уочљивих изборних прекршаја; организовањем ситуација у којима ће прекршај бити снимљен или документован; лажним представљањем припадности другој изборној листи; координисаним медијским ширењем таквих снимака или информација; представљањем појединачних инсценираних случајева као доказа да „сви краду изборе“. Зашто је важно Овај механизам има за циљ да замени тезе и релативизује одговорност за изборне неправилности. Уместо расправе о конкретним и документованим злоупотребама, пажња јавности усмерава се на тврдњу да су све стране подједнако одговорне. Последица може бити слабљење поверења грађана у независну изборну контролу, умањење значаја документованих неправилности и стварање конфузије у јавном простору. Како препознати неправилности које су очигледно изведене тако да буду лако уочене и снимљене; несразмерно брзо медијско ширење материјала без утврђивања свих чињеница; појаву лица чији стварни политички ангажман није у складу са изборном листом коју формално представљају; понављање истог обрасца на више бирачких места. Како документовати идентитет и формални статус учесника; записнике бирачких одбора; оригиналне снимке и њихову временску линију; изјаве сведока; анализу начина и времена јавног објављивања спорног материјала. Правни оквир Може указивати на злоупотребу изборног поступка, лажно представљање, ометање рада изборних органа или друге повреде изборних прописа, у зависности од конкретних чињеница. Процена утицаја Средњи до висок, нарочито ако је праћена организованом медијском кампањом. Јачина доказа За доказивање ове неправилности није довољно само постојање снимка прекршаја. Неопходно је утврдити идентитет учесника, њихов стварни статус, околности под којима је прекршај настао и евентуалну координацију са другим лицима или политичким субјектима. Препоручена реакција У сваком случају документованог прекршаја потребно је утврдити све релевантне чињенице пре јавног приписивања одговорности. Посебну пажњу треба посветити провери идентитета учесника, њиховог формалног и стварног ангажмана у изборном поступку, као и околностима под којима је неправилност настала. ↑ Назад на преглед 7.2. Поступање када се уочи неправилност Члан бирачког одбора или посматрач треба да поступа мирно, прецизно и у оквиру својих овлашћења. Препоручени редослед је: непосредно уочити и описати радњу; забележити тачно време; упозорити председника и чланове одбора; захтевати отклањање неправилности; тражити да се догађај унесе у записник; сачувати доказе; обавестити надлежни изборни орган; обавестити полицију ако постоји насиље или сумња на кривично дело; не предузимати радње које сам посматрач или члан нема право да предузме. 7.3. Шта не сме да ради контролор или посматрач Контролор или посматрач не сме: одузимати лични документ; претресати бирача; одузимати телефон; брисати фотографије; употребљавати силу; самостално отварати изборни материјал; говорити бирачу за кога да гласа; јавно објављивати личне податке; ометати редован поступак; напустити место без обезбеђене замене ако је члан одбора; потписати записник који није прочитао. 7.4. Садржина квалитетне примедбе Добра примедба мора бити чињенична. Пример: У 12.40 часова члан бирачког одбора задужен за извод из бирачког списка издао је листић бирачу пре него што је бирач потписао извод. На пропуст су указала два члана одбора. Бирач је након упозорења потписао извод пре убацивања листића у кутију. Лош пример: Власт краде изборе и све је нерегуларно. Примедба треба да садржи: време; место; конкретну радњу; лице или функцију лица; реакцију одбора; начин отклањања или неотклањања; доказе; име члана који захтева унос. 7.5. Знаци организованог обрасца Неправилност на једном бирачком месту може указивати на шири образац када: исти поступак постоји на више места; користе се исти формулари; појављују се исти активисти; постоје идентична упутства; више одбора добија исти незаконит налог; неправилности су концентрисане у политички важним срединама; институције на сличне пријаве реагују исто или не реагују; постоји веза са паралелним списковима, превозом и страначким пунктовима. 7.6. Закључак поглавља Заштита бирачког места не значи стварање сукоба, већ доследно поштовање процедуре. Најважније гаранције су: правилна идентификација; један бирач — један глас; лично и тајно гласање; потпуно евидентирање; присуство овлашћених чланова; јавност и проверљивост рада; очување изборног материјала; благовремено бележење сваког одступања."},{"title":"BR — Манипулације током бројања гласова","url":"pages/br.html","text":"BR — Манипулације током бројања гласова АТЛАС изборних манипулација Ћир Lat Почетна / BR — бројање гласова BR Манипулације током бројања гласова Комплетан текст осмог поглавља Атласа изборних манипулација: 19 манипулација, правила безбедног бројања, контролна табела и поступање у случају неслагања. Изаберите фазу изборног процеса: PRE Пре избора KAM Током кампање BM На бирачком месту BR Током бројања POST Након избора 8.1. Зашто је бројање критична фаза Бројање гласова је тренутак у којем се појединачни гласачки листићи претварају у службени изборни резултат. Чак и ако је гласање током дана протекло уредно, неправилности током бројања могу изменити или довести у питање коначан исход. Ова фаза је посебно осетљива зато што се у кратком времену обавља велики број повезаних радњи: затварање бирачког места; утврђивање броја бирача који су гласали; пребројавање неискоришћених листића; отварање гласачке кутије; одвајање и разврставање листића; утврђивање важећих и неважећих гласова; пребројавање гласова по изборним листама или кандидатима; логичко-рачунска контрола; попуњавање записника; паковање материјала; потписивање и предаја записника и изборног материјала. Свака од ових радњи мора бити видљива, проверљива и колективно контролисана. Највећи ризици настају када: део чланова одбора није присутан; материјал није све време у видокругу; резултати се диктирају без заједничке провере; записник се попуњава пре бројања или накнадно; чланови потписују документ који нису прочитали; примедбе се не уносе; материјал се пакује пре него што се утврди потпуна сагласност података. Преглед BR манипулација BR-01 Неправилно затварање бирачког места BR-02 Удаљавање чланова бирачког одбора или посматрача пре бројања BR-03 Отварање гласачке кутије супротно процедури BR-04 Додавање гласачких листића током бројања BR-05 Уклањање или уништавање гласачких листића BR-06 Неосновано проглашавање важећих листића неважећим BR-07 Неосновано проглашавање неважећег листића важећим BR-08 Накнадно кварење важећих листића BR-09 Намерно неправилно и погрешно разврставање листића BR-10 Намерно нетачно пребројавање BR-11 Одбијање понoвног бројања у случају неслагања BR-12 Логичко-Рачунско неслагање резултата, броја бирача или броја листића BR-13 Нетачно попуњавање записника BR-14 Потписивање празног или непотпуног записника BR-15 Притисак да се потпише нетачан или непроверен записник BR-16 Онемогућавање уношења примедбе у записник BR-17 Ускраћивање копије записника BR-18 Неправилно паковање изборног материјала BR-19 Замена или измена материјала пре предаје BR-01 Неправилно затварање бирачког места Фаза Бројање гласова и утврђивање резултата Процена утицаја Средњи до висок, зависно од броја бирача којима је право ускраћено. Кључни докази забележити тачно време;; евидентирати број лица у реду;; забележити ко је наредио затварање;; унети примедбу у записник; Надлежни органи Бирачки одбор и надлежна изборна комисија; полиција и тужилаштво када чињенице указују на кривично дело. Повезане целине BM POST Кратка дефиниција Неправилно затварање постоји када се гласање заврши пре прописаног времена, када се не дозволи гласање лицима која су на време стигла или када се поступак бројања започне без формалног затварања. Могући облици врата се затварају пре времена; бирачима који чекају у реду не дозвољава се гласање; гласање се наставља после времена без законског основа; не утврђује се ко је затечен на бирачком месту у тренутку затварања; одмах се приступа отварању кутије без припремних радњи; неовлашћена лица остају у просторији; материјал се премешта пре утврђивања стања. Како документовати забележити тачно време; евидентирати број лица у реду; забележити ко је наредио затварање; унети примедбу у записник; сачувати сведочења бирача; обавестити изборну комисију ако је некоме ускраћено гласање. Процена утицаја Средњи до висок, зависно од броја бирача којима је право ускраћено. ↑ Назад на преглед BR-02 Удаљавање чланова бирачког одбора или посматрача пре бројања Фаза Бројање гласова и утврђивање резултата Процена утицаја Висок. Кључни докази Записник, службена белешка, изјаве присутних и законито прибављени материјали. Надлежни органи Бирачки одбор и надлежна изборна комисија; полиција и тужилаштво када чињенице указују на кривично дело. Повезане целине BM POST Кратка дефиниција Постоји када се овлашћени чланови бирачког одбора или акредитовани посматрачи без законског разлога удаље непосредно пре или током бројања. Могући циљеви смањење контроле; онемогућавање увида; несметано мењање резултата; спречавање уношења примедби; стварање фактичке већине; прикривање спорних листића. Показатељи изненадан захтев да поједини чланови напусте просторију; позивање на „недостатак места“; селективно удаљавање; закључавање просторије; забрана повратка; искључење посматрача управо у тренутку отварања кутије. Важно разграничење Посматрач или члан може бити удаљен ако озбиљно нарушава ред или омета поступак, али разлог мора бити конкретан, документован и једнако примењен. Процена утицаја Висок. ↑ Назад на преглед BR-03 Отварање гласачке кутије супротно процедури Фаза Бројање гласова и утврђивање резултата Процена утицаја Висок. Кључни докази стање кутије пре отварања;; стање печата;; присутна лица;; време отварања; Надлежни органи Бирачки одбор и надлежна изборна комисија; полиција и тужилаштво када чињенице указују на кривично дело. Повезане целине BM POST Кратка дефиниција Гласачка кутија се отвара пре завршетка припремних радњи, без присуства чланова одбора или на начин који онемогућава контролу. Сва релевантна лица морају имати могућност да виде отварање кутије и поступање са њеним садржајем. Ризичне ситуације кутија се отвара пре пребројавања неискоришћених листића; садржај се истреса ван видокруга; једно лице самостално рукује кутијом; печати или траке нису проверени; кутија се отвара у другој просторији; листићи се одмах деле у више гомила без заједничког увида. Документовање стање кутије пре отварања; стање печата; присутна лица; време отварања; место на које су листићи истресени; свака уочена неправилност. Процена утицаја Висок. ↑ Назад на преглед BR-04 Додавање гласачких листића током бројања Фаза Бројање гласова и утврђивање резултата Процена утицаја Висок или системски. Кључни докази непосредно сведочење;; видео-запис ако је законито настао;; логичко неслагање броја листића;; различито стање паковања; Надлежни органи Бирачки одбор и надлежна изборна комисија; полиција и тужилаштво када чињенице указују на кривично дело. Повезане целине BM POST Кратка дефиниција Постоји када се у материјал који се броји накнадно уносе листићи који нису били у гласачкој кутији у тренутку затварања. Могући механизми убацивање листића из џепа, торбе или фасцикле; додавање из резервног пакета; мешање са неискоришћеним листићима; замена једне гомиле другом; убацивање током гужве или расправе; уношење листића из друге просторије. Показатељи лице држи материјал ван заједничког стола; појављује се нова гомила; број листића нагло се мења; листићи су другачије пресавијени; папир има различиту боју или серију; члан одбора самостално прилази неискоришћеним листићима. Докази непосредно сведочење; видео-запис ако је законито настао; логичко неслагање броја листића; различито стање паковања; отисци, серијски подаци или друга форензичка обележја; примедба у записнику. Процена утицаја Висок или системски. ↑ Назад на преглед BR-05 Уклањање или уништавање гласачких листића Фаза Бројање гласова и утврђивање резултата Процена утицаја Висок. Кључни докази Записник, службена белешка, изјаве присутних и законито прибављени материјали. Надлежни органи Бирачки одбор и надлежна изборна комисија; полиција и тужилаштво када чињенице указују на кривично дело. Повезане целине BM POST Кратка дефиниција Постоји када се листићи издвајају, сакривају, уништавају или односе пре него што буду урачунати. Могући облици листићи падају испод стола и не враћају се; једно лице задржава део гомиле; листићи се проглашавају „непотребним“; одређена гомила се односи ван просторије; листићи се цепају; листићи се стављају у погрешан пакет. Показатељи број листића се смањује без објашњења; материјал није све време видљив; појављују се листићи у корпи; лице држи папире ван стола; спорни листићи се одмах пакују. Процена утицаја Висок. ↑ Назад на преглед BR-06 Неосновано проглашавање важећих листића неважећим Фаза Бројање гласова и утврђивање резултата Процена утицаја Висок, посебно код тесног резултата. Кључни докази број спорних листића;; опис начина означавања;; одлука одбора;; ко је гласао за коју одлуку; Надлежни органи Бирачки одбор и надлежна изборна комисија; полиција и тужилаштво када чињенице указују на кривично дело. Повезане целине BM POST Кратка дефиниција Листић који јасно изражава вољу бирача проглашава се неважећим како би се умањио број гласова одређеном изборном учеснику. Могући облици претерано формалистичко тумачење; листић се одбацује због небитне ознаке; различити стандарди примењују се на различите листе; листић се не показује свим члановима; председник самостално одлучује; спорни листићи се одмах одвајају без расправе. Основно правило Кључно је да ли се из листића може јасно и недвосмислено утврдити воља бирача. Документовање број спорних листића; опис начина означавања; одлука одбора; ко је гласао за коју одлуку; фотографија, ако је дозвољена и ако не угрожава тајност; примедба у записнику. Процена утицаја Висок, посебно код тесног резултата. ↑ Назад на преглед BR-07 Неосновано проглашавање неважећег листића важећим Фаза Бројање гласова и утврђивање резултата Процена утицаја Висок. Кључни докази Записник, службена белешка, изјаве присутних и законито прибављени материјали. Надлежни органи Бирачки одбор и надлежна изборна комисија; полиција и тужилаштво када чињенице указују на кривично дело. Повезане целине BM POST Кратка дефиниција Листић који не изражава јасну вољу или је попуњен супротно правилима урачунава се у корист одређене листе или кандидата. Могући облици листић има заокружено више опција; воља није јасна; листић није званичан; листић је празан, али се додаје глас; спорна ознака се произвољно тумачи; једна листа добија повлашћени стандард. Процена утицаја Висок. ↑ Назад на преглед BR-08 Накнадно кварење важећих листића Фаза Бројање гласова и утврђивање резултата Процена утицаја Висок или системски. Кључни докази непосредно посматрање;; упоредни изглед спорних листића;; форензичко испитивање мастила;; фотографија пре и после, ако постоји; Надлежни органи Бирачки одбор и надлежна изборна комисија; полиција и тужилаштво када чињенице указују на кривично дело. Повезане целине BM POST Кратка дефиниција Постоји када се на већ попуњен листић накнадно додаје ознака како би постао неважећи. Типичан механизам листић са јасним гласом добија додатни знак; дописује се број друге листе; прецртава се ознака; листић се цепа; додаје се потпис или порука; радња се предузима током разврставања. Показатељи исто мастило на више спорних листића; исти облик додатне ознаке; једно лице самостално прегледа листиће; велики број неважећих гласова једне листе; чланови нису видели првобитно стање. Докази непосредно посматрање; упоредни изглед спорних листића; форензичко испитивање мастила; фотографија пре и после, ако постоји; сведочење више чланова. Процена утицаја Висок или системски. ↑ Назад на преглед BR-09 Намерно неправилно и погрешно разврставање листића Фаза Бројање гласова и утврђивање резултата Процена утицаја Средњи до висок. Кључни докази Записник, службена белешка, изјаве присутних и законито прибављени материјали. Надлежни органи Бирачки одбор и надлежна изборна комисија; полиција и тужилаштво када чињенице указују на кривично дело. Повезане целине BM POST Кратка дефиниција Листићи се стављају у погрешне гомиле, чиме се гласови приписују другој изборној листи или се умањује број важећих гласова. Могући узроци журба; недовољна обука; слични називи листа; намерно премештање; недовољно простора; истовремено бројање више избора; мешање листића различитих боја или врста. Превентивне мере јасно означене гомиле; једна врста избора у једном тренутку; заједничка контрола; поновна провера сваке гомиле; без журбе и паралелних приватних пребројавања. Процена утицаја Средњи до висок. ↑ Назад на преглед BR-10 Намерно нетачно пребројавање Фаза Бројање гласова и утврђивање резултата Процена утицаја Висок. Кључни докази Записник, службена белешка, изјаве присутних и законито прибављени материјали. Надлежни органи Бирачки одбор и надлежна изборна комисија; полиција и тужилаштво када чињенице указују на кривично дело. Повезане целине BM POST Кратка дефиниција Постоји када се број гласова свесно увећава или умањује током пребројавања. Могући облици прескакање листића; двоструко бројање; погрешно диктирање; замена цифара; приписивање гласова погрешној листи; пребројавање само од стране једног лица; прихватање „округлог“ броја без стварне провере. Показатељи резултат се мења при сваком поновном бројању; једно лице диктира пребрзо; чланови не виде листиће; резултат се унапред уписује; одбија се контролно бројање; број гласова не одговара величини гомиле. Процена утицаја Висок. ↑ Назад на преглед BR-11 Одбијање понoвног бројања у случају неслагања Фаза Бројање гласова и утврђивање резултата Процена утицаја Висок ако се одбијање користи да прикрије грешку или злоупотребу. Кључни докази Записник, службена белешка, изјаве присутних и законито прибављени материјали. Надлежни органи Бирачки одбор и надлежна изборна комисија; полиција и тужилаштво када чињенице указују на кривично дело. Повезане целине BM POST Кратка дефиниција Када постоји очигледно неслагање или основана сумња, већина одбора одбија да поново преброји спорне гомиле. Када је поновно бројање оправдано резултати се не слажу; број листића није логички усаглашен; гомила је била ван надзора; члан је указао на погрешно разврставање; записани број не одговара пребројаном; постоји спор око важећих листића. Процена утицаја Висок ако се одбијање користи да прикрије грешку или злоупотребу. ↑ Назад на преглед BR-12 Логичко-Рачунско неслагање резултата, броја бирача или броја листића Фаза Бројање гласова и утврђивање резултата Процена утицаја Висок. Кључни докази Записник, службена белешка, изјаве присутних и законито прибављени материјали. Надлежни органи Бирачки одбор и надлежна изборна комисија; полиција и тужилаштво када чињенице указују на кривично дело. Повезане целине BM POST Кратка дефиниција Подаци у записнику нису међусобно математички или логички сагласни. Типична неслагања више листића у кутији него бирача који су гласали; збир важећих и неважећих не одговара броју листића у кутији; збир гласова листа не одговара броју важећих листића; број примљених, неискоришћених и употребљених листића није усаглашен; број потписа не одговара броју бирача који су гласали. Могући узроци грешка у сабирању; погрешно преписивање; издавање без потписа; вишак или мањак листића; додавање или уклањање листића; мешање материјала; намерна измена резултата. Правилно поступање Подаци се не смеју „прилагођавати“ да би се формулар слагао. Потребно је поново проверити изворне бројеве и тачно описати неотклоњено неслагање. Процена утицаја Висок. ↑ Назад на преглед BR-13 Нетачно попуњавање записника Фаза Бројање гласова и утврђивање резултата Процена утицаја Висок. Кључни докази Записник, службена белешка, изјаве присутних и законито прибављени материјали. Надлежни органи Бирачки одбор и надлежна изборна комисија; полиција и тужилаштво када чињенице указују на кривично дело. Повезане целине BM POST Кратка дефиниција У записник се уносе подаци који не одговарају стварно утврђеном стању. Могући облици погрешан број гласова; замењене колоне; изостављен број неважећих листића; нетачан број бирача; неунете примедбе; погрешно време затварања; уписивање података пре бројања; преписивање са незваничног папира без провере. Значај записника Записник је кључни службени документ на основу којег се резултат даље обрађује. Зато сваки члан мора проверити све бројеве пре потписивања. Процена утицаја Висок. ↑ Назад на преглед BR-14 Потписивање празног или непотпуног записника Фаза Бројање гласова и утврђивање резултата Процена утицаја Висок или системски. Кључни докази Записник, службена белешка, изјаве присутних и законито прибављени материјали. Надлежни органи Бирачки одбор и надлежна изборна комисија; полиција и тужилаштво када чињенице указују на кривично дело. Повезане целине BM POST Кратка дефиниција Чланови потписују записник пре него што су сви подаци унети или пре него што су резултати коначно утврђени. Зашто је опасно Празан потписани записник може бити накнадно попуњен без контроле потписника. Могући притисци „Само потпишите, касније ћемо унети.“ „Сви то раде.“ „Нема потребе да чекате.“ „Резултат је већ познат.“ „Комисија ће исправити бројеве.“ Правило поступања Нико не треба да потпише документ који није: у целини попуњен; прочитан; проверен; усаглашен са стварним резултатом; допуњен примедбама. Процена утицаја Висок или системски. ↑ Назад на преглед BR-15 Притисак да се потпише нетачан или непроверен записник Фаза Бројање гласова и утврђивање резултата Процена утицаја Висок. Кључни докази Записник, службена белешка, изјаве присутних и законито прибављени материјали. Надлежни органи Бирачки одбор и надлежна изборна комисија; полиција и тужилаштво када чињенице указују на кривично дело. Повезане целине BM POST Кратка дефиниција Члан се принуђава да својим потписом потврди резултат са којим се не слаже или који није проверио. Облици притиска претња смењивањем; вређање; физичко окруживање; страначки налог; претња губитком накнаде; ускраћивање копије; тврдња да потпис „ништа не значи“; онемогућавање уношења примедбе. Правилан поступак Члан треба да: одбије потписивање нетачног документа; захтева уношење примедбе; забележи разлог; обавести предлагача и надлежну комисију; сачува доказ о притиску; обавести полицију ако постоји претња или насиље. Процена утицаја Висок. ↑ Назад на преглед BR-16 Онемогућавање уношења примедбе у записник Фаза Бројање гласова и утврђивање резултата Процена утицаја Висок, јер се онемогућава каснија правна заштита. Кључни докази Записник, службена белешка, изјаве присутних и законито прибављени материјали. Надлежни органи Бирачки одбор и надлежна изборна комисија; полиција и тужилаштво када чињенице указују на кривично дело. Повезане целине BM POST Кратка дефиниција Члану бирачког одбора се не дозвољава да у записник унесе своје запажање о неправилности. Могући облици председник одбија да запише примедбу; тврди се да „нема места“; примедба се скраћује или мења; члану се не даје записник; записник се закључује пре примедбе; примедба се уписује на незваничан папир који се не пакује. Како поступити Члан треба да: јасно и гласно формулише примедбу; тражи да се наведе његово име; направи сопствену писану белешку; затражи сведочење других чланова; обавести изборну комисију; не потписује записник без напомене, ако тиме потврђује нетачно стање. Процена утицаја Висок, јер се онемогућава каснија правна заштита. ↑ Назад на преглед BR-17 Ускраћивање копије записника Фаза Бројање гласова и утврђивање резултата Процена утицаја Висок. Кључни докази захтев за копију;; време одбијања;; лице које је одбило;; фотографија записника ако је дозвољена; Надлежни органи Бирачки одбор и надлежна изборна комисија; полиција и тужилаштво када чињенице указују на кривично дело. Повезане целине BM POST Кратка дефиниција Овлашћеном члану или представнику не доставља се копија записника, или се даје копија која није читљива, потпуна или истоветна оригиналу. Ризици онемогућавање паралелне контроле; накнадна промена оригинала; немогућност поређења са објављеним резултатом; слабљење доказне позиције у приговору. Како документовати захтев за копију; време одбијања; лице које је одбило; фотографија записника ако је дозвољена; сведоци; примедба у записнику; обавештење изборној комисији. Процена утицаја Висок. ↑ Назад на преглед BR-18 Неправилно паковање изборног материјала Фаза Бројање гласова и утврђивање резултата Процена утицаја Висок. Кључни докази Записник, службена белешка, изјаве присутних и законито прибављени материјали. Надлежни органи Бирачки одбор и надлежна изборна комисија; полиција и тужилаштво када чињенице указују на кривично дело. Повезане целине BM POST Кратка дефиниција Изборни материјал се пакује, означава или затвара супротно прописаној процедури. Могући облици важећи и неважећи листићи нису одвојени; неискоришћени листићи нису посебно запаковани; извод из бирачког списка није обезбеђен; записник се ставља у погрешну врећу; врећа није затворен; нема потписа или затворнице; материјал различитих избора се меша; кључни документ остаје ван вреће; вреће нису означене. Зашто је важно Правилно паковање обезбеђује: интегритет материјала; могућност касније контроле; утврђивање ланца чувања; спречавање замене; поуздан увид и поновно бројање. Процена утицаја Висок. ↑ Назад на преглед BR-19 Замена или измена материјала пре предаје Фаза Бројање гласова и утврђивање резултата Процена утицаја Висок или системски. Кључни докази фотографија затворених врећа;; број и ознака сваке вреће;; време затварања;; лица која су преузела материјал; Надлежни органи Бирачки одбор и надлежна изборна комисија; полиција и тужилаштво када чињенице указују на кривично дело. Повезане целине BM POST Кратка дефиниција Након што је резултат утврђен, али пре него што је материјал предат надлежној комисији, изборни материјал или његови поједини делови замењују се, преправљају или уклањају. Могући механизми замена оригиналног записника; преправљање бројева; замена коверте са листићима; убацивање друге вреће уместо оригиналне; уклањање примедбе; додавање потписа; отварање већ затворене вреће; остављање материјала без надзора; транспорт приватним возилом без контроле. Показатељи врећа се поново отвара; мења се лице задужено за транспорт; материјал нестаје из видокруга; оригинал и копија записника се разликују; траке или печати су оштећени; број вреће не одговара примопредајној листи; појављује се нова верзија записника. Документовање фотографија затворених врећа; број и ознака сваке вреће; време затварања; лица која су преузела материјал; возило; време поласка и доласка; копија записника; стање затворница при предаји; примопредајни документ. Процена утицаја Висок или системски. ↑ Назад на преглед 8.2. Основни принципи безбедног бројања Да би бројање било поуздано, потребно је обезбедити: Потпуну видљивост Сви листићи и сви кораци морају бити видљиви присутним члановима и посматрачима. Не треба дозволити: бројање у углу; одвојене столове без контроле; одношење гомила у другу просторију; држање материјала испод стола; приватно пребројавање од стране једног лица. Колективну контролу Ниједан члан не треба сам да: отвара кутију; разврстава све листиће; одлучује о неважећим гласовима; диктира коначни резултат; попуњава записник без провере; пакује материјал. Редослед радњи Поступак мора бити вођен јасним редом. Прескакање корака повећава могућност грешке и злоупотребе. Поновну проверу Поновна провера није израз неповерења, већ нормалан механизам контроле. Обавезно треба проверити: укупан број листића; сваку гомилу; спорне листиће; збир гласова; логичко слагање; бројеве у записнику; копије пре потписивања. 8.3. Како се процењује значај неправилности Није свака грешка током бројања једнако озбиљна. При процени треба узети у обзир: број спорних листића; разлику између изборних учесника; да ли је неправилност отклоњена; да ли је поступање било намерно; да ли се понавља; да ли је материјал сачуван; да ли је примедба унета; да ли постоји копија записника; да ли се исти образац јавља на више места. На пример, грешка од једног гласа може бити одлучујућа ако је разлика између изборних листа један или два гласа. Са друге стране, математичка грешка која је одмах исправљена пред свим члановима не мора указивати на манипулацију. 8.4. Модел контролне табеле за бројање Оваква табела не замењује службени записник, али помаже члану одбора да независно провери поступак. Контролна тачка Утврђено стање Неслагање Предузета радња Примљени листићи Неискоришћени листићи Број потписаних бирача Листићи у кутији Важећи листићи Неважећи листићи Збир гласова листа Број спорних листића Унете примедбе Да ли је копија записника преузета 8.5. Најчешће опасне реченице током бројања Следеће формулације треба схватити као упозорење: „Не морамо поново да бројимо.“ „Зна се отприлике колико има.“ „Комисија ће то касније исправити.“ „Потпишите сада, бројеве ћемо унети.“ „Не уписуј примедбу, само ћемо закомпликовати.“ „Та два гласа нису битна.“ „Ставите број који се уклапа.“ „Нема потребе да сви гледају.“ „Ова гомила је већ пребројана.“ „Немамо времена за контролу.“ Свака од ових реченица указује на покушај да се процедура замени неформалним договором. 8.6. Поступање члана одбора у случају неслагања Када члан уочи неслагање, треба да: јасно наведе шта се не слаже; затражи заустављање следеће радње; захтева поновно бројање; тражи да сви спорни листићи буду показани; направи сопствену белешку; захтева унос примедбе; не потписује нетачан записник; преузме или документује копију; обавести надлежну изборну комисију; обавести полицију или тужилаштво ако постоји сумња на намерно додавање, уклањање или фалсификовање. 8.7. Разлика између исправке и преправљања резултата Законита исправка Законита исправка постоји када се: открије очигледна грешка; поново провере изворни подаци; исправка изврши пред члановима; јасно види шта је било погрешно; сви релевантни чланови буду обавештени; исправка буде потписана или евидентирана у складу са процедуром; стварни резултат не буде произвољно мењан. Незаконито преправљање Сумњиво или незаконито поступање постоји када се: број мења без поновног бројања; исправка врши након потписивања; чланови нису присутни; оригинал се замењује; податак прилагођава очекиваном резултату; примедба уклања; исправка прикрива. 8.8. Повезаност са постизборним манипулацијама Манипулација започета током бројања може се наставити после напуштања бирачког места. Типичан низ може бити: нетачно пребројавање; унос нетачног броја у записник; потписивање под притиском; ускраћивање копије; замена записника током транспорта; унос другачијег резултата у информациони систем; одбијање приговора; онемогућавање увида. Зато су копија записника, забележено стање пакета и континуирани надзор материјала пресудни за каснију контролу. 8.9. Закључак поглавља Бројање није техничка формалност. Оно је правно и политички једнако важно као и само гласање. Поуздан резултат захтева: присуство свих овлашћених актера; потпуну видљивост материјала; јасан редослед радњи; једнаке критеријуме за важеће листиће; поновну проверу; математичку сагласност; тачан записник; право на примедбу; копију резултата; ← BM — бирачко место POST — после изборног дана →"},{"title":"Дневник члана бирачког одбора или посматрача — Атлас изборних манипулација","url":"pages/dnevnik-izbornog-dana.html","text":"Дневник члана бирачког одбора или посматрача — Атлас изборних манипулација АТЛАС изборних манипулација Ћир Lat Почетна / Практични обрасци / Дневник члана бирачког одбора или посматрача Практични обрасци Дневник члана бирачког одбора или посматрача Хронолошка евиденција важних догађаја, реакција и расположивих доказа. Практични обрасци Захтев за увид у изборни материјал Приговор изборној комисији Службена белешка о уоченој неправилности Записник о уоченој неправилности Контролна листа за изборни дан Дневник члана бирачког одбора или посматрача Како документовати изборну неправилност ↑ На врх Сврха: Помоћни практични алат за учеснике у изборном поступку. Правна природа: Пример који се прилагођава конкретном случају и важећем изборном законодавству; није законом прописан формулар. Намена: Чланови бирачких одбора, посматрачи, овлашћени представници изборних листа и друга овлашћена лица. Када се користи Дневник је лична хронолошка евиденција важних догађаја током изборног дана. Није службени документ, али помаже да се касније прецизно сачине белешка, записник или приговор. Предложени текст ДНЕВНИК ИЗБОРНОГ ДАНА Избори: ___________________________________ Бирачко место: ___________________________ Општина / град: __________________________ Лице и својство: __________________________ Време: ________ Догађај / радња: ______________________________ Присутна лица: ____________________________ Реакција и предузете радње: ________________ Повезани доказ / белешка: ___________________ Време: ________ Догађај / радња: ______________________________ Присутна лица: ____________________________ Реакција и предузете радње: ________________ Повезани доказ / белешка: ___________________ Наставити по потреби. Практични савети Уносите кратке белешке одмах, са временом. Не бележите непотребне личне податке бирача. Повежите сваки важнији унос са фотографијом, белешком или другим доказом. Ако неправилности није било, забележите и важне редовне радње — то олакшава потпуну реконструкцију дана. ← Контролна листа за изборни дан Сви практични обрасци Како документовати изборну неправилност →"},{"title":"Како документовати изборну неправилност — Атлас изборних манипулација","url":"pages/dokumentovanje-nepravilnosti.html","text":"Како документовати изборну неправилност — Атлас изборних манипулација АТЛАС изборних манипулација Ћир Lat Почетна / Практични обрасци / Како документовати изборну неправилност Практични обрасци Како документовати изборну неправилност Кратко завршно упутство које повезује обрасце и објашњава редослед поступања. Практични обрасци Захтев за увид у изборни материјал Приговор изборној комисији Службена белешка о уоченој неправилности Записник о уоченој неправилности Контролна листа за изборни дан Дневник члана бирачког одбора или посматрача Како документовати изборну неправилност ↑ На врх Сврха: Помоћни практични алат за учеснике у изборном поступку. Правна природа: Пример који се прилагођава конкретном случају и важећем изборном законодавству; није законом прописан формулар. Намена: Чланови бирачких одбора, посматрачи, овлашћени представници изборних листа и друга овлашћена лица. Основна правила Реагујте одмах. Забележите време, место и основне околности док су чињенице свеже. Записујте чињенице, не закључке. Опишите радњу; правну оцену препустите надлежном органу. Наведите присутна лица. Забележите сведоке и лица којима је догађај пријављен, без непотребног прикупљања личних података. Повежите доказ са догађајем. Означите шта фотографија, снимак или документ приказује и када је настао. Чувајте оригинале. Не преправљајте снимке и белешке; направите резервну копију. Тражите унос примедбе. Када за то постоји основ, затражите да примедба буде унета у службену изборну документацију. Поштујте рокове. Добар доказ не може надокнадити неблаговремено правно средство. Чувајте доказ о предаји. Задржите копију сваког поднеска и потврду о времену пријема. Препоручени редослед поступања забележити догађај у дневнику; сачинити службену белешку; прикупити и означити доступне доказе; затражити отклањање неправилности и, по потреби, унос примедбе; сачинити записник о уоченој неправилности; проверити надлежност, овлашћење и рок; поднети приговор или други одговарајући акт; по потреби затражити увид у изборни материјал. Важно: Ови примери не замењују правни савет, важеће прописе нити упутства надлежних изборних органа. У сваком конкретном случају проверите актуелни законски основ, рок, овлашћеног подносиоца и надлежни орган. ← Дневник члана бирачког одбора или посматрача Сви практични обрасци"},{"title":"Изборна форензика — Атлас изборних манипулација","url":"pages/izborna-forenzika.html","text":"Изборна форензика — Атлас изборних манипулација АТЛАС изборних манипулација Ћир Lat Почетна / Изборна форензика Поглавље 12 Изборна форензика Практична правила за утврђивање, документовање, анализу и чување чињеница значајних за оцену законитости изборног процеса. 12 главних целина пуни текст поглавља практична упутства Садржај поглавља 12.1. Појам изборне форензике 12.2. Основна правила документовања 12.3. Правило непосредности 12.4. Правило објективности 12.5. Ланац чувања доказа (Chain of Custody) 12.6. Законито документовање догађаја на бирачком месту 12.7. Евидентирање примедбе 12.8. Белешке контролора 12.9. Поступање када постоји сумња на фотографисање гласачког листића 12.10. Забрањено самостално „обезбеђивање доказа“ 12.11. Законито фотографисање ван просторије за гласање 12.12. Евиденција телефонских и електронских пријава ↑ На врх Изборна форензика не служи доношењу преурањених закључака, већ стварању проверљивог и законито прибављеног чињеничног трага. 12.1. Појам изборне форензике Изборна форензика представља скуп метода и поступака којима се утврђују, документују, анализирају и чувају чињенице од значаја за оцену законитости изборног процеса. За разлику од кривичне форензике, чији је циљ откривање извршиоца кривичног дела, изборна форензика има за циљ утврђивање чињеничног стања изборног процеса и обезбеђивање поузданих доказа који могу бити употребљени у поступцима пред изборним органима, судовима или другим надлежним институцијама. Основни принцип изборне форензике гласи: Не претпостављај — документуј. Не тумачи — забележи. Не закључуј — обезбеди доказ. Контролор и посматрач нису овлашћени да утврђују кривицу, већ да прикупљају чињенице на начин који омогућава њихову каснију проверу. 12.2. Основна правила документовања Свако документовање неправилности треба да буде засновано на пет основних питања: Шта? Која је неправилност уочена? Где? На ком бирачком месту? У ком делу просторије? Када? Тачно време. По могућности у сатима, минутима и секундама. Ко? Ко је учествовао? Ко је присуствовао? Ко је видео догађај? Како? Како је неправилност настала? Како је уочена? Како је документована? 12.3. Правило непосредности Највећу доказну вредност имају докази који су настали непосредно током догађаја. Редослед доказне снаге је, по правилу: службени записник; оригинална фотографија; оригинални видео-снимак; оригинални документ; сведочење непосредног очевица; накнадно сачињена белешка; посредно сведочење. У пракси је често неопходно комбиновати више врста доказа ради потпуније реконструкције догађаја. 12.4. Правило објективности Једна од најчешћих грешака контролора јесте да у записнику уместо чињеница уноси своје закључке. На пример: ❌ „Извршена је изборна крађа.\" То није чињеница. Правилан опис гласи: ✓ „Лице је фотографисало гласачки листић након попуњавања.\" ✓ „Два лица су истовремено ушла иза паравана.\" ✓ „Бирачки одбор није дозволио унос примедбе у записник.\" Таквим описом избегава се субјективност и омогућава се да надлежни орган сам оцени правни значај утврђених чињеница. 12.5. Ланац чувања доказа (Chain of Custody) Сваком доказу потребно је обезбедити документован пут од тренутка настанка до његовог достављања надлежном органу. Евиденција треба да садржи: назив доказа; датум и време настанка; место настанка; лице које је доказ прибавило; начин прибављања; лице коме је доказ предат; време предаје; начин чувања. Недокументован прекид у ланцу чувања може умањити доказну вредност материјала. 12.6. Законито документовање догађаја на бирачком месту 12.6.1. Основно правило Документовање неправилности не сме само по себи представљати повреду изборних правила. Контролор, члан бирачког одбора или посматрач не сме да: неовлашћено фотографише или снима дешавања на бирачком месту; снима бирача док попуњава гласачки листић; снима садржину попуњеног гласачког листића; снима податке о бирачима из извода из бирачког списка; снима или преноси податке о томе ко је гласао, а ко није; употребом телефона омета гласање или рад бирачког одбора; документовањем наруши тајност гласања или заштиту података о личности. Закон о избору народних посланика предвиђа да се ред на бирачком месту сматра нарушеним, између осталог, када се неовлашћено снимају и фотографишу дешавања на бирачком месту, када се средствима везе неовлашћено преносе обавештења о излазности конкретних лица или када се ван службене евиденције праве спискови лица која су гласала или нису гласала. Оперативно правило Унутар бирачког места контролор треба да се ослања првенствено на непосредну белешку, захтев да се неправилност отклони, захтев да се примедба унесе у записник и обавештавање надлежног координатора или правног тима. 12.6.2. Шта контролор треба да забележи Када уочи неправилност, контролор треба без одлагања да сачини хронолошку белешку која садржи: број и адресу бирачког места; датум и тачно време; место у просторији на којем се догађај одиграо; чињенични опис радње; функцију лица које је учествовало у догађају; имена присутних чланова бирачког одбора, ако су позната; реакцију председника бирачког одбора; реакцију осталих чланова; захтев који је контролор упутио; одговор или одлуку бирачког одбора; да ли је радња престала или је настављена; да ли је примедба унета у записник; имена других непосредних сведока; време када је обавештен координатор или правни тим. Белешка се сачињава чињенично, без квалификација о кривици или намери. Не треба писати: Председник бирачког одбора је намерно дозволио крађу избора. Треба писати: У 10.42 часа два бирача су се истовремено налазила иза истог паравана. Члан бирачког одбора А. Б. упозорио је председника одбора. Председник није прекинуо радњу. Бирачи су потом гласачке листиће убацили у кутију. 12.6.3. Захтев за отклањање неправилности Контролор који је члан бирачког одбора не треба да остане само пасивни посматрач. Када уочи неправилност, треба да: мирно и јасно укаже председнику бирачког одбора на конкретну радњу; затражи да се неправилност одмах прекине или отклони; затражи да бирачки одбор о питању одлучи ако постоји несагласност; захтева да се његова примедба и одлука одбора евидентирају; забележи ко је гласао за предложену меру, а ко против, када је то могуће и правно релевантно; обавести надлежног координатора ако неправилност није отклоњена. Контролор не сме физички спречавати бирача, одузимати телефон, додиривати гласачки листић или самостално удаљавати лице са бирачког места. Одржавање реда је обавеза бирачког одбора, који може прекинути гласање док се ред не успостави. 12.7. Евидентирање примедбе 12.7.1. Значај примедбе Усмено указивање на неправилност важно је ради њеног непосредног отклањања, али само по себи често није довољно за каснију правну заштиту. Због тога контролор треба да настоји да: неправилност буде унета у одговарајућу службену документацију; опис садржи време, радњу и реакцију бирачког одбора; се избегавају неодређене формулације; се забележи ако је унос примедбе одбијен; примедба буде достављена правном тиму без одлагања. 12.7.2. Садржина добре примедбе Добра примедба треба да садржи: Чињеницу: шта је непосредно уочено. Време: када се догодило. Лице или функцију: ко је поступао. Реакцију: шта је предузео бирачки одбор. Последицу: да ли је неправилност отклоњена. Захтев: шта је члан одбора тражио. Пример: У 12.18 часова бирач је након попуњавања гласачког листића употребио мобилни телефон иза паравана. Није било могуће утврдити шта је приказано на екрану телефона. Члан бирачког одбора ______ одмах је обавестио председника и затражио да се бирач упозори да употреба телефона не сме угрозити тајност гласања и ред на бирачком месту. Председник је бирача упозорио, након чега је телефон склоњен. Ова формулација не тврди да је листић фотографисан ако то није непосредно и поуздано утврђено. 12.8. Белешке контролора Белешке треба водити током читавог изборног дана. Свака белешка треба да садржи: време; место; кратак опис; број фотографије; број видео-снимка; евентуалне сведоке. Белешке написане непосредно након догађаја имају већу поузданост од накнадних реконструкција. Разликовање опажања, информације и закључка За доказну поузданост неопходно је раздвојити три категорије. Непосредно опажање Контролор је лично видео или чуо догађај. Пример: Видео сам да је лице држало телефон изнад попуњеног гласачког листића. Информација другог лица Контролор није видео догађај, већ му га је неко пријавио. Пример: Бирач који се представио као ______ изјавио је да му је испред бирачког места нуђена новчана накнада. Закључак или сумња Закључак се изводи из једне или више чињеница, али није непосредно опажање. Пример: Положај телефона и попуњеног листића изазвао је сумњу да је листић фотографисан, али садржај екрана није виђен. Ове категорије се не смеју представљати као једнако сигурне. 12.9. Поступање када постоји сумња на фотографисање гласачког листића Контролор треба да поступа следећим редом: Не покушава да види за кога је бирач гласао. Не улази иза паравана. Не одузима телефон. Не захтева да му бирач покаже галерију или садржину телефона. Обавештава председника бирачког одбора о конкретно уоченој радњи. Захтева да председник предузме мере ради очувања реда и тајности гласања. Бележи тачно време и реакцију одбора. Захтева евидентирање примедбе. Обавештава координатора или правни тим. Одвојено бележи евентуалне повезане околности, али их не представља као доказане чињенице. Само држање телефона не доказује да је гласачки листић фотографисан. Чак ни утврђено фотографисање листића, посматрано изоловано, не доказује аутоматски куповину гласа. За такву оцену били би потребни додатни, међусобно повезани докази. 12.10. Забрањено самостално „обезбеђивање доказа“ Контролор не сме да: претреса лице или његове ствари; одузима мобилни телефон; прегледа приватне поруке или фотографије; захтева откључавање уређаја; задржава бирача против његове воље; физички блокира излаз; одузима или издваја гласачки листић без одлуке и прописане процедуре; самостално отвара гласачку кутију; самостално отвара или препакује изборни материјал; објављује личне податке бирача; снима извод из бирачког списка. Основно правило Контролор обезбеђује доказ тако што прецизно бележи чињенице и активира прописану процедуру, а не тако што преузима овлашћења полиције, тужилаштва, суда или изборног органа. 12.11. Законито фотографисање ван просторије за гласање Фотографисање ван просторије за гласање такође мора бити опрезно и законито. Чињеница да се нека радња одвија испред зграде не значи да је свако снимање аутоматски дозвољено или сврсисходно. Пре снимања треба проценити: да ли се снима јавни простор; да ли се бележи општа ситуација или се циљано прати конкретан бирач; да ли се снимају лични документи или други лични подаци; да ли снимак може открити политичко опредељење лица; да ли се ометају бирачи; да ли је могуће исту чињеницу документовати мање инвазивним средством; да ли постоји безбедносни ризик. Чак и када је снимање могуће, оригинални запис не треба јавно објављивати пре него што га прегледа правни тим. Сврха доказног материјала је правна заштита, а не тренутно објављивање на друштвеним мрежама. 12.12. Евиденција телефонских и електронских пријава Када контролни центар прими пријаву, оператор треба да забележи: јединствени број пријаве; датум и време пријема; идентитет пријавиоца, ако је познат; његову улогу; број бирачког места; да ли је догађај лично видео; шта је тачно видео или чуо; када се догађај одиграо; да ли и даље траје; које су мере већ предузете; да ли постоје други сведоци; да ли је примедба унета у записник; коме је случај прослеђен; време прослеђивања; исход поступања. Оператор не треба да сугерише пријавиоцу шта „мора да се догодило“, већ да поставља неутрална питања. Добро питање: Шта сте лично видели? Лоше питање: Да ли су покушали да украду гласове? ← Студије случаја Почетна →"},{"title":"KAM — Манипулације током изборне кампање","url":"pages/kam.html","text":"KAM — Манипулације током изборне кампање АТЛАС изборних манипулација Ћир Lat Почетна / KAM — изборна кампања KAM Манипулације током изборне кампање Комплетан текст шестог поглавља Атласа изборних манипулација: дванаест кампањских манипулација, повезани механизми, процена системског карактера, контролна питања и закључак. Изаберите фазу изборног процеса: PRE Пре избора KAM Током кампање BM На бирачком месту BR Током бројања POST Након избора 6.1. Значај изборне кампање Изборна кампања није само период у којем политички субјекти представљају програме и кандидате. То је фаза у којој бирачи формирају или учвршћују политичке ставове, а изборни учесници покушавају да придобију подршку. Да би избори били слободни и равноправни, кампања мора да се одвија у условима у којима: политички учесници имају стварну могућност да представе програм државни органи и јавни ресурси не служе једном изборном актеру медији не прикривају политичку пропаганду као независно информисање запослени и корисници јавних услуга нису изложени притиску гласачка подршка се не купује подаци о грађанима не користе се за контролу политичког понашања трошкови кампање и извори финансирања могу бити проверени. Манипулације током кампање ретко су потпуно одвојене једна од друге. Функционерска кампања може бити повезана са злоупотребом јавних ресурса, медијском доминацијом и јавним давањима. Паралелни спискови могу бити повезани са капиларним гласовима, притиском на запослене и контролом излазности. Због тога је неопходно посматрати не само појединачну радњу већ и шири механизам у којем се она јавља. Преглед KAM манипулација KAM-01 Функционерска кампања KAM-02 Злоупотреба јавних ресурса KAM-03 Куповина гласова KAM-04 Политички притисак, претња и уцена KAM-05 Капиларни гласови и систем „сигурних гласова“ KAM-06 Паралелни бирачки спискови KAM-07 Неравноправна медијска заступљеност KAM-08 Прикривено политичко оглашавање KAM-09 Дезинформације и координисано обмањивање бирача KAM-10 Застрашивање политичких противника, активиста и посматрача KAM-11 Злоупотреба јавних установа, институција и јавних догађаја KAM-12 Нетранспарентно и незаконито финансирање кампање KAM-01 Функционерска кампања Фаза Изборна кампања Процена утицаја Висок или системски, нарочито када се јавља током целе кампање и прати га медијска доминација. Кључни докази Треба сачувати:; снимак целог догађаја; службену најаву Надлежни органи Агенција за спречавање корупције; надлежно регулаторно тело за медије; изборне комисије у оквиру својих надлежности Повезане манипулације KAM-02 KAM-07 KAM-08 KAM-12 Кратка дефиниција Функционерска кампања постоји када носилац јавне функције користи службени положај, институционалну видљивост или јавне активности ради стицања изборне предности за политички субјект којем припада или који подржава. Заштићена вредност равноправност изборних учесника раздвојеност државе и политичке странке неутралност јавних институција слободно информисање бирача законито коришћење јавних средстава. Како функционише Јавни функционер током кампање наставља да обавља службене послове, али се ти послови организују и представљају тако да постану средство политичке промоције. Могући облици су учестала отварања објеката обилазак радова који су већ раније започети посете школама, болницама, вртићима и предузећима додела опреме, кључева, помоћи или уговора пред камерама ванредно велики број службених догађаја представљање јавне инвестиције као личне заслуге функционера истицање страначких порука током службене активности преношење службеног догађаја у страначким медијима као дела кампање укључивање кандидата који нема службену улогу. Како је препознати Показатељи могу бити: нагло повећање броја службених догађаја пред изборе присуство страначких обележја изборни слоган на службеном догађају позивање грађана да подрже одређену листу представљање јавног новца као поклона функционера медијско извештавање које не раздваја службену и страначку улогу обавезно присуство запослених присуство страначких активиста у организацији догађаја емитовање страначког спота снимљеног током службене посете. Правна оцена Није свака службена активност јавног функционера током кампање незаконита. Државни и локални послови не престају због избора. Потребно је испитати: да ли је активност редовна или ванредно организована да ли је време одржавања изборно мотивисано ко је финансирао догађај да ли су коришћене страначке поруке да ли је функционер наступао као носилац функције или кандидат да ли су медији јасно раздвојили те улоге да ли су други изборни учесници имали упоредиву могућност представљања. Документовање Треба сачувати: снимак целог догађаја службену најаву страначку најаву медијске прилоге фотографије обележја податке о финансирању списак присутних функционера и кандидата доказ о обавезном присуству запослених упоредне податке о броју службених активности пре и током кампање. Надлежне институције Агенција за спречавање корупције надлежно регулаторно тело за медије изборне комисије у оквиру својих надлежности буџетска инспекција полиција и тужилаштво ако постоје елементи кривичног дела суд. Процена утицаја Висок или системски, нарочито када се јавља током целе кампање и прати га медијска доминација. Шта не треба радити Не треба сваку фотографију функционера или обављање редовне службене дужности аутоматски означавати као злоупотребу. Потребно је описати конкретно мешање јавне функције и изборне промоције. ↑ Назад на преглед KAM-02 Злоупотреба јавних ресурса Фаза Изборна кампања Процена утицаја Системски, јер јавни ресурси могу створити предност коју конкуренти не могу финансијски или организационо достићи. Кључни докази регистарске ознаке службених возила; фотографије и снимци; налози руководилаца Надлежни органи Надлежност зависи од конкретног облика манипулације. Повезане манипулације KAM-01 KAM-07 KAM-08 KAM-12 Кратка дефиниција Злоупотреба јавних ресурса постоји када се јавни новац, имовина, опрема, подаци, запослени или службена овлашћења користе у корист политичког субјекта. Шта се сматра јавним ресурсом буџетска средства службена возила гориво јавне просторије рачунари и телефони службени имејл базе података опрема јавних установа запослени у јавном сектору службено радно време јавна предузећа медији финансирани јавним новцем службени налози на друштвеним мрежама. Начини злоупотребе превоз активиста службеним возилима штампање страначког материјала у јавној установи коришћење запослених током радног времена слање политичких порука са службене адресе коришћење базе корисника јавне услуге бесплатан или повлашћен закуп јавног простора буџетско финансирање догађаја који има страначку сврху ангажовање јавног предузећа у организацији скупа коришћење службених налога за промоцију листе плаћање огласа који формално промовише институцију, а стварно политичког актера. Показатељи службена возила испред страначког скупа запослени на страначкој активности у радно време исти визуелни идентитет јавне кампање и изборне листе службена база корисника употребљена за позиве јавна установа шаље страначке поруке јавни простор једном учеснику дат бесплатно, а другом није трошак кампање не постоји у извештају политичког субјекта јавни службеник добија налог за страначки рад. Документовање регистарске ознаке службених возила фотографије и снимци налози руководилаца службена преписка евиденција радног времена уговори о закупу рачуни одлуке о коришћењу простора извештаји о трошковима кампање сведочења запослених. Процена утицаја Системски, јер јавни ресурси могу створити предност коју конкуренти не могу финансијски или организационо достићи. Хитна реакција Доказе треба сачувати пре него што буду уклоњени. Код службених возила и јавних догађаја потребно је забележити тачно време, место и сврху употребе. ↑ Назад на преглед KAM-03 Куповина гласова Фаза Изборна кампања Процена утицаја Висок или системски. Кључни докази Начин доказивања је описан у тексту. Надлежни органи полиција; јавно тужилаштво; изборна комисија, ако догађај утиче на поступак гласања Повезане манипулације KAM-06 Кратка дефиниција Куповина гласова постоји када се бирачу нуди, даје или обећава новац, роба, услуга или друга корист да гласа, не гласа или гласа за одређеног изборног учесника. Облици користи готов новац пакети хране огрев лекови плаћање рачуна допуна телефона посао или продужење уговора опрост дуга бесплатан превоз условљен гласањем пољопривредни материјал грађевински материјал услуга јавне институције новчана накнада после гласања. Како механизам функционише посредници идентификују економски угрожене или зависне бираче договара се корист бирачу се даје упутство тражи се доказ или потврда гласања прати се излазност награда се исплаћује пре или после избора. Доказ начина гласања може бити фотографија листића унапред обележени листић изношење празног листића посебна ознака сведочење посредника праћење изласка на бирачко место. Показатељи подела новца или пакета уочи избора спискови са износима велики број кратких исплата пунктови у близини бирачких места бирачи показују фотографију телефона посредници контролишу долазак исти људи довозе и исплаћују бираче пакети се деле само политички опредељеним лицима корист се условљава гласањем. Доказни стандард Није свака подела помоћи куповина гласа. Потребно је утврдити везу између користи и изборног понашања. Највреднији докази су: директна порука или снимак понуде сведочење примаоца обележена евиденција исплата новац са упутствима више сагласних сведочења веза са фотографисањем листића лице затечено у исплати организован систем посредника. Надлежне институције полиција јавно тужилаштво изборна комисија, ако догађај утиче на поступак гласања Агенција за спречавање корупције Повереник, ако су коришћени лични подаци суд. Процена утицаја Висок или системски. Хитна реакција Када је исплата у току, треба обавестити полицију. Не треба самостално одузимати новац, претресати лица или изазивати сукоб. Шта не треба радити објављивати име примаоца без сагласности обећавати имунитет од одговорности подстицати бирача да настави радњу ради „бољег снимка“ фабриковати или режирати доказ закључивати само на основу поделе социјалне помоћи. ↑ Назад на преглед KAM-04 Политички притисак, претња и уцена Фаза Изборна кампања Процена утицаја Системски када се спроводи преко институција, јавних предузећа или организоване страначке хијерархије. Кључни докази поруке; имејлови; аудио-снимци ако су законито настали Надлежни органи Надлежност зависи од конкретног облика манипулације. Повезане манипулације KAM-05 KAM-06 Кратка дефиниција Политички притисак постоји када се лице доводи у положај да страхује од штетне последице ако не подржи одређеног политичког учесника. Обухвата претњу губитком посла, прихода, услуге, права или друге користи ако лице не подржи одређеног изборног учесника. Могући облици претња отказом непродужавање уговора губитак социјалне помоћи ускраћивање здравствене или административне услуге губитак субвенције инспекцијска контрола као средство одмазде притисак на чланове породице претња премештајем јавна дискредитација условљавање школског, пословног или стамбеног статуса претња физичким насиљем. Директан и посредан притисак Директан притисак садржи јасну претњу. Посредан притисак може бити изражен реченицама: „Знаш од кога ти зависи уговор.“ „Видећемо ко је био на списку.“ „Немој после да се жалиш.“ „Свако мора да доведе своје људе.“ „Очекује се да сви из колектива дођу.“ Иако не садрже изричиту претњу, контекст може показати да лице реално страхује од последице. Документовање поруке имејлови аудио-снимци ако су законито настали сведочења спискови квота доказ о последици након одбијања решења о отказу или премештају упоредни третман других запослених медицинска документација ако је притисак изазвао здравствене последице. Процена утицаја Системски када се спроводи преко институција, јавних предузећа или организоване страначке хијерархије. Заштита сведока Идентитет сведока не треба објавити без његове изричите сагласности. Прикупљање доказа мора бити организовано тако да не повећава ризик од одмазде. ↑ Назад на преглед KAM-05 Капиларни гласови и систем „сигурних гласова“ Фаза Изборна кампања Процена утицаја Системски. Кључни докази табеле и базе; поруке са квотама; извештаји координатора Надлежни органи Надлежност зависи од конкретног облика манипулације. Повезане манипулације KAM-04 KAM-06 Кратка дефиниција Капиларни систем је организациони модел у којем активисти добијају задатак да идентификују, придобију и прате одређени број бирача. Политичко убеђивање и рад са бирачима сами по себи нису незаконити. Манипулација постоји када је систем повезан са притиском, злоупотребом података, јавним ресурсима, куповином гласова или контролом гласања. Типична структура централни штаб регионални координатори локални координатори активисти задужени бирачи извештаји о подршци контрола излазности оцена „испуњене обавезе“. Категоризација бирача У списковима се могу користити ознаке: сигуран вероватан неодлучан против контактиран гласао није гласао потребан превоз добио помоћ запослен преко организације. Када постаје незаконит или манипулативан када се подаци прикупљају без правног основа када се подршка условљава радним статусом када се тражи доказ гласања када се користе службене базе када активиста контролише излазност конкретног лица када се корист повезује са политичком подршком када се бирач застрашује. Документовање табеле и базе поруке са квотама извештаји координатора упутства за позивање ознаке о излазности сведочења активиста повезаност са јавним установама захтеви да се доставе подаци чланова породице. Процена утицаја Системски. Треба разликовати легитиман страначки рад од присиле. Није спорно да странка контактира своје чланове или добровољне присталице. Спорно је када се систем заснива на зависности, тајном прикупљању података или контроли политичког понашања. ↑ Назад на преглед KAM-06 Паралелни бирачки спискови Фаза Изборна кампања Процена утицаја Системски. Кључни докази Треба сачувати оригинални фајл или фотографију, али јавна верзија мора бити анонимизована. Пун документ доставља се надлежном органу. Надлежни органи Надлежност зависи од конкретног облика манипулације. Повезане манипулације KAM-03 KAM-04 KAM-05 Кратка дефиниција Паралелни списак је незванична евиденција коју воде политички или други актери ради праћења подршке и излазности конкретних бирача. Нико осим надлежних државних органа, а нарочито политичке странке не би смеле да буду у поседу ажурираног бирачког списка. Када активисти странака на власти имају копије бирачких спискова то указује на злоупотребу. Могући садржај име и презиме адреса број телефона радно место ЈМБГ чланови породице политичка процена име активисте информација о помоћи или запослењу податак да ли је лице изашло на изборе напомена о начину гласања. Законита и незаконита евиденција Политички субјект може имати одређене податке о својим члановима и добровољним присталицама. Ризик незаконитости постоји ако: лице није обавештено о обради подаци су преузети из јавне установе политичко опредељење је претпостављено списак садржи прекомерне податке подаци се деле неовлашћеним лицима користе се за притисак или одмазду бележи се ко је гласао на основу информација са бирачког места. Како их препознати активисти поседују детаљне податке које им лице није дало листе садрже службене идентификаторе спискови се ажурирају током изборног дана запослени добијају задатак да допуне колоне исти формулар користе различите институције подаци се достављају преко група за дописивање. Документовање Треба сачувати оригинални фајл или фотографију, али јавна верзија мора бити анонимизована. Пун документ доставља се надлежном органу. Процена утицаја Системски. ↑ Назад на преглед KAM-07 Неравноправна медијска заступљеност Фаза Изборна кампања Процена утицаја Системски, нарочито у медијима са националном покривеношћу. Кључни докази За озбиљну анализу потребно је водити медијски мониторинг:; датум; медиј Надлежни органи Надлежност зависи од конкретног облика манипулације. Повезане манипулације KAM-01 KAM-08 Кратка дефиниција Неравноправна медијска заступљеност постоји када медијски систем једном изборном учеснику обезбеђује несразмерну видљивост или повољнији третман, док друге систематски маргинализује или представља негативно. Обухвата квантитативну и квалитативну доминацију једног изборног учесника, нарочито у медијима са јавним утицајем или националном покривеношћу. Квантитативна неравноправност Односи се на: број појављивања трајање прилога ударне термине број директних обраћања заступљеност у информативним емисијама учесталост преноса службених активности. Квалитативна неравноправност Односи се на: тон извештавања избор саговорника постављена питања прекидање саговорника контекст у којем се актер представља повезивање са негативним догађајима употребу увредљивих квалификација одсуство права на одговор. Функционерска видљивост Посебан проблем постоји када кандидат истовремено као функционер добија велики медијски простор који се формално не рачуна као изборна кампања. Документовање За озбиљну анализу потребно је водити медијски мониторинг: датум медиј емисија трајање актер својство у којем наступа тон непосредан или посредан говор тема присуство страначких порука означавање плаћеног садржаја. Процена утицаја Системски, нарочито у медијима са националном покривеношћу. Шта не треба радити Појединачан негативан прилог није доказ системске неравноправности. Неопходни су подаци о дужем периоду, више емисија и упоредивом третману политичких учесника. ↑ Назад на преглед KAM-08 Прикривено политичко оглашавање Фаза Изборна кампања Процена утицаја Средњи до висок, а када је масовно и координисано — системски. Кључни докази снимак или копија целог прилога; датум и време; подаци о аутору Надлежни органи Надлежност зависи од конкретног облика манипулације. Повезане манипулације KAM-01 KAM-07 KAM-12 Кратка дефиниција Прикривено оглашавање постоји када се политички промотивни садржај представља као независан новинарски, забавни или информативни садржај. Могући облици плаћени интервју без ознаке наручени телевизијски прилог промотивни текст који изгледа као вест инфлуенсерска објава без навођења да је плаћена страначки садржај на формално независној страници координисано објављивање идентичних порука представљање рекламног спота као извештаја садржај јавне институције који стварно промовише кандидата. Показатељи исти текст на више портала одсуство критичких питања искључиво промотивни тон професионално произведен садржај без наведеног наручиоца нагло повећање позитивних прилога истоветан визуелни идентитет са кампањом плаћање преко трећег лица садржај није приказан у извештају о трошковима. Документовање снимак или копија целог прилога датум и време подаци о аутору ознака или одсуство ознаке оглашавања подаци о плаћеној промоцији исти садржај на другим страницама финансијски извештаји кампање. Процена утицаја Средњи до висок, а када је масовно и координисано — системски. ↑ Назад на преглед KAM-09 Дезинформације и координисано обмањивање бирача Фаза Изборна кампања Процена утицаја Висок, нарочито ако се односи на начин остваривања изборног права. Кључни докази снимак екрана са видљивим датумом; оригинална веза; цела објава Надлежни органи Надлежност зависи од конкретног облика манипулације. Повезане манипулације — Кратка дефиниција Дезинформација је нетачна или обмањујућа информација која се намерно шири ради утицања на политичко понашање или изборни поступак. Изборно опасне дезинформације погрешан датум избора нетачно радно време бирачких места погрешно место гласања лажна информација да листа није проглашена лажна информација да се кандидат повукао нетачни услови за гласање тврдња да одређена група нема право гласа лажни резултати лажно саопштење изборне комисије лажни позив за бојкот у име другог актера. Координисано ширење Манипулација може укључивати: лажне налоге аутоматизоване профиле групе портала координисане страначке активисте лажне документе монтиране снимке масовне поруке злоупотребу визуелног идентитета институције. Документовање снимак екрана са видљивим датумом оригинална веза цела објава подаци о налогу време првог појављивања идентичне објаве службено саопштење којим се информација демантује технички подаци када су доступни. Процена утицаја Висок, нарочито ако се односи на начин остваривања изборног права. Хитна реакција Нетачну информацију треба брзо исправити јасном и проверљивом информацијом. Деманти не треба да понавља дезинформацију више него што је неопходно. ↑ Назад на преглед KAM-10 Застрашивање политичких противника, активиста и посматрача Фаза Изборна кампања Процена утицаја Висок или системски. Кључни докази снимци; фотографије оштећења; полицијски записник Надлежни органи полиција; тужилаштво; суд Повезане манипулације — Кратка дефиниција Ова манипулација обухвата претње, насиље, праћење, уништавање имовине, административни притисак или јавну кампању усмерену на спречавање политичког деловања. Облици физичка претња напад оштећење просторија уништавање штандова праћење активиста фотографисање породице претња послодавцу селективне инспекције злоупотреба приватних података јавна кампања означавања као „издајника“ или „непријатеља“ претња кривичним поступком без основа онемогућавање закупа простора. Показатељи организованог обрасца исти починиоци или начин поступања понављање у више места неактивност надлежних органа координисано медијско таргетирање претње након конкретне политичке активности истовремени притисак на више чланова организације. Документовање снимци фотографије оштећења полицијски записник медицинска документација поруке и позиви сведоци временска линија медијски садржај доказ о ранијим пријавама. Надлежне институције полиција тужилаштво суд Повереник за равноправност Заштитник грађана у случају поступања органа изборна комисија ако је угрожен изборни поступак. Процена утицаја Висок или системски. ↑ Назад на преглед KAM-11 Злоупотреба јавних установа, институција и јавних догађаја Фаза Изборна кампања Процена утицаја Висок. Кључни докази службена позивница; страначка објава; фотографије Надлежни органи Надлежност зависи од конкретног облика манипулације. Повезане манипулације — Кратка дефиниција Злоупотреба постоји када се школе, вртићи, здравствене установе, установе културе, месне заједнице или јавна предузећа укључују у политичку кампању. Могући облици страначки скуп у установи обавезно присуство запослених присуство деце политичкој промоцији дељење страначког материјала политички говор током школске или културне приредбе коришћење података родитеља, пацијената или корисника фотографисање корисника са кандидатима промоција политичког субјекта преко службених канала условљавање руководилаца да обезбеде присуство. Посебна заштита деце Укључивање деце у страначку промоцију захтева посебно опрезну оцену, нарочито када: деца не могу разумети политичку сврху присуство је организовала школа или вртић родитељи нису обавештени фотографије се користе у кампањи дете носи страначко обележје јавни функционер користи контакт са децом за личну промоцију. Документовање службена позивница страначка објава фотографије видео-снимак налог запосленима преписка подаци о финансирању сагласност или одсуство сагласности за коришћење снимака сведочења запослених и родитеља. Процена утицаја Висок. ↑ Назад на преглед KAM-12 Нетранспарентно и незаконито финансирање кампање Фаза Изборна кампања Процена утицаја Висок или системски, јер нетранспарентно финансирање омогућава неограничену и неравноправну кампању. Кључни докази извештаји о финансирању; подаци о донаторима; фактуре Надлежни органи Агенција за спречавање корупције; порески органи; Управа за спречавање прања новца, када постоје услови Повезане манипулације KAM-01 KAM-02 KAM-08 Кратка дефиниција Ова манипулација обухвата прикривање стварних извора новца, трошкова, услуга или материјалне подршке коришћене у изборној кампањи. Могући облици фиктивне донације велики број идентичних малих прилога прилози лица без реалне финансијске могућности плаћање преко повезаног предузећа непријављени огласи бесплатне услуге које нису евидентиране трошкови које плаћа треће лице коришћење удружења за страначку промоцију скривени кредит или зајам јавни ресурс који није приказан као корист лажни или непотпуни извештаји готовинске исплате посредницима. Показатељи видљива кампања знатно скупља од пријављених трошкова велики број билборда без јасног наручиоца донатори повезани са јавним пословима идентичне уплате истог дана трошкови се појављују код повезаних правних лица медијски садржај није пријављен као оглашавање услуге се приказују по нереално ниској цени страначку активност формално организује друго удружење. Документовање извештаји о финансирању подаци о донаторима фактуре уговори цене огласног простора фотографије билборда подаци о власништву повезаних фирми регистри јавних набавки медијске тарифе процена стварног обима кампање. Надлежне институције Агенција за спречавање корупције порески органи Управа за спречавање прања новца, када постоје услови полиција и тужилаштво суд други надзорни органи у зависности од извора средстава. Процена утицаја Висок или системски, јер нетранспарентно финансирање омогућава неограничену и неравноправну кампању. ↑ Назад на преглед 6.2. Међусобно повезани механизми кампање 6.2.1. Функционерска кампања и медијска доминација Механизам може изгледати овако: јавни функционер организује службени догађај; догађај се финансира јавним новцем; јавни медији га преносе као вест; страначки налози преузимају снимак; исти материјал се користи у кампањи; трошак није приказан као изборни трошак. На тај начин једна активност може истовремено представљати: функцонерску кампању; злоупотребу јавних ресурса; прикривено оглашавање; неравноправну медијску заступљеност; непријављени трошак кампање. 6.2.2. Капиларни гласови и политички притисак Типичан систем може обухватити: прикупљање података о запосленима; доделу квота руководиоцима; евидентирање „сигурних“ бирача; позивање чланова породице; контролу присуства на скупу; праћење излазности; претњу последицама; награду или казну после избора. 6.2.3. Куповина гласова и контрола доказа Куповина гласова често није само исплата новца. Она може бити повезана са: фотографисањем листића; „бугарским возом“; паралелним списковима; организованим превозом; страначким пунктовима; праћењем излазности; исплатом после гласања. 6.3. Процена системског карактера кампањских манипулација Манипулација има системски карактер када постоји више следећих елемената: централна или хијерархијска координација; исти обрасци у више градова или општина; употреба јавних институција; велики број обухваћених лица; повезаност са запошљавањем или јавним давањима; организовано прикупљање података; медијска подршка; финансијска непрозирност; одсуство делотворне реакције институција; понављање кроз више изборних циклуса. Системски карактер не доказује се једним снимком или једним сведочењем. Потребно је повезати различите врсте доказа. 6.4. Контролна питања за праћење кампање Приликом посматрања изборне кампање треба проверити: У ком својству наступа јавни функционер? Ко финансира догађај? Да ли се користе службени ресурси? Да ли су запослени присутни добровољно? Да ли се јавна давања повезују са политичком подршком? Да ли медијски прилог има промотивни карактер? Да ли је плаћени садржај означен? Да ли се прикупљају лични и политички подаци? Да ли се бирачима нуди материјална корист? Да ли постоји претња или условљавање? Да ли се активност појављује у извештају о трошковима? Да ли су надлежни органи поступили по пријави? Ко то може да потврди? Који је непосредни доказ? 6.5. Закључак поглавља Манипулације током кампање могу формално оставити поступак гласања нетакнутим, а ипак дубоко нарушити слободу избора. Бирач који је месецима изложен претњи, економској зависности, једностраној пропаганди или контроли политичког опредељења не доноси одлуку у истим условима као бирач који је слободан од таквог утицаја. Зато изборна равноправност не подразумева само једнак гласачки листић на дан избора. Она подразумева и: једнаке услове политичког такмичења; раздвајање јавне власти од странке; слободне медије; транспарентно финансирање; заштиту запослених и зависних лица; забрану куповине и контроле гласа; делотворно поступање институција. ← PRE — пре избора BM — бирачко место →"},{"title":"Контролна листа за изборни дан — Атлас изборних манипулација","url":"pages/kontrolna-lista.html","text":"Контролна листа за изборни дан — Атлас изборних манипулација АТЛАС изборних манипулација Ћир Lat Почетна / Практични обрасци / Контролна листа за изборни дан Практични обрасци Контролна листа за изборни дан Практичан подсетник за чланове бирачког одбора и посматраче током отварања и рада бирачког места. Практични обрасци Захтев за увид у изборни материјал Приговор изборној комисији Службена белешка о уоченој неправилности Записник о уоченој неправилности Контролна листа за изборни дан Дневник члана бирачког одбора или посматрача Како документовати изборну неправилност ↑ На врх Сврха: Помоћни практични алат за учеснике у изборном поступку. Правна природа: Пример који се прилагођава конкретном случају и важећем изборном законодавству; није законом прописан формулар. Намена: Чланови бирачких одбора, посматрачи, овлашћени представници изборних листа и друга овлашћена лица. Када се користи Ова контролна листа је практичан подсетник за чланове бирачког одбора и посматраче. Не замењује закон, упутство за спровођење избора нити обуку за конкретан изборни циклус. Пре отварања бирачког места ☐ изборни материјал је примљен и проверен; ☐ утврђено је да је гласачка кутија празна; ☐ контролни лист је правилно попуњен и убачен у кутију; ☐ простор обезбеђује тајност гласања и приступачност у складу са условима; ☐ уклоњен је недозвољени пропагандни материјал; ☐ забележено је време почетка рада и евентуалног кашњења. Током гласања ☐ идентитет бирача утврђује се на прописан начин; ☐ бирач се правилно евидентира пре издавања листића; ☐ издаје се одговарајући број гласачких листића; ☐ обезбеђена је тајност гласања; ☐ нема недозвољеног утицаја, агитације или вођења паралелних евиденција у бирачком месту; ☐ гласање ван бирачког места спроводи се по прописаној процедури; ☐ свака важна неправилност одмах је забележена и пријављена. Пред затварање и после затварања ☐ бирачима затеченим на бирачком месту омогућено је гласање у складу са правилима; ☐ затварање, бројање и попуњавање записника спроведени су прописаним редоследом; ☐ примедбе су затражене и унете у службену документацију када за то постоји основ; ☐ копија записника и други доступни подаци сачувани су у складу са правилима; ☐ изборни материјал је правилно упакован и предат. Практични савет Контролну листу користите током дана, а не тек након затварања. Ако ставка није испуњена, забележите време, разлог, реакцију и доказе; сама ознака на листи није довољна за правну заштиту. ← Записник о уоченој неправилности Сви практични обрасци Дневник члана бирачког одбора или посматрача →"},{"title":"Методологија — Атлас изборних манипулација","url":"pages/metodologija.html","text":"Методологија — Атлас изборних манипулација АТЛАС изборних манипулација Ћир Lat Почетна / Методологија Поглавље 1 Методологија Начин настанка Атласа, извори, критеријуми, јединице анализе, процена утицаја и доказне вредности. 1. МЕТОДОЛОГИЈА 1.1. Предмет и циљ публикације Предмет ове публикације јесу поступци, праксе и пропусти који могу угрозити слободно формирање и веродостојно изражавање изборне воље грађана Републике Србије. Публикација има пет основних циљева: да систематизује најчешће облике изборних неправилности, злоупотреба, манипулација и превара; да објасни фазу изборног процеса у којој се свака појава јавља и начин на који може утицати на изборе; да понуди практична упутства за њено препознавање и документовање; да повеже описане појаве са релевантним домаћим прописима и међународним изборним стандардима; да грађанима, контролорима и другим учесницима у изборном процесу пружи основне информације о надлежним институцијама и расположивим механизмима заштите. Публикација не обухвата само поступања која непосредно мењају број гласова. У њен предмет улазе и радње којима се утиче на слободу опредељивања бирача, равноправност учесника избора, доступност информација, тајност гласања, законитост рада изборних органа и поверење јавности у изборни процес. 1.2. Начин настанка документа Документ је настао систематизацијом: јавно доступних извора о изборним процесима у Републици Србији; запажања домаћих и међународних посматрача; искустава чланова бирачких одбора и контролора; извештаја организација цивилног друштва; медијски документованих случајева; доступних одлука изборних комисија и судова; правних анализа; сведочења учесника и грађана; образаца поступања који су се појављивали током више изборних циклуса. Постојећи практични материјал организован је по јединственој методологији. Сваки облик манипулације разматра се кроз опис појаве, начин функционисања, значај за изборни интегритет, показатеље на основу којих се може препознати, начин документовања, правни оквир, доказну вредност расположивог материјала и могући утицај на изборни резултат. 1.3. Коришћени извори При изради публикације користе се следеће групе извора. 1.3.1. Домаћи правни извори У ову групу спадају: Устав Републике Србије; закони којима се уређују избори народних посланика, председника Републике и одборника; прописи којима се уређују јединствени бирачки списак, финансирање политичких активности, спречавање корупције, електронски медији и заштита података о личности; Кривични законик и други казнени прописи; подзаконски акти, упутства, роковници, приручници и обрасци које доносе Републичка изборна комисија и друге надлежне институције; одлуке локалних изборних комисија; одлуке судова донете у поступцима за заштиту изборног права. Прописи се користе у тексту који је важио у време конкретног изборног догађаја. Када се правна правила накнадно промене, потребно је разликовати пропис који је важио у време догађаја од прописа важећег у време објављивања ове публикације. 1.3.2. Извештаји посматрачких мисија и организација Посебно се користе: извештаји Канцеларије за демократске институције и људска права ОЕБС-а — ODIHR; препоруке и документи Венецијанске комисије; извештаји домаћих посматрачких мисија; извештаји организација CRTA и CeSID; анализе других организација цивилног друштва које се баве изборима, владавином права, медијима и политичким финансирањем; извештаји независних и регулаторних институција, уколико су релевантни за конкретну појаву. Налази ових организација не третирају се аутоматски као судски утврђене чињенице. У публикацији се јасно означава да ли је одређени навод резултат посматрања, статистичке анализе, правне оцене, сведочења или одлуке надлежног органа. 1.3.3. Службена документа и изборни материјал Ова група може обухватити: записнике о раду бирачких одбора; контролне листове; изводе из бирачког списка, у мери у којој је законито располагање њима; решења и закључке изборних комисија; приговоре и жалбе; одлуке судова; службене белешке; статистичке приказе резултата; податке објављене на интернет страницама изборних органа; друге документе настале у оквиру званичног изборног поступка. Службено порекло документа не значи да је његов садржај непогрешив. Управо неслагање између различитих службених докумената може бити важан доказ неправилности. 1.3.4. Фотографије, аудио и видео-записи Визуелни и звучни записи могу бити важан извор, али се њихова доказна вредност процењује према: могућности утврђивања места и времена настанка; континуитету снимка; видљивости лица и радњи; постојању оригиналног фајла; метаподацима, када су доступни; могућности идентификовања аутора; повезаности са другим доказима; постојању назнака да је садржај монтиран, исечен или измењен. Фотографија или кратак снимак често не приказују цео контекст. Зато их, кад год је могуће, треба повезати са записничком примедбом, изјавама више сведока и другим материјалним доказима. 1.3.5. Изјаве сведока и учесника Сведочења могу потицати од: бирача; чланова бирачких одбора; контролора; посматрача; запослених у јавном или приватном сектору; кандидата и представника изборних листа; новинара; других непосредних учесника. При процени сведочења узима се у обзир да ли је лице непосредно присуствовало догађају, колико је времена прошло до давања изјаве, да ли је исказ детаљан и доследан, да ли постоје друга лица која га потврђују и да ли је сведок спреман да изјаву понови пред надлежним органом. Анонимна сведочења могу бити значајна као полазна информација, нарочито у случајевима притисака и страха од одмазде, али обично имају ограниченију доказну вредност у формалном поступку. 1.3.6. Медијски и јавно доступни извори Медијски извештаји користе се као извор информација о конкретним догађајима и реакцијама институција. Њихова поузданост процењује се према: наведеним изворима; постојању докумената или снимака; могућности независне провере; разликовању вести од коментара; томе да ли је другој страни омогућено да се изјасни; накнадним исправкама или демантијима; потврди истих чињеница из више независних извора. Објаве на друштвеним мрежама не сматрају се саме по себи поузданим доказом, али могу упутити на догађај који треба додатно проверити. 1.4. Критеријуми за укључивање примера Пример се може уврстити у публикацију када испуњава најмање један од следећих критеријума: документован је службеним актом; забележили су га акредитовани посматрачи; потврђен је из више независних извора; постоји аутентичан аудио-визуелни материјал; представља образац који је забележен у више изборних циклуса; значајан је за разумевање начина функционисања одређене манипулације; поводом њега је вођен поступак пред изборном комисијом, судом, полицијом, тужилаштвом или другим надлежним органом. Укључивање примера не значи да је у сваком случају правноснажно утврђено извршење кривичног дела, прекршаја или друге повреде закона. Статус сваког примера мора бити прецизно означен. 1.5. Разликовање чињеница, навода и оцена Ради очувања кредибилитета публикације, у тексту се разликују: Утврђена чињеница — податак потврђен службеним документом, правноснажном одлуком или већим бројем међусобно сагласних и проверљивих доказа. Документована неправилност — догађај за који постоји материјал или поуздано сведочење, али поводом којег не мора постојати коначна одлука надлежног органа. Навод или пријава — тврдња коју је изнело одређено лице или организација, а чија тачност није у потпуности потврђена. Индиција — околност која сама не доказује неправилност, али у вези са другим чињеницама може указивати на потребу за даљом провером. Аналитичка оцена — закључак аутора или извора заснован на повезивању доступних чињеница и образаца. Ове категорије не смеју се мешати. Нарочито је важно да се пријава или сумња не представљају као већ доказано кривично дело. 1.6. Јединица анализе Основна јединица анализе у приручнику јесте појединачни облик изборне манипулације. Свака јединица добија посебну шифру у зависности од фазе изборног процеса: PRE — манипулације пре формалног почетка или у раним фазама избора; KAM — манипулације током изборне кампање; BM — манипулације на бирачком месту; BR — манипулације током бројања гласова; POST — манипулације након затварања бирачког места и у поступку утврђивања резултата. Ознака се састоји од скраћенице фазе и редног броја, на пример: BM-04 или POST-03. Коначна класификација конкретних појава биће извршена након распоређивања целокупног постојећег садржаја. Када се одређена појава може јавити у више фаза, сврстава се у фазу у којој производи најнепосредније дејство, уз упућивање на повезане категорије. 1.7. Стандардни образац обраде манипулације Свака манипулација обрађује се према следећем моделу: Назив и шифра — кратак и препознатљив назив појаве. Фаза изборног процеса — време у којем се манипулација најчешће јавља. Опис — јасно објашњење радње или обрасца поступања. Начин функционисања — механизам спровођења и лица која у њему могу учествовати. Зашто је важно — последице по слободу избора, тајност гласања, законитост поступка или тачност резултата. Како препознати — непосредни и посредни показатељи. Како документовати — радње које контролор, посматрач или грађанин може предузети у складу са законом. Правни оквир — могуће повреде прописа, правна природа радње и надлежни органи. Процена утицаја — низак, средњи, висок или системски утицај. Јачина доказа — процена доказне вредности расположивих извора. Пример из праксе — документован случај, када постоји довољно поузданих података. Препоручена реакција — практични кораци који се могу предузети без угрожавања безбедности лица и законитости поступка. 1.8. Процена тежине и утицаја Процена утицаја не представља коначну правну квалификацију. Она служи за разумевање ризика који одређена појава представља за изборни процес. Користе се четири категорије: Низак утицај Неправилност је углавном процедурална, ограничена и отклоњива. Сама по себи обично не може значајно утицати на резултат, али може указивати на недостатак обуке или организације. Средњи утицај Неправилност може повредити право појединачног бирача, тајност гласања или правилност рада бирачког одбора. Њен утицај је ограничен ако је изолована, али може бити значајан уколико се понавља. Висок утицај Радња може непосредно утицати на већи број бирача, број гласова, садржај изборног материјала или резултат на једном или више бирачких места. Системски утицај Појава је организована, широко распрострањена, институционално подржана или се понавља по истом обрасцу на већем броју места. Може утицати на слободно опредељивање великог броја грађана, равноправност изборне утакмице или укупни изборни резултат. Приликом оцене узимају се у обзир: број обухваћених бирача; број бирачких места; трајање и учесталост; степен организованости; могућност отклањања последица; разлика у броју гласова између изборних учесника; учешће носилаца јавних овлашћења; постојање координисаног обрасца. Иста врста манипулације може добити различиту оцену у зависности од обима. На пример, један изолован случај неовлашћеног помагања бирачу не мора имати исти значај као организовано и масовно утицање на начин гласања лица у више бирачких места. 1.9. Процена доказне вредности Доказна вредност не зависи само од врсте доказа, већ и од његовог квалитета, аутентичности, законитости прибављања и повезаности са другим изворима. У публикацији се користи оријентациона скала: Пет степени — веома јака доказна вредност оригинални службени документ; записник који су потписали чланови бирачког одбора; правноснажна одлука; континуиран и аутентичан видео-запис који јасно приказује радњу; више међусобно сагласних материјалних доказа. Четири степена — јака доказна вредност јасна фотографија или видео повезани са местом и временом; копија службеног документа чија се аутентичност може проверити; сагласне изјаве више независних непосредних сведока; подударност записника, снимка и других докумената. Три степена — средња доказна вредност изјава једног непосредног и идентификованог сведока; службена белешка; делимичан снимак; фотографија којој недостаје шири контекст; медијски извештај заснован на идентификованим изворима. Два степена — ограничена доказна вредност посредно сведочење; анонимна изјава; непотпуна документација; објава на друштвеној мрежи чије порекло није у потпуности потврђено. Један степен — почетна информација или индиција гласина; претпоставка; непроверљива објава; статистичка необичност која није повезана са конкретним доказима. Слабији доказ не треба аутоматски одбацити. Више међусобно сагласних индиција може оправдати даљу проверу. Међутим, индиције се не смеју представити као потпун доказ извршења противправне радње. 1.10. Ограничења публикације Ова публикација има неколико ограничења. Прво, изборне манипулације се по природи често спроводе прикривено, па нису сви случајеви доступни јавности или формално документовани. Друго, непоступање надлежног органа не доказује да неправилност није постојала, али ни сама пријава не доказује да је до неправилности заиста дошло. Треће, правна квалификација зависи од чињеница сваког конкретног случаја. Иста радња може, зависно од околности, представљати процедурални пропуст, прекршај, кривично дело, повреду радне обавезе или основ за поништавање гласања. Четврто, извори нису увек једнако доступни. У неким случајевима постоје комплетна службена документа и одлуке, док су у другим доступна само сведочења или медијски извештаји. Пето, изборни прописи се мењају. Зато се правни оквир мора проверити и ажурирати пре сваког новог издања публикације и пре употребе у конкретном изборном поступку. 1.11. Етичка правила и заштита личности При објављивању примера морају се поштовати достојанство личности, претпоставка невиности, право на приватност и правила о заштити података о личности. Посебно треба избегавати: објављивање јединственог матичног броја грађана; објављивање адреса становања; објављивање комплетних извода из бирачког списка; откривање идентитета лица која би могла бити изложена одмазди; неосновано означавање лица као извршиоца кривичног дела; објављивање снимака насталих противно закону; угрожавање тајности гласања. Када је идентитет лица важан за разумевање случаја, треба навести само податке који су неопходни и чије је објављивање оправдано јавним интересом и засновано на проверљивим чињеницама. 1.12. Ажурирање публикације Ова публикација је замишљена као документ који се периодично допуњује. Нова издања треба да обухвате: измене изборних закона и подзаконских аката; нове препоруке ODIHR-а и других међународних тела; нову праксу изборних комисија и судова; нове облике дигиталних и других манипулација; нове документоване студије случаја; податке о поступању институција по раније поднетим пријавама. Свака верзија публикације треба да садржи датум закључења правне и чињеничне редакције."},{"title":"О Атласу — Атлас изборних манипулација","url":"pages/o-knjizi.html","text":"О Атласу — Атлас изборних манипулација АТЛАС изборних манипулација Ћир Lat Почетна / О Атласу Страница 2 О Атласу изборних манипулација Шта је ова публикација, зашто је настала и коме је намењена. На овој страници Шта је Атлас изборних манипулација Циљ публикације Како је настала Коме је намењена Како се користи Шта је Атлас изборних манипулација „Атлас изборних манипулација“ је стручна и практична публикација која систематизује најчешће облике нарушавања изборног процеса, од периода пре расписивања избора до поступака који следе након проглашења резултата. Њена посебна вредност је у томе што изборне неправилности не посматра као издвојене инциденте, већ као појаве које се могу препознати, описати, документовати и повезати са одговарајућим правним нормама. Атлас изборних манипулација је истовремено систематизован преглед, приручник за практично поступање и документ о институционалним слабостима изборног процеса. Циљ публикације Основни циљ публикације је да допринесе бољем разумевању начина на који изборне манипулације настају и делују, као и да понуди јасан оквир за њихово благовремено препознавање и доказивање. Књига настоји да сложене изборне поступке и правне механизме учини доступнијим контролорима, посматрачима, правницима, новинарима, истраживачима и грађанима који желе да разумеју изборни процес. Како је настала Атлас изборних манипулација је настала прикупљањем и систематизацијом искустава из различитих изборних циклуса, анализом домаћег правног оквира, извештаја посматрачких мисија, одлука изборних органа и судова, као и документованих примера из праксе. Садржај је организован према фазама изборног процеса, како би се појединачне манипулације лакше пронашле и повезале са временом, институцијом и поступком у којем настају. Коме је намењена контролорима и члановима бирачких одбора; домаћим и међународним посматрачима; правницима и учесницима у поступцима изборне заштите; новинарима и истраживачима; организацијама цивилног друштва; студентима и свим грађанима заинтересованим за изборни интегритет. Како се користи Свака манипулација је обрађена по јединственој структури: назив и шифра, опис, начин функционисања, показатељи за препознавање, начин документовања, правни оквир, процена утицаја и препоручена реакција. Дигитално издање задржава ту структуру, али омогућава бржу навигацију, повезивање сродних појава и касније увођење претраге кроз целокупан садржај. ← Назад на почетну страницу"},{"title":"POST — Постизборне манипулације","url":"pages/post.html","text":"POST — Постизборне манипулације АТЛАС изборних манипулација Ћир Lat Почетна / POST — после избора POST Постизборне манипулације Комплетан текст деветог поглавља Атласа изборних манипулација: 20 манипулација, ланац чувања материјала, контрола резултата и делотворна правна заштита. Изаберите фазу изборног процеса: PRE Пре избора KAM Током кампање BM На бирачком месту BR Током бројања POST Након избора 9.1. Зашто постизборна фаза није мање важна од гласања Изборни процес се не завршава затварањем бирачких места. После гласања следе радње које одређују да ли ће резултат са бирачког места бити: правилно пренет; верно унет у информациони систем; доступан јавности; проверљив; предмет делотворне правне заштите; коначно утврђен у складу са законом. У постизборној фази могу се исправљати стварне грешке, али се под видом исправке могу и прикрити неправилности или изменити резултати. Посебно су осетљиви: транспорт изборног материјала; пријем материјала у изборној комисији; контрола записника; логичко-рачунска провера; унос података; објављивање резултата; поступање по приговорима; увид у материјал; поновно бројање; утврђивање коначних резултата; расподела мандата; понављање гласања. Манипулација у овој фази често није видљива грађанима. Она се одвија у административним, техничким и правним поступцима, па је за њено откривање неопходно поредити више докумената и извора. Преглед POST манипулација POST-01 Необезбеђен транспорт изборног материјала POST-02 Преправљање записника после напуштања бирачког места POST-03 Замена или нестанак изборног материјала POST-04 Неовлашћено отварање вреће са изборним материјалом POST-05 Нетачан унос резултата у информациони систем POST-06 Нејавне или недокументоване „исправке“ POST-07 Селективно прихватање неуредних записника POST-08 Одбијање увида у изборни материјал POST-09 Ограничавање права на приговор POST-10 Непоступање или кашњење по приговорима POST-11 Необразложено одбијање приговора POST-12 Селективно поништавање и поновљено гласање POST-13 Неправилно поновно бројање POST-14 Непотпуно или селективно објављивање резултата POST-15 Преурањено проглашавање коначних резултата POST-16 Неправилна расподела мандата POST-17 Притисак на изборне органе, судове и друга надлежна тела POST-18 Уништавање, скривање или недоступност доказа POST-19 Ускраћивање приступа подацима неопходним за проверу POST-20 Непотпуно или обмањујуће представљање изборних неправилности POST-01 Необезбеђен транспорт изборног материјала Фаза После изборног дана и током утврђивања коначних резултата Процена утицаја Висок, а ако се исти пропуст јавља код већег броја бирачких места — системски. Кључни докази Потребно је забележити:; број бирачког места;; број затворнице;; боју, тип и изглед затворнице; Надлежни органи Надлежна изборна комисија, судови и други органи правне заштите; полиција и тужилаштво када постоје елементи кривичног дела. Повезане целине BR Студије случаја Кратка дефиниција Необезбеђен транспорт постоји када се вреће са гласачким листићима, записници и други изборни материјал преносе на начин који не обезбеђује непрекидан надзор, утврђену одговорност и заштиту од неовлашћеног отварања, замене, губитка или измене садржине. Начин затварања вреће После утврђивања резултата гласања изборни материјал пакује се у одговарајуће вреће. Врећа се затвара пластичном сигурносном затворницом са јединственим нумеричким бројем. Број затворнице мора бити: проверен пре употребе; гласно прочитан присутним члановима; тачно евидентиран у прописаној документацији; видљив на фотографији, када је фотографисање дозвољено; поново проверен приликом предаје и пријема вреће. Нумерисана затворница има сврху да покаже да ли је врећа после затварања отварана или је оригинална затворница замењена. Међутим, сама подударност броја није довољна гаранција интегритета. Потребно је проверити и: физичко стање затворнице; затегнутост; положај механизма за закључавање; трагове савијања, сечења или механичког оштећења; стање отвора вреће; трагове развлачења материјала; подударност изгледа затворнице са оном која је употребљена на бирачком месту. Посебни ризици Могући ризици обухватају: недовољно затегнуту затворницу; разлабављивање затворнице без видљивог ломљења; извлачење дела садржаја кроз недовољно затворен отвор вреће; отварање и поновно затварање истом затворницом, ако њена конструкција то омогућава; замену затворнице другом која носи исти или визуелно сличан број; нетачно преписивање броја затворнице; накнадно мењање податка о броју; транспорт вреће без присуства више овлашћених лица; остављање вреће ван непосредног надзора. Могућност постојања две или више затворница са истим бројем представљала би озбиљан безбедносни пропуст. Таква сумња мора бити поткрепљена поређењем затворница, документацијом о набавци, евиденцијом серијских бројева или другим материјалним доказима. Посебно ризичне ситуације врећа се током транспорта смешта у пртљажник без непосредног надзора; возило се зауставља на непредвиђеном месту; део лица задужених за предају напушта возило; врећа се уноси у просторију која није место званичног пријема; врећа остаје у ходнику, возилу или другој незаштићеној просторији; пријем се не врши одмах; не постоји јасан редослед предаје; број затворнице се не проверава пред предаваоцима; стање вреће се не уноси у примопредајни документ. Документовање Потребно је забележити: број бирачког места; број затворнице; боју, тип и изглед затворнице; време затварања вреће; имена лица присутних приликом затварања; стање вреће и затворнице; време поласка; возило и регистарску ознаку; лица која превозе материјал; свако заустављање; време доласка; име лица које преузима врећу; поново утврђени број затворнице; свако физичко одступање. Процена утицаја Висок, а ако се исти пропуст јавља код већег броја бирачких места — системски. ↑ Назад на преглед POST-02 Преправљање записника после напуштања бирачког места Фаза После изборног дана и током утврђивања коначних резултата Процена утицаја Висок или системски. Кључни докази Најважнији су:; копија записника са бирачког места;; фотографија оригинала пре транспорта;; верзија коју је примила изборна комисија; Надлежни органи Надлежна изборна комисија, судови и други органи правне заштите; полиција и тужилаштво када постоје елементи кривичног дела. Повезане целине BR Студије случаја Кратка дефиниција Постоји када се бројеви, примедбе, потписи или други подаци у записнику мењају након што је записник закључен и потписан на бирачком месту. Могући облици преправљање цифре; замена странице; додавање новог податка; брисање примедбе; додавање потписа; замена оригиналног записника; израда нове верзије без присуства одбора; накнадно попуњавање празних поља. Показатељи копија члана одбора не одговара оригиналу; различито мастило или рукопис; видљиво брисање; цифра је преписана преко друге; недостаје примедба која је била унета; бројеви се не слажу са објављеном фотографијом; потпис се појављује накнадно. Докази Најважнији су: копија записника са бирачког места; фотографија оригинала пре транспорта; верзија коју је примила изборна комисија; техничка анализа документа; изјаве потписника; примопредајна документација. Процена утицаја Висок или системски. ↑ Назад на преглед POST-03 Замена или нестанак изборног материјала Фаза После изборног дана и током утврђивања коначних резултата Процена утицаја Висок или системски. Кључни докази примопредајни бројеви се не слажу;; ознаке врећа су мењане;; једна верзија документа нема све прилоге;; изборна комисија не може да лоцира материјал; Надлежни органи Надлежна изборна комисија, судови и други органи правне заштите; полиција и тужилаштво када постоје елементи кривичног дела. Повезане целине BR Студије случаја Кратка дефиниција Замена или нестанак изборног материјала постоји када се након затварања бирачког места оригинални гласачки листићи, записници или други делови изборне документације неовлашћено уклоне, замене, додају или учине недоступним. Материјал или његов део не стиже у изборну комисију, губи се или постаје недоступан за контролу. Део изборног материјала нестаје, појављује се у измењеном облику или се замењује другим материјалом. Могући облици недостаје врећа са листићима; недостаје извод из бирачког списка; оригинал записника је замењен копијом; нестају спорни листићи; појављују се нови неважећи листићи; недостаје контролни лист; садржај вреће припада другом бирачком месту. Показатељи примопредајни бројеви се не слажу; ознаке врећа су мењане; једна верзија документа нема све прилоге; изборна комисија не може да лоцира материјал; списак садржаја не одговара стварном стању. Процена утицаја Висок или системски. ↑ Назад на преглед POST-04 Неовлашћено отварање вреће са изборним материјалом Фаза После изборног дана и током утврђивања коначних резултата Процена утицаја Висок или системски. Кључни докази Записници, копије докумената, електронски трагови, службене белешке и изјаве овлашћених лица. Надлежни органи Надлежна изборна комисија, судови и други органи правне заштите; полиција и тужилаштво када постоје елементи кривичног дела. Повезане целине BR Студије случаја Кратка дефиниција Врећа са изборним материјалом отвара се након затварања бирачког места без законом прописаног основа, ван прописане процедуре или без присуства овлашћених лица, чиме се нарушава интегритет изборног материјала и ланац његовог чувања. Неовлашћено отварање постоји када се врећа са изборним материјалом отвори, разлабави или јој се омогући приступ без законског основа, без присуства овлашћених лица и без потпуног службеног евидентирања. Отварањем се сматра и приступ без потпуног уклањања затворнице Ризик не постоји само када је затворница пресечена или физички уклоњена. Интегритет је доведен у питање и када је: затворница разлабављена; отвор вреће проширен; садржају приступљено кроз делимично отворену врећу; затворница померана или поново затегнута; врећа оштећена са стране или на дну; затворница замењена другом. Зато контрола не сме бити ограничена само на питање да ли се број на затворници подудара са евидентираним бројем. Процена утицаја Висок или системски. ↑ Назад на преглед POST-05 Нетачан унос резултата у информациони систем Фаза После изборног дана и током утврђивања коначних резултата Процена утицаја Висок или системски. Кључни докази објављени резултат се разликује од копије записника;; број важећих гласова није исти;; једна листа има необјашњив вишак;; у систему недостаје бирачко место; Надлежни органи Надлежна изборна комисија, судови и други органи правне заштите; полиција и тужилаштво када постоје елементи кривичног дела. Повезане целине BR Студије случаја Кратка дефиниција Подаци из записника уносе се у електронски систем погрешно, непотпуно или у корист одређеног изборног учесника. Могући облици замена цифара; приписивање гласова погрешној листи; изостављање бирачког места; унос старе верзије записника; вишеструки унос; промена података после верификације; унос без контроле другог лица; ручно заобилажење системске контроле. Показатељи објављени резултат се разликује од копије записника; број важећих гласова није исти; једна листа има необјашњив вишак; у систему недостаје бирачко место; податак се више пута мења; нема трага о томе ко је извршио измену. Контролни механизми Поуздан систем треба да обезбеди: двоструку проверу уноса; евиденцију корисника; временски траг сваке измене; чување претходне верзије; аутоматску логичку контролу; поређење са скенираним записником. Процена утицаја Висок или системски. ↑ Назад на преглед POST-06 Нејавне или недокументоване „исправке“ Фаза После изборног дана и током утврђивања коначних резултата Процена утицаја Висок. Кључни докази Записници, копије докумената, електронски трагови, службене белешке и изјаве овлашћених лица. Надлежни органи Надлежна изборна комисија, судови и други органи правне заштите; полиција и тужилаштво када постоје елементи кривичног дела. Повезане целине BR Студије случаја Кратка дефиниција Изборна комисија мења податке из записника без јасне одлуке, без видљивог образложења или без могућности контроле. Рачунска грешка може бити стварна, али исправка мора оставити јасан траг и бити извршена у прописаном поступку. Манипулација постоји када се под видом исправке мења стварно утврђени резултат. Законита исправка Исправка може бити оправдана када: постоји очигледна рачунска грешка; изворни подаци су јасни; исправка не захтева нагађање; поступак је документован; може се утврдити ко је и зашто извршио измену; заинтересовани учесници могу да изврше увид. Манипулативна исправка Ризик постоји када: бројеви се мењају без увида у листиће; исправка прикрива неслагање; чланови одбора нису консултовани; нема писаног трага; нови резултат одговара политички пожељном исходу; исправке се селективно врше само на одређеним местима. Процена утицаја Висок. ↑ Назад на преглед POST-07 Селективно прихватање неуредних записника Фаза После изборног дана и током утврђивања коначних резултата Процена утицаја Висок или системски. Кључни докази Записници, копије докумената, електронски трагови, службене белешке и изјаве овлашћених лица. Надлежни органи Надлежна изборна комисија, судови и други органи правне заштите; полиција и тужилаштво када постоје елементи кривичног дела. Повезане целине BR Студије случаја Кратка дефиниција Изборна комисија различито поступа према записницима са истим или сличним недостацима. Могући облици један записник се прихвата, други враћа; једном одбору се дозвољава исправка, другом не; неке грешке се проглашавају техничким, а друге суштинским; примедбе једних чланова се узимају у обзир, других не; критеријуми се мењају током поступка. Како се доказује селективност Потребно је упоредити: исте врсте грешака; исту фазу поступка; исту правну норму; одлуке комисије; образложења; политичку структуру бирачких места или предлагача. Једна различита одлука није довољна. Потребан је образац неједнаког поступања. Процена утицаја Висок или системски. ↑ Назад на преглед POST-08 Одбијање увида у изборни материјал Фаза После изборног дана и током утврђивања коначних резултата Процена утицаја Висок, јер може онемогућити правну заштиту. Кључни докази Записници, копије докумената, електронски трагови, службене белешке и изјаве овлашћених лица. Надлежни органи Надлежна изборна комисија, судови и други органи правне заштите; полиција и тужилаштво када постоје елементи кривичног дела. Повезане целине BR Студије случаја Кратка дефиниција Овлашћеном изборном учеснику или другом лицу које има право на увид онемогућава се да прегледа записнике, гласачке листиће или другу релевантну документацију. Могући облици захтев се игнорише; заказује се термин после истека рока за приговор; дозвољава се увид само у део материјала; забрањује се бележење; материјал се проглашава недоступним; не даје се копија документа; увид се омогућава под условима који га фактички онемогућавају. Зашто је увид важан Без увида није могуће поуздано проверити: разлику између копије и оригинала; спорне листиће; број потписа; исправке записника; стање пакета; основ за правно средство. Процена утицаја Висок, јер може онемогућити правну заштиту. ↑ Назад на преглед POST-09 Ограничавање права на приговор Фаза После изборног дана и током утврђивања коначних резултата Процена утицаја Висок или системски. Кључни докази Записници, копије докумената, електронски трагови, службене белешке и изјаве овлашћених лица. Надлежни органи Надлежна изборна комисија, судови и други органи правне заштите; полиција и тужилаштво када постоје елементи кривичног дела. Повезане целине BR Студије случаја Кратка дефиниција Право на правно средство се формално признаје, али се његово коришћење фактички отежава или онемогућава. Могући облици претерано формалистички захтеви; нејасна упутства; кратки рокови без приступа материјалу; одбијање пријема поднеска; недоступност органа; технички систем не ради; подносилац не добија потврду; тражи се доказ који орган сам поседује; приговор се одбацује без разматрања суштине. Правна оцена Рокови у изборним споровима су по правилу кратки због потребе брзог окончања процеса. Ипак, брзина не сме да укине стварну могућност подносиоца да: сазна разлог; приступи доказима; поднесе правно средство; добије образложену одлуку. Процена утицаја Висок или системски. ↑ Назад на преглед POST-10 Непоступање или кашњење по приговорима Фаза После изборног дана и током утврђивања коначних резултата Процена утицаја Висок или системски. Кључни докази више предмета са истим кашњењем;; рокови се поштују селективно;; нема образложења;; доказ нестаје током чекања; Надлежни органи Надлежна изборна комисија, судови и други органи правне заштите; полиција и тужилаштво када постоје елементи кривичног дела. Повезане целине BR Студије случаја Кратка дефиниција Надлежни орган не одлучује у року, не предузима потребне радње или поступа тек када правна заштита више не може делотворно утицати на исход. Могући облици предмет се не заводи; не прибавља се материјал; сведоци се не саслушавају; спорна врећа се не обезбеђује; одлука се доноси после проглашења резултата; подносилац не добија одлуку на време; орган формално одговори без испитивања доказа. Показатељи више предмета са истим кашњењем; рокови се поштују селективно; нема образложења; доказ нестаје током чекања; одлука стиже после истека наредног правног рока. Процена утицаја Висок или системски. ↑ Назад на преглед POST-11 Необразложено одбијање приговора Фаза После изборног дана и током утврђивања коначних резултата Процена утицаја Висок. Кључни докази Записници, копије докумената, електронски трагови, службене белешке и изјаве овлашћених лица. Надлежни органи Надлежна изборна комисија, судови и други органи правне заштите; полиција и тужилаштво када постоје елементи кривичног дела. Повезане целине BR Студије случаја Кратка дефиниција Приговор се одбија без одговора на кључне чињенице, доказе и правне наводе. Облици недовољног образложења преписивање законске одредбе; тврдња да „није доказано“ без анализе доказа; игнорисање приложене копије записника; неодговарање на тврдњу о преправљању; позивање на формални недостатак који није битан; различито образложење од стварног разлога одбијања. Квалитетна одлука треба да садржи утврђене чињенице; оцену сваког кључног доказа; примену правне норме; одговор на главне наводе; разлог прихватања или одбијања; поуку о правном средству. Процена утицаја Висок. ↑ Назад на преглед POST-12 Селективно поништавање и поновљено гласање Фаза После изборног дана и током утврђивања коначних резултата Процена утицаја Висок или системски. Кључни докази Записници, копије докумената, електронски трагови, службене белешке и изјаве овлашћених лица. Надлежни органи Надлежна изборна комисија, судови и други органи правне заштите; полиција и тужилаштво када постоје елементи кривичног дела. Повезане целине BR Студије случаја Кратка дефиниција Гласање се поништава или не поништава по различитим критеријумима, у зависности од тога коме одлука политички користи. Могући облици иста неправилност различито се оцени; поништава се место на којем резултат не одговара одређеном актеру; не поништава се место са тежом неправилношћу; делимично понављање се одређује тако да може изменити расподелу мандата; одлука се доноси без анализе утицаја неправилности. Кључна питања Да ли је неправилност стварно могла утицати на резултат? Да ли је исти стандард примењен на упоредиве случајеве? Да ли је понављање неопходно и сразмерно? Да ли је одлука добро образложена? Да ли су сви учесници имали једнак приступ доказима? Процена утицаја Висок или системски. ↑ Назад на преглед POST-13 Неправилно поновно бројање Фаза После изборног дана и током утврђивања коначних резултата Процена утицаја Висок. Кључни докази Записници, копије докумената, електронски трагови, службене белешке и изјаве овлашћених лица. Надлежни органи Надлежна изборна комисија, судови и други органи правне заштите; полиција и тужилаштво када постоје елементи кривичног дела. Повезане целине BR Студије случаја Кратка дефиниција Поновно бројање се спроводи без адекватне контроле, уз непотпун материјал или без поштовања унапред утврђених правила. Ризици броји се материјал чији интегритет није обезбеђен; нису присутни овлашћени представници; спорни листићи се не показују; не зна се зашто је поновно бројање одређено; резултат се мења без објашњења; не прави се нови службени запис; није могуће упоредити старо и ново стање. Правилно поновно бројање треба да обезбеди правни основ; јавност поступка; непрекидан надзор; утврђено стање пакета; јасна правила за важеће листиће; детаљан записник; упоредни приказ претходног и новог резултата; образложење разлика. Процена утицаја Висок. ↑ Назад на преглед POST-14 Непотпуно или селективно објављивање резултата Фаза После изборног дана и током утврђивања коначних резултата Процена утицаја Средњи до висок, а ако систематски спречава проверу — системски. Кључни докази Записници, копије докумената, електронски трагови, службене белешке и изјаве овлашћених лица. Надлежни органи Надлежна изборна комисија, судови и други органи правне заштите; полиција и тужилаштво када постоје елементи кривичног дела. Повезане целине BR Студије случаја Кратка дефиниција Резултати се објављују без свих бирачких места, без копија записника или на начин који онемогућава јавну проверу. Могући облици објављују се само збирни подаци; недостају резултати по бирачким местима; скенирани записници нису доступни; поједини записници су нечитљиви; не види се историја исправки; објављени подаци се мењају без напомене; резултати се достављају само одабраним медијима; формат не омогућава претрагу и анализу. Зашто је транспарентност важна Јавност података омогућава: поређење копија; откривање грешака; независно сабирање; анализу неправилности; проверу исправки; повећање поверења. Процена утицаја Средњи до висок, а ако систематски спречава проверу — системски. ↑ Назад на преглед POST-15 Преурањено проглашавање коначних резултата Фаза После изборног дана и током утврђивања коначних резултата Процена утицаја Висок. Кључни докази Записници, копије докумената, електронски трагови, службене белешке и изјаве овлашћених лица. Надлежни органи Надлежна изборна комисија, судови и други органи правне заштите; полиција и тужилаштво када постоје елементи кривичног дела. Повезане целине BR Студије случаја Кратка дефиниција Коначни резултати проглашавају се пре окончања свих законом релевантних поступака. Политички актер или институција представља непотпуне податке као коначне и тиме ствара притисак на изборне органе и јавност. Сама политичка процена резултата није нужно противправна, али постаје проблематична када се представља као званична или се користи за обесмишљавање правних поступака. Могући облици нису решени приговори; није завршено поновљено гласање; судски поступак је у току; недостају резултати са појединих места; спорни записници нису проверени; материјал није комплетан; одлука се доноси пре истека рокова. Последице стварање привида да је поступак завршен; притисак на орган који одлучује; отежавање делотворне правне заштите; могућност неправилне доделе мандата; политичко коришћење незавршеног резултата. Процена утицаја Висок. ↑ Назад на преглед POST-16 Неправилна расподела мандата Фаза После изборног дана и током утврђивања коначних резултата Процена утицаја Висок, јер непосредно мења састав представничког тела. Кључни докази одлука о укупним резултатима;; табела расподеле;; формула;; број гласова сваке листе; Надлежни органи Надлежна изборна комисија, судови и други органи правне заштите; полиција и тужилаштво када постоје елементи кривичног дела. Повезане целине BR Студије случаја Кратка дефиниција Мандати се расподељују на основу погрешних података, погрешног прага, погрешне формуле или неправилно признатог статуса изборне листе. Могући облици погрешан укупан број важећих гласова; погрешна примена изборног прага; нетачан статус мањинске листе; погрешно заокруживање; изостављање листе; нетачан број мандата; расподела на основу неконачних резултата; замена редоследа кандидата; незаконита замена кандидата после избора. Документовање одлука о укупним резултатима; табела расподеле; формула; број гласова сваке листе; статус листе; списак кандидата; независан контролни прорачун. Процена утицаја Висок, јер непосредно мења састав представничког тела. ↑ Назад на преглед POST-17 Притисак на изборне органе, судове и друга надлежна тела Фаза После изборног дана и током утврђивања коначних резултата Процена утицаја Системски. Кључни докази одлуке се мењају после политичких изјава;; чланови органа не могу да образложе промену става;; постоје поруке или позиви;; службено лице се повлачи из поступка; Надлежни органи Надлежна изборна комисија, судови и други органи правне заштите; полиција и тужилаштво када постоје елементи кривичног дела. Повезане целине BR Студије случаја Кратка дефиниција Чланови изборних комисија, судије, тужиоци, службеници или друга овлашћена лица изложени су политичком, институционалном, медијском или личном притиску у вези са одлучивањем. Могући облици страначки налог; претња сменом; претња губитком посла; јавна кампања против члана органа; непосредан позив функционера; захтев да се предмет реши на одређени начин; ускраћивање информација; селективно достављање материјала; притисак кроз медије; претња члановима породице. Показатељи одлуке се мењају после политичких изјава; чланови органа не могу да образложе промену става; постоје поруке или позиви; службено лице се повлачи из поступка; гласање у органу прати јасна страначка подела; одлука одступа од раније праксе без објашњења. Процена утицаја Системски. ↑ Назад на преглед POST-18 Уништавање, скривање или недоступност доказа Фаза После изборног дана и током утврђивања коначних резултата Процена утицаја Висок или системски. Кључни докази доказ постаје недоступан одмах после приговора;; различити органи пребацују одговорност;; не постоји евиденција уништења;; фајл је накнадно мењан; Надлежни органи Надлежна изборна комисија, судови и други органи правне заштите; полиција и тужилаштво када постоје елементи кривичног дела. Повезане целине BR Студије случаја Кратка дефиниција Документи, електронски записи, снимци или други докази о изборном поступку уништавају се, уклањају, мењају или чине недоступним. Могући облици нестаје оригинални записник; брише се електронска историја измена; уништавају се листићи пре истека рока; не чува се видео-запис; нестаје примопредајна документација; серверски записи нису доступни; сведоку се наређује да обрише поруке; јавни орган тврди да документ не поседује; материјал се проглашава уништеним без службеног доказа. Показатељи доказ постаје недоступан одмах после приговора; различити органи пребацују одговорност; не постоји евиденција уништења; фајл је накнадно мењан; резервна копија не постоји; документација је непотпуна само за спорна места. Превентивне мере правовремено прављење копија; чување оригиналних метаподатака; евиденција преузимања; захтев за обезбеђење доказа; чување материјала на више безбедних места; употреба контролних вредности електронских фајлова; службено евидентирање сваког увида. Процена утицаја Висок или системски. ↑ Назад на преглед POST-19 Ускраћивање приступа подацима неопходним за проверу Фаза После изборног дана и током утврђивања коначних резултата Процена утицаја Није посебно наведено. Кључни докази није могуће независно проверити објављене резултате;; различити извори садрже међусобно неусклађене податке;; недостају поједини записници или прилози;; захтеви за приступ информацијама остају без одговора или се одбијају без ваљаног образложења; Надлежни органи Надлежна изборна комисија, судови и други органи правне заштите; полиција и тужилаштво када постоје елементи кривичног дела. Повезане целине BR Студије случаја Кратка дефиниција Надлежни органи не објављују, не достављају или отежавају приступ подацима и документима неопходним за независну проверу изборног процеса и утврђивање чињеничног стања. Обухвата и недоступност машински читљивих резултата, записника, одлука, података о исправкама и других јавних докумената. Могући облици необјављивање записника са бирачких места; недоступност машински читљивих изборних резултата; одбијање или одлагање приступа изборном материјалу; непотпуно објављивање одлука и образложења; изостављање података о исправкама и накнадним изменама; објављивање докумената у форматима непогодним за анализу; селективно достављање података појединим учесницима; брисање или накнадна измена већ објављених података. Показатељи није могуће независно проверити објављене резултате; различити извори садрже међусобно неусклађене податке; недостају поједини записници или прилози; захтеви за приступ информацијама остају без одговора или се одбијају без ваљаног образложења; подаци се објављују са значајним кашњењем; накнадне измене нису јасно евидентиране и образложене. Процена утицаја Висок или системски. ↑ Назад на преглед POST-20 Непотпуно или обмањујуће представљање изборних неправилности Фаза После изборног дана и током утврђивања коначних резултата Процена утицаја Није посебно наведено. Кључни докази Записници, копије докумената, електронски трагови, службене белешке и изјаве овлашћених лица. Надлежни органи Надлежна изборна комисија, судови и други органи правне заштите; полиција и тужилаштво када постоје елементи кривичног дела. Повезане целине BR Студије случаја Кратка дефиниција Надлежне институције или јавни функционери умањују значај изборних неправилности тако што их приказују као изоловане техничке пропусте, без разматрања њихове учесталости, међусобне повезаности и могућег утицаја на интегритет изборног процеса. Могући облици истицање само појединачних техничких грешака; занемаривање образаца понављања неправилности; одбацивање навода без суштинске анализе; приказивање системских проблема као појединачних инцидената; селективно представљање статистичких података; изостављање налаза домаћих и међународних посматрача; умањивање значаја већег броја појединачних неправилности; јавно саопштавање закључака без одговарајућег образложења. Кључна питања Да ли су неправилности анализиране појединачно и као целина? Да ли је процењен њихов кумулативни утицај на изборни процес? Да ли су размотрени сви расположиви докази и извештаји? Да ли је образложено зашто се неправилности сматрају несистемским? Да ли је јавност добила потпуне и проверљиве информације? Процена утицаја Висок или системски. ↑ Назад на преглед 9.2. ЛАНАЦ ЧУВАЊА ИЗБОРНОГ МАТЕРИЈАЛА Ланац чувања представља документован низ лица, места и радњи кроз које је изборни материјал прошао од затварања бирачког места до коначног архивирања. Добар ланац чувања омогућава да се у сваком тренутку утврди: ко је преузео материјал; у које време; у каквом стању; коме га је предао; да ли је пакет отваран; на основу које одлуке; ко је присуствовао; шта је после отварања поново запаковано. Минимални подаци Прекид у ланцу чувања не доказује аутоматски да је материјал измењен, али значајно слаби његову доказну поузданост. Чување изборних врећа након пријема Након пријема изборног материјала у изборној комисији, вреће се чувају до истека законом прописаних рокова, односно до окончања поступака по приговорима и евентуалних поновних бројања. У тој фази један од најважнијих предуслова очувања интегритета изборног материјала јесте непрекидан и независан надзор над просторијама у којима се вреће налазе. Потенцијални ризици Ризик по интегритет изборног материјала може постојати ако: приступ просторији има ограничен круг лица; приступ није евидентиран; не постоји видео-надзор или се снимци не чувају; није могуће независно проверити да ли је неко приступао врећама; политички учесници немају могућност да прате чување материјала када закон то дозвољава или када би таква контрола представљала добру праксу; не постоји двострука контрола приликом сваког уласка у просторију; не води се евиденција о сваком приступу; није могуће утврдити ко је и када располагао изборним материјалом. Међународни стандарди Добра изборна пракса подразумева да се интегритет изборног материјала обезбеђује не само физичким обезбеђењем, већ и поступком који омогућава проверљивост. То укључује: евиденцију сваког приступа; јасан ланац одговорности; видео-надзор где је предвиђен; документовање сваког отварања просторије; могућност независне контроле поступања са изборним материјалом у складу са законом. Зашто је ово важно Само чување врећа у закључаној просторији није само по себи довољна гаранција интегритета материјала. Поверење у изборни поступак повећава се када постоје процедуре које омогућавају да се накнадно провери да ли је изборни материјал био под непрекидном контролом и да ли је сваки приступ био документован. 9.3. ПОРЕЂЕЊЕ КОПИЈЕ ЗАПИСНИКА И ОБЈАВЉЕНОГ РЕЗУЛТАТА Један од најважнијих постизборних контролних механизама јесте систематско поређење: копије записника коју је члан одбора преузео; скенираног оригинала који је објавила изборна комисија; података унетих у електронски систем; збирног резултата. Шта треба упоредити број уписаних бирача; број бирача који су гласали; број листића у кутији; број важећих и неважећих листића; број гласова сваке листе; примедбе; потписе; датум и време; накнадне исправке. Модел упоредне табеле Само неслагање не доказује нужно намерну манипулацију. Потребно је утврдити: када је настало; ко га је унео; да ли је исправка документована; да ли се исти образац понавља; у чију корист делује. 9.4. ПОСТУПАЊЕ ПО ПРИГОВОРУ Квалитетан приговор треба да буде: благовремен; поднет надлежном органу; чињенично прецизан; правно образложен; поткрепљен доказима; усмерен на конкретну радњу или одлуку; јасан у погледу захтева. Основна структура приговора назив надлежног органа; подаци подносиоца; предмет приговора; опис чињеница; време и место догађаја; правни основ; докази; објашњење утицаја неправилности; конкретан захтев; датум и потпис. Слабе формулације „Избори су покрадени.“ „Сви знају шта се догодило.“ „Резултат није реалан.“ „Било је много неправилности.“ Јаке формулације „Копија записника коју је члан бирачког одбора преузео у 22.15 часова садржи 214 гласова за листу број 4, док објављени електронски резултат садржи 241 глас.“ „На објављеном скену недостаје примедба која је видљива на копији потписаној на бирачком месту.“ „Врећа је примљена са оштећеном затворницом, што је наведено у примопредајном документу.“ 9.5. ПРОЦЕНА УТИЦАЈА ПОСТИЗБОРНЕ НЕПРАВИЛНОСТИ При процени значаја треба анализирати: број спорних гласова; разлику у резултату; утицај на изборни праг; утицај на број мандата; број погођених бирачких места; могућност понављања обрасца; степен очуваности материјала; постојање копије записника; могућност поновног бројања; поступање надлежног органа. Неправилност може бити значајна и када не мења укупног победника, ако мења: улазак листе у представничко тело; један мандат; већину у скупштини; статус мањинске листе; редослед кандидата; легитимност локалног резултата. 9.6. КАКО ПРЕПОЗНАТИ СИСТЕМСКИ ОБРАЗАЦ Постизборна неправилност добија системски карактер када се уоче: иста неслагања на више места; исти начин преправљања; исте особе у ланцу обраде; селективне исправке; одбијање увида у већем броју предмета; исти шаблон образложења; централизована измена у систему; истовремено кашњење по приговорима; изостанак трагова о изменама; политички једносмеран ефекат. За доказивање системског обрасца потребно је повезати: документе; временске линије; копије записника; електронске податке; сведочења; одлуке; статистичке показатеље. 9.7. ШТА НЕ ТРЕБА РАДИТИ У постизборној фази не треба: објављивати непроверене резултате као коначне; тврдити да је свака исправка фалсификат; јавно излагати личне податке; мењати оригиналне фајлове; слати једину копију доказа без резерве; улазити у службене просторије без овлашћења; отварати изборне вреће; узимати оригиналне документе; пропустити кратак рок за правно средство; ослањати се само на усмено обећање органа. 9.8. ЗАКЉУЧАК ПОГЛАВЉА Постизборна манипулација не мора бити спектакуларна. Често се састоји од једне промењене цифре, једне изостављене примедбе, једног неодржаног рока или једне недоступне коверте. Ипак, такве радње могу имати непосредан утицај на: резултат; расподелу мандата; могућност правне заштите; поверење грађана; легитимност изабраних органа. Поуздан постизборни поступак захтева: непрекидан ланац чувања; подударност свих верзија записника; потпун електронски траг; јавност резултата по бирачким местима; доступност изборног материјала; брзо и образложено одлучивање; једнаку примену критеријума; делотворно судско преиспитивање; безбедно чување доказа. ← BR — бројање гласова Студије случаја →"},{"title":"Практични обрасци — Атлас изборних манипулација","url":"pages/prakticni-obrasci.html","text":"Практични обрасци — Атлас изборних манипулација АТЛАС изборних манипулација Ћир Lat Почетна / Практични обрасци Практични део Практични обрасци Неопходни примери текстова и кратко упутство за бележење, документовање и правно оспоравање изборних неправилности. Практични алат Захтев за увид у изборни материјал Пример текста захтева за увид у изборни материјал и кратка упутства за његово прилагођавање. Отворите образац → Практични алат Приговор изборној комисији Универзална основа за приговор, са местом за чињенице, доказе и јасно одређен захтев. Отворите образац → Практични алат Службена белешка о уоченој неправилности Помоћни текст за благовремено и прецизно бележење догађаја током изборног дана. Отворите образац → Практични алат Записник о уоченој неправилности Структурисани пример за систематично документовање једне конкретне неправилности. Отворите образац → Практични алат Контролна листа за изборни дан Практичан подсетник за чланове бирачког одбора и посматраче током отварања и рада бирачког места. Отворите образац → Практични алат Дневник члана бирачког одбора или посматрача Хронолошка евиденција важних догађаја, реакција и расположивих доказа. Отворите образац → Практични алат Како документовати изборну неправилност Кратко завршно упутство које повезује обрасце и објашњава редослед поступања. Отворите образац → Напомена: Ови обрасци и упутства представљају практичне примере и помоћне алате. Нису законом прописани формулари и потребно их је прилагодити конкретном случају, важећем изборном законодавству, надлежности и роковима."},{"title":"Правни оквир — Атлас изборних манипулација","url":"pages/pravni-okvir.html","text":"Правни оквир — Атлас изборних манипулација АТЛАС изборних манипулација Ћир Lat Почетна / Правни оквир Поглавље 4 Правни оквир заштите изборног интегритета Уставне гаранције, изборни закони, правна средства, одговорност институција и практична правила за документовање и заштиту изборног права. 54 тематске целине 15 области правне заштите пуни текст поглавља Области I. УСТАВНЕ ОСНОВЕ II. ОСНОВНИ ИЗБОРНИ ЗАКОНИ III. ФИНАНСИРАЊЕ КАМПАЊЕ И ЈАВНИ РЕСУРСИ IV. МЕДИЈИ И ИНФОРМИСАЊЕ V. ЗАШТИТА ПОДАТАКА О ЛИЧНОСТИ VI. КРИВИЧНОПРАВНА ЗАШТИТА ИЗБОРНИХ ПРАВА VII. ПРЕКРШАЈНА, УПРАВНА И ДРУГА ОДГОВОРНОСТ VIII. ОРГАНИ ЗА СПРОВОЂЕЊЕ ИЗБОРА IX. ПОЛИЦИЈА И ЈАВНО ТУЖИЛАШТВО X. СУДСКА И ДРУГА ПРАВНА ЗАШТИТА XI. НАДЛЕЖНОСТИ ДРУГИХ ИНСТИТУЦИЈА XII. КОЈОЈ ИНСТИТУЦИЈИ СЕ ОБРАТИТИ XIII. ПРАКТИЧНИ МОДЕЛ ПРАВНЕ ОЦЕНЕ XIV. ОГРАНИЧЕЊА ПРАВНЕ ОЦЕНЕ XV. ЗАКЉУЧАК ПОГЛАВЉА Све целине 4.1. Сврха правног оквира 4.2. Изборно право 4.3. Друга уставна права значајна за изборе 4.4. Закон о избору народних посланика 4.5. Закон о локалним изборима 4.6. Закон о избору председника Републике 4.7. Закон о Јединственом бирачком списку 4.8. Подзаконски акти и упутства 4.9. Закон о финансирању политичких активности 4.10. Надлежност Агенције за спречавање корупције 4.11. Закон о спречавању корупције 4.12. Право бирача на обавештеност 4.13. Регулаторно тело за електронске медије 4.14. Политичко мишљење као посебна врста података 4.15. Паралелни спискови 4.16. Надлежност Повереника 4.17. Општа напомена 4.18. Повреда права кандидовања 4.19. Повреда права гласања 4.20. Давање и примање мита у вези са гласањем 4.21. Злоупотреба права гласања 4.22. Састављање нетачног бирачког списка 4.23. Спречавање одржавања гласања 4.24. Повреда тајности гласања 4.25. Фалсификовање резултата гласања 4.26. Уништавање изборних докумената 4.27. Друга кривична дела 4.28. Прекршајна одговорност 4.29. Одговорност члана бирачког одбора 4.30. Одговорност јавног службеника и функционера 4.31. Републичка изборна комисија 4.32. Локална изборна комисија 4.33. Бирачки одбор 4.34. Председник бирачког одбора 4.35. Када се обавештава полиција 4.36. Улога јавног тужиоца 4.37. Чување доказа 4.38. Изборни приговор 4.39. Уношење примедбе у записник 4.40. Увид у изборни материјал 4.41. Судска заштита 4.42. Министарство надлежно за државну управу 4.43. Агенција за спречавање корупције 4.44. Повереник за информације од јавног значаја и заштиту података о личности 4.45. Заштитник грађана 4.46. Инспекција рада 4.47. Повереник за заштиту равноправности 4.48. Јавна предузећа, установе и послодавци 4.49. Питања која треба поставити 4.50. Модел правног пасоша манипулације 4.51. Претпоставка невиности 4.52. Разлика између доказане радње и правне квалификације 4.53. Временско важење прописа 4.54. Обавеза ажурирања Правни оквир се не користи механички: навођење закона и члана не замењује утврђивање чињеница, надлежног органа, расположивог правног средства и рока за поступање. 4.1. Сврха правног оквира Правна оцена изборне неправилности не зависи само од тога да ли је нека радња политички или друштвено неприхватљива. Потребно је утврдити: која је конкретна радња предузета; ко ју је предузео; у којој фази изборног процеса; које право, правило или поступак су повређени; да ли је постојала намера; каква је последица наступила; који је орган надлежан за поступање; које правно средство стоји на располагању; у ком року се оно може употребити. Један догађај може истовремено представљати више различитих правних повреда. На пример, организовано прикупљање података о политичком опредељењу запослених може отворити питање: заштите података о личности; злоупотребе службеног положаја; дискриминације; повреде радних права; политичког притиска; финансирања политичких активности; кривичне одговорности, ако је праћено принудом, претњом или давањем користи. Исто тако, фотографисање гласачког листића не мора само по себи доказивати куповину гласа, али у вези са исплатом новца, паралелним списком и сведочењем бирача може представљати део ширег механизма контролисаног гласања. Зато правни оквир у овој публикацији не треба користити механички. Навођење закона и члана не замењује утврђивање чињеница. I. УСТАВНЕ ОСНОВЕ 4.2. Изборно право Устав Републике Србије гарантује право пунолетног држављанина да бира и да буде биран. Изборно право је опште и једнако, избори су слободни и непосредни, а гласање је тајно и лично. Устав такође предвиђа да изборно право ужива правну заштиту у складу са законом. Из ових начела произлазе четири основна захтева: Општост изборног права Свако лице које испуњава уставне и законске услове мора имати стварну могућност да гласа и да се кандидује. Повреде овог начела могу бити: незаконито брисање из бирачког списка; неосновано спречавање гласања; незаконито онемогућавање кандидовања; дискриминаторно поступање према појединим групама бирача. Једнакост изборног права Глас сваког бирача мора имати једнаку правну вредност. Једнакост се нарушава када: једно лице гласа више пута; неко гласа у име другог; додају се непостојећи гласови; одређеним бирачима се омогућава гласање мимо правила; гласови се различито вреднују супротно закону. Слобода избора Бирач мора одлуку донети без претње, принуде, куповине, контроле или незаконитог условљавања. Слобода није обезбеђена само одсуством физичке силе. Она може бити нарушена и претњом отказом, губитком социјалне помоћи, ускраћивањем јавне услуге, праћењем излазности или захтевом да бирач докаже за кога је гласао. Тајност и личност гласања Бирач гласа лично, а његов избор не сме бити доступан другим лицима. Ово начело повређују: гласање у туђе име; породично гласање; неовлашћено помагање; фотографисање листића као доказ трећем лицу; положај паравана који не обезбеђује тајност; праћење начина попуњавања листића; означавање или препознавање гласа бирача. Уставна гаранција изборног права из члана 52. представља основ за тумачење свих изборних закона и поступака. Устав гарантује и право грађана да буду истинито, потпуно и благовремено обавештени о питањима од јавног значаја, што је посебно важно за медијске услове изборне кампање. 4.3. Друга уставна права значајна за изборе Поред изборног права, изборни интегритет зависи и од поштовања: права на једнаку заштиту и правно средство; слободе мишљења и изражавања; слободе окупљања; слободе удруживања; права на приватност; права на заштиту података о личности; права на обавештеност; забране дискриминације; права на правично поступање пред државним органима. Изборна манипулација зато не мора бити изричито названа у изборном закону да би била правно релевантна. Радња може нарушити изборни процес преко повреде другог уставног права. II. ОСНОВНИ ИЗБОРНИ ЗАКОНИ 4.4. Закон о избору народних посланика Закон о избору народних посланика уређује избор народних посланика, органе за спровођење избора, кандидовање, гласање, утврђивање резултата и заштиту изборног права. За ову публикацију посебно су важне одредбе које се односе на: положај и надлежности Републичке изборне комисије; састав и рад локалних изборних комисија; састав и рад бирачких одбора; именовање чланова у сталном и проширеном саставу; уређење бирачких места; предају и чување изборног материјала; идентификацију бирача; тајност гласања; гласање ван бирачког места; утврђивање резултата; контролу записника; увид у изборни материјал; приговоре и друга средства правне заштите. Изменама из маја 2026. године уведен је, између осталог, систем обука за рад у локалним изборним комисијама и бирачким одборима, које организује Републичка изборна комисија, као и потврда о завршеној обуци са ограниченим роком важења. При коначној редакцији сваке појединачне манипулације потребно је навести тачан члан закона који важи у време конкретних избора. Бројеви чланова могу се мењати изменама закона, док основна правна обавеза остаје иста. 4.5. Закон о локалним изборима Закон о локалним изборима уређује избор одборника скупштина јединица локалне самоуправе. Основна начела локалних избора су: опште и једнако изборно право; слободни и непосредни избори; тајно и лично гласање. За локалне изборе посебно је значајно пребивалиште бирача на територији јединице локалне самоуправе у којој остварује изборно право. Зато законитост пријаве пребивалишта и тачност бирачког списка могу непосредно утицати на састав локалног бирачког тела. Закон уређује: локалну изборну комисију; бирачке одборе; проглашење изборних листа; положај мањинских листа; гласање; утврђивање резултата; понављање гласања; правну заштиту. Изменама из маја 2026. године предвиђени су нови услови у погледу обучености лица која се именују у органе за спровођење локалних избора. 4.6. Закон о избору председника Републике Овај закон уређује кандидовање и избор председника Републике. У великом делу поступка примењују се правила која се односе на: изборне органе; бирачки списак; уређење бирачког места; гласање; бројање; записнике; заштиту изборног права. Када се истовремено одржава више врста избора, посебно је важно јасно раздвојити: гласачке листиће; изводе из бирачког списка; контролне листове; записнике; коверте и пакете изборног материјала; резултате сваке врсте избора. Мешање материјала различитих избора може бити ненамерна грешка, али и средство прикривања неправилности. 4.7. Закон о Јединственом бирачком списку Јединствени бирачки списак је јавна исправа у којој се води јединствена евиденција држављана који имају бирачко право. Основна правила су: бирачки списак је сталан; редовно се ажурира; упис је услов за остваривање бирачког права; једно лице може бити уписано само једном; списак се води по службеној дужности; за његово вођење надлежно је министарство надлежно за послове управе. Правно релевантне промене у списку обухватају: упис; брисање; измену; допуну; исправку података; промену места гласања; промену пребивалишта; упис податка о гласању у иностранству или према месту боравишта, када су испуњени услови. Посебно треба разликовати: нетачан податак настао административном грешком; неблаговремено ажурирање службене евиденције; незакониту или фиктивну пријаву пребивалишта; намерно састављање нетачног бирачког списка ради утицања на изборе. Само постојање преминулог лица у неком приказу или обавештењу није довољно да се закључи да је његов глас злоупотребљен. Потребно је утврдити да ли је лице било у закљученом изводу, да ли постоји потпис, да ли је издат листић и да ли постоје други докази. Изменама из 2025. године уведени су додатни механизми увида, примедаба и ревизије тачности и ажурности бирачког списка. Чланови и заменици чланова Републичке изборне комисије добили су приступ посебном модулу за увид у податке, уз прописана ограничења и поступак подношења примедаба. 4.8. Подзаконски акти и упутства Закони прописују основна правила, док се бројна практична питања уређују: упутствима за спровођење избора; правилима о раду бирачких одбора; упутствима о примопредаји изборног материјала; роковницима; обрасцима; приручницима за рад изборних органа; одлукама изборних комисија; контролним формуларима за логичко-рачунско слагање резултата. Републичка изборна комисија објављује изборне законе, упутства, обрасце, записнике, роковнике и друга изборна документа. Контролор не треба да се ослања само на опште знање закона. За сваки изборни циклус мора да користи упутство и правила донета баш за те изборе. III. ФИНАНСИРАЊЕ КАМПАЊЕ И ЈАВНИ РЕСУРСИ 4.9. Закон о финансирању политичких активности Овим законом уређују се: извори финансирања политичких субјеката; финансирање редовног рада; финансирање изборне кампање; прикупљање прилога; коришћење јавних извора; изборни рачуни; евиденције; извештаји; контрола и санкције. Изборна кампања обухвата активности политичког субјекта као подносиоца проглашене изборне листе или предлагача кандидата. Правно спорне појаве могу бити: непријављени трошкови; фиктивне донације; посредно финансирање; плаћање кампање преко повезаних лица; бесплатне услуге које нису приказане; злоупотреба јавних ресурса; коришћење службених возила и запослених; прикривено плаћено оглашавање; финансирање страначке активности преко удружења или привредног субјекта. Изменама објављеним 10. јула 2026. године додатно су уређени кредити и зајмови политичких субјеката, коришћење средстава за редован рад и кампању, као и услови под којима се добра и услуге из јавних извора могу пружати политичким субјектима. Основно правило је да, када се јавна добра и услуге уступају политичким субјектима, морају бити доступни под једнаким условима. 4.10. Надлежност Агенције за спречавање корупције Агенција за спречавање корупције контролише финансирање политичких активности и поступање јавних функционера у законом утврђеним областима. Агенцији се могу пријавити сумње на: незаконито коришћење јавних ресурса; недозвољено поступање јавног функционера у кампањи; непријављене трошкове; недозвољене прилоге; нетачне или непотпуне извештаје; мешање јавне функције и политичке промоције. Пријава треба да садржи: име функционера или политичког субјекта; датум и место; опис радње; јавни ресурс који је коришћен; фотографију, снимак, документ или медијски прилог; податке о сведоцима; објашњење везе између службене активности и кампање. 4.11. Закон о спречавању корупције Јавни функционер не сме да користи јавне ресурсе за промоцију политичких странака или политичких субјеката. Под јавним ресурсима подразумевају се, између осталог: јавна имовина; службене просторије; возила; опрема; запослени; средства комуникације; средства буџета; добра која користе државни органи, локалне самоуправе, јавна предузећа и установе. Забрана се посебно односи на коришћење ресурса за: представљање изборног учесника; позивање да се гласа или не гласа; рад са бирачима и чланством; организацију скупова; израду и поделу материјала; политичко оглашавање; истраживање јавног мњења; маркетиншке, медијске и консултантске услуге; страначке обуке. Није свака службена активност функционера током кампање незаконита. Потребно је испитати: да ли је активност редовна или ванредно организована; ко је финансира; да ли садржи страначке поруке; да ли се користе страначка обележја; да ли медијско представљање ствара изборну предност; да ли су запослени обавезани да присуствују; да ли се јавна корист представља као лични поклон функционера. IV. МЕДИЈИ И ИНФОРМИСАЊЕ 4.12. Право бирача на обавештеност Слободно гласање претпоставља да бирач има приступ различитим политичким ставовима и релевантним информацијама. Правно су значајни: тачност информација; раздвајање вести и оглашавања; означавање плаћеног садржаја; равноправно представљање изборних учесника; забрана дискриминације; правила изборне тишине; право на одговор и исправку; посебне обавезе јавних медијских сервиса. Неравноправност се не процењује само по броју минута. Важно је и: да ли је тон позитиван, неутралан или негативан; да ли учесник говори непосредно или се о њему само говори; да ли се један актер приказује у службеној и страначкој улози; да ли се политички противници систематски дискредитују; да ли се прикривена пропаганда представља као новинарски садржај. 4.13. Регулаторно тело за електронске медије Регулаторно тело за електронске медије поступа у оквиру надлежности које се односе на пружаоце медијских услуга. Пријава медијске повреде треба да садржи: назив медија; назив емисије; датум и тачно време; опис садржаја; снимак или везу ка снимку; назнаку правила које је могуће повређено; објашњење зашто садржај представља прикривено оглашавање, неравноправан третман, говор мржње или другу повреду. Општа тврдња да је медиј пристрасан има мању процесну вредност од прецизно документованог прилога. V. ЗАШТИТА ПОДАТАКА О ЛИЧНОСТИ 4.14. Политичко мишљење као посебна врста података Подаци који откривају политичко мишљење спадају у посебне врсте података о личности. Њихова обрада је начелно забрањена, осим у законом прописаним изузетним случајевима. Обрада подразумева: прикупљање; бележење; разврставање; повезивање; чување; достављање; коришћење; брисање; сваку другу радњу над подацима. Изборно релевантне повреде могу постојати када се воде спискови који повезују: име и презиме; адресу; број телефона; радно место; чланове породице; политичко опредељење; податак да ли је лице гласало; податак о примљеној помоћи; име активисте задуженог за лице. 4.15. Паралелни спискови Постојање сваког страначког списка није аутоматски незаконито. Политичка организација може под одређеним условима обрађивати податке својих чланова и лица која су јој податке добровољно дала. Међутим, посебан правни ризик постоји када су подаци: преузети из службене евиденције; добијени без знања лица; прикупљени под притиском; повезани са запослењем или јавном услугом; достављени неовлашћеним лицима; коришћени за контролу излазности; коришћени за награђивање или кажњавање. 4.16. Надлежност Повереника Поверенику за информације од јавног значаја и заштиту података о личности могу се пријавити сумње на незакониту обраду личних података. Корисно је приложити: фотографију или копију списка, уз заштиту података трећих лица; поруку којом се подаци траже; упутство за унос података; назив организације или органа који их прикупља; сврху која је наведена; податак о томе одакле су подаци вероватно преузети; доказ да лице није дало пристанак; опис евентуалног притиска. Спискове са личним подацима не треба јавно објављивати у целини. Доказ треба доставити надлежном органу уз одговарајућу заштиту. VI. КРИВИЧНОПРАВНА ЗАШТИТА ИЗБОРНИХ ПРАВА 4.17. Општа напомена Није свака изборна неправилност кривично дело. За кривичну одговорност потребно је да: радња одговара законском опису кривичног дела; постоји одговарајући облик кривице; постоје докази; нема околности које искључују противправност или кривицу. Кривична пријава може се поднети полицији или јавном тужилаштву. Подносилац не мора правно савршено да квалификује дело. Важније је да тачно опише чињенице и достави доказе. 4.18. Повреда права кандидовања Кривична одговорност може постојати када неко кршењем закона или другим противправним поступањем спречи или омета кандидовање на изборима. Могући примери: противправно онемогућавање подношења листе; уништавање документације; претње кандидатима или потписницима; злоупотреба службеног поступка ради спречавања кандидовања. 4.19. Повреда права гласања Ово дело може постојати када неко: противзаконито не упише лице у бирачки списак; избрише га; на други противправан начин спречи или омета гласање; силом или претњом принуди лице да гласа или не гласа; принуди га да гласа за или против одређеног кандидата или предлога. Кривични законик разликује спречавање гласања од принуде у погледу начина гласања. 4.20. Давање и примање мита у вези са гласањем Кривично дело може извршити лице које другоме: понуди; да; обећа награду, поклон или другу корист да гласа, не гласа или гласа за или против одређеног лица или предлога. Одговорност може постојати и на страни лица које корист захтева или прима. Није неопходно да обећана корист заиста буде исплаћена нити да бирач гласа на договорени начин. Правно је значајно и само нуђење или обећање користи са одговарајућом намером. Када дело изврши члан бирачког одбора или друго лице у вршењу дужности у вези са гласањем, закон предвиђа строже кажњавање. 4.21. Злоупотреба права гласања Кривична одговорност може постојати када лице: гласа уместо другога под његовим именом; гласа више од једном; употреби више од једног гласачког листића. Посебна одговорност предвиђена је за члана бирачког одбора који другом омогући такво поступање. Ово дело може бити повезано са: туђим идентификационим документом; лажним потписом; неизвршеном провером прста; издавањем више листића; сарадњом чланова бирачког одбора. 4.22. Састављање нетачног бирачког списка Кривичноправна одговорност може постојати када лице, у намери да утиче на резултат избора, сачини нетачан бирачки списак. Кључна је намера утицања на резултат. Административна грешка или неблаговремено ажурирање не представљају аутоматски ово кривично дело. 4.23. Спречавање одржавања гласања Кривично дело може постојати када неко силом, претњом или другим противправним начином спречи гласање на бирачком месту. Посебно је уређено и ометање гласања изазивањем нереда због којег гласање буде прекинуто. 4.24. Повреда тајности гласања Тајност може бити повређена: посматрањем начина гласања; откривањем садржаја гласа; обележавањем листића тако да се бирач може препознати; принудним фотографисањем; организованим породичним гласањем; неовлашћеним присуством иза паравана. Када повреду изврши члан бирачког одбора или друго лице које врши дужност у вези са гласањем, одговорност је тежа. 4.25. Фалсификовање резултата гласања Ово је једно од најтежих изборних кривичних дела. Може га извршити члан органа за спровођење избора или друго лице које врши дужност у вези са гласањем ако: додаје гласачке листиће или гласове; одузима листиће или гласове; мења број листића; мења број гласова; на други начин измени резултат; објави неистинит резултат. У ову категорију могу ући: убацивање листића; уништавање гласова; намерно нетачно бројање; замена резултата изборних листа; преправљање записника; неистинит електронски унос; објављивање резултата различитих од утврђених. Кривични законик кривична дела против изборних права уређује у посебној глави, укључујући повреду кандидовања, права гласања, изборно подмићивање, злоупотребу гласања, нетачне бирачке спискове, спречавање гласања, повреду тајности и фалсификовање резултата. 4.26. Уништавање изборних докумената Кривичноправно релевантно може бити уништавање, оштећивање, прикривање или одузимање: гласачких листића; извода из бирачког списка; записника; контролних листова; уверења; друге изборне документације. Посебно је важно одмах обезбедити доказ о последњем познатом стању материјала, лицима која су њиме располагала и времену када је нестанак или оштећење уочено. 4.27. Друга кривична дела У зависности од околности, изборна манипулација може садржати и елементе других кривичних дела, као што су: злоупотреба службеног положаја; трговина утицајем; примање или давање мита; фалсификовање исправе; принуда; угрожавање сигурности; неовлашћено прикупљање личних података; повреда равноправности; насилничко понашање; удруживање ради вршења кривичних дела. Давање и примање мита у вези са гласањем изричито је обухваћено и законом који уређује посебну организацију државних органа за сузбијање корупције, у оквиру услова прописаних тим законом. VII. ПРЕКРШАЈНА, УПРАВНА И ДРУГА ОДГОВОРНОСТ 4.28. Прекршајна одговорност Поједина поступања која не представљају кривично дело могу бити прекршаји. Прекршајна одговорност може бити прописана: изборним законима; законом о финансирању политичких активности; законом о спречавању корупције; медијским прописима; прописима о заштити података; прописима о јавном реду и миру; другим посебним законима. Пријава треба да буде поднета органу који је надлежан за покретање или вођење одговарајућег поступка. 4.29. Одговорност члана бирачког одбора Члан бирачког одбора може сносити: одговорност у оквиру изборног поступка; прекршајну одговорност; кривичну одговорност; радноправну или дисциплинску одговорност, ако је релевантно; политичку одговорност према предлагачу. Члан бирачког одбора није ослобођен одговорности зато што је поступао по налогу председника одбора, страначког координатора или другог лица. Очигледно незаконит налог не треба извршити. 4.30. Одговорност јавног службеника и функционера Јавни службеник или функционер може сносити одговорност ако: користи службене податке за страначке потребе; условљава запослене; користи јавне ресурсе; наређује политичке активности; врши одмазду; злоупотребљава службена овлашћења; спречава пријављивање неправилности. У зависности од радње, надлежни могу бити: Агенција за спречавање корупције; инспекција рада; управна инспекција; Повереник; Заштитник грађана; полиција; јавно тужилаштво; суд. VIII. ОРГАНИ ЗА СПРОВОЂЕЊЕ ИЗБОРА 4.31. Републичка изборна комисија Републичка изборна комисија има централну улогу у спровођењу парламентарних и председничких избора и обавља законом утврђене послове који се односе и на општи изборни оквир. Њене надлежности обухватају, у зависности од врсте избора: доношење упутстава; прописивање образаца; координацију изборних органа; проглашење изборних листа; утврђивање и објављивање резултата; одлучивање у изборним поступцима; обезбеђивање изборног материјала; обуке изборних органа; објављивање докумената и података. РИК није орган кривичног гоњења. Када постоји сумња на кривично дело, изборна комисија не замењује полицију и тужилаштво. 4.32. Локална изборна комисија Локална изборна комисија: организује локалне изборе; именује бирачке одборе; прима изборни материјал; контролише записнике; утврђује резултате; одлучује о питањима из своје надлежности; омогућава увид када закон то предвиђа; поступа по правним средствима у оквиру закона. Када се истовремено спроводи више избора, надлежности различитих изборних комисија морају се пажљиво разграничити. 4.33. Бирачки одбор Бирачки одбор непосредно спроводи гласање на бирачком месту. Он је одговоран за: пријем и контролу материјала; уређење бирачког места; отварање; проверу бирача; издавање листића; тајност гласања; одржавање реда; гласање ван бирачког места; затварање; бројање; попуњавање записника; паковање и предају материјала. Сваки члан има право и обавезу да прати цео поступак. Одлука већине не може учинити законитом радњу која је супротна закону. 4.34. Председник бирачког одбора Председник организује рад бирачког одбора, али није једини носилац изборних овлашћења. Он не сме: самостално одлучивати о свим питањима; удаљити члана без правног основа; ускратити увид у материјал; одбити уношење примедбе; сам попуњавати или мењати резултат; тражити потписивање празног записника; предати материјал супротно прописаном поступку. IX. ПОЛИЦИЈА И ЈАВНО ТУЖИЛАШТВО 4.35. Када се обавештава полиција Полицију треба обавестити када постоји: насиље; претња; нарушавање јавног реда; спречавање гласања; уништавање или крађа материјала; неовлашћено оружје; физичко застрашивање; организована куповина гласова у току; лице затечено у радњи која може представљати кривично дело; непосредна опасност по људе или материјал. Члан бирачког одбора не треба сам да спроводи истрагу, претреса лица, одузима телефон или употребљава силу, осим у границама општих правила нужне одбране и крајње нужде. 4.36. Улога јавног тужиоца Јавно тужилаштво руководи предистражним поступком и одлучује о кривичном гоњењу. Тужилаштву треба доставити: прецизан опис; датум и време; место; лица која су учествовала; имена сведока; фотографије и снимке; службене документе; податак о томе где се налази оригинал; податак да ли је полиција обавештена; опис могуће опасности од уништења доказа. Подносилац пријаве не мора да зна тачан члан Кривичног законика. Треба избегавати преувеличавање и ограничити се на проверљиве чињенице. 4.37. Чување доказа Код аудио-визуелних и дигиталних доказа треба: сачувати оригинални фајл; не мењати назив и садржај без потребе; направити резервну копију; забележити ко је аутор; забележити време и место; не објављивати цео материјал пре предаје надлежнима ако би то угрозило поступак; сачувати поруке, позиве и метаподатке; водити белешку о томе коме је копија предата. X. СУДСКА И ДРУГА ПРАВНА ЗАШТИТА 4.38. Изборни приговор Приговор служи за заштиту изборног права у оквиру изборног поступка. Он мора бити: поднет овлашћеном органу; поднет у прописаном року; довољно одређен; заснован на конкретној радњи; поткрепљен расположивим доказима. У приговору треба навести: подносиоца; изборе и бирачко место; радњу или одлуку која се оспорава; време када се догодила; лица која су учествовала; повређено правило; доказе; захтев подносиоца. Најчешћа грешка је чекање да се прикупе сви могући докази док рок за приговор истекне. Приговор треба поднети у року са доступним доказима, уз јасно навођење осталих доказа до којих орган може доћи. 4.39. Уношење примедбе у записник Примедба у записнику је један од најважнијих начина непосредног документовања догађаја на бирачком месту. Примедба треба да буде конкретна. Није довољно написати: „Било је много неправилности.“ Треба написати: „У 14.35 часова члан бирачког одбора издао је гласачки листић лицу које није претходно потписало извод из бирачког списка. На пропуст су указали чланови А и Б. Листић је предат бирачу пре отклањања неправилности.“ Примедба треба да садржи: време; радњу; лице; реакцију одбора; доказ; исход; име члана који захтева унос. 4.40. Увид у изборни материјал Увид може бити пресудан за проверу: записника; потписа; броја листића; важећих и неважећих гласова; правилности паковања; неслагања објављених резултата; накнадних исправки. При увиду треба водити сопствену белешку и тражити да се јасно евидентира: датум; време; присутна лица; материјал који је отворен; стање печата и паковања; уочено неслагање; фотографије или копије које су дозвољене; евентуално одбијање приступа. 4.41. Судска заштита Судска заштита зависи од врсте избора и одлуке која се оспорава. За изборне спорове могу бити надлежни судови одређени посебним изборним законом, док се за друга питања могу водити: управни поступак; управни спор; кривични поступак; прекршајни поступак; парнични поступак; поступак за заштиту података; радни спор. Не треба претпоставити да један поступак искључује све друге. Иста радња може бити предмет изборног приговора и кривичне пријаве, јер та два поступка имају различиту сврху. XI. НАДЛЕЖНОСТИ ДРУГИХ ИНСТИТУЦИЈА 4.42. Министарство надлежно за државну управу Надлежно је за вођење Јединственог бирачког списка и поступање у вези са: уписом; брисањем; изменама; исправкама; закључењем списка; анализом тачности и усаглашености; другим пословима прописаним законом. 4.43. Агенција за спречавање корупције Надлежна је за: контролу финансирања политичких активности; извештаје о трошковима кампање; поступање јавних функционера; злоупотребу јавних ресурса у оквиру својих законских овлашћења. 4.44. Повереник за информације од јавног значаја и заштиту података о личности Надлежан је за: незакониту обраду личних података; неовлашћено прикупљање политичких ставова; злоупотребу службених база; приступ подацима од јавног значаја; друга питања из своје надлежности. 4.45. Заштитник грађана Може испитивати поступање органа управе и повреде права грађана када су испуњени услови из закона којим је уређен његов рад. Он не замењује изборну комисију, суд, полицију или тужилаштво, али може бити значајан код: системских пропуста управе; неједнаког поступања; непоступања органа; повреде права осетљивих група. 4.46. Инспекција рада Надлежна је за повреде радних права, нарочито када су политички притисци повезани са: отказом; премештајем; радним временом; принудним одласком на скупове; незаконитим налогом послодавца; дискриминацијом у радном односу. 4.47. Повереник за заштиту равноправности Може поступати када политичко опредељење или претпостављено опредељење доведе до дискриминаторног поступања у областима обухваћеним законом. 4.48. Јавна предузећа, установе и послодавци Организација у којој се притисак врши има обавезу да поступа у складу са: радним прописима; забраном дискриминације; заштитом узбуњивача; заштитом података; правилима о политичкој неутралности, када су применљива; интерним процедурама. Интерна пријава не треба да буде једини корак ако је руководилац организације управо лице које врши притисак. XII. КОЈОЈ ИНСТИТУЦИЈИ СЕ ОБРАТИТИ Ова табела је оријентациона. У конкретном случају може бити потребно истовремено обраћање већем броју органа. XIII. ПРАКТИЧНИ МОДЕЛ ПРАВНЕ ОЦЕНЕ 4.49. Питања која треба поставити За сваки пријављени догађај потребно је одговорити на следећа питања: Ко? бирач; члан бирачког одбора; функционер; службеник; страначки активиста; послодавац; неовлашћено лице; медиј; правно лице. Шта? давање новца; претња; гласање у туђе име; преправљање документа; незаконита обрада података; издавање више листића; ускраћивање права; коришћење јавног ресурса. Где? на бирачком месту; испред бирачког места; у јавном предузећу; у установи; у страначком штабу; током транспорта; у изборној комисији; у информационом систему. Када? пре расписивања; током кампање; на дан гласања; током бројања; након предаје материјала; у поступку по приговору. Како? силом; претњом; обманом; давањем користи; злоупотребом овлашћења; фалсификовањем; техничком интервенцијом; пропуштањем дужне радње. Са којом последицом? лице није гласало; гласало је под притиском; нарушена је тајност; додати су гласови; одузети су гласови; промењен је записник; онемогућена је контрола; изборни учесник је стекао незакониту предност. Који докази постоје? службени записник; фотографија; снимак; порука; документ; сведок; електронски траг; копија резултата; подаци из више извора. 4.50. Модел правног пасоша манипулације За сваку манипулацију у даљем тексту публикације користиће се следећа структура: Шифра и назив: BM-03 — Гласање у туђе име Основно заштићено право: Личност и једнакост гласања. Могућа правна повреда: Повреда изборног закона и могуће кривично дело злоупотребе права гласања. Могући учиниоци: Бирач, лице чији се идентитет користи, члан бирачког одбора, организатор. Надлежни орган на лицу места: Бирачки одбор. Надлежни орган за изборну заштиту: Одговарајућа изборна комисија и надлежни суд. Надлежни орган за кривичну одговорност: Полиција и јавно тужилаштво. Кључни докази: Идентификациони документ, извод из бирачког списка, потпис, видео-запис, сведоци, примедба у записнику. Хитна радња: Зауставити издавање листића до законите провере идентитета, обавестити цео бирачки одбор и унети догађај у записник. Шта се не сме радити: Самовољно задржавати лице, одузимати документ или употребљавати силу, осим када поступа надлежни орган. XIV. ОГРАНИЧЕЊА ПРАВНЕ ОЦЕНЕ 4.51. Претпоставка невиности Ниједно лице не треба у публикацији означити као учиниоца кривичног дела ако његова одговорност није утврђена правноснажном одлуком. Дозвољене формулације су: „постоји сумња“; „према наводима сведока“; „документована је неправилност“; „поднета је кривична пријава“; „поступак је у току“; „радња може имати елементе кривичног дела“. 4.52. Разлика између доказане радње и правне квалификације Може бити поуздано доказано да је лице дало новац бирачу, али је за правну квалификацију потребно утврдити због чега је новац дат. Може бити доказано да је записник исправљен, али је потребно утврдити: ко га је исправио; када; зашто; да ли су чланови били присутни; да ли је исправка била дозвољена; да ли је промењен стварни резултат. Зато се чињенични и правни закључак увек наводе одвојено. 4.53. Временско важење прописа Правна оцена конкретног случаја врши се према пропису који је важио у време догађаја. Накнадна измена закона не може се аутоматски применити на ранији изборни поступак. У студијама случаја зато треба навести: датум избора; пропис који је тада важио; касније измене, ако су релевантне; правни положај према тадашњим, а не данашњим правилима. 4.54. Обавеза ажурирања Пре објављивања сваког издања ове публикације потребно је проверити: последњи пречишћени текст изборних закона; измене Кривичног законика; важећа упутства РИК-а; рокове за правну заштиту; надлежност судова; прописе о финансирању; медијске прописе; прописе о заштити података; нову судску праксу. На насловној или импресумској страни треба навести: Правни оквир ажуриран закључно са: [датум]. XV. ЗАКЉУЧАК ПОГЛАВЉА Правни систем Републике Србије предвиђа више облика заштите изборног права: заштиту пред бирачким одбором; приговор изборној комисији; судску заштиту; кривичноправну заштиту; прекршајну одговорност; контролу финансирања кампање; заштиту података о личности; радноправну и антидискриминациону заштиту; контролу јавних функционера и јавних ресурса. Највећи практични проблем често није потпуно одсуство правних правила, већ: неблаговремено пријављивање; непотпуна документација; пропуштање кратких рокова; нејасно разграничење надлежности; селективно или споро поступање; страх сведока; губитак или уништавање доказа; свођење системског обрасца на појединачни изоловани случај. Зато правна заштита почиње на месту настанка неправилности: тачним бележењем времена, лица, радње, доказа и реакције надлежних. Најјача пријава није она која користи најтеже политичке изразе, већ она која садржи најпрецизније и најпроверљивије чињенице. Следи детаљна анализа изборних манипулација: ↑ На врх странице"},{"title":"PRE — Манипулације пре избора","url":"pages/pre.html","text":"PRE — Манипулације пре избора АТЛАС изборних манипулација Ћир Lat Почетна / PRE — пре избора PRE Манипулације пре избора Комплетан текст петог поглавља Атласа изборних манипулација: увод, тринаест предизборних манипулација, њихова повезаност, контролна питања и закључак. Изаберите фазу изборног процеса: PRE Пре избора KAM Током кампање BM На бирачком месту BR Током бројања POST Након избора 5.1. Зашто је предизборна фаза пресудна Интегритет избора не зависи само од онога што се дешава на бирачком месту. Значајан део могућих манипулација настаје недељама, месецима, па и годинама пре дана гласања. У овој фази формирају се: састав бирачког тела услови за кандидовање састав изборних органа институционална предност појединих политичких актера зависност запослених и корисника јавних услуга базе података о политичком опредељењу грађана механизми за контролу и мобилизацију бирача. Предизборне манипулације често не остављају један јасан и непосредан доказ. Оне се препознају кроз повезивање већег броја података: наглих промена пребивалишта, подударних сведочења, интерних спискова, службених налога, статистичких промена и начина поступања институција. ODIHR је у извештајима о изборима у Србији више пута указивао на потребу ревизије бирачког и грађанских регистара, спречавања притисака на запослене у јавном сектору, раздвајања државних и страначких активности и спречавања злоупотребе јавних ресурса. Преглед PRE манипулација PRE-01 Незаконите или спорне промене у бирачком списку PRE-02 Организовано пријављивање пребивалишта ради гласања PRE-03 Онемогућавање или отежавање кандидовања PRE-04 Лажне или контролисане изборне листе PRE-05 Злоупотреба статуса мањинске изборне листе PRE-06 Неравноправан или контролисан састав изборних органа PRE-07 Притисци на запослене пре почетка кампање PRE-08 Незаконито прикупљање података о политичком опредељењу PRE-09 Стварање политичке зависности кроз запошљавање и јавна давања PRE-10 Заробљавање институција важних за изборни процес PRE-11 Манипулација редоследом изборних листа PRE-12 Онемогућавање контроле над штампањем, паковањем, примопредајом и чувањем изборног материјала PRE-13 Координисано постављање привидно независних контролора PRE-01 Незаконите или спорне промене у бирачком списку Кратка дефиниција Незаконита или спорна промена у бирачком списку постоји када се лице неосновано упише, избрише, премести или му се промене подаци на начин који може утицати на остваривање изборног права или на састав бирачког тела. Фаза изборног процеса Припрема избора и период до закључења бирачког списка. Заштићена вредност општо и једнако изборно право тачност бирачког списка право грађанина да гласа поверење у изборни процес законит састав локалног бирачког тела. Правни основ Јединствени бирачки списак је јавна исправа, води се као стална евиденција, редовно се ажурира, а један бирач може бити уписан само једном. Упис је услов за остваривање бирачког права. За вођење списка надлежно је министарство надлежно за послове управе, док се промене врше у законом прописаном поступку. Како манипулација може функционисати Могући облици су: упис лица које не испуњава услове брисање бирача без законског основа промена бирачког места без знања бирача упис на адреси на којој лице стварно нема пребивалиште вишеструки упис истог лица задржавање лица у списку и након промене релевантних чињеница намерно одлагање исправке података нетачно повезивање бирача са бирачким местом масовне промене података непосредно пре избора злоупотреба података из других службених евиденција. Како је препознати Могући показатељи су: бирач не постоји на месту на којем је раније гласао бирач је распоређен на удаљено или нелогично бирачко место на једној адреси пријављен је неуобичајено велики број лица број бирача у кратком року значајно расте или опада различити службени извори садрже различите податке захтеви за исправку остају нерешени више грађана пријављује истоветан проблем промене су концентрисане у изборно осетљивим срединама бирачи добијају позиве за лица која на адреси не живе. Ниједан од ових показатеља сам по себи не доказује манипулацију. Он представља основ за проверу. Како документовати Потребно је сачувати: обавештење о гласању претходно и ново бирачко место решење о промени, ако постоји доказ о поднетом захтеву за исправку датум подношења и одговор органа фотографију поштанског сандучета са више обавештења, уз заштиту личних података изјаву лица које живи на спорној адреси податке о броју пријављених лица, ако су законито прибављени службену преписку одлуку надлежног органа. Не треба јавно објављивати ЈМБГ, број личне карте, пуне адресе и друге осетљиве податке. Могући учесници овлашћени службеници лица која пријављују нетачне податке посредници страначки активисти друга лица која организују промене пребивалишта лица која злоупотребљавају службене евиденције. Надлежне институције надлежна општинска или градска управа министарство надлежно за државну управу Републичка изборна комисија, у оквиру изборних надлежности Повереник за заштиту података о личности полиција и јавно тужилаштво, ако постоји сумња на намерно противправно поступање надлежни суд. Процена утицаја Висок, а када су промене организоване и масовне — системски. Јачина доказа Најјачи докази су: службено решење извод из службене евиденције упоредни подаци пре и после промене више сагласних службених докумената правноснажна одлука доказана повезаност већег броја промена. Хитна реакција Бирач треба одмах да провери податке и поднесе захтев за исправку у прописаном року. Ако је изборни поступак већ започео, треба паралелно обавестити овлашћеног предлагача и правни тим који прати изборе. Шта не треба радити проглашавати сваку административну грешку изборном преваром објављивати целе спискове са личним подацима улазити у приватне објекте ради провере адресе узнемиравати лица која су пријављена на спорној адреси изводити закључак само на основу презимена или броја на поштанском сандучету. Савет контролору и истраживачу Најважније је направити временску линију: када је промена извршена, на основу ког документа, ко је донео решење и да ли је лице заиста гласало. Само присуство у евиденцији није исто што и злоупотребљен глас. ↑ Назад на преглед PRE-02 Организовано пријављивање пребивалишта ради гласања Кратка дефиниција Организовано пријављивање пребивалишта ради гласања постоји када се већи број лица формално пријављује на адресама у одређеној изборној јединици како би стекао право да гласа на локалним изборима, иако тамо нема стварно животно средиште. Заштићена вредност законит састав локалног бирачког тела једнакост изборног права аутентично представљање локалне заједнице поверење у бирачки списак. Како функционише Могући механизам обухвата: избор адреса погодних за масовне пријаве прикупљање личних докумената и података формално пријављивање пребивалишта упис у локални бирачки списак организовани превоз на дан избора усмеравање бирача ка одређеним бирачким местима контролу њиховог доласка и гласања. Показатељи велики број нових пријава на једној адреси лица која не познају место или адресу организовани долазак аутобусима и комбијима идентична упутства код више лица велики број пријава у кратком периоду необично повећање бирачког тела без демографског разлога адресе објеката који не могу реално примити толико станара сведочења власника или станара да лица тамо не живе. Правна оцена Промена пребивалишта сама по себи није незаконита. Неопходно је доказати да је пријава била фиктивна или да су службени поступци злоупотребљени. Кључно питање није само где је лице пријављено, већ да ли се на тој адреси стварно настанило са намером да тамо стално живи. Документовање Корисни су: службени подаци о броју промена упоређивање података кроз време сведочења станара фотографије организованог превоза снимци упутстава организатора подаци о времену пријаве решења надлежних органа подаци о већем броју лица повезаних са истом адресом. Надлежне институције Министарство унутрашњих послова министарство надлежно за државну управу изборне комисије полиција и тужилаштво суд Повереник, ако постоји злоупотреба личних података. Процена утицаја Системски, нарочито на локалним изборима са малом разликом у резултату. Савет Не треба користити израз „фантомски бирач“ као утврђену чињеницу док се не провере правни статус пребивалишта и службени документи. ↑ Назад на преглед PRE-03 Онемогућавање или отежавање кандидовања Кратка дефиниција Ова манипулација обухвата незаконито или селективно коришћење поступка кандидовања ради спречавања, одлагања или отежавања учешћа одређеног изборног учесника. Могући облици неједнака примена услова неоправдано одбијање документације произвољна провера потписа онемогућавање овере захтевање докумената који нису законом предвиђени селективно толерисање недостатака притисак на кандидате или потписнике злоупотреба потписа подршке намерно одлагање одлуке до истека рокова. Показатељи различито поступање према сличним листама неуобичајено кратак рок за отклањање недостатака образложење без јасног правног основа одбијање пријема документације службеник усмено поставља додатне услове кандидати или потписници повлаче подршку након притиска исти недостатак једној листи се толерише, а другој не. Документовање Потребно је сачувати: сву предату документацију потврду о пријему време предаје решење и образложење доказ о покушају овере преписку изјаве сведока поређење са поступањем према другим листама. Надлежне институције надлежна изборна комисија суд надлежан за изборну заштиту полиција и тужилаштво, ако постоје претње, фалсификовање или злоупотреба положаја Повереник за заштиту равноправности, ако постоји дискриминација. Процена утицаја Висок, јер може утицати на саму могућност политичког такмичења. Шта не треба радити Не треба сваки формални недостатак представљати као политичко онемогућавање. Потребно је утврдити да ли је правило било јасно, законито и једнако примењено. ↑ Назад на преглед PRE-04 Лажне или контролисане изборне листе Кратка дефиниција Реч је о листама које формално наступају као самостални политички учесници, али су стварно организоване, финансиране или контролисане ради користи другог изборног учесника. Могући циљеви стварање привида политичког плурализма збуњивање бирача сличним називом расипање гласова добијање места у проширеном саставу изборних органа повећање броја формално независних контролора напад на конкретног конкурента коришћење привилегованог статуса мањинске листе. Показатељи исти организатори, адресе или контакт-лица заједничка инфраструктура исти донатори или пружаоци услуга кандидати без познавања програма сопствене листе контролори који поступају у корист другог учесника истоветни потписи, документа или техничке грешке међусобно координисано наступање одсуство стварне кампање. Доказни проблем Политичка блискост није доказ контроле. За озбиљну тврдњу потребно је показати организациону, кадровску, финансијску или оперативну везу. Документовање уговори и финансијски извештаји подаци о донаторима адресе седишта заједнички активисти снимци координације преписка поступање чланова изборних органа подударности у документацији. Процена утицаја Висок или системски, посебно када се преко таквих листа утиче на састав изборне администрације. ↑ Назад на преглед PRE-05 Злоупотреба статуса мањинске изборне листе Кратка дефиниција Злоупотреба постоји када листа користи права и погодности намењене представљању националне мањине, а нема стварну и уверљиву везу са политичким представљањем те заједнице. Могући мотиви повољнији услови расподеле мандата нижи праг практичног уласка у представничко тело стварање додатних изборних листа заобилажење општих правила стицање места у изборним органима. Показатељи кандидати и организатори немају јавну везу са мањинском заједницом програм се не односи на положај мањине листа се активира само пред изборе исти организатори су раније наступали у другом својству мањинске организације оспоравају репрезентативност финансијске или кадровске везе са другом странком. Правна напомена Не постоји један једноставан тест „аутентичности“. Одлука мора бити заснована на закону и проверљивим критеријумима, без дискриминације и произвољног процењивања идентитета кандидата. Процена утицаја Висок. ↑ Назад на преглед PRE-06 Неравноправан или контролисан састав изборних органа Кратка дефиниција Ова манипулација обухвата формално законито, али фактички координисано попуњавање изборних комисија и бирачких одбора лицима која поступају у интересу истог политичког центра. Како функционише више формално различитих листа предлаже повезана лица чланови добијају налоге од лица које их формално није предложило контролори не долазе или препуштају место другим лицима предлози за именовање се намерно достављају неисправно поједини чланови немају приступ обуци и материјалу смене се врше непосредно пред изборе један изборни учесник страна контролише кључне функције. Показатељи идентични контакт-подаци исти координатори заједнички превоз и инструкције чланови не знају ко их је предложио поступање више формално различитих чланова по истом налогу неуобичајено честа замена опозиционих чланова ограничен приступ седницама или документима. Документовање решења о именовању спискови чланова изјаве именованих лица поруке са инструкцијама подаци о заменама записници са седница докази о онемогућеној обуци или приступу. Процена утицаја Висок или системски. ODIHR је у више циклуса препоручивао стандардизовану обуку свих чланова локалних изборних комисија и бирачких одбора, као и већу доследност и професионалност изборне администрације. ↑ Назад на преглед PRE-07 Притисци на запослене пре почетка кампање Кратка дефиниција Политички притисак постоји када се од запосленог захтева или очекује политичка подршка, активизам или обезбеђивање гласова, уз непосредну или посредну претњу последицама по радни статус, приход или професионални положај. Најчешћи облици тражење списка „сигурних гласова“ условљавање продужења уговора захтев за присуство скупу обавеза прикупљања потписа ангажовање током радног времена позивање са службеног телефона праћење чланова породице условљавање напредовања претња премештајем или отказом захтев да се фотографијом или другим средством докаже гласање. Посебно угрожене групе запослени на одређено време лица ангажована преко привремених уговора запослени у јавним предузећима корисници социјалних програма лица зависна од локалних дозвола или субвенција запослени код приватних послодаваца зависних од јавних послова. Показатељи исти захтев упућен већем броју запослених табеле са квотама извештавање руководиоцу састанци у радно време службени имејл или група за страначке налоге претње у вези са уговором спискови чланова породице евиденција присуства страначким скуповима. Документовање поруке и имејлови снимци, када су законито настали распореди и спискови налози руководилаца сведочења више запослених уговори и решења о радном статусу доказ о последицама након одбијања фотографије организованог одласка. Надлежне институције инспекција рада полиција и тужилаштво Агенција за спречавање корупције Повереник за заштиту равноправности Повереник за заштиту података суд органи за заштиту узбуњивача. Процена утицаја Системски када је притисак организован кроз јавне институције или већи број послодаваца. ODIHR је у извештајима о изборима 2022, 2023. и 2024. указивао на притиске на запослене у јавном сектору и потребу делотворних институционалних механизама за спречавање застрашивања бирача. Хитна реакција Запослени треба да сачува доказе ван службеног уређаја и да процени ризик пре интерне пријаве. Када је руководилац извор притиска, интерна пријава може бити недовољна или ризична. Шта не треба радити јавно објављивати име сведока без сагласности подстицати лице да се изложи одмазди мењати или преправљати оригиналне поруке најављивати пријаву лицу које може уништити доказе. ↑ Назад на преглед PRE-08 Незаконито прикупљање података о политичком опредељењу Кратка дефиниција Реч је о прикупљању, бележењу, повезивању или дељењу података о стварном или претпостављеном политичком опредељењу грађана без одговарајућег правног основа. Како функционише Подаци се могу прикупљати преко: запослених кућних посета телефонских позива интернет-образаца јавних предузећа установа центара за социјални рад месних заједница база корисника услуга страначких активиста друштвених мрежа. Затим се могу повезати са: адресом бројем телефона радним местом члановима породице социјалним статусом податком о примљеној помоћи податком о изласку на изборе. Показатељи лице зна податке које му грађанин није дао списак садржи службене идентификаторе запослени добијају већ припремљене базе више институција користи идентичне табеле подаци се прослеђују преко неслужбених група од грађана се тражи да наведу политичку подршку евиденција садржи оцене попут „сигуран“, „несигуран“ или „против“. Документовање фотографија дела списка уз анонимизацију оригинални електронски фајл порука којом се тражи попуњавање упутство за коришћење базе име лица које је податке доставило податак о извору сведочење лица чији су подаци коришћени доказ да сагласност није дата. Надлежне институције Повереник за заштиту података о личности полиција и тужилаштво Агенција за спречавање корупције инспекција рада суд. Процена утицаја Системски, јер овакве базе омогућавају дугорочни притисак и контролу бирача. Важна напомена Не треба јавно објављивати целу базу како би се доказало да она постоји. Тиме би се могла поновити повреда права лица чији су подаци незаконито прикупљени. ↑ Назад на преглед PRE-09 Стварање политичке зависности кроз запошљавање и јавна давања Кратка дефиниција Овај механизам постоји када се посао, уговор, социјална помоћ, субвенција, услуга или друга јавна корист додељује или одржава у зависности од политичке лојалности. Обухвата дугорочно коришћење јавних радних места, привремених уговора, социјалних давања, субвенција или других користи ради формирања политичке зависности. Није свака додела помоћи или запошљавање изборна злоупотреба. Ризик постоји када се корист повезује са политичком лојалношћу, активизмом или очекиваним гласањем. Разлика између законите мере и манипулације Јавно давање или запошљавање није само по себи изборна злоупотреба. Ризик постоји када се утврди веза између користи и: учлањења у странку присуства скупу прикупљања гласова гласања страначког активизма достављања личних података одбијања политичке активности. Показатељи корисник добија јасну политичку поруку корист се додељује преко страначког посредника списак корисника води страначки штаб запошљавање нагло расте пред изборе уговор се продужава након испуњења страначке обавезе више лица описује исти механизам јавна помоћ представља се као поклон политичара корисници се позивају на страначке активности. Документовање конкурс и услови решења и уговори временска повезаност поруке посредника спискови корисника сведочења одлуке о додели докази о различитом третману финансијски подаци. Надлежне институције Агенција за спречавање корупције инспекција рада буџетска инспекција полиција и тужилаштво Повереник за заштиту равноправности суд. Процена утицаја Системски, када зависност обухвата велики број лица и траје кроз више изборних циклуса. ↑ Назад на преглед PRE-10 Заробљавање институција важних за изборни процес Кратка дефиниција Заробљавање институција означава трајан образац у којем органи формално постоје и имају законска овлашћења, али их примењују селективно, недоследно или у корист једног политичког центра. Подразумева дугорочан утицај на органе који одлучују о изборима, медијима, јавним ресурсима, заштити података, корупцији и кривичној одговорности. Институције које могу бити релевантне изборне комисије органи који воде бирачки списак полиција јавно тужилаштво регулаторна тела органи за контролу финансирања јавни медијски сервиси инспекције локалне управе јавна предузећа. Показатељи различити стандарди у сличним случајевима непоступање по пријавама одлуке без јасног образложења кашњење до истека изборног процеса одсуство санкција у поновљеним случајевима ограничен приступ документима систематско игнорисање доказа поступање само према политичким противницима формално поступање без стварне истраге одлуке које се понављају по истом политички повољном обрасцу. Доказни стандард Тврдња о заробљавању институције не може бити заснована на једној неповољној одлуци. Потребно је показати: континуитет селективност упоредиве случајеве институционални образац одсуство разумног правног објашњења последице по изборну равноправност. Документовање серија одлука време поступања поређење сличних предмета статистика пријава и исхода службена преписка налази независних тела судске одлуке посматрачки извештаји. ODIHR је у извештајима о Србији указивао на потребу јачања надзорних механизама, раздвајања државе и странке, ревизије бирачког регистра и делотворнијег поступања против притисака и злоупотребе јавних ресурса. Процена утицаја Системски. ↑ Назад на преглед PRE-11 Манипулација редоследом изборних листа Фаза изборног процеса: PRE – припрема избора и кандидовање Опис Ова манипулација обухвата злоупотребу поступка кандидовања и оверавања изборних листа ради обезбеђивања повољнијег редног броја на гласачком листићу, најчешће првог места. Манипулација се може испољити селективним поступањем органа надлежних за пријем изборних листа, одлагањем или убрзавањем поступка овере потписа, неједнаким поступањем према предлагачима, привременим онемогућавањем предаје изборних листа другим учесницима или другим радњама које омогућавају да одређена изборна листа добије повлашћен редни број. За разлику од манипулација које онемогућавају само кандидовање (PRE-03), овде је циљ да се утиче на редослед изборних листа, а не на само право учешћа на изборима. Начин функционисања Манипулација се најчешће спроводи: селективним приступом поступку овере потписа одлагањем пријема изборних листа конкурената привременим прекидом рада органа који примају изборне листе различитим тумачењем процесних правила омогућавањем исправке недостатака само појединим предлагачима. Зашто је важно Истраживања изборног понашања показују да редослед изборних листа може имати утицај на део неодлучних и слабије информисаних бирача. Истовремено, прво место на гласачком листићу може стварати утисак политичке доминације, организационе снаге или институционалне подршке. Када се редослед не формира под једнаким условима за све учеснике, нарушава се начело равноправности изборне утакмице. Како препознати необјашњиво различито поступање према предлагачима кашњење у пријему појединих изборних листа различити рокови за отклањање недостатака спречавање приступа просторијама за предају документације привремени прекид рада непосредно пре предаје конкурентске листе. Како документовати записнике о предаји изборних листа службену преписку видео и фото документацију изјаве учесника поступка одлуке изборних комисија временску реконструкцију поступка кандидовања. Правни оквир Може указивати на повреду начела једнакости изборних учесника, законитости изборног поступка и једнаког приступа поступку кандидовања, у зависности од конкретних околности и важећих изборних прописа. Процена утицаја Висок Јачина доказа Највећу доказну вредност имају службени записници, временска документација поступка кандидовања и службена преписка. Препоручена реакција Одмах документовати ток поступка, захтевати писмено образложење сваког одступања од уобичајене процедуре и благовремено користити сва расположива правна средства. ↑ Назад на преглед PRE-12 Онемогућавање контроле над штампањем, паковањем, примопредајом и чувањем изборног материјала Фаза изборног процеса: PRE – припрема избора Опис Ова манипулација обухвата поступке којима се представницима изборних листа, контролорима или другим овлашћеним лицима онемогућава или битно отежава праћење штампања, паковања, примопредаје, транспорта и чувања изборног материјала пре његове доставе бирачким одборима. Манипулација не подразумева нужно да је изборни материјал накнадно измењен, већ ствара услове у којима независна контрола његовог интегритета није могућа. Недостатак транспарентности у овој фази може умањити поверење у цео изборни процес и отежати доказивање евентуалних каснијих злоупотреба. За разлику од манипулација које се односе на измену изборног материјала након гласања (POST), ова појава настаје пре отварања бирачких места, у периоду када се изборни материјал припрема и ставља под контролу изборне администрације. Начин функционисања Манипулација се може испољити: непозивањем овлашћених представника на штампање изборног материјала ограничавањем приступа просторијама у којима се материјал пакује онемогућавањем присуства примопредаји и складиштењу транспортом изборног материјала без присуства овлашћених представника непостојањем потпуне евиденције о лицима која су имала приступ изборном материјалу непотпуном или нетранспарентном документацијом о кретању изборног материјала. Зашто је важно Интегритет изборног материјала мора бити обезбеђен током целог изборног поступка. Уколико не постоји континуирана и независна контрола од тренутка штампања до примопредаје бирачким одборима, касније је знатно теже отклонити сумње у евентуалне злоупотребе. Недостатак транспарентности у овој фази може угрозити поверење у законитост целокупног изборног поступка. Како препознати ограничен приступ просторијама у којима се припрема изборни материјал одсуство позива овлашћеним представницима непотпуна документација о примопредаји транспорт изборног материјала без присуства представника изборних листа нејасна евиденција о лицима која су руковала изборним материјалом. Како документовати позиве и обавештења изборних комисија записнике о примопредаји службену преписку изјаве контролора и чланова изборних комисија фото и видео документацију, када је законито прибављена. Правни оквир Може указивати на повреду начела јавности, транспарентности, законитости рада изборних органа и контроле изборног материјала, у зависности од конкретних околности и важећих изборних прописа. Процена утицаја Висок Јачина доказа Највећу доказну вредност имају службени записници, документација о примопредаји, службена преписка и међусобно сагласне изјаве више непосредних сведока. Препоручена реакција Захтевати присуство представника свих заинтересованих изборних листа у свим фазама припреме изборног материјала, документовати свако ограничење приступа и одмах поднети приговор надлежној изборној комисији када независна контрола није омогућена. ↑ Назад на преглед PRE-13 Координисано постављање привидно независних контролора Фаза изборног процеса: PRE – формирање изборних органа Опис Ова манипулација обухвата постављање чланова и заменика чланова бирачких одбора који формално представљају различите изборне листе, а у стварности поступају координисано или делују у интересу истог политичког субјекта. Манипулација се најчешће спроводи преко формално различитих изборних листа које обезбеђују места у проширеном саставу бирачких одбора, али лица која су предложена немају стварну политичку или организациону везу са предлагачем, већ поступају по инструкцијама другог политичког актера. За разлику од PRE-04 (Лажне или контролисане изборне листе), где је предмет манипулације сама изборна листа, овде је предмет манипулације састав и функционисање бирачких одбора. Начин функционисања Манипулација се може испољити: предлагањем истих лица преко више формално различитих изборних листа именовањем лица која немају никакву стварну везу са предлагачем координисаним гласањем чланова који формално припадају различитим листама одсуством било какве комуникације са изборном листом која их је предложила поступањем по инструкцијама другог политичког субјекта организованим одбијањем стављања примедби у записник. Зашто је важно Бирачки одбор представља основни механизам међусобне контроле изборног процеса. Ако више чланова који формално представљају различите изборне листе у стварности делује као јединствена група, механизам узајамне контроле престаје да функционише. Таква пракса може омогућити прикривање неправилности, несметано доношење спорних одлука и умањити могућност благовременог реаговања на изборне злоупотребе. Како препознати идентично поступање лица предложених од различитих изборних листа одсуство контакта са предлагачем који их је именовао међусобно координисано гласање у свим спорним ситуацијама исти координатори који дају упутства формално различитим члановима понављање истог обрасца на већем броју бирачких места. Како документовати решења о именовању записнике о раду бирачких одбора изјаве чланова одбора службену комуникацију податке о организационим везама лица, када су законито доступни документацију која указује на координисано поступање. Правни оквир Може указивати на повреду начела независности и равноправности изборних учесника, као и законских правила о саставу и раду изборних органа, у зависности од конкретних околности. Процена утицаја Висок, а у случају организованог понављања системски. Јачина доказа Највећу доказну вредност имају службени акти о именовању, записници о раду бирачких одбора, документована комуникација и више међусобно сагласних сведочења. Препоручена реакција Документовати образац координисаног поступања, захтевати проверу испуњености услова за чланство у бирачком одбору и благовремено обавестити надлежну изборну комисију о сумњи да формално различити представници не поступају самостално. ↑ Назад на преглед 5.2. Међусобна повезаност предизборних манипулација Предизборне манипулације ретко делују изоловано. Често образују повезан систем: прикупљају се лични подаци бирачи се разврставају према политичкој поузданости запослени добијају квоте користе се запошљавање и јавна давања мењају се подаци о пребивалишту или месту гласања формирају се контролисане листе преко њих се утиче на састав изборних органа институције не реагују или реагују селективно. Посматрана појединачно, свака радња може изгледати ограничено или двосмислено. Посматрана заједно, она може показати механизам организованог утицаја на изборну вољу. 5.3. Контролна питања При процени предизборне појаве треба поставити следећа питања: Да ли се радња понавља? Да ли обухвата више лица или места? Да ли постоје исти организатори? Да ли се користе службени подаци или ресурси? Да ли грађанин трпи последицу ако одбије? Да ли је поступање различито према различитим политичким актерима? Да ли постоји материјални доказ? Да ли су надлежни органи обавештени? Да ли су поступили у року? Да ли се исти образац појавио и у ранијим изборима? 5.4. Закључак поглавља Манипулације пре избора могу имати већи утицај од појединачне неправилности на дан гласања, јер унапред одређују: ко има право да гласа ко може да се кандидује ко контролише изборну администрацију ко располаже личним подацима ко зависи од јавне власти да ли институције могу непристрасно да реагују. Зато се изборни интегритет не може штитити само контролом гласачке кутије. Он се мора штитити током целог изборног циклуса. ← О Атласу KAM — током кампање →"},{"title":"Приговор изборној комисији — Атлас изборних манипулација","url":"pages/prigovor-komisiji.html","text":"Приговор изборној комисији — Атлас изборних манипулација АТЛАС изборних манипулација Ћир Lat Почетна / Практични обрасци / Приговор изборној комисији Практични обрасци Приговор изборној комисији Универзална основа за приговор, са местом за чињенице, доказе и јасно одређен захтев. Практични обрасци Захтев за увид у изборни материјал Приговор изборној комисији Службена белешка о уоченој неправилности Записник о уоченој неправилности Контролна листа за изборни дан Дневник члана бирачког одбора или посматрача Како документовати изборну неправилност ↑ На врх Сврха: Помоћни практични алат за учеснике у изборном поступку. Правна природа: Пример који се прилагођава конкретном случају и важећем изборном законодавству; није законом прописан формулар. Намена: Чланови бирачких одбора, посматрачи, овлашћени представници изборних листа и друга овлашћена лица. Када се користи Овај текст служи као основа за приговор надлежној изборној комисији када овлашћени подносилац сматра да је у изборном поступку дошло до повреде закона. Мора се прилагодити конкретним чињеницама, активној легитимацији, надлежности и важећем року. Предложени текст Изборној комисији ______________________________ ПРИГОВОР Подносилац: ______________________________ Својство и основ овлашћења: ________________ Избори: ___________________________________ Бирачко место / изборна радња: _____________ Опис чињеница Дана _____________ у ______ часова догодило се: _____________________________________________________ _____________________________________________________ Докази ☐ службена белешка ☐ записник о уоченој неправилности ☐ фотографије или видео-запис ☐ изјаве сведока ☐ други прилози: _________________________________ Правни разлози Описано поступање, према оцени подносиоца, представља повреду: ____________________________________________ Захтев Предлаже се да изборна комисија, након утврђивања чињеница, донесе законом предвиђену одлуку којом ће: _____________________________________________________ Место и датум: ____________________ Потпис: ___________________________ Практични савети Проверите ко има право да поднесе приговор и ком органу се подноси. Наведите конкретне чињенице хронолошки, без општих политичких оцена. Захтев мора бити јасан: шта тачно тражите од комисије. Означите прилоге и сачувајте доказ о времену предаје. Најчешће грешке пропуштен рок; неовлашћени подносилац; неодређен опис догађаја; нејасан или непостојећи захтев; позивање на доказе који нису приложени. ← Захтев за увид у изборни материјал Сви практични обрасци Службена белешка о уоченој неправилности →"},{"title":"Системски механизми — Атлас изборних манипулација","url":"pages/sistemski-mehanizmi.html","text":"Системски механизми — Атлас изборних манипулација АТЛАС изборних манипулација Ћир Lat Почетна / Системски механизми Поглавље 10 Међуфазни и системски механизми изборних манипулација Како се појединачне неправилности повезују у организоване обрасце који трају кроз више фаза изборног процеса и производе кумулативни ефекат. 11 тематских целина пуни текст поглавља системска анализа Садржај поглавља 10.1. Појединачна неправилност и системска манипулација 10.2. Животни циклус изборне манипулације 10.3. Најчешћи системски модели 10.4. Кумулативни ефекат 10.5. Индикатори системске манипулације 10.6. Анализа мреже уместо анализе догађаја 10.7. Значај временске линије 10.8. Анализа ризика 10.9. Системски круг изборне манипулације 10.10. Како доказати системску манипулацију 10.11. Закључак поглавља ↑ На врх Системска манипулација не утврђује се на основу једног изолованог догађаја, већ повезивањем понављајућих радњи, актера, временске линије, институционалне подршке и њиховог заједничког утицаја. 10.1. Појединачна неправилност и системска манипулација Изборна манипулација ретко се састоји од једног незаконитог поступка. У већини случајева она представља низ међусобно повезаних активности које појединачно могу изгледати безначајно или чак законито, али заједно производе значајан утицај на изборни резултат. Због тога је приликом анализе неопходно разликовати: појединачну неправилност; организовану манипулацију; системски механизам. Појединачна неправилност је изолован догађај који није повезан са другим радњама. Организована манипулација представља више координисаних активности усмерених ка истом циљу. Системски механизам постоји када су институције, организација, ресурси и поступци повезани тако да омогућавају континуирано утицање на изборни процес. Највећи број озбиљних изборних злоупотреба настаје управо кроз ову последњу категорију. 10.2. Животни циклус изборне манипулације Манипулација не почиње изборног дана. Она најчешће пролази кроз више фаза. Прва фаза – припрема измене бирачког списка; организовано пријављивање пребивалишта; прикупљање личних података; притисци на запослене; формирање паралелних база података; избор подобних чланова бирачких одбора; припрема страначке инфраструктуре. Друга фаза – кампања функционерска кампања; злоупотреба јавних ресурса; медијска доминација; куповина гласова; организовање сигурних гласова; политички притисци; контролисано финансирање. Трећа фаза – изборни дан контрола излазности; организован превоз; фотографисање листића; породично гласање; бугарски воз; вођење паралелних спискова; агитација; притисци на чланове одбора. Четврта фаза – бројање спорни листићи; нетачно пребројавање; погрешно попуњавање записника; притисци на чланове; онемогућавање примедби; неправилно паковање изборног материјала. Пета фаза – после избора транспорт изборног материјала; чување врећа; унос резултата; приговори; исправке; поновно бројање; проглашење резултата. Ниједна од ових фаза не сме се анализирати изоловано. 10.3. Најчешћи системски модели Модел А – Контролисани бирач Циљ овог модела није промена резултата бројањем већ контрола понашања гласача. Најчешће укључује: PRE ↓ евиденција запослених ↓ прикупљање телефона ↓ KAM ↓ позиви ↓ сигурни гласови ↓ BM ↓ фотографија листића ↓ контрола излазности ↓ POST ↓ Провера испуњења обећања Појединачно гледано, ниједна радња не мора бити незаконита. Заједно представљају систем контроле политичке воље. Модел Б – Контролисани резултат Овај модел усмерен је на резултат гласања. PRE ↓ подобан одбор ↓ BM ↓ неправилности током гласања ↓ BR ↓ нетачно бројање ↓ нетачан записник ↓ POST ↓ погрешан унос ↓ коначан резултат Модел В – Институционална предност Овај модел заснива се на употреби институционалне моћи. Обухвата: јавне ресурсе; јавна предузећа; локалну администрацију; установе; медије; службене евиденције; функционере. Предност се не стиче једном незаконитом радњом већ кумулативним деловањем институција. 10.4. Кумулативни ефекат Највећи проблем изборних манипулација није увек тежина појединачне неправилности већ њихово сабирање. На пример: 30 неправилно уписаних бирача; 20 купљених гласова; 15 контролисаних фотографија; 10 погрешно проглашених неважећих листића; 8 нетачно унетих резултата. Свака појединачно можда није довољна да промени резултат. Заједно могу. Зато приликом правне оцене није довољно анализирати сваки догађај посебно. Потребно је проценити укупан ефекат. 10.5. Индикатори системске манипулације Постоји већа вероватноћа да је реч о организованом механизму ако се уочи више следећих показатеља: исти образац на већем броју бирачких места; исти тип неправилности; исте инструкције; исте формулације у записницима; исти страначки координатори; исти начин притиска; исти превозници; исти пунктови; исти медијски образац; исти начин поступања институција. Један показатељ није довољан. Што их је више, већа је вероватноћа да није реч о случајности. 10.6. Анализа мреже уместо анализе догађаја У савременој изборној форензици све више се користи мрежна анализа. Она не поставља питање: \"Да ли је овај један догађај незаконит?\" већ: \"Како су различити догађаји повезани?\" На пример: исто лице ↓ организује превоз ↓ води паралелне спискове ↓ контролише фотографије листића ↓ врши притисак на чланове одбора ↓ прати транспорт врећа ↓ појављује се код поновног бројања. Тада се не анализира шест одвојених догађаја већ једна организациона улога. 10.7. Значај временске линије Практично свака озбиљна анализа треба да садржи временску линију. Пример: Временска линија често открива везе које се иначе не би уочиле. 10.8. Анализа ризика Свака изборна манипулација може се проценити кроз три питања. Вероватноћа Колико је вероватно да ће се догодити? Последица Колико може променити резултат? Могућност откривања Колико је лако доказати да се догодила? Најопасније су манипулације које имају: велику вероватноћу; велики утицај; малу могућност откривања. Управо њима треба посветити највећу пажњу. 10.9. Системски круг изборне манипулације Практично све сложене изборне манипулације могу се приказати једним кругом. Припрема ↓ Прикупљање података ↓ Политички притисци ↓ Кампања ↓ Контрола гласача ↓ Изборни дан ↓ Бројање ↓ Обрада резултата ↓ Правна заштита ↓ Коначни резултат ↓ Очување система ↓ Нови избори Тако се затвара циклус. 10.10. Како доказати системску манипулацију Системска манипулација готово никада не може бити доказана једним документом. Потребно је повезати више категорија доказа: записнике; фотографије; видео-снимке; копије бирачких спискова; одлуке изборних комисија; службене евиденције; сведочења; електронске податке; статистичке анализе; временске линије; анализу мреже повезаних лица. Управо комбинација више независних извора даје највећу доказну снагу. 10.11. Закључак поглавља Изборна манипулација је ретко производ једне незаконите радње. Она је, по правилу, резултат низа међусобно повезаних поступака који делују у различитим фазама изборног процеса и које спроводе различити актери. Зато је за озбиљну анализу неопходно напустити приступ који посматра сваки инцидент изоловано и прећи на анализу система, образаца и међусобних веза. Тако се одговара не само на питање „шта се догодило“, већ и на далеко важније питање: „Како је читав механизам функционисао?“ ← POST манипулације Студије случаја →"},{"title":"Службена белешка о уоченој неправилности — Атлас изборних манипулација","url":"pages/sluzbena-beleska.html","text":"Службена белешка о уоченој неправилности — Атлас изборних манипулација АТЛАС изборних манипулација Ћир Lat Почетна / Практични обрасци / Службена белешка о уоченој неправилности Практични обрасци Службена белешка о уоченој неправилности Помоћни текст за благовремено и прецизно бележење догађаја током изборног дана. Практични обрасци Захтев за увид у изборни материјал Приговор изборној комисији Службена белешка о уоченој неправилности Записник о уоченој неправилности Контролна листа за изборни дан Дневник члана бирачког одбора или посматрача Како документовати изборну неправилност ↑ На врх Сврха: Помоћни практични алат за учеснике у изборном поступку. Правна природа: Пример који се прилагођава конкретном случају и важећем изборном законодавству; није законом прописан формулар. Намена: Чланови бирачких одбора, посматрачи, овлашћени представници изборних листа и друга овлашћена лица. Када се користи Службена белешка се сачињава што пре након уоченог догађаја, док су чињенице свеже. Она је помоћно средство и може касније бити прилог уз приговор или други акт. Предложени текст СЛУЖБЕНА БЕЛЕШКА О УОЧЕНОЈ НЕПРАВИЛНОСТИ Избори: ___________________________________ Бирачко место / локација: __________________ Датум и време: ____________________________ Лице које сачињава белешку: _______________ Својство: ☐ члан бирачког одбора ☐ посматрач ☐ друго: __________ Опис непосредно уоченог догађаја _____________________________________________________ _____________________________________________________ Присутна лица и сведоци _____________________________________________________ Реакција бирачког одбора или другог надлежног лица _____________________________________________________ Предузете радње ☐ затражено отклањање неправилности ☐ затражен унос примедбе у записник ☐ обавештена изборна комисија ☐ сачињена фотографија / видео-запис ☐ друго: _______________________________________ Прилози: _________________________________ Потпис: ___________________________ Практични савети Наведите тачно или приближно време. Бележите оно што сте непосредно видели или чули. Одвојите чињенице од претпоставки и правних оцена. За више неповезаних догађаја сачините одвојене белешке. ← Приговор изборној комисији Сви практични обрасци Записник о уоченој неправилности →"},{"title":"Студија случаја 1: Бирачки списак као средство изборног инжењеринга – организоване промене пребивалишта пред изборе 2023. године — Атлас изборних манипулација","url":"pages/studija-1.html","text":"Студија случаја 1: Бирачки списак као средство изборног инжењеринга – организоване промене пребивалишта пред изборе 2023. године — Атлас изборних манипулација АТЛАС изборних манипулација Ћир Lat Почетна / Студије случаја / 1 Прилог 2 · Документовани пример из изборне праксе Бирачки списак као средство изборног инжењеринга – организоване промене пребивалишта пред изборе 2023. године Студија случаја 1 Бирачки списак као средство изборног инжењеринга – организоване промене пребивалишта пред изборе 2023. године Интегритет бирачког списка представља један од основних предуслова слободних и поштених избора. Право гласа не подразумева само да сваки пунолетни држављанин може да гласа, већ и да то право остварује у изборној јединици којој законито припада. Код локалних избора та веза је посебно значајна, јер о саставу органа локалне самоуправе треба да одлучују грађани који у тој заједници имају пребивалиште и у њој стварно живе. Због тога пребивалиште није само административни податак. Оно представља правну везу грађанина са локалном заједницом у којој остварује права и испуњава обавезе. Ако се пребивалиште фиктивно или незаконито пријављује ради стицања права гласа на локалним изборима, не мењају се непосредно гласачки листићи или резултати бројања, већ се унапред мења састав бирачког тела. Управо такав механизам представља један од најсложенијих облика изборног инжењеринга. Контекст избора 2023. године Ванредни избори за народне посланике, избори за Скупштину Аутономне покрајине Војводине и локални избори у Београду и још 64 јединице локалне самоуправе одржани су 17. децембра 2023. године. Локални избори нису, дакле, одржавани у целој Србији. То је омогућило да се у јавности отвори питање да ли су бирачи из места у којима није било локалних избора формално пријављивани у Београду и другим срединама у којима су избори одржавани. У захтеву којим је пред Уставним судом оспорен поступак избора за одборнике Скупштине града Београда, подносиоци су тврдили да су изненадне и координисане оставке градоначелника и председника општина, које су створиле услове за ванредне локалне изборе само у делу земље, омогућиле организовано фиктивно пресељење бирача из јединица локалне самоуправе у којима се избори нису одржавали у оне у којима јесу, пре свега у Београд. Као институције без чијег учешћа такав механизам не би могао бити спроведен означени су органи надлежни за евиденцију пребивалишта и вођење Јединственог бирачког списка. Ово су наводи подносилаца захтева, о којима није донета коначна одлука којом би била утврђена одговорност појединачних органа или лица. Конкретне индиције и документовани примери Сумње у законитост промена пребивалишта нису биле засноване искључиво на општим политичким тврдњама. Грађани су пријављивали да су на њихове адресе стизали позиви за гласање намењени лицима која никада нису живела у тим становима или кућама. У појединим случајевима власници или корисници станова тек су након добијања изборних обавештења сазнали да се на њиховој адреси води више непознатих лица. У јавности су објављивани и примери великог броја бирача пријављених у недовршеним објектима или на адресама које по својој величини и намени нису могле реално да приме број пријављених лица. У захтеву за одлучивање о парламентарном изборном спору наведен је пример недовршеног објекта у Београду на чијој адреси је било пријављено 129 бирача. Пратећи податке једног лица са те адресе, организација ЦРТА је, према наводима захтева, идентификовала 679 бирача који су у различитим изборним евиденцијама били повезани са више бирачких места. Подносиоци су навели да су поједина лица током два изборна циклуса могла бити евидентирана на више бирачких места у Србији и Босни и Херцеговини. Ови подаци су у захтеву представљени као резултат анализе домаће посматрачке организације, а не као чињенице утврђене правноснажном судском одлуком. Посматрачка мисија ODIHR-а је након локалних избора 2024. године навела да је добила бројне извештаје о позивима за гласање достављеним лицима непознатим станарима адреса у Лазаревцу, Палилули, Новом Београду, Нишу, Новом Саду и Рашки. Мисија је навела и да је добила веродостојне извештаје о великом броју бирача пријављених у зградама на Савском венцу и Вождовцу које су биле у изградњи или нису биле погодне за смештај толиког броја лица. На дан избора и непосредно након њега објављивани су и снимци и сведочења о организованом довожењу бирача аутобусима и другим возилима. Сам организовани превоз бирача није незаконит. Међутим, у комбинацији са сумњама у законитост пријављених пребивалишта, колективним доласком лица која не познају средину у којој гласају и постојањем пунктова на којима им се дају упутства, он може представљати значајну индицију организоване миграције бирача. Статистички показатељи и њихова ограничења Према одлуци Градске изборне комисије, за изборе за одборнике Скупштине града Београда било је уписано 1.613.190 бирача. Према подацима Пописа становништва из 2022. године, у Београду је пописано 1.380.380 пунолетних лица. Разлика између ова два броја износила је приближно 232.000 лица. Подносиоци захтева Уставном суду сматрали су да тај несразмер, посебно имајући у виду да међу пописаним пунолетним лицима има и странаца и других лица која немају бирачко право, представља довољан разлог за темељну ревизију бирачког списка. Ипак, ова два податка не могу се механички изједначавати. Попис становништва и Јединствени бирачки списак заснивају се на различитим методологијама. Попис настоји да утврди уобичајено становништво, док се бирачки списак заснива на формално пријављеном пребивалишту и држављанству. У њему могу остати и грађани који привремено или дуже бораве у иностранству, али имају пријављено пребивалиште у Београду. Зато наведена разлика сама по себи не доказује постојање фиктивних бирача. Њен значај је у томе што, заједно са појединачним примерима, извештајима о необичним променама пребивалишта и ограниченом доступношћу података за независну проверу, представља индицију која захтева институционално објашњење и детаљну контролу. Статистичка необичност није доказ изборне манипулације, али може бити полазна основа за проверу када је подржана другим међусобно сагласним подацима. Налази ODIHR-а након избора 2023. године У Коначном извештају о ванредним парламентарним изборима од 17. децембра 2023. године ODIHR је навео да већина саговорника мисије није оспоравала свеобухватност бирачког списка, али да су ограничени механизми за његову ефикасну ревизију, недостатак детаљних података о променама пребивалишта и привременог боравка, као и тврдње о преминулим лицима и масовној миграцији бирача у вези са локалним изборима, значајно нарушили поверење јавности у тачност Јединственог бирачког списка. ODIHR је посебно указао да је ограничено поверење додатно погоршано изостанком свеобухватног одговора власти на изнете сумње. Ранија препорука да се спроведе потпуна ревизија Јединственог бирачког списка није била реализована до избора 2023. године. Мисија је зато поново препоручила побољшање тачности и транспарентности бирачког списка. Ова оцена је значајна јер ODIHR није закључио да је сваки спорни упис незаконит, нити да је утврђен тачан број фиктивно пријављених бирача. Међутим, потврдио је постојање системског проблема поверења, ограничене могућности провере и недовољног институционалног одговора. Управо се у томе разликује тврдња о појединачној злоупотреби од оцене да систем није обезбедио довољно транспарентан и уверљив начин да јавност провери тачност евиденције. Поступање институција и изостанак независне ревизије Јединствени бирачки списак води Министарство државне управе и локалне самоуправе, на основу података који се преузимају из службених евиденција, укључујући податке Министарства унутрашњих послова о пребивалишту. Изборне комисије користе закључене изводе из бирачког списка, али немају овлашћења да саме утврђују да ли је нечије пребивалиште фиктивно нити да спроводе полицијску или управну контролу законитости пријаве пребивалишта. Због такве расподеле надлежности, захтеви за проверу наилазили су на институционални круг у којем је сваки орган упућивао на ограничења сопствених овлашћења. Изборне комисије нису могле да спроводе потпуну ревизију пребивалишта, а органи који воде службене евиденције одбацивали су опште тврдње о нетачности списка или су указивали на заштиту података о личности као ограничење ширем увиду. Заштита личних података јесте легитимно ограничење и бирачки списак не може бити потпуно отворен јавности. Ипак, она не сме постати разлог због којег није могућа никаква независна и стручна контрола. Могуће је успоставити механизам у којем овлашћени стручњаци, представници релевантних институција, политичких субјеката и цивилног друштва врше проверу уз обавезу чувања података и без њиховог јавног објављивања. Управо такав модел свеобухватне ревизије није био успостављен пре избора 2023. године. Последица није само то што евентуалне незаконитости нису на време отклоњене, већ и то што јавности није пружен уверљив доказ да су изнете сумње неосноване. Законске измене пред локалне изборе 2024. године После спорова поводом београдских избора 2023. године и политичких разговора о изборним условима, у мају 2024. године измењен је Закон о јединственом бирачком списку. За локалне изборе од 2. јуна 2024. године уведено је привремено правило према којем су бирачи који су променили пребивалиште након 3. јула 2023. године гласали према ранијем месту пребивалишта. Према подацима Министарства државне управе и локалне самоуправе које је пренео ODIHR, применом ове измене 52.313 бирача враћено је на претходну адресу за потребе гласања. Од тог броја, 12.554 бирача враћена су у јединице локалне самоуправе у којима 2. јуна 2024. године нису одржавани избори. Ова мера не представља накнадно признање да су све промене пребивалишта биле незаконите. Она је била привремено законско решење донето као одговор на кризу поверења и сумње у организовану миграцију бирача. Ипак, сам обим примене — више од педесет хиљада бирача — показао је да промене пребивалишта у релативно кратком периоду нису биле занемарљиве и да су могле имати значај за локалне изборе. ODIHR је оценио да је ова мера допринела смањењу тензија уочи избора, али да су је многи учесници сматрали недовољном. Посебно је указано да услови које је Министарство обезбедило парламентарној радној групи нису омогућили суштинску проверу примене закона: време је било кратко, а доступни подаци нису били довољно проверљиви. Мисија је поновила препоруку да се спроведе потпуна ревизија Јединственог бирачког списка и грађанских евиденција, уз учешће независних стручњака и релевантних заинтересованих страна. Правни значај случаја Правни проблем овог случаја не своди се само на питање да ли је одређено лице правилно или неправилно пријавило пребивалиште. Када је реч о појединачном случају, могуће је да нетачан податак потиче од административне грешке, неблаговременог ажурирања или животне ситуације у којој се формално и стварно место боравка разликују. Таква околност не мора представљати изборну манипулацију. Изборни инжењеринг постоји када се промене спроводе организовано, према већем броју лица, у временској и функционалној вези са предстојећим локалним изборима и са циљем да се утиче на састав бирачког тела. За доказивање таквог механизма није довољан један спорни позив за гласање. Потребно је повезати: време и број промена пребивалишта; адресе на којима су лица пријављивана; стварну могућност становања на тим адресама; претходна и нова места гласања; постојање организованог превоза и координације; комуникацију и документацију лица укључених у поступак; начин поступања службених лица; статистички утицај промена на локално бирачко тело. Уколико би се утврдило да су службене евиденције намерно састављане или мењане са нетачним подацима ради утицаја на изборе, такво поступање могло би имати управноправне, дисциплинске и кривичноправне последице. Коначна квалификација, међутим, зависи од конкретних доказа, својства учинилаца, постојања намере и одлуке надлежних органа. Утицај на изборни интегритет Организовано фиктивно пресељење бирача може имати системски утицај, нарочито на локалним изборима. У јединици локалне самоуправе у којој је разлика између изборних листа релативно мала, промена места гласања неколико хиљада бирача може утицати на расподелу мандата и формирање већине. Посебна опасност овог механизма лежи у томе што се гласање споља може одвијати формално правилно. Бирач долази на бирачко место, показује важећу исправу, налази се у изводу из бирачког списка, потписује се и гласа. Чланови бирачког одбора на самом бирачком месту углавном немају правни основ да преиспитују како је и због чега лице стекло пребивалиште. Зато се ова врста манипулације не може ефикасно спречавати само контролом на дан избора. Њено откривање и спречавање захтева претходну анализу података, контролу пријава пребивалишта, благовремено објављивање довољно детаљних статистичких података и механизам независне ревизије. Поуке и препоруке Овај случај показује да изборне манипулације не морају започети у изборној кампањи нити на бирачком месту. Оне могу бити спроведене у административној фази, коришћењем службених евиденција које наизглед нису део политичке утакмице. Уместо мењања гласова, мења се круг лица која имају право да гласају у одређеној локалној заједници. Такође, случај показује да само формална законитост бирачког списка није довољна за очување поверења. Уколико јавност и релевантни учесници немају могућност да кроз контролисан и законит поступак провере значајне промене, сумња остаје и када неправилност није правноснажно утврђена. Зато је потребно: успоставити трајни механизам независне ревизије Јединственог бирачког списка и повезаних грађанских евиденција; објављивати временске серије статистичких података о броју бирача и променама пребивалишта по јединицама локалне самоуправе; омогућити овлашћеним представницима институција, политичких субјеката и цивилног друштва контролисан приступ подацима, уз пуно поштовање заштите података о личности; посебно проверавати нагле концентрације пријава на истој адреси и пријаве у објектима који не могу реално служити за становање; обезбедити благовремено поступање Министарства унутрашњих послова и других надлежних органа по документованим пријавама; прописати јасније механизме правне заштите у случајевима када се тврди да су промене у службеним евиденцијама системски утицале на састав бирачког тела. Најважнија поука је да бирачки списак није само техничка евиденција, већ један од темеља изборног легитимитета. Ако није могуће поуздано утврдити ко има право да гласа у одређеној локалној заједници и на основу којих података је то право стечено, правилност самог гласања и бројања не може у потпуности отклонити сумњу у веродостојност изборног резултата. Манипулације које ова студија илуструје: PRE-01 — незаконите или спорне промене у бирачком списку; PRE-02 — организовано пријављивање пребивалишта ради гласања; PRE-10 — заробљавање институција важних за изборни процес. Главни извори: захтеви Уставном суду поводом београдских и парламентарних избора 2023. године; Коначни извештај ODIHR-а о изборима од 17. децембра 2023. године; Коначни извештај ODIHR-а о локалним изборима од 2. јуна 2024. године; подаци Градске изборне комисије и Републичког завода за статистику; налази домаћих посматрачких организација. ← Преглед студија Студија 2 →"},{"title":"Студија случаја 10: Изборни календар као средство изборног инжењеринга – од уставног механизма до политичког инструмента — Атлас изборних манипулација","url":"pages/studija-10.html","text":"Студија случаја 10: Изборни календар као средство изборног инжењеринга – од уставног механизма до политичког инструмента — Атлас изборних манипулација АТЛАС изборних манипулација Ћир Lat Почетна / Студије случаја / 10 Прилог 2 · Документовани пример из изборне праксе Изборни календар као средство изборног инжењеринга – од уставног механизма до политичког инструмента Студија случаја 10 Изборни календар као средство изборног инжењеринга – од уставног механизма до политичког инструмента Време одржавања избора није само техничко питање нити неутрална календарска одлука. Оно непосредно утиче на услове политичке конкуренције: дужину припрема и кампање, могућност организовања изборних учесника, медијску агенду, економске и друштвене околности у којима бирачи одлучују, као и способност власти и опозиције да мобилишу своје присталице. Редовни изборни циклуси обезбеђују предвидивост. Политички учесници, институције, медији, посматрачке организације и грађани унапред знају када истиче мандат представничког тела и могу благовремено да се припреме. Ванредни избори представљају легитиман уставни механизам за решавање институционалне или политичке кризе, али по својој природи треба да буду изузетак. Проблем настаје када одлука о ванредним изборима више није превасходно средство за разрешење кризе, већ инструмент којим носиоци власти бирају политички најповољнији тренутак за гласање. Тада се не мењају непосредно гласови, бирачки спискови или записници. Мењају се услови у којима ће изборна воља бити формирана и исказана. Ова студија анализира начин на који је у Србији током дужег периода учестало расписивање ванредних парламентарних избора, а потом и одлагање њиховог расписивања у условима дубоке политичке кризе, отворило питање да ли је изборни календар постао један од ресурса политичке предности. Уставни оквир за редовне и ванредне изборе Уставни положај Народне скупштине заснива се на временски ограниченом мандату. Редовни избори треба да буду одржани тако да се обезбеди непрекидан демократски легитимитет представничког тела. Ванредни парламентарни избори могу бити расписани након распуштања Народне скупштине. Према Уставу Републике Србије, председник Републике може, на образложени предлог Владе, распустити Народну скупштину. Избори за нови сазив морају се одржати у року од 60 дана од дана распуштања. Овај механизам подразумева учешће два органа: Влада подноси образложени предлог за распуштање; председник Републике одлучује о предлогу и, ако распусти Скупштину, расписује изборе. Председник, дакле, не би требало да распушта Скупштину само на основу сопствене политичке процене, без формалног и образложеног предлога Владе. Истовремено, у политичком систему у којем председник има доминантан утицај на парламентарну већину и Владу, формална подела улога не мора нужно значити и стварну поделу политичког одлучивања. Правно питање је да ли су испуњени уставни услови и спроведена прописана процедура. Политичко и демократско питање је да ли се процедура користи ради решавања стварне кризе или ради избора тренутка који одговара владајућој већини. Учесталост ванредних парламентарних избора Учестали ванредни парламентарни избори постали су једна од препознатљивих карактеристика политичког система Србије. Ванредни парламентарни избори одржани су, између осталог, 2014, 2016, 2022. и 2023. године. ODIHR је све ове циклусе у својој документацији водио као превремене парламентарне изборе. Избори од 17. децембра 2023. године били су трећи парламентарни избори у периоду краћем од четири године и шести од 2012. године. Ова учесталост отежавала је спровођење свеобухватних изборних реформи, јер се законодавне и институционалне промене изнова припремају у условима приближавања новог изборног циклуса. Чести избори сами по себи нису доказ злоупотребе. У парламентарним демократијама може постојати више оправданих разлога за превремено гласање: губитак парламентарне већине; немогућност избора или одржања Владе; дубок сукоб унутар владајуће коалиције; блокада рада институција; потреба да се грађани изјасне о крупној промени политичког курса; немогућност решавања кризе у постојећем сазиву. Ипак, када се ванредни избори понављају и без видљивог губитка парламентарне већине, поставља се питање да ли се они користе ради обнове демократског мандата или као тактички инструмент политичког управљања. Избори 2023. године и избор тренутка Председник Републике је 1. новембра 2023. године распустио Народну скупштину и расписао ванредне парламентарне изборе за 17. децембар. Истог дана расписан је и део локалних избора. Локални избори нису одржани у свим јединицама локалне самоуправе, већ само у Београду и делу градова и општина. Такав распоред касније је постао важан и за сумње у организовано премештање бирача из средина у којима локалних избора није било у средине у којима су се одржавали. Изборни календар је, дакле, могао да произведе последице које превазилазе само датум гласања. Одлука: које изборе расписати; у којим јединицама локалне самоуправе; истовремено са којим другим изборима; након колико дугог мандата; у ком политичком и медијском тренутку, може утицати на састав бирачког тела, мобилизацију, изборну понуду и организациону предност учесника. То не значи да је само расписивање избора 2023. било незаконито. Значај случаја је у томе што избор календара не делује изоловано, већ може бити повезан са другим механизмима описаним у Атласу. Изборни календар и спајање различитих нивоа избора Истовремено одржавање парламентарних и локалних избора може имати практичне предности: мање трошкове; једноставнију организацију; већу излазност; мање узастопних кампања; мање оптерећење изборне администрације. Међутим, оно може створити и неравноправност. Када се национална кампања споји са локалном: национални политички лидери потискују локалне кандидате и теме; локални избори постају изјашњавање о централној власти; медији дају предност националним темама; странка која контролише централну власт користи видљивост државних функционера и на локалном нивоу; локалне листе и независни кандидати теже долазе до јавности; функционерска кампања на националном нивоу производи ефекат и у локалној утакмици. ODIHR је у извештају о локалним изборима 2024. године указао да су националне теме и национални политички актери потиснули локална питања, чиме су бирачи добијали ограничене информације о стварним локалним изборним темама. Зато спајање избора није неутрална организациона одлука. Његов ефекат зависи од медијског окружења, положаја јавних функционера и степена централизације политичког система. Политичка криза након пада надстрешнице у Новом Саду Пад надстрешнице на Железничкој станици у Новом Саду 1. новембра 2024. године, у којем је живот изгубило 16 људи, покренуо је дуготрајан талас студентских и грађанских протеста, захтева за утврђивање одговорности и критика начина рада институција. Протести су временом прерасли у шире захтеве за владавину права и политичку одговорност. У мају 2025. године студентски покрет је јавно затражио расписивање ванредних парламентарних избора, образлажући да је то начин за излазак из дубоке политичке кризе. Захтев за изборе остао је једна од централних порука протестног покрета и током 2025. и 2026. године. Ова околност је створила политички парадокс. У претходним периодима ванредни избори су расписивани и када је владајућа већина била стабилна и када није постојала институционална блокада. Насупрот томе, у условима дуготрајних масовних протеста, оспоравања легитимитета институција и изричитог захтева значајног друштвеног покрета да се криза разреши изборима, гласање није било одмах расписано. То не значи да власт има правну обавезу да распише изборе кад год то затраже демонстранти, студенти или опозиционе странке. Устав не предвиђа да јавни протест сам по себи аутоматски доводи до распуштања Народне скупштине. Међутим, различит однос према институту ванредних избора у различитим политичким околностима омогућава анализу да ли се критеријум за њихово расписивање заснива на потреби демократског разрешења кризе или на процени изборне користи за власт. Најављивање избора без њиховог расписивања Током кризе датум могућих избора био је предмет бројних јавних изјава, процена и промена најављених рокова. Помињани су различити периоди, али избори дуго нису били формално расписани. Анализа јавних изјава показује да су се потенцијални термини померали, што је одржавало трајну неизвесност о стварном почетку изборног процеса. Председник Републике је 23. јула 2026. године изјавио да очекује да парламентарни избори буду одржани у октобру или новембру и да би, у складу с тим, могли бити расписани у септембру или почетком октобра. У тренутку закључења ове редакције, 1. августа 2026. године, избори још нису били формално расписани. Јавна најава није правни акт. Она: не покреће законске изборне рокове; не утврђује дан гласања; не отвара формалну изборну кампању; не активира све обавезе изборне администрације; не обезбеђује правну сигурност учесницима; може бити промењена без правног поступка. Зато продужено најављивање избора може имати политички ефекат, иако нема правно дејство. Како неизвесност производи политичку предност Носиоци власти имају приступ информацијама и политичким проценама на основу којих могу планирати изборни тренутак. Ако се тачан датум зна само у уском кругу, владајућа странка може започети стварне припреме много пре формалног расписивања. Она може: организовати теренску мрежу; прикупљати податке о бирачима; активирати чланство; припремати кандидате; обезбедити финансијска средства; планирати јавне догађаје; временски распоредити социјална давања и инфраструктурне пројекте; прилагодити медијску стратегију; проценити најповољније економске и спољнополитичке околности. Други учесници остају у неизвесности. Ако започну кампању прерано, троше ограничене финансијске и организационе ресурсе без извесности када ће избори бити одржани. Ако чекају формално расписивање, могу ући у кампању са значајним закашњењем. Таква асиметрија је посебно изражена код: нових политичких покрета; група грађана; студентских или грађанских листа; мањих опозиционих странака; учесника који немају стабилно јавно финансирање; организација које тек треба да изграде инфраструктуру. Неизвесност, дакле, није једнако тешка за све. Политички субјект који контролише тренутак расписивања уједно има највише ресурса да неизвесност поднесе и искористи. Кампања пре кампање Формална изборна кампања почиње расписивањем избора. Политичка промоција, међутим, може започети много раније. У периоду када се избори јавно најављују, али нису расписани, могу се спроводити: појачане активности јавних функционера; обиласци градова и општина; представљање инфраструктурних пројеката; повећано медијско присуство; страначки скупови; теренске активности; прикупљање „сигурних гласова“; јавне најаве повећања примања и давања; негативне кампање против потенцијалних противника. Тај период можемо означити као предизборну кампању без формално расписаних избора . Његова посебна погодност за владајуће учеснике огледа се у томе што: поједине посебне изборне забране још нису активиране; не теку сви рокови за финансијско извештавање; надзорни органи активност могу третирати као редован политички или институционални рад; јавни функционери могу службене активности представљати као рад изван кампање; изборни конкуренти не знају када треба да започну пуни ангажман. Због тога контрола изборног интегритета не сме бити ограничена само на период од формалног расписивања избора до дана гласања. Избор најповољнијег тренутка Свака власт природно води рачуна о политичким последицама датума избора. Није реално очекивати да политички актери при доношењу одлуке потпуно занемаре сопствени рејтинг. Изборни инжењеринг настаје када могућност одређивања датума постане изразито једнострана предност и када не постоје довољни институционални критеријуми који ограничавају дискрецију. Политички најповољнији тренутак може бити изабран у односу на: тренутни рејтинг власти; слабост или неорганизованост конкурената; очекивана економска кретања; исплату плата, пензија или једнократних давања; завршетак јавних пројеката; међународне догађаје; школске и годишње одморе; интензитет протеста; временске услове; очекивану излазност појединих група бирача; могућност да се избори споје са другим нивоима гласања. Ниједан од ових фактора сам по себи не доказује злоупотребу. За озбиљну анализу потребно је показати образац: како су се јавне најаве, институционалне одлуке, кампањске активности и политички интереси временски повезивали. Форензичка реконструкција изборног календара Изборни календар се не анализира само према датуму на указу о распуштању Скупштине. Потребно је реконструисати целокупан процес доношења и јавног представљања одлуке. Анализа треба да обухвати: датум последњих парламентарних избора; почетак и очекивани крај редовног мандата; постојање или непостојање парламентарне већине; формалне разлоге Владе за предлагање распуштања; датум предлога Владе; датум указа председника; јавне најаве пре формалне одлуке; промене најављених термина; страначке активности пре расписивања; повећање броја јавних догађаја; временски распоред буџетских давања; покретање медијских кампања; стање рејтинга власти и опозиције; интензитет протеста; изборне реформе које су биле започете или незавршене. Посебно је корисно направити временску линију: Догађај Датум Формални или политички карактер Могући изборни значај Претходни избори формални почетак мандата Прва најава нових избора политички почетак неизвесности Следећа промена најављеног рока политички продужење предкампање Активирање страначке инфраструктуре политички организациона предност Предлог Владе за распуштање формални покретање уставног механизма Указ председника формални почетак изборног процеса Дан гласања формални завршна изборна радња Таква реконструкција омогућава да се разликује законита политичка процена од систематског коришћења неизвесности као изборног ресурса. Кључни докази За анализу ове врсте манипулације најважнији су: одлуке и предлози Владе; укази председника Републике; образложења распуштања Народне скупштине; стенограми и записници седница; службена саопштења; јавне изјаве о датуму избора; календар свих претходних избора; страначки планови и интерна комуникација, када су законито доступни; подаци о теренским активностима; извештаји о финансирању политичких активности; буџетска документација; календар јавних пројеката и давања; медијски мониторинг; извештаји домаћих и међународних посматрача; подаци о изменама изборних закона непосредно пред изборе. Једна нетачна или промењена најава није доказ изборног инжењеринга. Доказну снагу има низ најава и активности који показује да је један учесник располагао стварном информационом и организационом предношћу. Утицај на изборне реформе Учестали или неизвесни изборни циклуси отежавају спровођење препорука ODIHR-а и других реформи. Добра изборна пракса захтева да се суштинске измене изборних правила усвајају: довољно пре избора; у транспарентном поступку; након јавне расправе; уз учешће власти, опозиције и цивилног друштва; на основу широког политичког консензуса; уз довољно времена за обуку и примену. ODIHR је и 2026. године нагласио да изборна реформа треба да буде свеобухватна, инклузивна и окончана благовремено пре наредних избора. Истовремено је указао да су честе изборне активности и ограничен рад реформских тела раније ометали свеобухватне промене. Ако се датум избора држи у неизвесности, законодавне измене могу бити: убрзане непосредно пред гласање; усвојене без довољне расправе; примењене без припреме; одложене уз образложење да нема времена; селективно ограничене само на неколико препорука. Тако контрола календара може утицати не само на кампању већ и на правила по којима ће се избори одржати. Правни значај случаја Не постоји опште уставно право политичког субјекта да захтева изборе у датуму који му одговара. Председник и Влада имају уставна овлашћења и одговорност да процене да ли постоје услови за распуштање Скупштине. Ипак, начин коришћења тих овлашћења мора бити посматран у светлу: начела владавине права; политичког плурализма; равноправности изборних учесника; правне сигурности; периодичности избора; забране злоупотребе јавних овлашћења; обавезе да држава обезбеди услове за стварну политичку конкуренцију. Правна злоупотреба не мора увек бити лако доказива. Одлука о распуштању може бити формално у складу са Уставом, али истовремено производити политички асиметричне последице. Зато ова студија не тврди да је свако раније или касније расписивање избора незаконито. Она показује да формална уставност одлуке није довољна за потпуну оцену њеног утицаја на изборни интегритет. Утицај на изборни интегритет Злоупотреба изборног календара може имати системски утицај јер делује на све изборне учеснике и на читав период формирања политичке воље. Она може: дати власти информациону предност; продужити њену фактичку кампању; исцрпљивати ресурсе конкурената; спречити консолидацију нових листа; омогућити избор економски и медијски најповољнијег тренутка; скратити време за примену изборних реформи; отежати припрему посматрачких мисија; подстаћи спајање различитих избора; претворити расписивање избора у средство притиска и политичког преговарања; одржавати друштво у трајном предизборном стању. Последица није нужно видљива у једном записнику или једном броју гласова. Она се огледа у неравноправности почетних позиција и у томе ко има могућност да одреди када утакмица заиста почиње. Разлика између политичке одлуке и изборне манипулације Није свака политички мотивисана одлука о датуму избора изборна манипулација. Избори су по природи политички процес, па је немогуће одлуку потпуно одвојити од интереса политичких актера. На изборни инжењеринг могу указивати следеће околности посматране заједно: ванредни избори се често расписују без губитка већине; образложења су општа или се понављају; избори се избегавају када постоји дубока друштвена криза и јасан захтев за проверу легитимитета; јавне најаве се често мењају; владајућа странка започиње припреме пре конкурената; службене активности нагло се повећавају пре формалног расписивања; социјална давања и јавни пројекти временски се прилагођавају очекиваном гласању; изборне реформе остају недовршене; не постоје објективни и проверљиви разлози за избор конкретног тренутка. Ниједан од ових елемената није самосталан доказ. Њихова комбинација може указати да календар више није само последица политичке кризе, већ средство њеног управљања у корист једног учесника. Поуке и препоруке Овај случај показује да изборни интегритет почиње пре расписивања избора. Услови политичке конкуренције обликују се и у периоду када формални изборни рокови још не теку. Зато је потребно: унапредити образлагање предлога Владе за распуштање Народне скупштине; јавно објавити све акте и разлоге на којима је одлука заснована; размотрити прецизније критеријуме за расписивање ванредних парламентарних избора; обезбедити што већу предвидивост редовног изборног календара; избегавати учестало скраћивање мандата без јасне институционалне потребе; ограничити продужено и неодређено најављивање избора; применити правила о злоупотреби јавних ресурса и на период непосредно пре формалног расписивања када је изборна намера очигледна; проширити мониторинг функционерске кампање на предизборни период; објављивати податке о ванредним јавним давањима, запошљавању и инфраструктурним активностима у том периоду; обезбедити да све важне измене изборних закона буду усвојене довољно пре избора; оставити довољно времена за примену препорука ODIHR-а, обуку изборне администрације и независну контролу; избегавати спајање различитих нивоа избора када оно потискује локалне теме или производи изразиту предност национално доминантном учеснику; размотрити успостављање јавног, дугорочног оквирног календара редовних избора; омогућити независним институцијама и истраживачима да анализирају ефекте избора датума на јавну потрошњу, медијско присуство и равноправност учесника. Најважнија поука је да онај ко контролише почетак изборне утакмице може стећи предност и пре него што је објављен први изборни плакат. Уколико један политички субјект фактички зна када ће избори бити одржани, док сви остали месецима зависе од променљивих јавних најава, формално једнака дужина кампање не значи и стварно једнаке услове. Ванредни избори треба да служе демократском разрешењу кризе, а не да криза буде продужавана или прекидана у тренутку који највише одговара носиоцу власти. Када се избори расписују онда када политичка процена власти показује предност, а одлажу онда када постоји снажан друштвени захтев за провером легитимитета, изборни календар престаје да буде само уставни механизам. Он постаје део изборног инжењеринга. Манипулације и институционалне слабости које ова студија илуструје: PRE-11 — злоупотреба изборног календара; PRE-12 — тактичко расписивање ванредних избора; PRE-13 — одлагање избора ради избора повољнијег политичког тренутка; PRE-14 — продужена предизборна кампања пре формалног расписивања; PRE-15 — спајање различитих нивоа избора ради преношења националне политичке предности; PRE-16 — стварање информационе и организационе асиметрије; PRE-17 — скраћивање времена за изборне реформе и припрему учесника. Главни извори: Устав Републике Србије; одлуке о распуштању Народне скупштине и расписивању ванредних избора; изборни календар парламентарних избора од 2014. до 2026. године; Коначни извештаји ODIHR-а о изборима 2023. и 2024. године; Мишљење ODIHR-а о изменама изборног законодавства из 2026. године; јавни захтеви студентског протестног покрета за ванредне парламентарне изборе; јавне изјаве о могућим терминима избора. ← Студија 9 Преглед студија →"},{"title":"Студија случаја 2: Притисци на запослене у јавном сектору – политичка лојалност као услов радне и социјалне сигурности — Атлас изборних манипулација","url":"pages/studija-2.html","text":"Студија случаја 2: Притисци на запослене у јавном сектору – политичка лојалност као услов радне и социјалне сигурности — Атлас изборних манипулација АТЛАС изборних манипулација Ћир Lat Почетна / Студије случаја / 2 Прилог 2 · Документовани пример из изборне праксе Притисци на запослене у јавном сектору – политичка лојалност као услов радне и социјалне сигурности Студија случаја 2 Притисци на запослене у јавном сектору – политичка лојалност као услов радне и социјалне сигурности Слободно бирачко право подразумева да грађанин политичку одлуку доноси без претње, принуде, условљавања или страха од последица. Формална тајност гласања није довољна ако је бирач пре доласка на бирачко место изложен притиску послодавца, руководиоца или лица од којег зависи његов радни статус, приход или професионална будућност. Запослени у јавном сектору посебно су изложени овом ризику. Њихов положај често зависи од одлука руководилаца које постављају или контролишу политички органи, док су запослени на одређено време, лица ангажована по привременим уговорима и радници у јавним предузећима додатно рањиви због неизвесности радног статуса. У таквом окружењу и захтев који није праћен отвореном претњом може бити схваћен као налог чије одбијање носи последице. Притисак се не мора састојати у непосредном наређењу да се гласа за одређену изборну листу. Он се може испољити кроз обавезу присуствовања страначким скуповима, прикупљања „сигурних гласова“, достављања података о члановима породице, рада у страначком кол-центру, дељења пропагандног материјала, обезбеђивања потписа подршке или доказивања да је запослени испунио политички задатак. Када се такви захтеви повежу са продужењем уговора, напредовањем, премештајем, распоредом рада или претњом губитком посла, политичка активност престаје да буде добровољна. Контекст избора 2023. и 2024. године Током ванредних парламентарних избора одржаних 17. децембра 2023. године ODIHR је забележио наводе о притисцима на запослене у јавном сектору и оценио да су, заједно са злоупотребом јавних ресурса, такве праксе довеле у питање способност бирача да свој избор изврше без недозвољеног утицаја. У сажетку коначног извештаја наведено је да су основне слободе у кампањи углавном поштоване, али да су биле нарушене притисцима на запослене у јавном сектору, злоупотребом јавних ресурса и другим облицима неравноправности. Исти проблем није нестао у наредном изборном циклусу. У Коначном извештају о локалним изборима од 2. јуна 2024. године ODIHR је притиске на запослене у јавном сектору означио као широко распрострањену забринутост која је негативно утицала на изборни процес. Мисија је навела да су пријаве таквих притисака добијене у Београду, Чачку, Кикинди, Нишу, Новом Саду, Рашки, Сомбору, Суботици, Вршцу и Зрењанину. Понављање истих навода у различитим изборним циклусима и у већем броју градова не доказује аутоматски да је свака појединачна пријава истинита. Оно, међутим, указује да се не ради само о једном изолованом радном спору или појединачном неспоразуму, већ о проблему који захтева системску институционалну реакцију. Начини на које се притисак спроводи Политички притисак на запослене најчешће се не спроводи формалним писаним налогом у којем се изричито захтева гласање за одређену листу. Такав доказ би био сувише непосредан и лако проверљив. У пракси се користе посреднији механизми, прилагођени хијерархији радног места и зависности запосленог од руководиоца. Најчешће описивани облици обухватају: захтев да запослени обезбеди одређени број „сигурних гласова“; достављање спискова чланова породице, пријатеља или корисника услуга; обавезу присуствовања страначком скупу; организовани одлазак запослених на политичке догађаје; ангажовање у страначком кол-центру или теренској кампањи; прикупљање потписа подршке изборној листи; коришћење службених телефона, возила, просторија или радног времена за страначке активности; праћење да ли су запослени и чланови њихових породица изашли на изборе; условљавање продужења уговора, распоређивања или напредовања; претњу премештајем, смањењем прихода, дисциплинским поступком или отказом; захтев да се гласање на неки начин докаже. У многим случајевима претња није изговорена. Запосленом се само саопштава шта се „очекује“, уз свест о томе да руководилац одлучује о његовом уговору, радном месту, смени или професионалном напредовању. Управо због тога је правно и доказно тешко раздвојити добровољан политички активизам од активности предузете под притиском. Запослени има право да буде политички активан, да буде члан странке, присуствује скуповима и учествује у кампањи. Манипулација постоји када политичка активност престане да буде ствар слободног избора и постане стварна или прећутна обавеза заснована на радној зависности. Посебно угрожене категорије запослених Нису сви запослени подједнако изложени притиску. Посебно су рањива лица чији радни однос није трајно заштићен или чија материјална сигурност непосредно зависи од одлуке руководиоца. То се нарочито односи на: запослене на одређено време; лица ангажована по уговорима о привременим и повременим пословима; раднике јавних и јавно-комуналних предузећа; запослене у локалним управама и установама; раднике у здравственим и образовним установама; запослене у социјалним службама; лица запослена преко посредничких агенција; запослене код приватних послодаваца који значајан део прихода остварују кроз јавне набавке, субвенције или послове са државом. ODIHR је у извештају о локалним изборима 2024. године навео да су се пријаве односиле и на руководеће запослене у службама социјалног осигурања, домовима здравља, јавним комуналним предузећима, као и управама школа и предшколских установа. Овај податак је важан јер указује да механизам не мора бити ограничен само на непосредан однос политичког функционера и обичног запосленог. Притисак се може преносити кроз читаву управљачку хијерархију: од политички постављеног руководства, преко директора и шефова организационих јединица, до појединачних радника. Таква структура омогућава да се политички налог формално не може лако повезати са његовим извором. Сваки ниво хијерархије може захтев представити као сопствену иницијативу, колегијалну молбу или добровољну активност, иако се исти задатак истовремено појављује у већем броју институција. „Сигурни гласови“ као систем организационе контроле Један од најчешће описиваних механизама јесте обавеза обезбеђивања „сигурних гласова“. Запосленом се задаје да достави имена и контакт-податке лица за која тврди да ће подржати одређену изборну листу. На тај начин се од њега не тражи само лична политичка лојалност већ и да постане посредник у ширењу политичке контроле на породицу, пријатеље, колеге или кориснике јавних услуга. Овај механизам може обухватити више фаза: руководилац одређује квоту; запослени доставља списак лица; подаци се уносе у паралелну страначку евиденцију; лица се позивају током кампање; на дан избора прати се њихова излазност; запослени извештава да ли су лица са његовог списка гласала; испуњење задатка може утицати на процену његове политичке подобности. Појединачно посматрано, телефонски позив бирачу или разговор запосленог са чланом породице не мора бити незаконит. Системски проблем настаје када се лични подаци прикупљају кроз службену хијерархију, када постоје квоте и извештавање и када се учешће запосленог не заснива на слободној вољи. У таквим околностима притисак на запосленог повезује се са другим манипулацијама описаним у Атласу: капиларним гласовима, паралелним списковима, незаконитом обрадом података о политичком опредељењу и организованим праћењем излазности. Притисак кроз обавезно присуство политичким скуповима Други чест облик представља организовање запослених за присуство политичким скуповима. Само присуство запослених на скупу није доказ принуде. Они могу бити присталице странке и добровољно учествовати у политичком животу. На могући притисак указују додатне околности, као што су: састављање спискова присутних; организовање превоза из установе или предузећа; подела запослених по аутобусима и координаторима; обавеза фотографисања на месту скупа; провера присуства путем телефона или групних порука; одржавање скупа у радно време; коришћење службених возила или других јавних ресурса; негативне последице за лица која су одбила да присуствују. Доказна вредност једне фотографије аутобуса или групе запослених је ограничена. Међутим, ако се она повеже са списком путника, порукама руководиоца, распоредом радног времена, сведочењима више запослених и доказима о последицама за оне који су одбили учешће, може се реконструисати организовани механизам. Налази ODIHR-а за изборе 2023. године ODIHR је у Коначном извештају за изборе 2023. године оценио да су случајеви притисака на запослене у јавном сектору, заједно са злоупотребом јавних ресурса и различитим облицима подстицања бирача, изазвали забринутост у погледу способности грађана да свој избор направе без непримереног утицаја. Ови налази нису формулисани као судска одлука којом је доказана кривична или друга одговорност конкретних лица. Посматрачка мисија прикупља информације од великог броја саговорника, прати обрасце и оцењује изборно окружење у целини. Зато њени налази представљају документовану посматрачку оцену, а не замену за поступак пред тужилаштвом или судом. Ипак, значај извештаја је у томе што притисци нису третирани као споредни инциденти, већ као један од фактора који су допринели неједнаким условима изборне утакмице и замагљивању границе између државе и владајуће странке. Наставак истог обрасца на локалним изборима 2024. године Коначни извештај ODIHR-а о локалним изборима 2024. године пружа додатну основу за закључак да проблем није био ограничен на један изборни циклус. Мисија је пријаве притиска забележила у десет градова и општина и навела да су се односиле на различите делове јавног сектора. У извештају се наводи да су распрострањене тврдње о притисцима на запослене и злоупотреби јавних ресурса: довеле у питање могућност бирача да одлучују без недозвољеног утицаја; обезбедиле неоправдану предност владајућој странци и коалицији; замаглиле границу између државе и странке; биле супротне обавезама које произлазе из докумената ОЕБС-а. У једном поступку пред локалном изборном комисијом у Вршцу поднет је приговор са тврдњом о застрашивању запослених у јавним предузећима. Приговор је одбијен као неоснован, уз оцену да описане неправилности не представљају законски основ за поништавање избора, док је каснија жалба Вишем суду одбачена као неблаговремена. Овај случај не доказује тачност навода о притиску, али показује ограничење изборноправне заштите: чак и када се притисак пријави, он се не мора уклапати у уско прописане разлоге за поништавање гласања на конкретном бирачком месту. Притисак се, наиме, најчешће дешава пре изборног дана, у радној средини, и може обухватати већи број бирача распоређених на различитим бирачким местима. Зато га је тешко отклонити правним средством које је првенствено усмерено на неправилности настале током гласања или бројања на једном месту. Зашто се притисци тешко доказују Притисак на запослене спада у изборне манипулације које је најтеже доказати. Лице које је изложено притиску често истовремено представља и главног сведока и лице које може претрпети одмазду. Најчешћи разлози због којих запослени не пријављују притисак јесу: страх од губитка посла или непродужавања уговора; страх од премештаја или професионалне изолације; неповерење у интерне механизме заштите; уверење да су руководиоци и надлежне институције политички повезани; недостатак писаног доказа; страх да ће идентитет пријавиоца бити откривен; сумња да поступак неће бити окончан пре избора; зависност других чланова породице од исте институције или локалне власти. Због тога изостанак великог броја формалних пријава не мора значити да притисака није било. Са друге стране, анонимна тврдња сама по себи није довољна да се конкретно лице означи као одговорно. Потребно је истовремено заштитити сведоке и очувати стандард доказивања. Форензичка реконструкција притиска Овакви случајеви ретко се могу доказати једним документом. Највећу доказну снагу има повезивање више независних извора. Реконструкција треба да обухвати: ко је упутио захтев; у ком својству је то лице наступало; ком броју запослених је исти или сличан захтев упућен; да ли је постојала квота гласова или обавеза присуства; да ли је комуникација вођена службеним каналима; да ли је активност организована током радног времена; да ли су коришћена службена возила, просторије или опрема; да ли је вођена евиденција о извршеним задацима; да ли су лица која су одбила захтев претрпела последице; да ли постоје слична сведочења у другим организационим јединицама или установама. Посебно су значајни: оригиналне поруке и електронска пошта; групне комуникације са метаподацима; табеле са именима и квотама; спискови за превоз или присуство; распореди рада; налози руководилаца; уговори о раду и одлуке о њиховом продужењу; решења о премештају или дисциплинским мерама; искази више независних сведока; временска повезаност одбијања политичког задатка и касније штетне последице. Ниједан од ових елемената не мора самостално доказивати политички притисак. На пример, непродужавање уговора може имати законит разлог. Међутим, ако је више запослених претходно добило исти политички задатак, ако је руководилац најавио последице, а уговори нису продужени управо лицима која су одбила учешће, доказна слика постаје знатно снажнија. Однос добровољне политичке активности и недозвољеног притиска Јавни службеници и запослени у јавним предузећима имају политичка права као и други грађани. Не може се претпоставити да је њихово присуство страначком скупу, чланство у странци или учешће у кампањи последица принуде. За правну оцену значајно је утврдити: да ли је активност била добровољна; да ли је запослени могао да одбије без последица; да ли је захтев упутио руководилац користећи службени ауторитет; да ли се активност одвијала у радно време; да ли су коришћени јавни ресурси; да ли је политички ангажман утицао на радни статус; да ли је исти захтев систематски упућиван већем броју запослених. Кључна граница није у томе да ли је запослени политички активан, већ да ли је његова егзистенцијална зависност употребљена како би се обезбедила политичка подршка. Правни значај случаја Притисак на запослене може истовремено повредити више права и јавних интереса: слободу политичког опредељења; једнакост и слободу бирачког права; тајност гласања; забрану дискриминације по основу политичког уверења; права из радног односа; политичку неутралност јавне управе; законито и наменско коришћење јавних ресурса; правила о заштити података о личности. У зависности од начина извршења, конкретно поступање може представљати повреду радних обавеза, дискриминацију, злоупотребу службеног положаја, незакониту обраду личних података или дело против изборних права. Коначна правна квалификација зависи од садржаја захтева, положаја лица које га је упутило, врсте претње, последица и расположивих доказа. Посебан проблем представља расцепканост надлежности. Запослени се може обратити инспекцији рада, послодавцу, синдикату, Поверенику за заштиту равноправности, Агенцији за спречавање корупције, Поверенику за информације од јавног значаја и заштиту података о личности, полицији или јавном тужилаштву. Међутим, ниједан од ових органа не мора самостално сагледати читав изборни механизам. Тако појединачна пријава може бити третирана као радни спор, друга као питање заштите података, трећа као политичка активност, а четврта као могуће кривично дело. Ако се предмети не повежу, системски образац остаје невидљив. Утицај на изборни интегритет Притисци на запослене могу имати системски утицај и када није могуће доказати за кога је сваки појединачни запослени гласао. Њихова последица није само могућа промена одређеног броја гласова, већ стварање окружења у којем велики број грађана верује да власт или послодавац могу контролисати њихово политичко понашање. Такав страх може: утицати на избор политичке опције; приморати запосленог да учествује у кампањи; одвратити га од јавне подршке опозицији; спречити пријављивање неправилности; проширити притисак на чланове породице; омогућити формирање великих база „сигурних гласова“; обезбедити владајућој странци организациону инфраструктуру финансирану јавним средствима. Посебно је значајно што се овај механизам сам обнавља. Руководиоци који свој положај дугују политичкој власти могу захтевати подршку од подређених; запослени учествују из страха за радно место; изборни успех задржава исте руководиоце и продужава систем зависности до следећих избора. Поуке и препоруке Овај случај показује да тајност гласања не може сама по себи заштитити слободну изборну вољу. Бирач може гласати иза паравана, али његова одлука ипак није слободна ако верује да од политичке лојалности зависи посао, зарада или сигурност породице. Понављање навода у извештајима ODIHR-а за изборе 2023. и 2024. године указује да се проблем не може свести на неколико изолованих инцидената. Истовремено, због прикривене природе притиска и страха сведока, сваку конкретну тврдњу потребно је пажљиво проверити и не представљати је као утврђену чињеницу без одговарајућих доказа. Зато је потребно: установити безбедне и поверљиве канале за пријављивање политичких притисака; обезбедити стварну заштиту узбуњивача и сведока од радноправне и друге одмазде; прописати кратке рокове за поступање по пријавама током изборног периода; омогућити заједничко поступање инспекције рада, антикорупцијских органа, органа за заштиту података, полиције и тужилаштва када пријаве указују на организован образац; забранити употребу службених канала, радног времена и јавних ресурса за страначке задатке; појачати контролу запошљавања на одређено време и привремених ангажмана у јавном сектору током изборног периода; водити статистику о пријавама, поступцима и њиховим исходима, без откривања идентитета заштићених лица; обезбедити делотворне и одвраћајуће санкције за руководиоце који радни положај користе за политичко условљавање; омогућити да докази о системском притиску буду разматрани и у поступцима за оцену интегритета избора, а не само као изоловани радни спорови. Најважнија поука је да политички притисак не мора бити изричит да би био делотворан. У систему у којем руководилац контролише уговор, напредовање или егзистенцију запосленог, и наизглед обична „молба“ може имати снагу наређења. Зато се слобода избора не штити само у бирачкој кабини, већ и на радном месту, у јавном предузећу, школи, здравственој установи, локалној управи и свакој институцији у којој политичка моћ може бити претворена у средство личног и економског притиска. Манипулације које ова студија илуструје: PRE-07 — притисци на запослене пре кампање; PRE-08 — незаконито прикупљање података о политичком опредељењу; PRE-09 — стварање зависности кроз јавна давања и запошљавање; KAM-04 — политички притисак, претња и уцена; KAM-05 — капиларни гласови и мрежа сигурних гласова; KAM-06 — паралелни бирачки спискови; KAM-11 — злоупотреба јавних догађаја и институција. Главни извори: Коначни извештај ODIHR-а о ванредним парламентарним изборима од 17. децембра 2023. године; Коначни извештај ODIHR-а о локалним изборима од 2. јуна 2024. године; извештаји домаћих посматрачких организација и пријаве надлежним институцијама. ← Студија 1 Студија 3 →"},{"title":"Студија случаја 3: Неравноправни услови изборне кампање – функционерска кампања и злоупотреба јавних ресурса — Атлас изборних манипулација","url":"pages/studija-3.html","text":"Студија случаја 3: Неравноправни услови изборне кампање – функционерска кампања и злоупотреба јавних ресурса — Атлас изборних манипулација АТЛАС изборних манипулација Ћир Lat Почетна / Студије случаја / 3 Прилог 2 · Документовани пример из изборне праксе Неравноправни услови изборне кампање – функционерска кампања и злоупотреба јавних ресурса Студија случаја 3 Неравноправни услови изборне кампање – функционерска кампања и злоупотреба јавних ресурса Равноправност изборне утакмице подразумева да политички учесници наступају под условима који им омогућавају стварну конкуренцију. То не значи да сви морају располагати истим новцем, организацијом или медијском видљивошћу, али државна власт не сме своју институционалну моћ, буџет, службене ресурсе и јавну функцију претворити у трајну изборну предност једног политичког субјекта. Функционерска кампања настаје када се службена активност јавног функционера користи за непосредну или посредну промоцију изборне листе. Злоупотреба јавних ресурса постоји када се јавни новац, службена возила, просторије, опрема, запослени, базе података, јавни догађаји или институционални налози користе у страначку сврху. Ове две појаве често су нераздвојне. Јавни функционер има право и обавезу да обавља своју дужност и током изборне кампање. Није свака посета градилишту, отварање објекта, сусрет са грађанима или медијско извештавање о раду институције изборна злоупотреба. Проблем настаје када се службена функција користи као средство изборне промоције, када се јавни догађаји временски и садржински прилагођавају кампањи, када се институционална комуникација претвара у страначку пропаганду или када трошак политичке промоције сносе грађани. Контекст избора 2023. године Коначни извештај ODIHR-а о ванредним парламентарним изборима од 17. децембра 2023. године оценио је да су изборима доминирали преовлађујуће присуство и ангажовање председника Републике, што је, заједно са системском предношћу владајуће странке, створило неједнаке услове за изборне учеснике. Мисија је навела да су притисци на запослене у јавном сектору, злоупотреба јавних ресурса и нејасна граница између државе и странке негативно утицали на изборно окружење. Посебна околност била је то што председник Републике није био кандидат на парламентарним изборима, али је његово име било носећи део назива изборне листе владајуће коалиције, док је он истовремено био највидљивији актер кампање. На тај начин службена видљивост председничке функције, активности шефа државе и медијско праћење његовог рада били су тесно повезани са промоцијом једног изборног учесника. Ово не значи да је свака активност председника током кампање била незаконита. Председник Републике наставља да врши уставне дужности без обзира на изборе. Међутим, када исти функционер доминира кампањом изборне листе чији назив носи његово име, а медијско извештавање не прави јасну разлику између његових службених и страначких наступа, институционална предност функције прелива се у изборну корист. Механизам функционерске кампање Функционерска кампања најчешће не изгледа као класичан политички оглас. Њена предност је управо у томе што се политичка промоција представља као редовна службена активност. Механизам може изгледати овако: функционер најављује или посећује јавни пројекат; догађај организује и финансира јавна институција; користе се службена возила, обезбеђење, протокол и запослени; медији догађај преносе као вест од јавног значаја; функционер у говору истиче резултате власти, обећава нове пројекте или критикује политичке противнике; страначки налози преузимају снимке и фотографије; исти материјал постаје део изборне кампање; трошак организације и медијске производње не приказује се као трошак политичког субјекта. На тај начин један догађај може истовремено обухватити: функционерску кампању; злоупотребу јавних ресурса; прикривено политичко оглашавање; медијску доминацију; непријављени или прикривени трошак кампање. Атлас управо зато ове појаве не посматра изоловано, већ као делове истог механизма. Шта све може бити јавни ресурс Јавни ресурс није само новац из буџета. Он обухвата све што је функционеру или институцији доступно због вршења јавне власти, а што другим изборним учесницима није доступно под истим условима. То може укључивати: службена возила и гориво; службене просторије; опрему, телефоне и рачунаре; службене налоге на друштвеним мрежама; запослене у јавним органима и установама; радно време запослених; базе података и контакт-податке грађана; јавна предузећа; јавне медије и медије финансиране јавним новцем; протоколарне и безбедносне ресурсе; буџетске програме и јавна давања; јавне инфраструктурне пројекте; хуманитарне, социјалне или здравствене услуге које се представљају као заслуга политичке странке. Само коришћење неког од ових ресурса током кампање није аутоматски незаконито. Потребно је утврдити сврху, начин употребе, садржај поруке, време активности, организатора и везу са конкретним изборним учесником. Временско концентрисање јавних активности Један од показатеља функционерске кампање јесте нагло повећање броја службених активности непосредно пред изборе. То могу бити: отварања путева, школа, болница и других објеката; обиласци градилишта; доделе станова, субвенција или помоћи; потписивање уговора; најаве повећања плата или пензија; доделе једнократне новчане помоћи; јавне посете установама; промоција пројеката који су раније започети, али се представљају као нова постигнућа. Ниједан од ових догађаја сам за себе не доказује злоупотребу. Држава и локална самоуправа не смеју престати да функционишу током кампање. Ипак, ако се број таквих активности нагло повећа, ако се оне организују у срединама важним за изборни резултат и ако је њихова медијска презентација очигледно усмерена на промоцију једне листе, настаје образац који захтева проверу. За анализу је важно упоредити: број службених догађаја пре кампање и током кампање; датуме завршетка пројеката и датуме њихове промоције; институционални и страначки садржај говора; присуство страначких симбола; начин медијског извештавања; преузимање службеног материјала на страначке налоге; стварни извор финансирања. Ванредна јавна давања као изборни ресурс Посебан ризик представљају ванредна социјална давања и програми помоћи који се уводе након расписивања избора. Социјална политика и помоћ грађанима представљају легитимне обавезе државе. Проблем настаје када се ванредна давања временски вежу за кампању, када се представљају као лични поклон функционера или странке и када нема јасног дугорочног програмског и законског основа. ODIHR је у извештају о локалним изборима 2. јуна 2024. године навео да је више локалних самоуправа, укључујући привремени орган Града Београда, након расписивања избора понудило програме социјалне помоћи, што је изазвало забринутост због могуће злоупотребе државних ресурса. Мисија је зато препоручила разматрање забране најављивања и спровођења ванредних социјалних програма и јавних инфраструктурних пројеката након расписивања избора. Наведена оцена не значи да је свака појединачна мера била незаконита или да су сви корисници помоћ добили у замену за глас. Значај је у томе што се јавна средства могу користити тако да створе политички ефекат непосредно пред гласање, чак и без изричитог условљавања корисника. Да би се разликовала редовна социјална мера од изборне злоупотребе, треба проверити: да ли је мера била планирана пре расписивања избора; да ли је предвиђена буџетом; да ли се примењује према општим и унапред познатим критеријумима; да ли је временски ограничена само на кампању; да ли је функционер представља као личну или страначку заслугу; да ли се при додели користе страначка обележја; да ли се прикупљају политички подаци о корисницима; да ли постоји очекивање политичке противуслуге. Службени и институционални налози на друштвеним мрежама Савремена злоупотреба јавних ресурса све чешће се спроводи преко интернета. Службени налози органа, градова, општина, јавних предузећа и функционера имају публику, инфраструктуру и кредибилитет стечене јавним положајем. Када се они користе за промоцију странке, јавни ресурс се претвара у бесплатан канал политичког оглашавања. ODIHR је током локалних избора 2024. године забележио страначке и кампањске објаве на појединим званичним налозима јавних институција, градоначелника и општина, што је изазвало забринутост због злоупотребе државних ресурса у кампањи. Мисија је препоручила јасније регулисање онлајн кампање јавних институција и функционера, као и надзор са делотворним и сразмерним санкцијама. Овај облик злоупотребе може бити нарочито прикривен. Институционална објава често формално садржи информацију о раду органа, али је написана и визуелно обликована тако да истиче име, лик, слоган или резултате странке. Касније се исти садржај преноси на страначке налоге, без плаћања огласног простора и без евидентирања вредности произведеног материјала као доприноса кампањи. Налази ODIHR-а за изборе 2023. године ODIHR је у извештају за 2023. годину закључио да су изборном кампањом доминирали актуелни председник и владајућа странка, уз системску предност која је створила неједнаке услове. Посебно су истакнути: преовлађујуће учешће председника; нејасна граница између државе и странке; злоупотреба јавних ресурса; институционална и медијска предност власти; недовољно ефикасан надзор над злоупотребама. Извештај је указао да правни оквир није на задовољавајући начин решио раздвајање јавне функције и кампањских активности, нити обезбедио ефикасне механизме за спречавање злоупотребе положаја и државних ресурса. Ова оцена не значи да су све активности власти биле незаконите. Она се односи на укупан ефекат кампање, у којој је институционална видљивост била у функцији политичке предности једног учесника. Наставак проблема на локалним изборима 2024. године У Коначном извештају за локалне изборе 2024. године ODIHR је поново оценио да су злоупотреба јавних ресурса и притисци на запослене негативно утицали на изборни процес и замаглили границу између државе и странке. Мисија је указала на: ванредне програме социјалне помоћи након расписивања избора; кампањске садржаје на службеним налозима институција; коришћење активности јавних функционера у страначкој промоцији; пријаве о употреби државних ресурса у корист владајуће странке; ограничено и недовољно проактивно поступање надзорних органа. Понављање истих оцена у два узастопна изборна циклуса показује да проблем није отклоњен изменама прописа из 2022. године и да се не може посматрати као низ неповезаних инцидената. Поступање Агенције за спречавање корупције Агенција за спречавање корупције надлежна је за контролу злоупотребе јавних ресурса и функције у кампањи, као и за надзор финансирања политичких активности. Према извештају ODIHR-а за локалне изборе 2024. године, Агенција је до изборног дана примила 60 пријава, од којих се око 30 односило на јавне функционере и коришћење државних ресурса. Део пријава односио се на бесплатне правне услуге и курсеве српског језика, доделу инвалидских колица, хуманитарне активности и коришћење јавних ресурса за промоцију странке. Агенција је изрекла 14 упозорења Српској напредној странци. У појединим случајевима наложила је уклањање објава са друштвених мрежа које су се односиле на хуманитарне активности и упозорила странку да на својим налозима не дели активности јавних функционера. Међутим, неке одлуке којима је наложено уклањање садржаја донете су тек након избора. Овај податак илуструје један од главних проблема правне заштите у кампањи: чак и када надзорни орган утврди повреду, одлука донета након гласања више не може уклонити већ произведену изборну корист. Садржај је већ стигао до бирача, медијска порука је већ пренета, а политички ефекат је остварен. ODIHR је такође навео да бројни саговорници сматрају да Агенција не истражује довољно активно могуће повреде по службеној дужности. Додатни проблем представља то што се неки акти Агенције доносе у форми обавештења, а не формалне управне одлуке, због чега није увек обезбеђена делотворна судска контрола. Зашто је злоупотребу тешко доказати Функционерска кампања и злоупотреба јавних ресурса најчешће се не могу доказати једном фотографијом, говором или службеним путовањем. Потребно је утврдити читав контекст. Кључна питања су: ко је организовао догађај; ко га је финансирао; да ли је био планиран пре расписивања избора; да ли је постојала стварна службена потреба; какав је био садржај говора; да ли су коришћени страначки слогани и симболи; ко је производио фотографије и видео-материјал; где је материјал касније објављен; да ли је његова вредност пријављена у трошковима кампање; да ли су други изборни учесници имали упоредив приступ истом ресурсу; да ли се сличан образац понављао током целе кампање. Највећу доказну вредност могу имати: службени распореди и протоколарни документи; буџетска и финансијска документација; фактуре; налози за службена путовања; евиденције коришћења возила; уговори са медијским и продукцијским кућама; оригинални снимци и фотографије; метаподаци и време објављивања; институционалне и страначке објаве истог садржаја; извештаји Агенције за спречавање корупције; сведочења запослених и организатора. Једна фотографија функционера поред јавног објекта није доказ злоупотребе. Али велики број службених активности које временски, садржински, организационо и медијски прате изборну кампању може представљати снажан доказ обрасца. Разлика између службене дужности и изборне промоције Најосетљивије питање јесте где се налази граница између законитог вршења јавне функције и функционерске кампање. При оцени треба узети у обзир: да ли је догађај неопходан за редовно функционисање органа; да ли се сличне активности одржавају и ван изборног периода; да ли функционер говори у име институције или странке; да ли се помињу избори, политички противници и страначки резултати; да ли су присутни страначки симболи; да ли је службени догађај касније укључен у страначку кампању; да ли се користе институционални ресурси за производњу политичког садржаја; да ли су јавне мере представљене као лични поклон функционера. Функционер не престаје да буде политичар док обавља јавну дужност. Ипак, државна функција не сме бити средство којим се заобилазе правила кампање и стиче предност недоступна конкурентима. Финансијски ефекат злоупотребе Злоупотреба јавних ресурса има и непосредну финансијску димензију. Ако јавна институција плати догађај, превоз, продукцију снимка, обезбеђење, запослене и медијску промоцију, а странка користи резултат у кампањи, политички субјект добија корист коју није платио из средстава кампање. То може довести до: прикривања стварног обима трошкова; заобилажења правила о финансирању кампање; неједнакости између учесника; коришћења буџета за политичку пропаганду; смањења могућности јавне контроле. У Атласу је овај механизам описан као повезивање службеног догађаја, јавног финансирања, медијског преноса и касније страначке употребе истог материјала. Правни значај случаја Функционерска кампања и злоупотреба јавних ресурса могу повредити више правних и демократских начела: равноправност изборних учесника; политичку неутралност јавне управе; законито и наменско трошење буџетских средстава; правила о финансирању политичких активности; правила о спречавању корупције; забрану коришћења јавне функције за стицање политичке користи; право бирача да информације примају без прикривене институционалне пропаганде. Конкретна правна квалификација зависи од радње. Она може представљати повреду правила о јавним функционерима, неправилност у финансирању кампање, злоупотребу јавних средстава, повреду радних обавеза, прекршај или, у тежим случајевима, кривично дело. Међутим, правни оквир често појединачно уређује сваки сегмент, док је изборна предност резултат њиховог комбинованог дејства. Један орган контролише буџет, други понашање функционера, трећи финансирање кампање, четврти медије. Уколико се ти поступци не повежу, системски механизам може остати ван целовите правне оцене. Утицај на изборни интегритет Злоупотреба јавних ресурса има висок или системски утицај када траје током целе кампање и када је повезана са медијском доминацијом. Њена последица није само уштеда новца за једну странку, већ стварање утиска да су држава, јавне институције и владајући политички субјект једна иста целина. Такав механизам: повећава видљивост власти; омогућава континуирану бесплатну промоцију; потискује изборне конкуренте; јавне услуге и давања претвара у политичку заслугу; користи институционални ауторитет као средство убеђивања; нарушава поверење у политичку неутралност јавних органа; чини изборну утакмицу формално отвореном, али суштински неравноправном. Посебно је опасно када се овакав модел нормализује и представља као уобичајено вршење власти. Тада граница између државе и странке постепено нестаје, а јавни ресурси постају трајна инфраструктура владајућег политичког субјекта. Поуке и препоруке Овај случај показује да изборна кампања не постаје неравноправна само због већег броја плаћених огласа или јаче страначке организације. Она постаје суштински неравноправна када један учесник може да користи целокупну видљивост, имовину, запослене и комуникациону моћ државе, док остали учесници морају све активности да финансирају и организују из сопствених средстава. Зато је потребно: јасније законски разграничити службене активности и изборну промоцију; увести посебна правила за понашање јавних функционера током кампање; забранити најављивање и спровођење ванредних социјалних давања и инфраструктурних пројеката након расписивања избора, осим у случају стварне и доказиве хитности; забранити коришћење службених налога институција за страначку промоцију; обавезати институције и политичке субјекте да пријаве свако преузимање службеног материјала за потребе кампање; процењивати тржишну вредност јавних ресурса употребљених у политичке сврхе и третирати је као прилог кампањи; увести кратке и прецизне рокове за поступање Агенције за спречавање корупције; обезбедити да све одлуке Агенције буду формалне, образложене и подложне судској контроли; омогућити изрицање привремених мера током кампање, укључујући хитно уклањање спорног садржаја; објављивати све пријаве, одлуке и исходе поступака у претраживом регистру; појачати контролу буџетских издвајања и јавних набавки у периоду пре избора; системски повезивати податке надзорних, антикорупцијских, финансијских и медијских органа. Најважнија поука је да једна службена активност не мора бити злоупотреба, али њихов велики број, концентрисан у кампањи и организован тако да производи страначку корист, може створити неравноправност која се не може исправити само формалним правом других учесника да учествују на изборима. Изборна утакмица није равноправна ако један политички субјект наступа као странка, а истовремено користи државу као сопствену кампањску инфраструктуру. Манипулације које ова студија илуструје: KAM-01 — функционерска кампања; KAM-02 — злоупотреба јавних ресурса; KAM-07 — неравноправна медијска заступљеност; KAM-08 — прикривено политичко оглашавање; KAM-11 — злоупотреба јавних догађаја и институција; KAM-12 — нетранспарентно и незаконито финансирање кампање. Главни извори: Коначни извештај ODIHR-а о ванредним парламентарним изборима од 17. децембра 2023. године; Коначни извештај ODIHR-а о локалним изборима од 2. јуна 2024. године; извештаји и одлуке Агенције за спречавање корупције; јавно доступни медијски мониторинзи; ← Студија 2 Студија 4 →"},{"title":"Студија случаја 4: Тајност гласања као средство заштите слободне воље – фотографисање гласачких листића, породично гласање и доказивање политичке лојалности — Атлас изборних манипулација","url":"pages/studija-4.html","text":"Студија случаја 4: Тајност гласања као средство заштите слободне воље – фотографисање гласачких листића, породично гласање и доказивање политичке лојалности — Атлас изборних манипулација АТЛАС изборних манипулација Ћир Lat Почетна / Студије случаја / 4 Прилог 2 · Документовани пример из изборне праксе Тајност гласања као средство заштите слободне воље – фотографисање гласачких листића, породично гласање и доказивање политичке лојалности Студија случаја 4 Тајност гласања као средство заштите слободне воље – фотографисање гласачких листића, породично гласање и доказивање политичке лојалности Тајност гласања представља један од основних услова слободних избора. Њена сврха није само да сакрије избор појединца од других лица, већ да онемогући контролу над бирачем, куповину гласова, политичку принуду и кажњавање због начина гласања. Бирачко право може бити формално слободно само ако нико не може поуздано да утврди за кога је грађанин гласао. Чим се успостави механизам којим бирач може или мора да докаже свој избор, тајност гласања губи заштитну функцију. Фотографисање гласачког листића, показивање попуњеног листића другом лицу, породично гласање, неовлашћена помоћ и присуство трећих лица иза паравана зато нису само процедуралне неправилности. У одређеном контексту могу бити део организованог механизма контроле гласача. Посебно је важно разликовати појединачан инцидент од системске манипулације. Бирач може фотографисати листић из радозналости, незнања или намере да фотографију објави на друштвеној мрежи. Та радња сама по себи не доказује куповину гласа или политичку принуду. Међутим, ако се фотографија захтева као потврда испуњења обавезе, ако је повезана са исплатом новца, радним притиском, паралелним списковима или контролом излазности, она постаје могући доказ ширег организованог механизма. Контекст избора 2023. године У Коначном извештају о ванредним парламентарним изборима од 17. децембра 2023. године ODIHR је навео да су мере за обезбеђивање тајности гласања биле недовољне и да су посматрачи забележили бројне случајеве групног гласања, као и поједине случајеве фотографисања гласачких листића. Истовремено су уочени недозвољено праћење излазности, неприкладан утицај на бираче и други процедурални недостаци. Ови налази не значе да је у сваком случају фотографисање било део куповине гласа или организоване контроле. ODIHR је документовао појаве уочене на бирачким местима и оценио укупан ниво поштовања процедура. Ипак, њихово истовремено појављивање са притисцима на бираче, праћењем излазности и наводима о куповини гласова оправдава анализу могуће везе између тих механизама. Постојећи текст Атласа управо зато фотографисање листића не третира као самосталан доказ изборне преваре, већ као радњу чији значај зависи од контекста, комуникације пре и после гласања и везе са другим доказима. Наставак проблема на локалним изборима 2024. године ODIHR је и у Коначном извештају о локалним изборима од 2. јуна 2024. године указао да је изборни дан био оптерећен честим повредама тајности гласања, процедуралним проблемима, групним и посредничким гласањем, као и наводима о притисцима и куповини гласова. Понављање истих неправилности у два узастопна изборна циклуса показује да проблем није искључиво последица појединачне грешке члана бирачког одбора или непажње једног бирача. Он указује и на: недовољну обуку чланова бирачких одбора; неуједначену примену правила; неприкладан распоред простора на бирачким местима; толерисање групног гласања; недовољно брзу реакцију на фотографисање листића; непостојање јединственог разумевања зашто је тајност гласања суштинска, а не формална обавеза. Када се тајност систематски не штити, бирачко место постаје простор у којем се могу наставити притисци започети током кампање. Фотографија као доказ гласања Најчешће описивани механизам контроле гласача заснива се на захтеву да бирач фотографише заокружени гласачки листић и фотографију достави координатору, посреднику, послодавцу или лицу које му је понудило новац или другу корист. Такав механизам може изгледати овако: пре избора бирачу се даје упутство за кога треба да гласа; обећава му се новац, услуга, запослење, продужење уговора или друга корист; захтева се да понесе телефон на место за гласање; након заокруживања фотографише листић; фотографију шаље одређеном лицу или је показује по изласку; тек након доказивања гласа добија новац или потврду да је испунио обавезу. Фотографија у овом систему има функцију потврде извршења. Она омогућава да обећање, претња или куповина гласа постану проверљиви за организатора. Без таквог доказа бирач би могао да прихвати корист, а затим гласа по сопственој вољи. Управо зато је тајност гласања једна од главних препрека куповини и контроли гласова. Зашто сама фотографија није довољан доказ Фотографија попуњеног гласачког листића не доказује аутоматски: ко је фотографисао листић; на ком бирачком месту је фотографија настала; да ли је фотографисани листић заиста убачен у кутију; да ли је фотографисање било добровољно; да ли је постојала претња или награда; да ли је фотографија послата трећем лицу; да ли је бирач касније поништио листић или гласао на други начин. Могуће је и да фотографија буде инсценирана, да је направљена у друго време, да приказује модел листића или да је објављена ради политичке поруке. Зато се она мора анализирати заједно са другим доказима. Највећу доказну вредност има када је повезана са: порукама у којима се фотографија захтева; подацима о пошиљаоцу и примаоцу; исплатом новца или другом користи; сведочењем бирача; паралелним списком лица; евиденцијом излазности; комуникацијом координатора; снимком предаје новца; већим бројем сличних случајева; подацима са истог или повезаних бирачких места. У таквом склопу фотографија више није само слика листића, већ један елемент реконструкције организованог поступања. Паралелни спискови и праћење излазности Фотографисање гласачког листића често се повезује са паралелним списковима и праћењем излазности. Паралелни списак може садржати имена бирача за које политички организатор сматра да су обећали подршку, примили корист или се налазе под одређеним видом контроле. На дан избора, лица у близини бирачког места или чланови организоване мреже могу пратити ко је изашао на гласање. Након тога се од бирача може захтевати додатна потврда начина гласања — фотографија листића, порука или јављање координатору. Механизам се тако састоји од два различита нивоа контроле: контрола излазности — утврђује се да ли је бирач дошао; контрола избора — настоји се утврдити за кога је гласао. Први ниво сам по себи не доказује како је лице гласало. Други ниво је могућ само ако се наруши тајност гласања. Због тога су фотографисање, показивање листића и присуство другог лица иза паравана кључне тачке у којима систем политичког притиска може постати стварна контрола гласа. Породично и групно гласање Породично гласање постоји када два или више лица истовремено приступе простору за гласање или када један члан породице надзире, усмерава или фактички одређује како ће други гласати. У пракси се оно често оправдава навиком, блискошћу, неписменошћу, старошћу или потребом за помоћи. Међутим, законска помоћ при гласању није исто што и породично гласање. Помоћ се пружа само бирачу који због инвалидитета, неписмености или другог оправданог разлога није у стању да сам попуни листић, и то на начин који чува његову вољу и тајност. Породично гласање може прикрити: контролу супружника над другим супружником; контролу старијег члана породице; политичку принуду унутар домаћинства; колективно гласање према претходном договору; гласање у име другог лица; навођење бирача како да заокружи листић. Чак и када нема организоване политичке манипулације, породично гласање нарушава индивидуалну природу бирачког права. Бирач не гласа као члан породичне групе, већ као самосталан носилац политичког права. Помоћ при гласању као могући простор злоупотребе Право на помоћ при гласању неопходно је за остваривање бирачког права лица која не могу самостално да попуне листић. Забрана сваке помоћи била би дискриминаторна и могла би их лишити права гласа. Ипак, овај институт може бити злоупотребљен када: помоћ добија лице које може самостално да гласа; исто лице помаже већем броју бирача; помагач уместо бирача одређује избор; члан бирачког одбора не проверава постојање основа; помоћ се организује за групу зависних или рањивих лица; поступак није правилно евидентиран; бирач није слободно изабрао помагача. Посебну пажњу захтевају случајеви у којима једно лице доводи више бирача и свима „помаже“. Та околност сама по себи не доказује злоупотребу, али захтева да се утврди да ли су бирачи заиста тражили помоћ и да ли је њихова воља била слободна. Просторни услови на бирачком месту Тајност гласања зависи и од физичког уређења бирачког места. Неправилно постављени паравани, мала просторија, гужва, пролаз чланова одбора иза бирача или могућност да се са стране види листић могу довести до повреде тајности и без намерне манипулације. Ризик је већи када: параван није довољно висок или широк; место за гласање је окренуто ка члановима одбора; други бирачи стоје непосредно иза лица које гласа; више лица истовремено користи исти простор; чланови одбора или посматрачи могу видети садржај листића; телефон се користи без реакције одбора; бирач после попуњавања држи листић тако да је избор видљив. Овакве неправилности могу бити последица лоше организације, а не намере да се контролише гласање. Ипак, њихов ефекат је исти: смањује се заштита бирача од спољног утицаја. Поступање бирачког одбора Бирачки одбор има непосредну одговорност да обезбеди да сваки бирач гласа самостално и тајно. То подразумева да: не дозволи присуство више лица иза паравана без законског основа; реагује на фотографисање листића; спречи показивање попуњеног листића; провери услове за пружање помоћи; обезбеди правилан распоред простора; упозори лица која нарушавају ред; унесе неправилност у записник; омогући члановима одбора да издвоје мишљење или примедбу. Највећи проблем настаје када се неправилна пракса толерише као нешто уобичајено. Чланови одбора понекад породично гласање виде као безначајну навику, а фотографисање као личну ствар бирача. Такво разумевање занемарује ширу улогу тајности гласања. Бирачки одбор не мора знати да ли иза фотографисања постоји куповина гласа. Његова дужност је да спречи радњу која може омогућити доказивање избора трећем лицу и да је документује тако да надлежни органи касније могу испитати контекст. Форензичка реконструкција Када постоји сумња да је фотографисање или показивање листића део организоване контроле, потребно је реконструисати читав низ догађаја. Треба утврдити: када је бирач добио инструкцију; ко му је инструкцију дао; да ли је захтевана фотографија; коме је требало да буде достављена; да ли је постојала обећана корист или претња; да ли је лице било на паралелном списку; ко је пратио његов долазак; када је фотографија настала; да ли метаподаци одговарају времену гласања; да ли се на фотографији виде карактеристике конкретног листића; да ли је фотографија послата или показана; да ли је након тога извршена исплата или друга радња; да ли су на исти начин поступали и други бирачи. Посебно је важно сачувати оригиналну дигиталну датотеку, а не само снимак екрана. Оригинална фотографија и комуникација могу садржати податке о времену, уређају и начину слања, који могу имати значај за проверу аутентичности. Кључни докази Највећу доказну вредност могу имати: оригинална фотографија листића; оригиналне поруке и групне комуникације; метаподаци фотографије; подаци о пошиљаоцу и примаоцу; аудио или видео-снимци договора; доказ о исплати или предаји користи; паралелни спискови; евиденције позива; снимци лица која организују контролу; сведочења више независних бирача; записник бирачког одбора; примедбе чланова одбора и посматрача; снимци са дозвољених локација у близини бирачког места; временско поклапање гласања, слања фотографије и исплате. Сваки доказ мора се прикупљати законито. Нарочито треба водити рачуна да се документовањем неправилности додатно не наруши тајност других бирача и да се не снима унутрашњост бирачког места на начин који је забрањен. Правни значај случаја Нарушавање тајности гласања може повредити: уставно право на слободне и непосредне изборе; индивидуалност и тајност бирачког права; правила о раду бирачког одбора; забрану утицаја на бирача; забрану куповине гласова; забрану повреде слободе опредељења; правила о заштити личних и политички осетљивих података. Конкретна правна квалификација зависи од околности. Само фотографисање може бити изборна процедурална неправилност. Ако се фотографија захтева у замену за новац, може бити део куповине гласа. Ако се захтева под претњом губитка посла, може бити доказ политичког притиска. Ако се користи у систему паралелних спискова, може указивати на организовану контролу бирача. Због тога правна оцена не сме бити заснована само на видљивој радњи на бирачком месту. Потребно је утврдити шта јој је претходило и шта је уследило након ње. Утицај на изборни интегритет Појединачно породично гласање или једна фотографија најчешће имају ограничен непосредан утицај на укупан изборни резултат. Међутим, систематско понављање ових радњи мења њихов значај. Када велики број бирача мора да докаже за кога је гласао, тајност гласања престаје да постоји за читаву контролисану групу. Тада постају могући: масовна куповина гласова; организациона контрола „сигурних гласова“; кажњавање непослушних запослених; контрола корисника јавне помоћи; породична и локална политичка принуда; провера извршења договорене изборне обавезе. Таква пракса може имати значајан или системски утицај и без измене једног гласачког листића после његовог убацивања у кутију. Манипулација се остварује тако што се бираче пре гласања приморава или подстиче да гласају на одређени начин, а затим се од њих захтева доказ. Поуке и препоруке Овај случај показује да тајност гласања није само приватно право којег се бирач може лако одрећи. Она има и јавну, системску функцију: штити читав изборни процес од куповине, уцене и контроле гласача. Зато је потребно: унапредити обавезну обуку чланова бирачких одбора о заштити тајности; јасно објаснити да фотографисање листића може бити део ширег механизма контроле; обезбедити правилно постављање паравана и довољан простор за самостално гласање; доследно спречавати породично и групно гласање; прецизно уређивати и евидентирати пружање помоћи; сваку уочену повреду унети у записник; сачувати поруке, фотографије и друге дигиталне доказе у оригиналном облику; омогућити брзу реакцију полиције и тужилаштва када постоје индиције куповине или принуде; повезивати податке о фотографисању са пријавама куповине гласова, паралелним списковима и праћењем излазности; спроводити циљану едукацију бирача да нико нема право да од њих захтева доказ начина гласања; обезбедити посебну заштиту лицима која пријаве организовани механизам; анализирати учесталост ових појава по бирачким местима и изборним циклусима. Најважнија поука је да куповина и принуда могу функционисати само ако организатор може да контролише испуњење договорене обавезе. Тајност гласања прекида ту везу. Зато свака радња која омогућава доказивање избора — фотографија, показивање листића, присуство другог лица или организовано породично гласање — мора бити схваћена као потенцијално озбиљна претња слободи изборне воље, а не као безначајан процедурални пропуст. Манипулације које ова студија илуструје: KAM-04 — политички притисак, претња и уцена; KAM-05 — капиларни и сигурни гласови; KAM-06 — паралелни бирачки спискови; DAN-07 — повреда тајности гласања; DAN-08 — фотографисање гласачког листића; DAN-09 — породично и групно гласање; DAN-10 — злоупотреба помоћи при гласању; DAN-11 — куповина гласова и доказивање гласа. Главни извори: Коначни извештај ODIHR-а о ванредним парламентарним изборима од 17. децембра 2023. године; Коначни извештај ODIHR-а о локалним изборима од 2. јуна 2024. године; записници бирачких одбора и примедбе контролора и посматрача; извештаји домаћих посматрачких организација; постојећа поглавља Атласа о тајности гласања, фотографисању листића, паралелним списковима, куповини гласова и политичким притисцима. ← Студија 3 Студија 5 →"},{"title":"Студија случаја 5: Косјерић – формалистичко ускраћивање благовременог увида у изборни материјал — Атлас изборних манипулација","url":"pages/studija-5.html","text":"Студија случаја 5: Косјерић – формалистичко ускраћивање благовременог увида у изборни материјал — Атлас изборних манипулација АТЛАС изборних манипулација Ћир Lat Почетна / Студије случаја / 5 Прилог 2 · Документовани пример из изборне праксе Косјерић – формалистичко ускраћивање благовременог увида у изборни материјал Студија случаја 5 Косјерић – формалистичко ускраћивање благовременог увида у изборни материјал Право на увид у изборни материјал представља један од најважнијих механизама контроле изборног поступка након затварања бирачких места. Без могућности да изборни учесник провери записнике, гласачке листиће, контролне листове и другу документацију, право на приговор може остати само формално. Увид није сам себи сврха. Његова улога је да омогући: проверу података у записнику бирачког одбора; утврђивање евентуалног неслагања између броја листића, потписа и гласова; проверу спорних или неважећих листића; очување и опис доказа; благовремену припрему приговора; контролу веродостојности утврђеног резултата. Зато се право на увид мора остваривати брзо и делотворно. У изборном поступку, у којем су рокови изузетно кратки, одлагање од једног дана може имати много већи значај него у редовном управном или судском поступку. Случај из Косјерића показује како се формални недостатак у поднеску може употребити за одлагање приступа изборном материјалу, иако је из целокупног контекста било јасно на које се изборе и на који материјал захтев односи. Основни подаци о случају Локални избори за Скупштину општине Косјерић одржани су 8. јуна 2025. године. Након гласања, овлашћено лице изборне листе „Уједињени за Косјерић“ поднело је Општинској изборној комисији општине Косјерић захтев за увид у изборни материјал. Општинска изборна комисија није омогућила увид по првом захтеву, већ га је одбацила зато што у њему није било изричито наведено да се увид тражи у материјал са избора одржаних на територији општине Косјерић. Формални недостатак се, дакле, није односио на: идентитет подносиоца; његово овлашћење; надлежност комисије којој је захтев упућен; непостојање права на увид; нејасно одређење врсте изборног материјала; неблаговременост захтева. Спорно је било искључиво то што назив јединице локалне самоуправе није поновљен у самом тексту захтева. Контекст из којег се видела стварна намера подносиоца Иако у захтеву није било изричито написано да се односи на изборе у општини Косјерић, више околности је јасно указивало на његов предмет: захтев је био упућен Општинској изборној комисији општине Косјерић; поднет је непосредно након избора одржаних у тој општини; поднело га је овлашћено лице изборне листе која у самом називу садржи речи „Уједињени за Косјерић“; комисија којој је поднет спроводила је управо изборе на које се захтев могао односити. Из ових околности могло се разумно и недвосмислено закључити да подносилац тражи увид у изборни материјал са локалних избора у Косјерићу. Комисија, међутим, није поднесак тумачила према његовој стварној садржини и очигледној сврси, већ је изостанак једне формалне одреднице употребила као разлог да захтев одбаци. Овај случај не значи да захтеви у изборном поступку могу бити нејасни или непотпуни. Напротив, због кратких рокова и значаја поступка, подносилац је дужан да свој захтев састави прецизно. Међутим, поставља се питање да ли је пропуст био такве природе да оправдава одбацивање, уместо тумачења поднеска у складу са његовом јасном сврхом или омогућавања да се недостатак одмах отклони. Последице одбацивања Након одбацивања првог захтева било је потребно поднети нови, формално исправљен захтев. Увид у изборни материјал омогућен је тек наредног дана. На први поглед, одлагање од једног дана може изгледати безначајно. У изборном поступку, међутим, оно може имати озбиљне последице. Изборни рокови су кратки и често се рачунају у часовима. Подносилац правног средства мора у ограниченом времену да: сазна да је неправилност постојала; идентификује бирачко место и спорну радњу; изврши увид; прикупи доказе; састави правно образложен приговор; достави га надлежном органу. Ако је приступ материјалу одложен, подносилац може изгубити значајан део расположивог рока. У најтежем случају, право на приговор постаје неупотребљиво јер се доказима приступа прекасно. Увид као предуслов делотворне правне заштите Право на правно средство није делотворно ако лице нема приступ чињеницама и доказима на којима треба да заснује свој приговор. Изборни учесник може сумњати да: број гласачких листића није правилно утврђен; записник не одговара стварном стању; спорни листићи нису правилно оцењени; примедба члана бирачког одбора није унета; постоји неслагање између различитих примерака записника; изборни материјал није правилно упакован или обезбеђен. Међутим, без увида, све то остаје на нивоу претпоставке. Приговор који се заснива само на сумњи лакше се одбацује као неоснован, неодређен или недовољно доказан. Зато увид има двоструку улогу: омогућава откривање и доказивање стварне неправилности; омогућава да се неоснована сумња отклони. И у једном и у другом случају доприноси поверењу у изборни поступак. Формализам и легитимни процесни захтеви Није сваки формални захтев изборног органа неоправдан. Изборна комисија мора да зна: ко подноси захтев; да ли је лице овлашћено; на које изборе се захтев односи; који материјал се тражи; за која бирачка места; да ли је захтев благовремен; да ли постоји законски основ. Ови подаци су потребни како би се спречила злоупотреба права на увид, заштитио изборни материјал и омогућила уредна организација поступка. Међутим, формализам постаје проблем када се од подносиоца захтева више него што је стварно потребно за разумевање и поступање или када се очигледно отклоњив недостатак користи као разлог да се право привремено или трајно онемогући. Разлика између легитимног процесног захтева и прекомерног формализма може се процењивати према следећим питањима: Да ли је комисија могла да разуме предмет захтева? Да ли је постојала стварна опасност од забуне? Да ли је недостатак могао бити отклоњен одмах? Да ли је подносилац могао бити позван да допуни захтев? Да ли је одбацивање било сразмерно тежини пропуста? Да ли је последица одбацивања угрозила употребу другог правног средства? У случају Косјерића, централно питање није да ли је захтев био савршено састављен — није. Питање је да ли је тај пропуст оправдавао одлагање увида, иако није постојала реална нејасноћа о томе на које се изборе захтев односи. Временски фактор и ризик по изборни материјал Увид непосредно након избора има посебан значај. У том периоду се изборни материјал: транспортује; предаје изборној комисији; прегледа и разврстава; чува у службеним просторијама; користи у поступцима контроле и утврђивања резултата. Свако одлагање увида повећава временску дистанцу између спорног догађаја и контроле материјала. То само по себи не доказује да је материјал измењен, оштећен или замењен. Ипак, смањује могућност да се брзо документује његово првобитно стање. Због тога је важно забележити: када је материјал примљен; где је чуван; ко је имао приступ; да ли је паковање било запечаћено; када је први захтев поднет; када је одбачен; када је поднет нови захтев; када је увид стварно омогућен; у каквом стању је материјал затечен. Не треба тврдити да је само одлагање доказа о манипулацији материјалом. Али када је увид одложен, континуитет чувања и приступа материјалу постаје још значајнији за очување поверења у поступак. Како је комисија могла да поступи другачије Чак и када је утврдила да захтев није потпун, комисија је могла размотрити мање рестриктивна решења. Могла је: да поднесак тумачи према целокупној садржини и контексту; да од подносиоца одмах затражи усмено или писмено појашњење; да омогући исправку на лицу места; да одреди кратак рок за допуну без губитка првобитног редоследа поступања; да омогући увид у неспорни део материјала; да недостатак забележи, али да не спречи остваривање права. Такво поступање не би значило привилеговање једног изборног учесника. Напротив, представљало би примену начела делотворне заштите права, уз очување процесне дисциплине. Форензичка реконструкција поступка За анализу оваквог случаја потребно је прикупити и упоредити: оригинални први захтев; доказ о датуму и времену његовог подношења; одлуку или закључак којим је одбачен; правно образложење комисије; записник или снимак седнице на којој је одлучивано; евентуално издвојено мишљење члана комисије; нови, исправљени захтев; доказ о времену његовог подношења; одлуку којом је увид омогућен; записник о извршеном увиду; податке о месту и начину чувања материјала између два захтева. На основу тих докумената може се утврдити: да ли је захтев био стварно нејасан; да ли је комисија поступала доследно својој ранијој пракси; да ли је другим подносиоцима допуштала отклањање сличних недостатака; колико је времена стварно изгубљено; да ли је одлагање утицало на могућност подношења приговора; да ли је подносилац претрпео конкретну процесну штету. Једнакост поступања Правна оцена оваквог случаја не зависи само од текста једне одлуке, већ и од праксе комисије у другим предметима. Ако комисија свим подносиоцима једнако строго примењује формалне услове, може се говорити о претерано формалистичкој, али доследној пракси. Ако, међутим, једнима допушта допуну, исправку или повољно тумачење, а другима исти или мањи пропуст користи као основ за одбацивање, проблем добија и димензију неједнаког поступања. Зато треба упоредити: друге захтеве за увид; одлуке комисије по тим захтевима; врсту недостатака; рокове за допуну; начин комуникације са подносиоцима; време у којем је увид омогућен. Селективни формализам може бити ефикасно средство изборне манипулације јер се споља представља као неутрална примена процедуре, док у пракси различито погађа изборне учеснике. Правни значај случаја Овај случај поставља питање односа између процесне форме и суштинске заштите изборног права. Форма у изборном поступку има важну улогу. Она обезбеђује правну сигурност, једнакост, брзину и јасноћу поступања. Али форма не сме постати сама себи сврха. Када је: подносилац препознатљив; његово овлашћење неспорно; надлежни орган правилно означен; предмет захтева разумљив; право на увид законом признато, одбацивање због податка који је већ јасан из целокупног контекста може представљати несразмерно ограничење права. Посебно је важно што у изборном поступку последице процесне одлуке могу бити неповратне. У редовном поступку странка често може поднети нови захтев без значајне штете. У изборном поступку, нови захтев може бити формално прихваћен, али тек када је значајан део рока за приговор већ истекао. Утицај на изборни интегритет Одбацивање једног захтева за увид само по себи не мења изборни резултат. Његов непосредни утицај може бити ограничен. Међутим, утицај постаје значајнији ако: се увид тражи због конкретних сумњи у неправилности; је изборни резултат тесан; су рокови за правна средства веома кратки; се исти формализам понавља према више подносилаца; комисија различито поступа према различитим изборним листама; одлагање онемогућава прикупљање доказа; се материјалу приступа тек након окончања кључних рокова. Системска опасност лежи у могућности да се изборна контрола не спречава отвореном забраном, већ низом процесних препрека. Свака појединачно може изгледати технички оправдано, али њихов кумулативни ефекат може бити онемогућавање делотворне провере изборног резултата. Практична поука за састављање захтева Иако поступање комисије може бити оцењено као претерано формалистичко, случај истовремено показује да подносиоци не смеју оставити простор за такво тумачење. У сваком захтеву за увид потребно је изричито навести: пун назив подносиоца захтева; име, презиме и својство овлашћеног лица; основ овлашћења; пун назив изборне листе; назив изборне комисије којој се захтев подноси; врсту избора; назив општине, града или изборне јединице; датум одржавања избора; тачно одређен изборни материјал; бирачка места на која се захтев односи, када су позната; правни основ за увид; начин на који се тражи спровођење увида; датум и време подношења; својеручни или квалификовани електронски потпис, када је применљиво. Не треба се ослањати на то да се податак „подразумева“, чак ни када је очигледан из адресата, назива листе или околности случаја. Поуке и препоруке Овај случај показује да делотворност правне заштите не зависи само од тога да ли је неко право прописано, већ и од начина на који га институција примењује. Право на увид може постојати у закону, али бити суштински ослабљено ако се: захтеви тумаче крајње рестриктивно; отклоњиви недостаци користе за одбацивање; не омогућава хитна допуна; поступање одлаже до истека важних рокова; различити стандарди примењују на различите учеснике. Зато је потребно: прописати јасан и јединствен образац захтева за увид; објавити упутство са обавезним елементима; обавезати изборне комисије да омогуће хитно отклањање мањих недостатака; разликовати недостатак који стварно онемогућава поступање од пропуста који не ствара забуну; обезбедити да подношење допуне не доводи до губитка редоследа или права; водити јавни регистар захтева за увид и одлука по њима; бележити тачно време подношења, одлучивања и омогућавања увида; обезбедити једнако поступање према свим изборним учесницима; омогућити брзу правну контролу одлуке којом се увид одбија или одлаже; чувати потпун траг о приступу изборном материјалу до момента увида. Најважнија поука је да у изборном поступку време представља део самог права. Увид који је омогућен прекасно може формално постојати, али практично изгубити сврху. Зато изборна администрација не треба да тражи разлог да право не примени, већ начин да га омогући уз поштовање неопходних процесних правила. Манипулације које ова студија илуструје: POST-01 — ограничење или одлагање увида у изборни материјал; POST-02 — прекомерни формализам у поступању изборних органа; POST-03 — одуговлачење у кратким изборним роковима; POST-04 — онемогућавање прикупљања доказа; POST-05 — селективна примена процесних правила; POST-06 — формално постојање, а практично ускраћивање правне заштите. Главни извори: захтев овлашћеног лица изборне листе „Уједињени за Косјерић“ за увид у изборни материјал; одлука Општинске изборне комисије општине Косјерић о одбацивању првог захтева; исправљени захтев и документација о накнадно омогућеном увиду. ← Студија 4 Студија 6 →"},{"title":"Студија случаја 6: Зајечар – одбацивање приговора због непрецизног означавања подносиоца — Атлас изборних манипулација","url":"pages/studija-6.html","text":"Студија случаја 6: Зајечар – одбацивање приговора због непрецизног означавања подносиоца — Атлас изборних манипулација АТЛАС изборних манипулација Ћир Lat Почетна / Студије случаја / 6 Прилог 2 · Документовани пример из изборне праксе Зајечар – одбацивање приговора због непрецизног означавања подносиоца Студија случаја 6 Зајечар – одбацивање приговора због непрецизног означавања подносиоца Право на приговор представља један од основних механизама заштите изборног права. Његова сврха је да омогући да изборна комисија испита наводе о неправилностима, утврди чињенично стање и, када су испуњени законски услови, отклони последице незаконитог поступања. Међутим, приговор може бити разматран само ако га поднесе лице које је законом овлашћено и ако садржи прописане елементе. Због кратких рокова и потребе да се брзо утврди ко покреће поступак и у чије име, изборни прописи оправдано захтевају прецизно означавање подносиоца. Проблем настаје када се разлика између назива коалиције која је поднела изборну листу, назива проглашене изборне листе и овлашћеног лица користи као основ да се приговор одбаци без разматрања његове суштине, иако се из целокупног поднеска и изборне документације може разумети ко га подноси и у чије име. Случај из Зајечара показује колико једна терминолошка непрецизност може имати озбиљне последице у изборном поступку и како формално право на приговор може остати без стварног дејства ако поднесак није састављен са потпуном правном прецизношћу. Основни подаци о случају Локални избори за Скупштину града Зајечара одржани су 8. јуна 2025. године. Након избора, Градској изборној комисији у Зајечару поднет је приговор у вези са изборним поступком. Комисија није разматрала основаност навода из приговора, нити је испитивала да ли се описана изборна неправилност заиста догодила. Приговор је одбачен као непотпун и као поднет од неовлашћеног лица. Спорно питање није било да ли је приговор поднет у року, да ли је упућен надлежној комисији или да ли је потписник био лице које је учествовало у изборном поступку. Комисија је проблем видела у начину на који су у поднеску означени: подносилац изборне листе; проглашена изборна листа; овлашћено лице које је потписало приговор. Разлог наведен у одлуци комисије Према образложењу Градске изборне комисије, у приговору није наведен пун назив подносиоца проглашене изборне листе: „Коалиција Промена у коју верујемо“. У поднеску је потписник био означен као овлашћено лице изборне листе: „Промена у коју верујемо — Угљеша Ђуричковић — Драгана Рашић“. Комисија је направила правну разлику између: коалиције као подносиоца изборне листе; проглашене изборне листе као изборног учесника са посебним називом; овлашћеног лица које поступа у име подносиоца. Према ставу комисије, лице које је потписало приговор није било овлашћено да га поднесе у својству овлашћеног лица саме изборне листе, већ у име коалиције која је листу поднела. Пошто у наслову и тексту приговора није изричито и у пуном облику наведена коалиција као подносилац изборне листе, комисија је закључила да приговор не садржи обавезни елемент и да је формално поднет од неовлашћеног лица. Три различита правна појма Овај случај је важан јер показује да се у изборном поступку три појма, који у свакодневном говору могу изгледати као једно исто, правно разликују. Подносилац изборне листе може бити: политичка странка; коалиција политичких странака; група грађана. Подносилац предузима формалне радње у поступку кандидовања. Он подноси изборну листу, одређује овлашћено лице и, у границама закона, користи правна средства. Проглашена изборна листа носи назив под којим учествује на изборима. Тај назив може садржати: назив странке или коалиције; име носиоца листе; имена кандидата; политички слоган; комбинацију више назива и имена. Назив изборне листе зато не мора бити истоветан називу правног или политичког субјекта који ју је поднео. Овлашћено лице је физичко лице које на основу овлашћења поступа у име подносиоца. Оно не подноси приговор у лично име, нити нужно „у име изборне листе“ као самосталног правног субјекта, већ у име странке, коалиције или групе грађана која га је овластила. Мешање ових појмова може довести до закључка да лице које је несумњиво учествовало у изборном поступку формално није правилно означило субјекта у чије име поступа. Да ли се из контекста могло утврдити ко подноси приговор Кључно питање није само да ли је у поднеску употребљена правно најпрецизнија формулација. Потребно је испитати и да ли је, упркос непрецизности, из целокупне документације било могуће недвосмислено утврдити: о којој изборној листи је реч; ко је ту листу поднео; ко је њено овлашћено лице; у чије име то лице поступа; на које изборе и неправилност се приговор односи. Уколико је изборна комисија располагала решењем о проглашењу листе, коалиционим споразумом, овлашћењем и другом изборном документацијом, могла је да повеже наведене податке и утврди стварног подносиоца. Са друге стране, изборна комисија није дужна да реконструише вољу подносиоца ако је поднесак до те мере нејасан да није могуће утврдити ко покреће поступак. Право на приговор припада законом одређеним субјектима, па питање активне легитимације није безначајна формалност. Зато правна оцена зависи од степена непрецизности. Ако је постојала стварна и разумна сумња ко је подносилац, одбацивање може бити оправдано. Ако је, међутим, идентитет подносиоца био очигледан, а спор се сводио само на непотпуно навођење службеног назива, поставља се питање да ли је комисија применила несразмерно строг формализам. Одбацивање без испитивања суштине Најважнија последица одлуке била је то што наводи из приговора нису мериторно испитани. Комисија није утврђивала: шта се наводно догодило; где и када се неправилност догодила; који су докази понуђени; да ли су наводи били тачни; да ли је неправилност могла утицати на изборни резултат; да ли је постојао основ за поништавање или другу меру. Поступак се завршио на питању ко је формално означен као подносилац. То не значи да су наводи из приговора самим тим били основани. Одбацивање не потврђује неправилност, али је ни не оповргава. Оно само значи да изборни орган није ушао у њихову суштину. У изборним споровима таква последица има посебну тежину. Након истека рока, исти приговор се по правилу не може поново поднети у исправљеном облику. Формална грешка тако може трајно спречити да спорна радња буде институционално испитана. Формализам као заштита правне сигурности Процесна правила нису сама по себи препрека правној заштити. Она имају легитимну сврху. Захтев да се подносилац прецизно означи омогућава комисији да утврди: да ли лице има право на приговор; да ли овлашћено лице заиста поступа у његово име; да ли постоји више субјеката са сличним називима; да ли се правно средство односи на конкретну изборну листу; коме треба доставити одлуку; ко сноси процесне последице. Без ових правила могло би доћи до подношења приговора у туђе име, злоупотребе овлашћења или спорова о томе ко је заиста покренуо поступак. Зато поука овог случаја није да изборне комисије треба да игноришу формалне недостатке. Поука је да морају направити разлику између: недостатка који стварно онемогућава утврђивање подносиоца; терминолошке непрецизности која не ствара стварну забуну. Прекомерни формализам као препрека правној заштити Прекомерни формализам постоји када се процесно правило примењује на начин који није сразмеран његовој сврси и који спречава разматрање суштине права, иако формални недостатак није створио стварну правну неизвесност. У овом случају треба поставити следећа питања: Да ли је комисија знала која коалиција је поднела листу? Да ли је знала пун назив проглашене изборне листе? Да ли је потписник био уписан као овлашћено лице? Да ли је постојало друго лице или субјект са којим је могао бити помешан? Да ли је из приговора било јасно на који изборни поступак се односи? Да ли је непрецизност могла бити отклоњена непосредним увидом у службене акте? Да ли је подносиоцу могла бити омогућена хитна исправка или допуна? Уколико су одговори показивали да није постојала стварна неизвесност, одбацивање је имало за последицу да форма надвлада суштину. Могућност допуне поднеска Једно од централних питања јесте да ли је изборна комисија могла или морала да омогући подносиоцу да отклони недостатак. У редовним управним поступцима непотпун или неразумљив поднесак се често враћа на допуну. Изборни поступак је, међутим, специфичан због изузетно кратких рокова и потребе за хитним одлучивањем. Због тога могућност допуне није увек уређена или примењива на исти начин као у општем управном поступку. Ипак, чак и када закон не предвиђа формалан вишедневни рок за допуну, могуће је размотрити бржа решења: тренутно обавештавање подносиоца; исправку очигледне омашке; достављање додатног овлашћења истог дана; тумачење поднеска у вези са службеном документацијом; позивање овлашћеног лица да недвосмислено потврди у чије име поступа. Такво поступање мора бити једнако доступно свим изборним учесницима и не сме довести до продужења законских рокова на штету других страна. Али када је недостатак лако и одмах отклоњив, строго одбацивање није нужно једини могући приступ. Однос коалиције и проглашене изборне листе Назив коалиције и назив изборне листе могу бити веома слични, али правно нису нужно истоветни. На пример, коалиција може носити један службени назив, док проглашена изборна листа може поред тог назива садржати имена кандидата или додатни слоган. У јавности, медијима и политичкој комуникацији често се користи скраћени назив листе, док се у изборној документацији захтева пуни службени назив. Управо та разлика ствара ризик да лице: у заглављу наведе назив листе; у тексту говори о коалицији; у потпису себе означи као овлашћено лице изборне листе; приложи овлашћење које гласи на подносиоца листе. Садржински је могуће разумети о ком субјекту је реч, али формално различити појмови нису доследно употребљени. Зато се у сваком правном средству мора јасно написати, на пример: Приговор подноси Коалиција „...“, као подносилац проглашене изборне листе „...“, преко овлашћеног лица ... Оваква формулација недвосмислено раздваја сва три елемента. Форензичка реконструкција поступка За потпуну анализу случаја потребно је упоредити следеће документе: коалициони споразум или други акт о образовању коалиције; акт којим је одређен службени назив коалиције; изборну листу поднету комисији; решење о проглашењу изборне листе; овлашћење лица које је поднело приговор; оригинални приговор; доказ о времену подношења; одлуку Градске изборне комисије; записник или снимак седнице на којој је одлучивано; евентуално издвојено мишљење члана комисије; одлуку суда, ако је против одбацивања изјављена жалба; друге одлуке исте комисије о сличним поднесцима. Посебно треба проверити: да ли је име потписника истоветно имену у овлашћењу; да ли је овлашћење било важеће; да ли је обухватало подношење приговора; да ли је у приговору наведен назив листе који се подудара са решењем о проглашењу; да ли је назив коалиције изостављен или само скраћен; да ли је комисија у другим предметима прихватала сличне скраћене називе; да ли је постојала реална могућност забуне. Једнакост у примени процесних правила Као и у случају Косјерића, правна оцена поступања комисије зависи и од тога да ли је исти стандард примењиван на све изборне учеснике. Потребно је упоредити: приговоре других изборних листа; начин на који су у њима означени подносиоци; да ли су коришћени пуни или скраћени називи; да ли су овлашћена лица означена као лица коалиције или изборне листе; да ли је комисија тражила допуну; да ли је недостатке тумачила благо или строго; да ли су приговори неких подносилаца разматрани иако су садржали сличне непрецизности. Ако је комисија свима примењивала исти строг стандард, проблем је пре свега у прекомерном формализму. Ако је исти недостатак код једног подносиоца толерисан, а код другог употребљен за одбацивање, онда се поставља и питање селективне примене закона. Селективни формализам је нарочито опасан јер се може представити као неутрална процесна одлука, иако у пракси различито утиче на изборне учеснике. Последице по правну заштиту Одбацивање приговора због непрецизног означавања подносиоца може имати више последица: наводи о неправилности остају неиспитани; докази се не изводе; сведоци се не саслушавају; спорна радња се не оцењује; кратак рок за подношење новог приговора може истећи; виши орган или суд може разматрати само законитост одбацивања, а не саму неправилност; изборни резултат може бити потврђен без мериторног одговора на пријављени проблем. Ове последице не значе да је изборна неправилност доказана. Оне значе да институционални систем није дао одговор на питање да ли је постојала. У јавности се зато може створити двоструко незадовољство: подносилац сматра да му је ускраћена заштита, док изборни орган формално тврди да се није ни могао упустити у суштину због процесног недостатка. Правни значај случаја Овај случај показује напетост између два легитимна циља: правне сигурности и уредности поступка; делотворне заштите изборног права. Правна сигурност захтева да се зна ко подноси приговор и да ли има овлашћење. Делотворна заштита захтева да мања терминолошка грешка не онемогући испитивање озбиљне изборне неправилности када је идентитет подносиоца иначе неспоран. Правилан приступ не подразумева укидање формалних правила, већ њихову сразмерну примену. Када недостатак: ствара стварну нејасноћу; онемогућава проверу овлашћења; не дозвољава утврђивање субјекта; може довести до поступања у туђе име, одбацивање може бити оправдано. Када је, међутим: подносилац познат; овлашћено лице идентификовано; изборна листа недвосмислено одређена; комисија располаже службеном документацијом; непрецизност лако отклоњива, строго одбацивање може представљати несразмерну препреку приступу правној заштити. Утицај на изборни интегритет Један одбачен приговор сам по себи не доказује да је изборни резултат нетачан. Његов непосредни утицај зависи од садржине неправилности која је остала неиспитана. Ипак, системски значај настаје ако изборне комисије често користе формалне недостатке да избегну мериторно одлучивање. Такав образац може: обесхрабрити изборне учеснике да користе правна средства; повећати зависност од специјализоване правне помоћи; привилеговати субјекте са већим организационим капацитетом; омогућити да озбиљни наводи остану без институционалног одговора; створити неједнакост између учесника; смањити поверење у непристрасност изборне администрације; претворити право на приговор у формалну, али тешко употребљиву могућност. Када се изборни спорови завршавају превасходно на процесним питањима, јавност не добија одговор о суштини спорног догађаја. То дугорочно нарушава поверење чак и када су формалне одлуке законите. Практична правила за састављање приговора Овај случај показује да сваки приговор мора бити састављен тако да не оставља простор за спор о активном легитимисању. У приговору треба изричито навести: пун и службени назив подносиоца изборне листе; правни облик подносиоца — странка, коалиција или група грађана; пун назив проглашене изборне листе; број изборне листе, када је релевантно; име и презиме овлашћеног лица; својство у којем то лице поступа; да се приговор подноси у име подносиоца изборне листе; основ и обим овлашћења; пун назив надлежне изборне комисије; врсту и датум избора; прецизан опис спорне радње; место и време неправилности; доказе; јасан правни и чињенични захтев; датум, место и потпис. Називе треба дословно преписати из: решења о проглашењу изборне листе; коалиционог споразума; акта о образовању групе грађана; службеног овлашћења. Не треба користити медијске, скраћене или колоквијалне називе, чак ни када су општепознати. Контролна формулација Најсигурнија уводна формулација може изгледати овако: Подносилац приговора је Коалиција „[пун службени назив]“, као подносилац проглашене изборне листе „[пун назив листе]“, коју у овом поступку заступа овлашћено лице [име и презиме], на основу овлашћења [ознака и датум, ако постоје]. Оваквом формулацијом јасно се раздвајају: политички субјект; проглашена изборна листа; овлашћено физичко лице. Она не гарантује да ће приговор бити усвојен, али у великој мери отклања могућност да буде одбачен због нејасног означавања подносиоца. Поуке и препоруке Случај Зајечара показује да у изборном поступку није довољно да из контекста буде разумљиво ко подноси приговор. Подаци морају бити изричито, потпуно и доследно наведени. Истовремено, случај отвара питање да ли изборна администрација треба да буде усмерена искључиво на откривање формалних пропуста или на обезбеђивање делотворне контроле законитости избора. Зато је потребно: усвојити јединствен образац приговора за локалне изборе; јасно разликовати подносиоца изборне листе, проглашену листу и овлашћено лице; у званичним упутствима објавити примере правилног означавања; омогућити хитно отклањање очигледних и мањих недостатака када то не угрожава изборне рокове; одбацивање применити само када није могуће поуздано утврдити подносиоца или овлашћење; захтевати да свака одлука о одбацивању објасни какву је стварну правну нејасноћу недостатак изазвао; обезбедити једнаку праксу према свим изборним учесницима; објављивати одлуке у претраживој бази ради уједначавања праксе; организовати правну обуку овлашћених лица изборних листа; успоставити интерну двоструку проверу поднеска пре предаје; сачувати доказ о времену, начину и садржини подношења; у случају одбацивања одмах користити расположиви правни лек. Најважнија поука је двострука. Подносиоци приговора морају рачунати да и најмања терминолошка непрецизност може бити употребљена против њих. Изборне комисије, са друге стране, морају водити рачуна да процесна форма служи законитости, а не избегавању одлучивања о суштини. Правна заштита није делотворна ако озбиљан навод о изборној неправилности остане неиспитан само зато што је неспорно овлашћено лице употребило назив изборне листе тамо где је требало дословно навести назив коалиције која ју је поднела. Манипулације које ова студија илуструје: POST-02 — прекомерни формализам у поступању изборних органа; POST-03 — онемогућавање мериторног одлучивања; POST-05 — селективна примена процесних правила; POST-06 — формално постојање, а практично ограничавање правне заштите; POST-07 — одбацивање приговора због непрецизног означавања подносиоца. Главни извори: приговор поднет Градској изборној комисији у Зајечару након локалних избора од 8. јуна 2025. године; одлука којом је приговор одбачен као непотпун и поднет од неовлашћеног лица; решење о проглашењу изборне листе; документација о коалицији и овлашћеном лицу; постојећи текст Атласа о случају Зајечар и контролној листи за подношење захтева и приговора. ← Студија 5 Студија 7 →"},{"title":"Студија случаја 7: Злоупотреба личних података и спорни потписи подршке изборним листама – случај кандидовања на београдским изборима 2023. године — Атлас изборних манипулација","url":"pages/studija-7.html","text":"Студија случаја 7: Злоупотреба личних података и спорни потписи подршке изборним листама – случај кандидовања на београдским изборима 2023. године — Атлас изборних манипулација АТЛАС изборних манипулација Ћир Lat Почетна / Студије случаја / 7 Прилог 2 · Документовани пример из изборне праксе Злоупотреба личних података и спорни потписи подршке изборним листама – случај кандидовања на београдским изборима 2023. године Студија случаја 7 Злоупотреба личних података и спорни потписи подршке изборним листама – случај кандидовања на београдским изборима 2023. године Поступак кандидовања представља прву формалну контролу законитости изборне утакмице. Да би изборна листа учествовала на изборима, она мора бити подржана прописаним бројем бирача, чије се изјаве дају лично и оверавају пред надлежним оверитељем. Потпис подршке није исто што и глас. Њиме се бирач не обавезује да ће за ту листу гласати, већ потврђује да подржава њено право да учествује на изборима. Овај механизам треба да спречи појаву листа које немају ни минималну подршку грађана и да обезбеди да се изборна понуда формира на основу аутентичних изјава бирача. Ако се лични подаци грађана употребе без њиховог знања, ако им се припишу потписи које нису дали или ако се изјаве овере без њиховог присуства, не компромитује се само један документ. Доводи се у питање законитост кандидовања, поузданост поступка овере, заштита личних података и способност изборних органа да провере документацију на основу које се листа проглашава. Ова студија односи се на догађаје са избора за Скупштину града Београда од 17. децембра 2023. године и на законски режим који је тада важио. Њен значај је данас пре свега документарни и аналитички: она показује како је ограничење према којем је један бирач могао да подржи само једну листу могло створити подстицај за незаконито прибављање потписа за листе које нису располагале довољном сопственом подршком. Законски контекст избора 2023. године У време избора 2023. године важило је правило да један бирач својим потписом може подржати само једну изборну листу. Потпис дат једној листи није могао бити употребљен као важећа подршка другој. Такво правило је имало за циљ да покаже колико различитих бирача стварно подржава кандидовање сваке листе. Међутим, оно је истовремено отежавало формирање листа које нису имале сопствену организациону мрежу и довољан број присталица. У таквом систему политички субјект који би желео да помогне појаву друге, формално независне листе није могао једноставно позвати своје чланове да потпишу обе листе. Њихови потписи су већ били потребни матичној странци или коалицији. Због тога је постојао могући подстицај да се подршка другим листама обезбеди коришћењем података лица која изјаву нису дала, притиском на бираче или другим незаконитим поступањем. Ова студија не утврђује да је нека конкретна странка организовала такав механизам. Она показује да су током избора 2023. документоване озбиљне сумње у аутентичност оверених изјава код више листа и да тадашњи законски режим треба узети у обзир приликом анализе могућих мотива за такву злоупотребу. Уочавање спорних изјава Приликом увида у документацију достављену Градској изборној комисији, чланови Комисије које су предложиле опозиционе изборне листе уочили су да се међу изјавама подршке налазе лични подаци грађана за које су сумњали да наведене листе нису подржали. Након непосредне провере, више лица је изјавило да: није потписало спорну изјаву подршке; није приступило надлежном оверитељу; није дало сагласност за употребу својих података; не познаје листу којој је наводно дало подршку; у појединим случајевима у време наводне овере није ни било у Србији. Према документацији припремљеној за ранију верзију ове студије, сумње су обухватиле седам проглашених изборних листа и још једну листу која није проглашена. Идентификована су најмање двадесет четири лица чији су се подаци налазили у спорним изјавама. Више њих је под кривичном и материјалном одговорношћу оспорило да је дало потпис подршке. Израз „фалсификовани потписи“ у овом контексту треба користити опрезно. Постојали су конкретни наводи и изјаве лица која су оспоравала аутентичност потписа, али се кривична одговорност и начин настанка сваког документа могу коначно утврдити само у поступку пред надлежним тужилаштвом и судом. Обим приговора и покренути поступци Поводом спорних изјава поднето је десет приговора Градској изборној комисији, међу којима су предмети: 02-013-78-4/2023; 02-013-78-5/2023; 02-013-89-2/23; 02-013-87-2/23; 02-013-84/23; 02-013-79/23; 02-013-87-3/2023; 02-013-87-4/23; 02-013-87-5/23; 02-013-84-4/23. Градска изборна комисија је приговоре одбила, а против њених одлука подношене су жалбе Вишем суду у Београду. Поред изборних правних средстава, осморо грађана чији су се подаци налазили у спорној документацији поднело је уставне жалбе. Подношене су и кривичне пријаве због сумње на фалсификовање исправа и неовлашћену употребу личних података. Имена тих лица у овој студији нису наведена, јер за разумевање механизма нису неопходна, а њихово објављивање би их могло изложити непотребним притисцима и непријатностима. Одбијање изборних приговора не значи нужно да је у сваком предмету спроведено графолошко вештачење и утврђено да је потпис аутентичан. За оцену институционалног одговора важно је утврдити: да ли су прибављени оригинали изјава; да ли су саслушана лица чији су потписи оспорени; да ли су проверене оверне књиге; да ли су испитани оверитељи; да ли су проверени подаци о присуству лица на месту овере; да ли је извршено стручно вештачење; да ли је испитана могућа повезаност спорних изјава код различитих листа. Зашто је формална овера била посебно значајна Спорне изјаве нису биле обични неоверени спискови. Оне су, према документацији, носиле формалну потврду да је грађанин лично приступио надлежном оверитељу и да је пред њим потписао изјаву или признао потпис за свој. Зато оспоравање једне такве исправе не отвара само питање ко је исписао потпис. Оно отвара и питање: како је утврђен идентитет потписника; да ли је лице лично присуствовало; ко је унео његове податке; да ли је оверни број правилно евидентиран; да ли се исправа налази у службеној оверној књизи; да ли је овера извршена у време и на месту наведеном у документу; да ли је оверитељ поступао законито и савесно. Могућа објашњења крећу се од административне грешке и замене документације до крађе идентитета, лажног представљања, фалсификовања потписа или незаконите овере. Ниједно од тих објашњења не сме се претпоставити без доказа. Провера аутентичности Поуздана провера спорне изјаве треба да обухвати: оригинал изјаве подршке; оверни број, датум и место овере; службену евиденцију оверитеља; податке о документу коришћеном за идентификацију; изјаву грађанина чији се потпис оспорава; неспорне узорке његовог потписа; податке о његовом кретању у време наводне овере; евентуални видео-надзор; исказ оверитеља и службених лица; графолошко и документарно вештачење. Графолошко вештачење није увек довољно. Чак и када је потпис аутентичан, могуће је да је прибављен на празном обрасцу, за другу сврху или обманом. Зато је потребно испитати цео ланац настанка, овере, преузимања и предаје документа изборној комисији. Значај за проглашење изборне листе Један спорни потпис не значи аутоматски да листа није имала довољну подршку. Потребно је утврдити: колико је потписа листа предала; колико јој је било потребно; колико је већ било неважећих; колико је накнадно оспорено; да ли после издвајања спорних изјава остаје законски минимум. Ипак, чак и када листа има довољан број других потписа, један утврђени случај злоупотребе личних података може указивати на потребу да се провери већи узорак или целокупна документација. Не треба се задовољити закључком да један потпис „не мења број“, ако околности указују на могући организовани образац. Према подацима из коришћене документације, седам проглашених листа код којих су забележене спорне изјаве освојило је укупно 31.958 гласова, али ниједна није прешла изборни цензус. Ти гласови нису због тога незаконити. Грађани су могли слободно да гласају за проглашене листе. Спорно је било питање да ли су те листе законито стекле право да се нађу на гласачком листићу. Могућа функција формално независних листа Листа која нема стварну самосталну подршку може, у зависности од конкретних околности, служити различитим политичким и организационим циљевима: стварању привида ширег политичког плурализма; збуњивању бирача сличним називом; одузимању гласова политички сродној листи; стицању места у проширеном саставу изборних органа; именовању чланова бирачких одбора; стицању медијског простора или јавних средстава; обезбеђивању додатне контроле изборног поступка у корист другог субјекта. Ово су могуће функције таквог механизма, а не утврђене чињенице о конкретним листама из 2023. године. За доказивање координације потребни су финансијски, организациони и комуникациони докази. Измене закона из 2026. године Народна скупштина је 20. маја 2026. године усвојила измене Закона о избору народних посланика и Закона о локалним изборима, објављене у „Службеном гласнику РС“, број 47/26. Измењено правило сада гласи: „Бирач може потписом подржати више изборних листа.“ Иста промена уведена је и за парламентарне и за локалне изборе. Пошто закон не прописује максималан број листа које један бирач може подржати, бирач више није ограничен на само једну изјаву подршке у истом изборном поступку. Измена је у складу са дугогодишњом препоруком ODIHR-а и Венецијанске комисије да се избегава правило према којем бирач сме да подржи само једну листу, јер потпис подршке не представља гласање нити политичко везивање бирача за једног учесника. ODIHR је и у извештајима за изборе 2023. и 2024. критиковао дотадашње ограничење. Како измена мења могуће механизме злоупотребе Према ранијем режиму, странка је морала да чува потписе сопствених присталица за своју листу. Ако је желела да помогне кандидовање друге листе, њени чланови нису могли законито да подрже обе. Након измене из 2026. године, чланови и присталице једне странке могу законито потписати подршку: листи сопствене странке; једној или више других листа; листама са којима се политички не слажу, али чије кандидовање желе да омогуће. Због тога више није неопходно фалсификовати потписе само да би се избегла забрана двоструке подршке. Ако политички субјект жели да организационо помогне другој листи, може позвати сопствене присталице да јој јавно и законито дају потписе. Ово смањује један од могућих подстицаја за злоупотребу забележену 2023. године. Истовремено, отвара други проблем: снажна странка сада може својом организационом мрежом помоћи формирање већег броја формално независних листа, без кршења правила о броју потписа. Такав поступак сам по себи није незаконит. Закон сада дозвољава да исти бирач подржи више листа. Међутим, он може олакшати: формирање сателитских или псеудонезависних листа; стварање привида политичког плурализма; кандидовање листа са сличним називима; распоређивање већег броја повезаних лица у изборне органе; фрагментацију изборне понуде; преусмеравање гласова. Стога се тежиште будуће контроле помера. Више није кључно питање да ли је исти бирач подржао две листе — то је сада законито. Важније постаје питање да ли су формално различите листе стварно организационо и финансијски независне и да ли се право на вишеструку подршку користи за прикривено координисано кандидовање. Злоупотреба личних података и даље остаје могућа Промена закона не значи да фалсификовање потписа више није могуће нити да је ова врста контроле постала непотребна. Спорни потписи се и даље могу појавити: ако листа нема довољно стварних присталица; ако жели да убрза прикупљање потписа; ако незаконито користи доступне базе личних података; ако не жели да открије стварну организациону везу са другом странком; ако се потписи прибављају без знања грађана; ако се поступак овере злоупотреби. Зато студија није изгубила сваку превентивну вредност. Промењен је њен главни контекст: она више није пре свега упозорење на последице правила „један бирач — једна листа“, већ документ о ранијем механизму и подсетник да лични подаци и поступак овере морају остати под строгом контролом. Нова обавеза изборних комисија Изменама из 2026. уведена је и важна заштитна одредба. Ако постоји основана сумња да је приликом прикупљања потписа дошло до злоупотребе података о личности бирача, Републичка изборна комисија, односно надлежна локална изборна комисија, дужна је да поднесе кривичну пријаву надлежном јавном тужилаштву. Ова измена је непосредно релевантна за искуство из 2023. године. Изборна комисија више не би смела да се ограничи само на одлуку да ли конкретан потпис улази у потребан број за проглашење листе. Када постоји основана сумња у злоупотребу података, закон јој сада налаже да покрене кривичноправни механизам. Ефикасност ове одредбе зависиће од: критеријума по којима се утврђује „основана сумња“; брзине поступања изборне комисије; квалитета документације достављене тужилаштву; чувања оригинала спорних исправа; поступања јавног тужилаштва; могућности да се незаконитост отклони пре избора, а не тек након њих. Историјски и аналитички значај студије После измена из 2026. ова студија више не треба да буде представљена као опис механизма који ће се нужно поновити у истом облику. Њен главни значај је у томе што: документује озбиљне сумње настале током кандидовања 2023. године; показује слабости поступка овере и контроле; објашњава ризике које је производило правило да један бирач може подржати само једну листу; показује како је злоупотреба личних података могла утицати на формирање изборне понуде; омогућава процену да ли су измене из 2026. одговориле на раније проблеме; упозорава да се после измена ризик може преместити са фалсификовања потписа на законито, али прикривено организовано формирање повезаних листа. Другим речима, конкретан механизам може променити облик, али питање аутентичности и стварне независности изборних листа остаје релевантно. Поуке и препоруке Овај случај показује да формална овера не сме бити третирана као необорив доказ када грађанин конкретно и уверљиво тврди да изјаву није дао. Истовремено, након измена из 2026. више није оправдано аутоматски третирати подршку истих лица већем броју листа као индицију злоупотребе. Таква подршка је сада законита. Контрола мора бити усмерена на друга питања: да ли је свака изјава стварно и добровољно дата; да ли су лични подаци законито коришћени; да ли је овера правилно извршена; да ли постоји прикривена организациона или финансијска веза између листа; да ли су листе формиране да би се злоупотребила права у изборним органима или збунили бирачи. Потребно је: омогућити бирачу да безбедно провери којим је листама евидентирана његова подршка; успоставити поуздан електронски траг о датуму, месту и оверитељу; обезбедити хитну проверу када грађанин оспори потпис; доследно примењивати нову обавезу подношења кривичне пријаве; чувати оригинале изјава до окончања свих поступака; испитати већи узорак када један спорни потпис указује на могући образац; објављивати анонимизоване податке о броју оспорених изјава и исходима поступака; анализирати организационе, кадровске и финансијске везе између формално независних листа; спречити злоупотребу проширеног састава изборних органа преко координисаних листа; обезбедити да се поступци окончају док се последице незаконитог кандидовања још могу отклонити. Најважнија поука је да законска промена може уклонити један подстицај за манипулацију, али не мора уклонити политички циљ који је манипулацијом оствариван. Након што је омогућено да исти бирач подржи више листа, потреба за фалсификовањем ради заобилажења ранијег ограничења може бити значајно смањена. Ипак, могућност да један политички субјект организује подршку формално независним листама није нестала — постала је законски лакша и мање видљива. Зато ова студија данас пре свега представља документ о ранијој пракси и основу за поређење старог и новог законског режима. Њена вредност није само у упозорењу шта се може поновити, већ и у разумевању начина на који измена правила мења технике и подстицаје изборног инжењеринга. Манипулације које ова студија илуструје: PRE/CAND-01 — спорни и неаутентични потписи подршке; PRE/CAND-02 — злоупотреба личних података ради кандидовања; PRE/CAND-03 — формирање фиктивних или формално независних листа; PRE/CAND-04 — злоупотреба поступка овере; PRE/CAND-05 — недовољна институционална контрола кандидатуре. У новом законском режиму посебан значај добија контрола прикривене координације и стварне независности изборних листа. Главни извори: Захтев Уставном суду поводом избора за Скупштину града Београда од 17. децембра 2023. године; предмети покренути пред Градском изборном комисијом и Вишим судом у Београду; осам уставних жалби и кривичне пријаве лица која су оспорила потписе, без навођења њихових имена; документација о спорним изјавама подршке; Коначни извештаји ODIHR-а о изборима 2023. и 2024. године; Закон о изменама и допунама Закона о избору народних посланика и Закон о изменама и допунама Закона о локалним изборима из 2026. године, објављени у „Службеном гласнику РС“, број 47/26. ← Студија 6 Студија 8 →"},{"title":"Студија случаја 8: Селективна примена закона приликом проглашавања мањинских изборних листа – различити критеријуми у поступку кандидовања 2023. године — Атлас изборних манипулација","url":"pages/studija-8.html","text":"Студија случаја 8: Селективна примена закона приликом проглашавања мањинских изборних листа – различити критеријуми у поступку кандидовања 2023. године — Атлас изборних манипулација АТЛАС изборних манипулација Ћир Lat Почетна / Студије случаја / 8 Прилог 2 · Документовани пример из изборне праксе Селективна примена закона приликом проглашавања мањинских изборних листа – различити критеријуми у поступку кандидовања 2023. године Студија случаја 8 Селективна примена закона приликом проглашавања мањинских изборних листа – различити критеријуми у поступку кандидовања 2023. године Једнака примена закона представља основни услов равноправне изборне утакмице. Није довољно да изборна правила буду формално иста за све учеснике. Неопходно је да изборна администрација у упоредивим чињеничним и правним ситуацијама примењује исте критеријуме, захтева исту врсту доказа и спроводи једнако темељну контролу. Ово начело има посебан значај приликом одлучивања о статусу изборне листе националне мањине. Тај статус није само политичка или симболичка ознака, већ производи важне правне последице. Мањинске листе подносе мањи број потписа подршке, не подлежу општем изборном цензусу и учествују у расподели мандата по повољнијем режиму. Зато признавање или одбијање мањинског статуса може непосредно утицати на то да ли ће листа учествовати на изборима и да ли ће освојити представнички мандат. На парламентарним изборима одржаним 17. децембра 2023. године отворено је питање да ли је Републичка изборна комисија приликом одлучивања о мањинском статусу различитих листа примењивала уједначене критеријуме. Према наводима захтева поднетог Уставном суду, у појединим случајевима спроведена је детаљна провера стварне везе листе са националном мањином и веродостојности поднете документације, док код других листа сличне сумње нису довеле до упоредиве контроле. Значај статуса мањинске изборне листе Посебна правила за мањинске изборне листе имају легитиман циљ: да омогуће националним мањинама делотворно политичко представљање и спрече да бројчано мање заједнице буду трајно искључене из парламента због општег изборног цензуса. Ова правила не представљају привилегију у недозвољеном смислу, већ посебну меру којом се обезбеђује стварна равноправност. Њихова оправданост, међутим, зависи од тога да мањински статус добијају листе које заиста представљају политичке интересе одређене националне мањине. У супротном, посебан режим може бити употребљен за: заобилажење изборног цензуса; кандидовање са мањим бројем потписа; стицање повољнијег положаја у расподели мандата; улазак у изборне органе под олакшаним условима; формирање листа које се само формално представљају као мањинске; освајање мандата без стварне везе са заједницом чије име користе. Зато изборна комисија мора истовремено штитити два интереса: право аутентичних мањинских листа на посебан режим и интегритет избора од злоупотребе тог режима. Поступак на изборима 2023. године У поступку кандидовања за парламентарне изборе 2023. године девет подносилаца затражило је да њихове изборне листе буду проглашене као листе националних мањина. Према документацији коришћеној за ову студију, Републичка изборна комисија признала је мањински статус седам листа, док су захтеви две листе одбијени. Сам различит исход није доказ неједнаког поступања. Различите листе могу располагати различитим доказима, имати другачији састав кандидата или испуњавати различите законске услове. Спорно питање било је нешто друго: да ли је Комисија у упоредивим случајевима користила исте методе провере и једнаку меру сумње. Према наводима из захтева Уставном суду, код једних листа тражени су додатни подаци, мишљења националних савета и опсежне провере потписа и кандидата, док се код других листа одлучивало без исте врсте контроле, иако су током седнице изнете сумње у њихов мањински карактер. Случај листе „Доста! Европски пут“ Код изборне листе „Доста! Европски пут“, која је затражила статус листе буњевачке националне мањине, Републичка изборна комисија спровела је додатну проверу. Према документацији, Комисија је: затражила мишљење Националног савета буњевачке националне мањине; разматрала стварну усмереност листе на представљање мањинских интереса; проверавала исправност потписа подршке; испитивала испуњеност услова за признавање мањинског статуса. Након спроведене провере, листи није признат статус мањинске изборне листе. Због тога је морала да испуни општи услов у погледу броја потписа подршке. Пошто потребан број није обезбедила, листа није проглашена. Овај поступак показује да је Републичка изборна комисија сматрала да формално позивање на националну мањину није само по себи довољно и да има право да испита стварни мањински карактер листе. Уколико је такав приступ правилан, онда би исти принцип требало применити и на све друге листе код којих су постојале упоредиве сумње. Случај листе „Руски мањински савез – Павле Бихали Гаврин“ Детаљна контрола спроведена је и код изборне листе „Руски мањински савез – Павле Бихали Гаврин“. Према наводима из захтева Уставном суду, Републичка изборна комисија је у овом предмету: вршила опсежнију проверу ваљаности потписа; тражила податке од Министарства државне управе и локалне самоуправе; проверавала да ли кандидати испуњавају услове повезане са бирачким правом; разматрала недостатке у поднетој документацији; на крају одбила да прогласи изборну листу. Одлука о одбијању могла је бити потпуно законита и заснована на утврђеним недостацима. Значај овог примера није у тврдњи да је листа морала бити проглашена, већ у степену контроле који је Комисија сматрала потребним и могућим. Тај стандард провере представља важну основу за поређење са поступањем према другим листама. Случај листе „Руска странка – Слободан Николић“ Другачији приступ, према наводима подносилаца захтева, примењен је код изборне листе „Руска странка – Слободан Николић“. Током разматрања листе изнете су сумње у њен стварни мањински карактер. Према документацији коришћеној за ову студију, указивано је да: су поједини кандидати непосредно пре избора били повезани са странкама које нису странке националних мањина; постоји питање стварне политичке и организационе везе листе са руском националном мањином; је велики број потписа подршке био концентрисан на подручју једне локалне самоуправе; би било потребно затражити мишљење надлежног националног савета или спровести додатну проверу. Упркос изнетим сумњама, Републичка изборна комисија, према захтеву Уставном суду, није затражила мишљење Националног савета руске националне мањине нити је спровела контролу упоредиву са оном која је примењена у друга два описана предмета. Листа је проглашена као изборна листа националне мањине. На изборима је освојила приближно 0,3 одсто гласова и, захваљујући правилима која се примењују на мањинске листе, освојила један посланички мандат. Ова чињеница не доказује да листа није представљала националну мањину нити да јој је статус признат незаконито. Она показује да је одлука о мањинском статусу имала непосредну последицу на састав Народне скупштине и да је зато уједначеност поступка била од суштинског значаја. Шта је било суштинско спорно питање Суштина случаја није у тврдњи да су све мањинске листе морале бити прихваћене или одбијене. Такво становиште не би уважило различитост чињеница у појединачним предметима. Суштина је у питању да ли је Републичка изборна комисија: користила исте критеријуме за процену мањинског статуса; тражила исту врсту додатне документације; у упоредивим ситуацијама прибављала мишљење националног савета; једнако проверавала порекло и ваљаност потписа; исто процењивала политичку и организациону везу листе са мањином; доследно испитивала састав и претходно политичко деловање кандидата; једнако образлагала своје одлуке. Различита одлука може бити законита ако је заснована на различитим чињеницама. Различита процедура у упоредивим случајевима, без јасног образложења зашто је једна листа подвргнута темељној контроли а друга није, ствара сумњу у селективну примену закона. Налази ODIHR-а Коначни извештај ODIHR-а о парламентарним изборима 2023. године изричито је указао да је Републичка изборна комисија недоследно примењивала критеријуме приликом разматрања захтева листа које су се представљале као листе националних мањина. Ова оцена је посебно значајна јер не потиче само од незадовољног изборног учесника. Независна међународна посматрачка мисија такође је препознала неуједначеност у поступању. ODIHR није заменио надлежни суд нити је утврдио да је конкретан мандат незаконито додељен. Његов налаз односи се на квалитет и доследност административног поступка. Управо је тај ниво анализе важан за ову студију: чак и када се не може коначно доказати да је одређена листа неоправдано добила статус, недоследан поступак сам по себи нарушава поверење у непристрасност изборне администрације. И у извештају о локалним изборима 2024. године ODIHR је оценио да критеријуми за утврђивање да ли листа представља националну мањину нису довољни да спрече злоупотребу. Више саговорника мисије тврдило је да су поједине листе користиле мањински статус ради лакшег стицања представништва, места у изборним комисијама или јавног финансирања. То показује да проблем није био ограничен на једну одлуку РИК-а из 2023. године, већ се односи на недовољно јасан и уједначен систем признавања мањинског статуса. Улога националних савета Једно од спорних питања јесте улога националних савета националних мањина у поступку проглашавања листе. Мишљење националног савета може бити важно јер тај орган познаје организације, политичке актере и јавне активности унутар мањинске заједнице. Међутим, национални савет не сме имати неограничено право да одлучује ко сме да представља мањину на изборима. Превелика зависност од његовог мишљења могла би: ограничити политички плурализам унутар мањине; фаворизовати већ постојеће мањинске странке; спречити појаву нових политичких група; претворити национални савет у чувара приступа изборној конкуренцији. Са друге стране, потпуно игнорисање могућности да се затражи стручно и институционално мишљење може олакшати злоупотребу мањинског статуса. Зато мишљење националног савета треба да буде један од доказа, а не једини или коначни критеријум. Најважније је да се прибавља према унапред познатим и једнако примењеним правилима. Ако се код једне листе тражи, а код друге у упоредивој ситуацији не тражи, Комисија мора јасно да објасни разлог за разлику. Како утврдити стварни мањински карактер листе Ниједан појединачни показатељ не може поуздано доказати да листа јесте или није аутентична мањинска листа. Назив листе није довољан. Исто важи и за националност једног кандидата, регистрацију странке као мањинске или мишљење једне организације. Потребно је посматрати скуп околности: програмске циљеве странке или групе; претходне активности у мањинској заједници; јавне ставове и политичко деловање кандидата; састав кандидатске листе; језик, симболе и садржај кампање; присуство у срединама у којима мањина живи; сарадњу са мањинским удружењима; изворе финансирања и организациону структуру; евентуалне везе са другим политичким субјектима; начин на који су прикупљени потписи; континуитет политичког деловања, а не само активност непосредно пред изборе. Ниједан од ових критеријума не сме бити примењен тако да се од кандидата захтева доказивање личног етничког идентитета на начин који би нарушио слободу националног изјашњавања. Предмет контроле није „крвно порекло“ кандидата, већ стварна политичка сврха и деловање изборне листе. Форензичка реконструкција поступка Да би се утврдило да ли је закон примењиван селективно, потребно је упоредити целокупне предмете свих листа које су тражиле мањински статус. Треба прикупити: захтеве за проглашење листа; оснивачке и програмске акте подносилаца; решења о регистрацији странака; спискове кандидата; документацију о потписима подршке; записнике и снимке седница РИК-а; предлоге и примедбе чланова Комисије; захтеве за прибављање додатних података; мишљења националних савета; одговоре министарстава и других органа; решења о проглашењу или одбијању; образложења одлука; жалбе и судске одлуке. После тога треба направити упоредну табелу: Контролна радња Листа А Листа Б Листа В Затражено мишљење националног савета да/не да/не да/не Провера потписа обим обим обим Провера кандидата да/не да/не да/не Додатни подаци од министарства да/не да/не да/не Одржана расправа о мањинском статусу да/не да/не да/не Разлози за одлуку наведени наведени наведени Оваква анализа не утврђује само исход, већ начин на који је до исхода дошло. Кључни докази Највећу доказну вредност имају: записници и видео-снимци седница РИК-а; писани предлози чланова Комисије; одлуке о прибављању додатних података; службена мишљења националних савета; преписка са министарствима; оригинална документација подносилаца; образложена решења РИК-а; судске одлуке по жалбама; докази о организационој или финансијској повезаности листа; упоредна пракса Комисије у другим изборним циклусима. Медијски текстови и политичке изјаве могу указати на спорно питање, али не могу заменити службену документацију. Различито поступање не значи аутоматски дискриминацију Важно је нагласити да различит обим провере није сам по себи доказ незаконитости. Комисија може имати оправдан разлог да једну листу проверава детаљније ако: документација садржи видљиве недостатке; постоје конкретни докази који изазивају сумњу; подаци су међусобно противречни; листа не испуњава јасно прописан услов; подносилац није доставио тражено појашњење; у једном предмету постоји околност које у другом нема. Проблем настаје када такви разлози: нису наведени; нису видљиви из предмета; нису доследно примењени; служе само као накнадно оправдање; не објашњавају очигледну разлику у третману. Зато свака одлука мора садржати довољно јасно образложење да независни посматрач или суд може разумети зашто је примењен одређени ниво контроле. Правни значај случаја Овај случај обухвата више правних начела: једнакост изборних учесника; забрану произвољног поступања; право националних мањина на политичко представљање; равноправност изборне утакмице; обавезу образлагања одлука; доследност и предвидивост рада изборне администрације; право на делотворно правно средство. Посебне мере за националне мањине морају се примењивати тако да истовремено: не отежавају аутентичним мањинским листама приступ изборима; не омогућавају немaњинским политичким субјектима да злоупотребе посебан режим. Ова два циља могу се остварити само јасним, објективним и унапред познатим критеријумима. Уколико Комисија од случаја до случаја слободно бира које ће доказе тражити, ризик произвољности остаје висок чак и када појединачне одлуке формално имају законски основ. Утицај на изборни интегритет Погрешно или селективно признавање мањинског статуса може непосредно утицати на изборни резултат. Листа којој је признат статус може: бити проглашена са мањим бројем потписа; учествовати у расподели мандата иако није прешла општи цензус; добити повољнији количник; освојити мандат са релативно малим процентом гласова; стећи представнике у изборним органима; утицати на расподелу политичке моћи. Са друге стране, аутентична мањинска листа којој је статус неоправдано ускраћен може бити онемогућена да уопште учествује или да оствари представништво. Тако селективна примена правила може деловати у оба смера: некоме неоправдано омогућити посебан положај; другом неоправдано ускратити право које му припада. Последица није само могућа промена једног мандата. Нарушава се поверење националних мањина у изборни систем и ствара сумња да се посебне мере користе као инструмент политичког инжењеринга. Поуке и препоруке Овај случај показује да изборни интегритет може бити нарушен и без директног кршења текста закона. Довољно је да се исти закон једнима примењује строго, а другима благо, без објективног и проверљивог објашњења. Зато је потребно: законом или подзаконским актом прецизније уредити критеријуме за признавање мањинског статуса; унапред утврдити када се тражи мишљење националног савета; обезбедити да то мишљење буде саветодавно, а не коначно; прописати исту основну контролну процедуру за све подносиоце; објавити контролну листу доказа и питања која Комисија разматра; сваку разлику у обиму провере посебно образложити; водити рачуна да се не захтева недозвољено доказивање личне националне припадности кандидата; испитивати стварну програмску и организациону усмереност листе; проверити могуће организационе, кадровске и финансијске везе са другим политичким субјектима; обезбедити хитну и делотворну судску контролу пре штампања гласачких листића; објављивати комплетне и претраживе одлуке и записнике; уједначавати праксу РИК-а кроз образложена начелна правила; после сваког изборног циклуса анализирати да ли су мањинске листе стварно допринеле политичком представљању мањина. Најважнија поука је да посебна права националних мањина морају бити заштићена и од ускраћивања и од злоупотребе. Престрога контрола може онемогућити аутентично мањинско представљање, док недовољна или селективна контрола може омогућити да посебан режим користе листе које са мањинском заједницом немају стварну политичку везу. Изборна администрација зато не сме одлучивати према политичком утиску или променљивом стандарду. Свака листа мора бити оцењена по истим, унапред познатим и проверљивим критеријумима. Само тако посебне мере могу задржати своју демократску сврху и не постати средство изборног инжењеринга. Манипулације које ова студија илуструје: PRE/CAND-06 — злоупотреба статуса мањинске изборне листе; PRE/CAND-07 — селективна примена критеријума приликом проглашавања листа; PRE/CAND-08 — фиктивне или псеудомањинске листе; PRE/CAND-09 — неједнака институционална контрола; PRE/CAND-10 — злоупотреба посебних изборних погодности. Главни извори: Захтев Уставном суду поводом парламентарних избора од 17. децембра 2023. године; документација и одлуке Републичке изборне комисије у поступцима проглашавања мањинских листа; записници и снимци седница РИК-а; Коначни извештај ODIHR-а о изборима 2023. године; Коначни извештај ODIHR-а о локалним изборима 2024. Године. ← Студија 7 Студија 9 →"},{"title":"Студија случаја 9: Када правна заштита престане да буде заштита – институционални неуспех у изборном поступку — Атлас изборних манипулација","url":"pages/studija-9.html","text":"Студија случаја 9: Када правна заштита престане да буде заштита – институционални неуспех у изборном поступку — Атлас изборних манипулација АТЛАС изборних манипулација Ћир Lat Почетна / Студије случаја / 9 Прилог 2 · Документовани пример из изборне праксе Када правна заштита престане да буде заштита – институционални неуспех у изборном поступку Студија случаја 9 Када правна заштита престане да буде заштита – институционални неуспех у изборном поступку Право на делотворну правну заштиту један је од основних услова демократских избора. Ниједан изборни систем не може у потпуности спречити неправилности, али мора обезбедити да свака озбиљна и доказима поткрепљена сумња буде брзо, непристрасно и темељно испитана. Изборно право разликује се од већине других правних области по изузетно кратким роковима и неповратности политичких последица. Ако се о приговору, жалби или изборном спору одлучи тек након што су резултати проглашени, мандати додељени, скупштина конституисана и значајан део мандата протекао, правна заштита може формално постојати, али више не може остварити своју основну сврху. Зато у изборним споровима није довољно да надлежни орган једном донесе одлуку. Он мора одлучити у време када се утврђена неправилност још може отклонити. Право које се призна прекасно у практичном смислу може постати право без заштите. Искуство након избора одржаних 17. децембра 2023. године показује како велики број појединачних правних средстава може постојати, а да систем ипак не обезбеди целовито испитивање навода о системским изборним неправилностима. Контекст избора 2023. године Након парламентарних, покрајинских и дела локалних избора одржаних 17. децембра 2023. године, поднет је велики број правних средстава. Она су се односила на различите фазе изборног поступка и различите врсте навода, укључујући: спорне промене пребивалишта и тачност бирачког списка; организовано довожење бирача; притиске на запослене и друге бираче; злоупотребу јавних ресурса; спорне потписе подршке изборним листама; неједнако поступање према подносиоцима листа; нарушавање тајности гласања; неправилности на бирачким местима; неправилности приликом бројања и утврђивања резултата. Правна средства су подношена изборним комисијама, судовима, јавном тужилаштву и Уставном суду. Међутим, постојање више институционалних путева није довело до јединственог поступка у којем би се испитало њихово могуће међусобно дејство. Један навод је могао бити посматран као питање бирачког списка, други као кривично дело, трећи као процедурална неправилност на бирачком месту, а четврти као питање уставности целокупног изборног поступка. Када сваки орган разматра само уски сегмент сопствене надлежности, системски образац може остати неиспитан иако је о његовим појединачним деловима поднет велики број пријава. Правна средства пред изборним комисијама Изборне комисије представљају прву инстанцу правне заштите за велики број изборних неправилности. Њихова предност је у томе што могу поступати брзо и непосредно су упознате са изборном документацијом. Ипак, њихова надлежност има ограничења. Комисија може да: испита радњу изборног органа; утврди одређене процедуралне неправилности; поништи гласање на бирачком месту када су испуњени законски услови; исправи или наложи исправљање појединих грешака; одлучи о проглашењу изборне листе; контролише формалну исправност изборне документације. Она, међутим, нема сва истражна овлашћења полиције и тужилаштва. Не може самостално спровести потпуну истрагу о организованој промени пребивалишта, фалсификовању већег броја исправа, финансијским токовима, злоупотреби службеног положаја или координацији више институција. Поред тога, изборне комисије истовремено спроводе изборе и одлучују о приговорима на поступање органа изборне администрације. Њихов састав је политички, јер чланове предлажу политички субјекти. Политички састав сам по себи не значи да комисија не може поступати законито, али повећава значај транспарентности, образложења одлука и независне судске контроле. Одбацивање и одбијање приговора У пракси правна средства могу бити окончана на два суштински различита начина: одбацивањем , када орган не улази у суштину због процесног недостатка; одбијањем , када орган разматра предмет, али закључи да приговор није основан. Ова разлика је важна за процену делотворности заштите. Када је приговор одбачен због неблаговремености, неовлашћеног подносиоца, непотпуности или другог формалног разлога, орган није утврдио да се неправилност није догодила. Он је само утврдио да процесни услови за њено испитивање нису испуњени. Када је приговор одбијен, потребно је проверити шта је заиста било предмет испитивања: да ли су изведени предложени докази; да ли су саслушани сведоци; да ли су прибављене службене евиденције; да ли је извршен увид у оригиналну документацију; да ли је одлука одговорила на све битне наводе; да ли је образложење конкретно или само понавља законске одредбе. Формулација да је приговор „неоснован“ не значи нужно да је спроведена свеобухватна истрага. Зато се делотворност не процењује само према исходу, већ према квалитету поступка који му је претходио. Фрагментација правне заштите Једна од главних слабости система јесте расподела различитих аспеката истог случаја између више органа. На пример, код сумње да су бирачи фиктивно пријављени на одређеној адреси: Министарство унутрашњих послова проверава пребивалиште; Министарство државне управе и локалне самоуправе води Јединствени бирачки списак; изборна комисија користи закључени извод; тужилаштво испитује евентуално кривично дело; суд одлучује о појединачном правном средству; Уставни суд може одлучивати о изборном спору који није у надлежности другог суда. Слично томе, код спорних потписа подршке: изборна комисија одлучује о проглашењу листе; оверитељ води евиденцију о овери; орган за заштиту података испитује употребу личних података; тужилаштво испитује фалсификовање; суд одлучује о кривичној одговорности; Уставни суд може разматрати повреду уставног права. Сваки орган може формално правилно закључити да део проблема припада неком другом. Последица је да нико не испита целокупан механизам. Улога редовних судова Судска контрола одлука изборних комисија треба да обезбеди независно преиспитивање законитости. Њена делотворност зависи од тога да ли суд има: довољно времена; приступ целокупном предмету; могућност извођења доказа; јасну надлежност; одговарајући стандард преиспитивања; обавезу да одговори на суштинске наводе. ODIHR је у Коначном извештају за изборе 2023. године навео да су приговори и жалбе решавани у законским роковима и да су одлуке Управног суда биле образложене, али и да усмене расправе нису одржаване, супротно међународној доброј пракси. Мисија је забележила и ограничено поверење дела изборних учесника у непристрасно одлучивање изборних комисија и судова. У извештају о локалним изборима 2024. године ODIHR је поново указао да су потребне додатне гаранције делотворног правног лека. Посебно је навео ограничења активне легитимације, изостанак јавних судских расправа и неповерење дела саговорника у непристрасност органа који одлучују о споровима. Право на усмену расправу није неопходно у сваком једноставном изборном предмету. Међутим, код спорних чињеница, већег броја сведока или навода о системском механизму, одлучивање искључиво на основу писаних поднесака може ограничити могућност да се предмет потпуно расветли. Уставни суд као крајња инстанца Уставни суд има посебну улогу у заштити изборног права. Према Уставу, он одлучује о изборним споровима за које законом није одређена надлежност другог суда. Та надлежност треба да обезбеди да не постоји правна празнина у којој озбиљан спор о уставности и законитости избора остаје без суда који може да га испита. Након избора 2023. године Уставном суду су поднети захтеви који су се односили на парламентарне и локалне изборе. Они нису били ограничени на један записник или једно бирачко место, већ су садржали тврдње о међусобно повезаним неправилностима које су, према подносиоцима, могле утицати на изборни процес као целину. У таквом предмету Уставни суд би требало најпре да одговори на питања: да ли је надлежан; ко има право да покрене поступак; који је однос овог поступка према другим правним средствима; који стандард доказивања се примењује; које мере може изрећи; у ком року мора одлучити. Ако суд сматра да није надлежан, и та одлука мора бити донета благовремено и јасно образложена. Вишегодишње неодлучивање не пружа подносиоцу ни заштиту, ни коначну потврду да заштиту мора тражити другим путем. Дуготрајно неодлучивање о захтеву поводом парламентарних избора Захтев за одлучивање о спору поводом парламентарних избора из децембра 2023. године остао је нерешен и током 2026. године. Према извештајима објављеним крајем јула 2026, подносиоцима је у међувремену достављен одговор у предмету који се односио на београдске изборе, док захтев поводом парламентарних избора ни после готово три године није добио коначан епилог. Ова временска дистанца има суштински значај. У међувремену су: проглашени коначни резултати; додељени мандати; конституисана Народна скупштина; изабрана Влада; усвајани закони и друге одлуке; протекао значајан део скупштинског мандата; започеле припреме за наредне изборе. Чак и ако би се накнадно утврдила повреда, могућност да се у потпуности отклоне њене политичке и правне последице постаје све мања. Изјаве председника Уставног суда из 2026. године Председник Уставног суда Владан Петров био је судија известилац у предмету поводом избора 2023. године пре него што је у јануару 2026. изабран за председника Суда. У јавном наступу у априлу 2026. године изјавио је да је реферат у предмету написао и изложио на припремној седници, али да наставка те седнице у претходном саставу Суда није било. О даљем поступању рекао је: „Можда ћемо на томе радити до краја, а можда и нећемо.“ Као разлог за могућност да предмет не буде окончан навео је приближавање нових избора и процену да би одлука могла да изазове „непотребне потресе“, додајући да би у изборној или предизборној години можда било боље усмерити се на будуће изборе. У каснијем интервјуу Петров је одбацио тврдњу да је некоме наложио да предмет „стави у фиоку“. Рекао је да је био међу судијама који су се залагали за решавање предмета и обећао да ће учинити оно што је у његовој моћи да Суд пружи одговор. Због тога не би било прецизно у Атласу написати да је председник Уставног суда признао да је лично „ставио изборну жалбу у фиоку“. Прецизна и документована чињеница јесте да је као судија известилац саставио и представио реферат, да поступак годинама није окончан и да је као председник Суда јавно оставио отвореном могућност да Суд предмет уопште не реши до краја, између осталог због процене могућих политичких „потреса“. Зашто је образложење о „потресима“ проблематично Уставни суд не одлучује о томе да ли је нека одлука политички погодна, већ да ли је уставно и правно основана. Могуће друштвене или политичке реакције могу бити релевантне за разумевање последица одлуке, али не би смеле да замене правне критеријуме за одлучивање. Ако Суд одлаже предмет зато што би: усвајање захтева могло да доведе у питање легитимитет власти; одбијање захтева могло да изазове незадовољство опозиције; било који исход могао да произведе политичке потресе, онда се правна заштита подређује процени политичке целисходности. Управо је функција уставног суда да одлучује и у предметима који су политички осетљиви. Што је спор важнији и последице веће, то је већа потреба за јасним, независним и правовременим правним одговором. Одлагање не уклања политички проблем. Оно га оставља нерешеним и истовремено слаби поверење у институцију која је дужна да одлучи. Право на одлуку, а не право на повољан исход Делотворна правна заштита не подразумева да подносилац мора успети у спору. Уставни суд може: одбацити захтев због ненадлежности или другог процесног разлога; одбити га као неоснован; усвојити га у целини или делимично; утврдити повреду и одредити одговарајућу последицу. Сваки од тих исхода може бити правно легитиман ако је: донет од надлежног и непристрасног органа; заснован на закону и доказима; довољно образложен; донет у разумном и изборно релевантном року. Подносилац нема право на одлуку која ће му политички одговарати. Има право да његов захтев не остане неодређено време без одговора. Зато се институционални неуспех не огледа нужно у томе што захтев није усвојен, већ у томе што Суд годинама није заузео коначан правни став. Одлука која стигне после истека своје сврхе У редовном грађанском или управном спору и закаснела одлука понекад може обезбедити накнаду штете или исправљање последице. У изборном спору то је много теже. Изборни поступак има јасан временски ток: кандидовање; кампања; гласање; утврђивање резултата; додела мандата; конституисање представничког тела; вршење власти. Што се даље одмакне у овом низу, то је теже вратити поступак у стање пре повреде. Након више година није могуће једноставно поновити политички и друштвени контекст у којем су избори одржани. Зато време у изборном спору није само питање ефикасности суда. Оно је део самог садржаја права. Може ли нови изборни циклус оправдати неодлучивање о старом Тврдња да се треба усмерити на предстојеће изборе уместо на нерешени спор из претходног циклуса ствара опасан институционални образац. У Србији су избори чести, а ванредни изборни циклуси могу се расписивати у кратким размацима. Ако близина нових избора представља разлог да се не одлучује о старим, готово никада неће постојати „погодан“ тренутак за решавање политички осетљивог изборног спора. Такав приступ може створити круг: предмет није решен непосредно након избора; протеком времена последице постају све теже отклоњиве; приближавају се нови избори; решавање се одлаже да не би утицало на нови циклус; после нових избора јављају се нови спорови; стари предмет губи практични значај без коначне одлуке. На тај начин неодлучивање постаје трајан модел, а не привремено кашњење. Институционална ћутња као облик одлуке Формално, неодлучивање није исто што и одбијање захтева. Међутим, за подносиоца и изборни процес оно може произвести сличан или тежи ефекат. Када Суд не одлучи: спорна правна питања остају неразјашњена; наводи остају ни потврђени ни оповргнути; институције немају смернице за будуће поступање; могућа повреда остаје без последице; јавност не добија образложен одговор; исте неправилности могу се поновити; подносилац не зна да ли и када може тражити заштиту пред другом инстанцом. Таква институционална тишина практично чува постојеће стање. Зато неодлучивање, иако није формална судска одлука, производи стварну правну и политичку последицу. Могућност обраћања Европском суду за људска права Дуготрајно неодлучивање може отворити питање да ли је домаће правно средство стварно делотворно и да ли подносилац мора неограничено да чека његов исход пре обраћања међународној инстанци. Пред Европским судом за људска права питање исцрпљивања домаћих правних средстава зависи од конкретног права, природе спора, статуса подносиоца и стварне делотворности расположивог средства. Није могуће унапред закључити да би свака изборна жалба била допуштена пред тим судом. Ипак, јавно изражена могућност да домаћи суд можда уопште неће окончати предмет може бити релевантна за оцену да ли се од подносиоца разумно може захтевати да и даље чека. Стручњаци који су коментарисали изјаву председника Суда оценили су да она додатно отвара питање делотворности домаћег правног пута. Налази ODIHR-а о правној заштити ODIHR је у извештају за 2023. годину оценио да правни оквир омогућава подношење приговора и жалби, али је забележио ограничено поверење дела учесника у непристрасност одлучивања. Мисија је указала и на формално одбацивање дела приговора и изостанак усмених расправа пред Управним судом. У извештају о локалним изборима 2024. године ODIHR је навео да су потребне додатне гаранције како би се обезбедио пун приступ делотворном правном леку. Указано је на ограничења у погледу лица која могу покренути поступак, недостатак јавних судских расправа и неповерење у непристрасност органа који одлучују. Ови налази показују да проблем правне заштите није ограничен само на један нерешен предмет Уставног суда. Он обухвата: уске процесне услове; кратке рокове; неуједначен приступ доказима; формалистичко одлучивање; ограничену активну легитимацију; недостатак јавности поступка; неодлучивање у предметима системског значаја. Форензичка реконструкција институционалног неуспеха Да би се оценила делотворност правне заштите, није довољно пребројати колико је приговора и жалби поднето. Потребно је реконструисати пут сваког важнијег навода кроз институције. За сваки случај треба утврдити: када је неправилност уочена; ко ју је пријавио; ком органу; у ком року; који докази су достављени; да ли је поднесак одбачен или мериторно разматран; које доказе је орган извео; када је одлука донета; да ли је постојао правни лек; када је о њему одлучено; да ли је утврђена повреда могла бити отклоњена; да ли је предмет прослеђен другом надлежном органу; да ли је кривични, управни или уставносудски поступак окончан. Посебно је корисно направити временску линију: Догађај Датум Орган Предузета радња Исход Уочена неправилност Поднет приговор Одлука комисије Поднета жалба Судска одлука Кривична пријава Поступање тужилаштва Захтев Уставном суду Коначна одлука Тек таква анализа показује да ли је систем стварно испитао случај или га је само прослеђивао између институција. Кључни докази За анализу ове студије најважнији су: оригинални приговори и жалбе; докази о времену њиховог подношења; одлуке изборних комисија; судске одлуке; записници и снимци седница; захтеви Уставном суду; потврде о пријему и бројеви предмета; акти о додељивању предмета судији известиоцу; подаци о одржаним припремним седницама; извештаји о току предмета; јавне изјаве представника Суда; одговори на захтеве за увид у списе; кривичне пријаве и обавештења тужилаштва; извештаји ODIHR-а и других посматрачких организација. Медијска оцена да предмет „стоји у фиоци“ није сама по себи доказ процесног стања. За прецизну анализу потребно је раздвојити новинарску или политичку квалификацију од проверљивих чињеница: када је предмет формиран, шта је у њему предузето, да ли је реферат састављен, да ли је о њему расправљано и зашто коначна одлука није донета. Правни значај случаја Овај случај обухвата више основних начела: право на делотворно правно средство; право на одлуку у разумном року; заштиту изборног права; правну сигурност; независност и непристрасност суда; обавезу образлагања одлука; начело владавине права; поделу правног и политичког одлучивања. Делотворна заштита не мери се само постојањем институције и могућношћу да јој се поднесе захтев. Она мора бити: доступна; независна; способна да утврди чињенице; овлашћена да отклони повреду; довољно брза; предвидива; образложена. Ако један од ових елемената трајно изостане, правно средство може постати само формална могућност. Утицај на изборни интегритет Изостанак делотворне правне заштите има системски утицај и када се не може доказати да би исход конкретног спора био другачији. Последице су: могуће неправилности остају неиспитане; одговорна лица не сносе последице; институције не добијају обавезујуће смернице; исти механизми могу се поновити; изборни учесници губе поверење у правна средства; спор се са правног терена преноси на протесте и политички сукоб; јавност изборни резултат доживљава као питање политичке моћи, а не правне провере; Уставни суд губи улогу крајњег гаранта изборног права. Најопаснија последица јесте стварање уверења да се озбиљна изборна неправилност исплати ако њена правна провера може бити одложена док не изгуби практични значај. Поуке и препоруке Овај случај показује да велики број правних средстава не гарантује делотворну правну заштиту. Систем може имати приговоре, жалбе, кривичне пријаве, уставне жалбе и изборне спорове, а да ниједан орган не испита целину навода и не донесе одлуку у време када се повреда може отклонити. Зато је потребно: законом прописати кратке и јасне рокове за одлучивање Уставног суда у изборним споровима; прецизно уредити његову надлежност и однос према другим судовима; јасно одредити ко може покренути изборни спор; обезбедити приоритетно поступање у свим изборним предметима; прописати јавну расправу када предмет садржи спорне чињенице од системског значаја; омогућити хитно извођење доказа и прибављање службених евиденција; објављивати основне податке о фази у којој се предмет налази, уз заштиту поверљивих података; образложити свако значајније одступање од прописаног рока; успоставити механизам координације изборних комисија, судова, полиције и тужилаштва; обезбедити да одбацивање из формалних разлога буде ограничено на недостатке који стварно онемогућавају поступање; омогућити хитну исправку отклоњивих недостатака; обезбедити да судови могу разматрати кумулативни утицај више повезаних неправилности; водити јединствену и претраживу базу изборних спорова и њихових исхода; прописати делотворне привремене мере када постоји опасност од неповратне последице; осигурати да политичка процена могућих реакција не замени правну оцену предмета. Најважнија поука је да у изборном спору неодлучивање није неутрално. Оно оставља на снази резултат чија је законитост оспорена, омогућава да све политичке последице произведу дејство и постепено лишава правно средство практичне сврхе. Уставни суд не мора да усвоји захтев поводом избора 2023. године. Може га одбацити, одбити или усвојити у складу са Уставом, законом и доказима. Оно што није спојиво са делотворном правном заштитом јесте могућност да предмет од највећег јавног и уставног значаја остане без коначног одговора зато што би било који одговор могао изазвати политичке „потресе“. Када судска заштита стигне тек пошто је изборни циклус окончан, мандат готово потрошен и нови избори на прагу, она више не исправља изборни процес. Она само накнадно описује повреду чије су последице постале неповратне. У том тренутку правна заштита престаје да буде стварна заштита. Манипулације и институционалне слабости које ова студија илуструје: POST-02 — прекомерни процесни формализам; POST-03 — одуговлачење у изборним споровима; POST-06 — формално постојање, а практична неделотворност правне заштите; POST-08 — фрагментација надлежности; POST-09 — избегавање мериторног испитивања системских неправилности; POST-10 — неодлучивање као облик ускраћене правне заштите; POST-11 — политизација времена и начина судског одлучивања. Главни извори: захтеви Уставном суду поводом парламентарних и београдских избора од 17. децембра 2023. године; одлуке изборних комисија и редовних судова; кривичне пријаве и други поступци покренути поводом документованих неправилности; Коначни извештај ODIHR-а о изборима 2023. године; Коначни извештај ODIHR-а о локалним изборима 2024. године; јавно доступне изјаве председника Уставног суда из априла 2026. године; подаци о стању предмета објављени током 2026. године. ← Студија 8 Студија 10 →"},{"title":"Студије случаја — Атлас изборних манипулација","url":"pages/studije-slucaja.html","text":"Студије случаја — Атлас изборних манипулација АТЛАС изборних манипулација Ћир Lat Почетна / Студије случаја Прилог 2 Студије случаја Десет детаљно обрађених примера који показују механизме изборних манипулација, институционалне одговоре, правни значај и поуке за будуће изборне процесе. Студија случаја 1 Бирачки списак као средство изборног инжењеринга – организоване промене пребивалишта пред изборе 2023. године Интегритет бирачког списка представља један од основних предуслова слободних и поштених избора. Право гласа не подразумева само да сваки пунолетни држављанин може да гласа, већ и да то право остварује у изборној јединици којој законито… Прочитајте целу студију → Студија случаја 2 Притисци на запослене у јавном сектору – политичка лојалност као услов радне и социјалне сигурности Слободно бирачко право подразумева да грађанин политичку одлуку доноси без претње, принуде, условљавања или страха од последица. Формална тајност гласања није довољна ако је бирач пре доласка на бирачко место изложен притиску… Прочитајте целу студију → Студија случаја 3 Неравноправни услови изборне кампање – функционерска кампања и злоупотреба јавних ресурса Равноправност изборне утакмице подразумева да политички учесници наступају под условима који им омогућавају стварну конкуренцију. То не значи да сви морају располагати истим новцем, организацијом или медијском видљивошћу, али државна… Прочитајте целу студију → Студија случаја 4 Тајност гласања као средство заштите слободне воље – фотографисање гласачких листића, породично гласање и доказивање политичке лојалности Тајност гласања представља један од основних услова слободних избора. Њена сврха није само да сакрије избор појединца од других лица, већ да онемогући контролу над бирачем, куповину гласова, политичку принуду и кажњавање због начина… Прочитајте целу студију → Студија случаја 5 Косјерић – формалистичко ускраћивање благовременог увида у изборни материјал Право на увид у изборни материјал представља један од најважнијих механизама контроле изборног поступка након затварања бирачких места. Без могућности да изборни учесник провери записнике, гласачке листиће, контролне листове и другу… Прочитајте целу студију → Студија случаја 6 Зајечар – одбацивање приговора због непрецизног означавања подносиоца Право на приговор представља један од основних механизама заштите изборног права. Његова сврха је да омогући да изборна комисија испита наводе о неправилностима, утврди чињенично стање и, када су испуњени законски услови, отклони… Прочитајте целу студију → Студија случаја 7 Злоупотреба личних података и спорни потписи подршке изборним листама – случај кандидовања на београдским изборима 2023. године Поступак кандидовања представља прву формалну контролу законитости изборне утакмице. Да би изборна листа учествовала на изборима, она мора бити подржана прописаним бројем бирача, чије се изјаве дају лично и оверавају пред надлежним… Прочитајте целу студију → Студија случаја 8 Селективна примена закона приликом проглашавања мањинских изборних листа – различити критеријуми у поступку кандидовања 2023. године Једнака примена закона представља основни услов равноправне изборне утакмице. Није довољно да изборна правила буду формално иста за све учеснике. Неопходно је да изборна администрација у упоредивим чињеничним и правним ситуацијама… Прочитајте целу студију → Студија случаја 9 Када правна заштита престане да буде заштита – институционални неуспех у изборном поступку Право на делотворну правну заштиту један је од основних услова демократских избора. Ниједан изборни систем не може у потпуности спречити неправилности, али мора обезбедити да свака озбиљна и доказима поткрепљена сумња буде брзо,… Прочитајте целу студију → Студија случаја 10 Изборни календар као средство изборног инжењеринга – од уставног механизма до политичког инструмента Време одржавања избора није само техничко питање нити неутрална календарска одлука. Оно непосредно утиче на услове политичке конкуренције: дужину припрема и кампање, могућност организовања изборних учесника, медијску агенду, економске и… Прочитајте целу студију →"},{"title":"Глосар појмова — Атлас изборних манипулација","url":"pages/termini.html","text":"Глосар појмова — Атлас изборних манипулација АТЛАС изборних манипулација Ћир Lat Почетна / Глосар појмова Поглавље 2 Глосар појмова Терминолошке и методолошке напомене: значење основних појмова који се користе у Атласу. 2. ТЕРМИНОЛОШКЕ И МЕТОДОЛОШКЕ НАПОМЕНЕ 2.1. Изборна неправилност Изборна неправилност је свако одступање од прописаног правила или поступка у вези са припремом, спровођењем и утврђивањем резултата избора. Неправилност може настати: намерно; непажњом; услед незнања; погрешним тумачењем прописа; организационим пропустом; техничком грешком. Због тога сам појам неправилности не подразумева аутоматски постојање намере да се утиче на изборни резултат. 2.2. Изборна манипулација Изборна манипулација је намерна радња, пропуштање или организована пракса којом се утиче или покушава утицати на: слободно формирање изборне воље; опредељење бирача; излазност; тајност гласања; равноправност изборних учесника; рад изборних органа; број или расподелу гласова; утврђивање и објављивање резултата; могућност делотворне правне заштите. Манипулација не мора увек непосредно променити број гласова. Довољно је да нарушава услове у којима бирачи доносе одлуку или у којима се политички актери такмиче. 2.3. Изборна злоупотреба Изборна злоупотреба подразумева коришћење права, положаја, институције, јавног ресурса, личног податка или прописане процедуре у сврху која је супротна њеној законској или демократској намени. Примери могу укључивати употребу јавних ресурса у страначке сврхе, коришћење службеног положаја за притисак на бираче или прибављање података о грађанима ради политичке контроле. 2.4. Изборна превара Изборна превара је намерна противправна радња којом се обманом, фалсификовањем, прикривањем, заменом или другим недозвољеним поступањем настоји стећи незаконита изборна предност, повредити изборно право или изменити веродостојно исказану изборну вољу. Постојање изборне преваре као правно утврђене чињенице зависи од конкретних доказа и одлуке надлежног органа. Зато се у опису нерешених случајева користе формулације као што су „сумња на изборну превару“, „навод о изборној превари“ или „поступање које може имати елементе изборне преваре“. 2.5. Изборна крађа Израз „изборна крађа“ није јединствен правни термин. У јавном и политичком говору користи се за различите појаве — од појединачног незаконитог гласања до системског мењања изборне воље. У овој публикацији израз се употребљава ограничено, као колоквијални назив за тешке, организоване или системске изборне преваре које могу значајно утицати на изборни резултат или онемогућити веродостојно утврђивање изборне воље. Када се говори о правној одговорности, користе се прецизни називи конкретних радњи и правних повреда. 2.6. Изборни интегритет Изборни интегритет означава поштовање демократских принципа и правних правила током целог изборног циклуса. Он обухвата: једнако и опште бирачко право; слободно опредељивање; тајност гласања; равноправност изборних учесника; транспарентност; непристрасност изборне администрације; тачност бирачког списка; правилно бројање гласова; објављивање веродостојних резултата; делотворну правну заштиту; одговорност за повреде закона. 2.7. Системска манипулација Системска манипулација није само појава која се дешава на великом броју места. Она подразумева постојање најмање једног од следећих обележја: координисано поступање; понављање истог обрасца; организовање са вишег нивоа; коришћење институционалних или јавних ресурса; толерисање или прикривање од стране надлежних лица; велики број обухваћених бирача; трајање током више фаза изборног процеса; способност да значајно утиче на изборни резултат или легитимитет избора. Системска природа не може се закључити само на основу једног изолованог догађаја, осим када сам догађај открива ширу организацију или механизам. 2.8. Образац поступања Образац поступања постоји када се сличне радње јављају на више места, у више временских периода или према истим групама лица, а међу њима постоје значајне заједничке карактеристике. Утврђивање обрасца може се заснивати на: истом начину спровођења; истим средствима; истој врсти мета; истим организационим везама; сличним документима или списковима; истоветним упутствима; подударним сведочењима из различитих средина. Појединачни случај не треба аутоматски генерализовати. О системском обрасцу може се говорити тек након поређења већег броја проверљивих случајева. 2.9. Контролор и члан бирачког одбора У јавности се израз „контролор“ често користи за лице које је изборна листа предложила за члана или заменика члана бирачког одбора. Контролор није неформални посматрач. Када је именован у бирачки одбор, он има права и обавезе члана тог органа и учествује у његовом раду у складу са законом и упутствима надлежне изборне комисије. Његова улога обухвата: праћење законитости рада; учешће у доношењу одлука; контролу изборног материјала; праћење гласања и бројања; стављање примедаба у записник; потписивање записника или навођење разлога због којих га не потписује; обавештавање овлашћених предлагача о уоченим проблемима. Контролор не сме ометати гласање, нарушавати тајност гласања, водити кампању на бирачком месту или самовољно одузимати изборни материјал. 2.10. Посматрач Посматрач је лице акредитовано да непристрасно прати изборни процес у име домаће или међународне посматрачке организације. Посматрач по правилу: прати поступак; бележи запажања; поставља питања у оквирима правила; не учествује у одлучивању бирачког одбора; не даје налоге члановима изборних органа; не додирује изборни материјал; не омета гласање. Права и ограничења контролора и посматрача нису иста и не треба их мешати. 2.11. Сведок Сведок је лице које је непосредно опазило догађај релевантан за изборни процес или има непосредна сазнања о њему. Лице које је информацију чуло од другог лица није непосредни сведок догађаја, али може бити сведок околности под којима му је информација саопштена. 2.12. Доказ и индиција Доказ је податак или материјал који може послужити за утврђивање релевантне чињенице. Индиција је посредна околност која указује да се одређени догађај можда догодио, али сама по себи није довољна за поуздан закључак. На пример, необично висока излазност представља статистичку околност која може оправдати проверу, али сама по себи не доказује да су убачени неважећи или фалсификовани гласови. 2.13. Документовање Документовање подразумева законито и систематично бележење чињеница о изборном догађају. Квалитетно документовање садржи: тачан датум и време; место и број бирачког места; опис радње; идентитет или опис укључених лица, када је то законито и могуће; имена сведока; фотографије или снимке, када су дозвољени; означавање релевантних докумената; примедбу у записнику; податак о томе коме је догађај пријављен; податак о реакцији надлежног лица. Документовање није исто што и јавно објављивање. Материјал који може бити доказ не треба непромишљено објављивати ако би се тиме угрозили поступак, приватност, безбедност лица или тајност гласања. 2.14. Фантомски бирач Израз „фантомски бирач“ користи се за лице за које постоји сумња да је у бирачки списак уписано на адреси на којој стварно не живи, да не испуњава услове за упис на конкретном месту или да је његов упис искоришћен ради незаконитог утицаја на изборе. Само неслагање формалног пребивалишта и места фактичког боравка не доказује изборну манипулацију. Неопходно је испитати законитост пријаве пребивалишта, време уписа, број пријављених лица на адреси и друге околности. 2.15. Бугарски воз „Бугарски воз“ је колоквијални назив за организовани механизам контролисаног гласања у којем се бирачу унапред даје већ попуњен гласачки листић, а од њега се захтева да из бирачког места изнесе непопуњен листић који је тамо добио. Изнети листић затим се попуњава и даје следећем бирачу, чиме се циклус наставља. Механизам угрожава тајност и слободу гласања и може бити повезан са куповином гласова, претњама или другим облицима контроле бирача. 2.16. Капиларни гласови Израз „капиларни гласови“ означава систем организованог прикупљања података о потенцијалним и сигурним гласачима преко разгранате мреже страначких активиста, запослених, локалних посредника или других лица. Само вођење евиденције о присталицама политичке организације није нужно противправно. Проблем настаје када се подаци прикупљају без правног основа, злоупотребом службених или пословних евиденција, уз притисак, претњу, условљавање или надзор начина гласања. 2.17. Сигуран глас „Сигуран глас“ је страначки термин за лице од којег се очекује или за које се тврди да ће гласати за одређену изборну листу или кандидата. Политичко убеђивање грађана је дозвољени део кампање. Међутим, формирање „сигурних гласова“ постаје проблематично када је повезано са незаконитом обрадом личних података, притиском, праћењем излазности, куповином гласова, претњама или условљавањем права и услуга. 2.18. Паралелни списак Паралелни списак је незванична евиденција бирача која се користи ван прописане изборне документације. Он може садржати: имена и адресе; редне бројеве из званичног извода из бирачког списка; бројеве телефона; политичку припадност или процену политичког опредељења; податак да ли је лице гласало; име активисте задуженог за бирача; напомене о запослењу, породичним односима или оствареним погодностима. Постојање сваког списка није аутоматски незаконито. Правна оцена зависи од извора података, сврхе, начина употребе, сагласности лица и повезаности са притисцима или контролом гласања. 2.19. Функционерска кампања Функционерска кампања означава коришћење јавне функције, службених активности и институционалне видљивости ради промовисања изборног учесника. Она се може испољити кроз нагло повећање броја јавних догађаја, отварање објеката, доделу помоћи, посете јавним установама и медијско представљање функционера на начин који брише границу између службене дужности и изборне промоције. Није свака активност јавног функционера током кампање незаконита. Оцена зависи од употребе јавних ресурса, начина представљања, садржаја поруке, учесталости активности и правила која уређују јавне функционере и медије. 2.20. Куповина гласова Куповина гласова подразумева давање или обећање новца, робе, услуге, посла, помоћи или друге користи у замену за гласање, негласање или гласање за одређеног учесника. Она може бити директна или прикривена, индивидуална или организована. Посебно је тешко разликовати закониту социјалну меру од изборног подмићивања када се јавна давања временски поклапају са кампањом. За оцену су важни правни основ, општост мере, време доношења, начин представљања и постојање захтева или очекивања у вези са гласањем. 2.21. Породично или групно гласање Породично или групно гласање је пракса у којој више чланова породице или неке групе заједно приступа простору за гласање или једно лице контролише, усмерава или обележава листиће других чланова породице или групе без законског основа за пружање помоћи. Ова појава нарушава индивидуалност и тајност изборног права, чак и када се одвија без отворене принуде. 2.22. Фотографисање гласачког листића Фотографисање попуњеног гласачког листића може служити као доказ трећем лицу да је бирач гласао на захтевани начин. Само поседовање телефона на бирачком месту не доказује манипулацију, али фотографисање у кабини може указивати на куповину гласа, притисак или организовану контролу. Реакција чланова бирачког одбора мора бити у складу са изборним прописима и не сме довести до нарушавања тајности гласања или самовољног претресања бирача. 2.23. Гласање у туђе име Гласање у туђе име подразумева да једно лице гласа користећи идентитет или податке другог бирача. Оно се може покушати употребом туђег документа, уз недовољну проверу идентитета, сарадњу чланова бирачког одбора или коришћење података лица за које се очекује да неће доћи на гласање. 2.24. Лажно потписивање бирача Лажно потписивање постоји када друго лице потпише извод из бирачког списка уместо бирача или када се потпис упише без стварног присуства и гласања тог бирача. Потпис у изводу представља важан део контроле броја лица која су приступила гласању. Због тога неслагање потписа, броја издатих листића и броја листића у кутији може бити значајан показатељ неправилности. 2.25. Преправљање записника Преправљање записника обухвата неовлашћену или нетранспарентну промену података о раду бирачког одбора и резултатима гласања. Исправљање очигледне рачунске грешке не мора бити незаконито, али мора бити спроведено у прописаном поступку, уз видљив траг измене, учешће овлашћених лица и очување првобитног документа. Посебно су ризичне измене извршене након што су чланови бирачког одбора потписали записник или напустили место примопредаје материјала. У пракси су забележени случајеви накнадне измене само првог примерка записника док су остали примерци већ подељени представницима изборних листа. 2.26. Погрешан унос резултата Погрешан унос резултата је неслагање између података из записника бирачког одбора и података унетих у званичну базу или објављених у резултатима. Он може бити последица ненамерне техничке грешке, али и намерне замене бројева или резултата изборних листа. Због тога је неопходно поређење објављених података са копијом оригиналног записника. 2.27. Осетљиви лични подаци и политичко опредељење Подаци о политичком мишљењу и опредељењу представљају посебно осетљиву категорију података о личности. Њихово прикупљање, повезивање са именом, запослењем, адресом, социјалним статусом или другим личним околностима може створити основу за притисак, дискриминацију и политичку контролу. Због тога се сваки паралелни списак мора посматрати и из угла правила о заштити података о личности, а не само изборног законодавства. 2.28. Политички притисак Политички притисак је поступање којим се лице принуђава, застрашује, условљава или ставља у неповољнији положај због свог стварног или претпостављеног политичког опредељења. Може се односити на: запослење; продужење уговора; напредовање; социјална давања; приступ јавним услугама; школовање; пословне дозволе; јавне набавке; друге користи или права. Притисак може бити експлицитан, али и посредан, када се лицу ставља до знања да се од њега очекује политичка активност или доказ гласања. 2.29. Злоупотреба јавних ресурса Злоупотреба јавних ресурса постоји када се новац, просторије, возила, опрема, запослени, подаци, службена комуникација или друга средства јавног органа користе ради изборне користи одређеног политичког учесника, супротно закону и начелу политичке неутралности јавне управе. 2.30. Правна квалификација Навођење могућег прекршаја, кривичног дела или друге повреде закона у овој публикацији представља оријентациону правну оцену. Коначна квалификација зависи од: потпуно утврђених чињеница; времена и места радње; својства учиниоца; постојања намере; обима последице; важећег прописа; одлуке надлежног органа. Зато се, осим када постоји правноснажна одлука, користи формулација да одређена радња „може представљати“, „може имати елементе“ или „може указивати на“ повреду закона. 3. ТИПОЛОГИЈА ИЗБОРНИХ МАНИПУЛАЦИЈА"},{"title":"Типологија изборних манипулација — Атлас изборних манипулација","url":"pages/tipologija.html","text":"Типологија изборних манипулација — Атлас изборних манипулација АТЛАС изборних манипулација Ћир Lat Почетна / Типологија изборних манипулација Поглавље 3 Типологија изборних манипулација Шта типологија представља, чему служи и због чега су манипулације подељене према фазама изборног процеса. 3. ТИПОЛОГИЈА ИЗБОРНИХ МАНИПУЛАЦИЈА 3.1. Сврха типологије Изборне манипулације могу се јавити у свакој фази изборног циклуса. Неке су усмерене на формирање политичке воље грађана пре расписивања или одржавања избора, друге на услове у којима се води изборна кампања, треће на сам поступак гласања, а четврте на бројање гласова, изборни материјал и утврђивање резултата. Подела према фазама изборног процеса омогућава: лакше препознавање ризика; прецизније одређивање надлежних институција; бољу припрему контролора и посматрача; систематично прикупљање доказа; разликовање појединачне неправилности од организованог обрасца; повезивање више радњи које заједно могу чинити системску манипулацију. Типологија у овој публикацији не полази искључиво од места на којем се радња дешава, већ од њене основне сврхе и последице. Тако се, на пример, фотографисање гласачког листића физички дешава на бирачком месту, али може бити завршни део претходно организоване куповине или контроле гласа. Паралелни спискови могу бити формирани током кампање, употребљавани на дан избора и касније коришћени за награђивање или кажњавање бирача. Поједине манипулације зато могу бити повезане са више категорија. Оне се сврставају у фазу у којој имају најизраженије дејство, уз упућивање на сродне појаве. 3.2. Основна подела Изборне манипулације разврставају се у пет главних група: PRE — манипулације пре изборне кампање и у припреми избора Обухватају утицај на изборне услове, бирачки списак, кандидовање, институције, запослене и друге групе грађана пре непосредног почетка гласања. KAM — манипулације током изборне кампање Обухватају неравноправну изборну утакмицу, злоупотребу функција и јавних ресурса, притиске, куповину гласова, медијске злоупотребе и незаконито прикупљање података о бирачима. BM — манипулације на бирачком месту Обухватају неправилности приликом отварања бирачког места, идентификације бирача, издавања листића, обезбеђивања тајности гласања и рада бирачког одбора. BR — манипулације током бројања гласова Обухватају поступања од затварања бирачког места до утврђивања резултата рада бирачког одбора и паковања изборног материјала. POST — манипулације након утврђивања резултата на бирачком месту Обухватају транспорт и предају изборног материјала, накнадне измене записника, погрешан унос и објављивање резултата, поступање изборних комисија и онемогућавање правне контроле. Следи преглед свих у овом приручнику обрађених изборних манипулација. Свака од њих ће бити детаљније обрађена у наставку књиге. Изаберите фазу изборног процеса PRE Пре избора KAM Током кампање BM На бирачком месту BR Током бројања POST Након избора"},{"title":"Захтев за увид у изборни материјал — Атлас изборних манипулација","url":"pages/zahtev-uvid.html","text":"Захтев за увид у изборни материјал — Атлас изборних манипулација АТЛАС изборних манипулација Ћир Lat Почетна / Практични обрасци / Захтев за увид у изборни материјал Практични обрасци Захтев за увид у изборни материјал Пример текста захтева за увид у изборни материјал и кратка упутства за његово прилагођавање. Практични обрасци Захтев за увид у изборни материјал Приговор изборној комисији Службена белешка о уоченој неправилности Записник о уоченој неправилности Контролна листа за изборни дан Дневник члана бирачког одбора или посматрача Како документовати изборну неправилност ↑ На врх Сврха: Помоћни практични алат за учеснике у изборном поступку. Правна природа: Пример који се прилагођава конкретном случају и важећем изборном законодавству; није законом прописан формулар. Намена: Чланови бирачких одбора, посматрачи, овлашћени представници изборних листа и друга овлашћена лица. Када се користи Овај текст служи као основа за подношење захтева надлежној изборној комисији ради увида у изборни материјал. Пре подношења потребно је проверити ко има право на увид, који материјал може бити предмет увида и који рокови важе у конкретном изборном поступку. Предложени текст Изборној комисији ______________________________ Предмет: Захтев за увид у изборни материјал ЗАХТЕВ Захтевам да ми се, у складу са важећим изборним законодавством, омогући увид у изборни материјал који се односи на: ☐ изборе за народне посланике ☐ изборе за одборнике скупштине јединице локалне самоуправе ☐ изборе за председника Републике ☐ друге изборе: ___________________________ Подаци о подносиоцу Име и презиме / назив: ___________________________ Својство и основ овлашћења: _______________________ Контакт: _________________________________________ Материјал у који се тражи увид ☐ записник о раду бирачког одбора ☐ контролни лист ☐ извод из бирачког списка, у законом дозвољеном обиму ☐ гласачки листићи ☐ други изборни материјал: ________________________ Образложење _____________________________________________________ _____________________________________________________ Молим да ме о термину и начину вршења увида благовремено обавестите. Место и датум: ____________________ Потпис: ___________________________ Практични савети Проверите надлежност комисије и рок пре предаје. Прецизно означите изборе, бирачко место и материјал који тражите. Предајте захтев у писаној форми и сачувајте доказ о пријему. Понесите доказ о својству и овлашћењу за увид. Сви практични обрасци Приговор изборној комисији →"},{"title":"Записник о уоченој неправилности — Атлас изборних манипулација","url":"pages/zapisnik-nepravilnost.html","text":"Записник о уоченој неправилности — Атлас изборних манипулација АТЛАС изборних манипулација Ћир Lat Почетна / Практични обрасци / Записник о уоченој неправилности Практични обрасци Записник о уоченој неправилности Структурисани пример за систематично документовање једне конкретне неправилности. Практични обрасци Захтев за увид у изборни материјал Приговор изборној комисији Службена белешка о уоченој неправилности Записник о уоченој неправилности Контролна листа за изборни дан Дневник члана бирачког одбора или посматрача Како документовати изборну неправилност ↑ На врх Сврха: Помоћни практични алат за учеснике у изборном поступку. Правна природа: Пример који се прилагођава конкретном случају и важећем изборном законодавству; није законом прописан формулар. Намена: Чланови бирачких одбора, посматрачи, овлашћени представници изборних листа и друга овлашћена лица. Када се користи Овај записник је структурисани помоћни алат за систематично документовање једне конкретне неправилности. Није службени записник бирачког одбора и не замењује унос примедбе у законом прописану изборну документацију. Предложени текст ЗАПИСНИК О УОЧЕНОЈ НЕПРАВИЛНОСТИ Избори: ___________________________________ Бирачко место / локација: __________________ Општина / град: __________________________ Време догађаја: од ______ до ______ часова Лице које сачињава записник: ______________ Својство: ☐ члан бирачког одбора ☐ посматрач ☐ друго: __________ Опис неправилности и редослед догађаја _____________________________________________________ _____________________________________________________ Присутна лица _____________________________________________________ Пријављивање и реакција Да ли је неправилност пријављена председнику бирачког одбора? ☐ Да ☐ Не Реакција: ___________________________________________ Да ли је затражен унос примедбе у записник о раду? ☐ Да ☐ Не Докази ☐ фотографије ☐ видео-запис ☐ службена белешка ☐ изјаве сведока ☐ други доказ: __________________________________ Датум и потпис: ____________________________________ Практични савети Један записник нека се односи на један догађај. Означите сваки доказ и објасните шта доказује. Не мењајте накнадно текст без видљиве напомене о измени. Када више лица има непосредна сазнања, корисно је да свако сачини сопствену белешку. ← Службена белешка о уоченој неправилности Сви практични обрасци Контролна листа за изборни дан →"},{"title":"Завршна порука — Атлас изборних манипулација","url":"pages/zavrsna-poruka.html","text":"Завршна порука — Атлас изборних манипулација АТЛАС изборних манипулација Завршна разматрања Завршна порука Изборни интегритет почива на законитости, чињеницама и способности да се свака уочена неправилност благовремено и употребљиво документује. Интегритет изборног процеса не зависи искључиво од постојања законских правила, већ и од способности учесника да њихову примену прате, неправилности благовремено препознају и чињенице о њима тачно и законито документују. Контролори и посматрачи немају улогу полиције, тужилаштва, суда или изборне администрације. Њихов задатак није да самостално утврђују кривицу или доносе коначне правне закључке, већ да непосредно уочене догађаје објективно забележе, захтевају примену прописане процедуре и сачувају податке који могу бити значајни за каснију проверу и правну заштиту. Највреднија евиденција није она која садржи најтеже оптужбе, већ она из које се јасно може утврдити шта се догодило, где, када, ко је био присутан, како је бирачки одбор реаговао и да ли је неправилност отклоњена или унета у службену документацију. Овај приручник полази од постојећег изборног система Републике Србије и намењен је непосредној припреми контролора и посматрача за предстојеће изборе. Његова сврха није предлагање реформе изборног система, већ пружање практичног и правно утемељеног оквира за спречавање, препознавање, евидентирање и пријављивање неправилности. Доследна примена описаних поступака не може сама по себи отклонити све ризике изборног процеса. Она, међутим, може значајно допринети очувању законитости, поузданости изборне документације и могућности да свака озбиљна сумња буде проверена на основу чињеница, а не претпоставки. Основно правило Уочити благовремено. Реаговати мирно. Поступати законито. Забележити прецизно. Сачувати доказ. ← 50 грешака контролора Почетна →"},{"title":"Претрага — Атлас изборних манипулација","url":"pretraga.html","text":"Претрага — Атлас изборних манипулација АТЛАС изборних манипулација Ћир Lat Претрага целог издања Пронађите појам или случај Претрага обухвата сва поглавља сајта, студије случаја, изборну форензику, практични прилог са 50 најчешћих грешака изборних контролора и завршну поруку. Појам за претрагу Претражи Унесите појам који тражите."}];
function latinizeForSearch(value){
  const map={'а':'a','б':'b','в':'v','г':'g','д':'d','ђ':'dj','е':'e','ж':'z','з':'z','и':'i','ј':'j','к':'k','л':'l','љ':'lj','м':'m','н':'n','њ':'nj','о':'o','п':'p','р':'r','с':'s','т':'t','ћ':'c','у':'u','ф':'f','х':'h','ц':'c','ч':'c','џ':'dz','ш':'s'};
  return Array.from((value||'').toLocaleLowerCase('sr')).map(ch=>map[ch]||ch).join('');
}
function normalizeText(value){return latinizeForSearch(value).normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'dj').replace(/[^a-z0-9]+/g,' ').trim();}
function runSearch(event){if(event)event.preventDefault();const input=document.getElementById('site-search');const results=document.getElementById('search-results');if(!input||!results)return;const q=normalizeText(input.value.trim());results.innerHTML='';if(q.length<2){results.innerHTML='<p class="search-status">Унесите најмање два знака.</p>';return;}const terms=q.split(/\s+/).filter(Boolean);const found=SEARCH_INDEX.filter(item=>{const hay=normalizeText(item.title+' '+item.text);return terms.every(t=>hay.includes(t));}).slice(0,100);if(!found.length){results.innerHTML='<p class="search-status">Нема резултата за задати упит.</p>';return;}const list=document.createElement('div');list.className='search-list';found.forEach(item=>{const a=document.createElement('a');a.className='search-result';a.href=item.url+(item.url.includes('?')?'&':'?')+'highlight='+encodeURIComponent(input.value.trim());const strong=document.createElement('strong');strong.textContent=item.title.replace(/ — Атлас изборних манипулација$/,'');const span=document.createElement('span');span.textContent='Отвори страницу →';a.append(strong,span);list.appendChild(a);});results.appendChild(list);}
document.addEventListener('DOMContentLoaded',()=>{const form=document.getElementById('search-form');if(form)form.addEventListener('submit',runSearch);const params=new URLSearchParams(location.search);const q=params.get('q');const input=document.getElementById('site-search');if(q&&input){input.value=q;runSearch();}});